-- 1. Clean up existing tables to ensure clean schema recreation
DROP TABLE IF EXISTS public.voti_bloopers CASCADE;
DROP TABLE IF EXISTS public.errori CASCADE;
DROP TABLE IF EXISTS public.films CASCADE;
DROP TABLE IF EXISTS public.profiles CASCADE;
DROP TABLE IF EXISTS public.configurazioni CASCADE;
DROP TABLE IF EXISTS public.suggerimenti CASCADE;
DROP TABLE IF EXISTS public.log_ricerche CASCADE;

-- 2. Create tables with exact columns matching Production
CREATE TABLE public.films (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  titolo text NOT NULL,
  anno integer,
  regista text,
  attori text,
  genere text,
  trama text,
  sinossi text,
  poster_url text,
  backdrop_url text,
  durata integer,
  tmdb_id bigint,
  tmdb_collection_id bigint,
  original_title text,
  slug text,
  creato_il timestamp with time zone DEFAULT timezone('utc'::text, now()),
  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()),
  aggiornato_il timestamp with time zone DEFAULT timezone('utc'::text, now())
);

CREATE TABLE public.errori (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  film_id bigint REFERENCES public.films(id) ON DELETE CASCADE,
  minuto text,
  categoria text,
  descrizione text NOT NULL,
  approvato boolean DEFAULT false,
  youtube_query text,
  screenshot_url text,
  conferme integer DEFAULT 0,
  contestazioni integer DEFAULT 0,
  inserito_da text,
  provenienza text DEFAULT 'ia',
  creato_il timestamp with time zone DEFAULT timezone('utc'::text, now()),
  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()),
  aggiornato_il timestamp with time zone DEFAULT timezone('utc'::text, now())
);

CREATE TABLE public.profiles (
  id uuid PRIMARY KEY,
  email text,
  username text,
  tier text DEFAULT 'free',
  tipo_abbonamento text DEFAULT 'nessuno',
  subscription_type text DEFAULT 'nessuno',
  calls_today integer DEFAULT 0,
  last_reset_date text,
  data_scadenza text,
  expires_at timestamp with time zone,
  punti integer DEFAULT 0,
  punti_premiati integer DEFAULT 0,
  mesi_accreditati integer DEFAULT 0,
  is_admin boolean DEFAULT false,
  created_at timestamp with time zone DEFAULT timezone('utc'::text, now())
);

CREATE TABLE public.configurazioni (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  chiave text UNIQUE NOT NULL,
  valore text,
  descrizione text,
  visibile boolean DEFAULT true,
  creato_il timestamp with time zone DEFAULT timezone('utc'::text, now())
);

CREATE TABLE public.voti_bloopers (
  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id uuid,
  errore_id bigint REFERENCES public.errori(id) ON DELETE CASCADE,
  tipo text NOT NULL,
  motivo text,
  created_at timestamp with time zone DEFAULT timezone('utc'::text, now())
);

CREATE TABLE public.suggerimenti (
  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id uuid,
  email text,
  messaggio text NOT NULL,
  created_at timestamp with time zone DEFAULT timezone('utc'::text, now())
);

CREATE TABLE public.log_ricerche (
  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id uuid,
  termine text,
  query text,
  created_at timestamp with time zone DEFAULT timezone('utc'::text, now())
);

