INSERT INTO public.films ("id", "titolo", "anno", "regista", "genere", "trama", "poster_url", "creato_il", "attori") VALUES
(143, 'Lo squalo 3', 1983, 'Joe Alves', 'Horror, Thriller, Avventura', 'Un enorme grande squalo bianco s''introduce nel parco acquatico di SeaWorld in Florida poco prima dell''inaugurazione di una nuova attrazione subacquea. Quando il cucciolo dello squalo muore all''interno della struttura, la gigantesca madre comincia a seminare il terrore e la distruzione, intrappolando i visitatori e il personale nei tunnel e nelle gallerie sottomarine.', 'https://image.tmdb.org/t/p/w500/kqDXj53F9paqVGJLGfHtz7giJ3s.jpg', '2026-09-27T19:48:40.064399', 'Dennis Quaid, Bess Armstrong, Simon MacCorkindale, Louis Gossett Jr.'),
(135, 'Rocky V', 1990, 'John G. Avildsen', 'Drammatico, Sportivo', 'Costretto al ritiro dai combattimenti a causa dei danni cerebrali riportati contro Ivan Drago e finito in rovina finanziaria, Rocky Balboa torna con la famiglia nel suo vecchio quartiere a Philadelphia. Qui comincia ad allenare un giovane e promettente pugile, Tommy Gunn, trascurando il proprio figlio. L''ambizione e l''avidità spingeranno però Tommy a voltare le spalle a Rocky, portando i due a uno scontro finale in una rissa di strada.', 'https://image.tmdb.org/t/p/w500/tevHaVxtrMTaUi8f3YjLWYSSY8A.jpg', '2026-09-19T22:20:24.685429', 'Sylvester Stallone, Talia Shire, Burt Young, Sage Stallone, Tommy Morrison, Richard Gant'),
(138, 'Jackie Brown', 1997, 'Quentin Tarantino', 'Crime, Thriller, Noir', 'Una hostess di volo di mezza età, che contrabbanda denaro sporco per un trafficante d''armi, viene incastrata dall''FBI. Per salvarsi, decide di fare il doppio gioco, ideando un piano rischioso per truffare sia i federali che il suo boss e fuggire con mezzo milione di dollari.', 'https://image.tmdb.org/t/p/w500/rOUx7qg4KmEh1juEDwqzbDSL1Nr.jpg', '2026-09-26T14:35:51.485995', 'Pam Grier, Samuel L. Jackson, Robert Forster, Bridget Fonda, Michael Keaton, Robert De Niro'),
(145, 'Le iene', 1992, 'Quentin Tarantino', 'Crime, Thriller', 'Dopo che una rapina a una gioielleria sfocia in un sanguinoso scontro a fuoco con la polizia, i sopravvissuti di una banda di criminali sconosciuti tra loro si rifugiano in un capannone abbandonato, convinti che tra di loro ci sia un infiltrato.', 'https://image.tmdb.org/t/p/w500/xi8Iu6qyTfyZVDVy60raIOYJJmk.jpg', '2026-09-28T17:15:18.136647', 'Harvey Keitel, Tim Roth, Michael Madsen, Chris Penn, Steve Buscemi, Lawrence Tierney'),
(149, '...altrimenti ci arrabbiamo!', 1974, 'Marcello Fondato', 'Commedia, Azione', 'Ben e Kid, un meccanico e un camionista appassionati di autocross, vincono a pari merito una fantastica Dune Buggy rossa con cappottina gialla. Non potendola dividere, decidono di giocarsela in una sfida a birra e salsicce. La gara viene però interrotta dagli scagnozzi di un gangster speculatore edilizio chiamato ''il Capo'', che distruggono il locale e danno fuoco alla macchina. I due si recano dal boss per pretendere una Dune Buggy nuova identica a quella distrutta, avvertendolo con un chiaro ''...altrimenti ci arrabbiamo!'': di fronte al rifiuto, scateneranno l''inferno a suon di memorabili scazzottate.', 'https://image.tmdb.org/t/p/w500/oERikPHC3cr9UDCale6YrQxkyNW.jpg', '2026-09-29T16:30:07.421745', 'Bud Spencer, Terence Hill, Donald Pleasence, John Sharp, Patty Shepard'),
(4, 'Ace Ventura - L''acchiappanimali', 1994, 'Tom Shadyac', 'Commedia', 'Ace Ventura è un eccentrico e stravagante investigatore privato specializzato nel ritrovare animali scomparsi. Alla vigilia del Super Bowl, viene ingaggiato per ritrovare Snowflake, il delfino mascotta dei Miami Dolphins, finito al centro di un misterioso complotto di vendetta legato all''ex giocatore Ray Finkle.', 'https://image.tmdb.org/t/p/w500/pqiRuETmuSybfnVZ7qyeoXhQyN1.jpg', '2026-09-13T14:44:03.51454', 'Jim Carrey, Courteney Cox, Sean Young, Tone Loc, Dan Marino'),
(158, 'Batman Begins', 2005, 'Christopher Nolan', 'Azione, Fantascienza', 'Dopo aver assistito all''omicidio dei suoi genitori, il giovane erede Bruce Wayne viaggia per il mondo alla ricerca di un modo per combattere le ingiustizie. Tornato a Gotham City, crea l''iconico alter ego di Batman per salvare la città dalla corruzione e dalle minacce del temibile Ra''s al Ghul e dello Spaventapasseri.', 'https://image.tmdb.org/t/p/w500/sPX89Td70IDDjVr85jdSBb4rWGr.jpg', '2026-09-30T18:34:58.428467', 'Christian Bale, Michael Caine, Liam Neeson, Katie Holmes, Gary Oldman, Cillian Murphy, Morgan Freeman'),
(159, 'Il cavaliere oscuro', 2008, 'Christopher Nolan', 'Azione, Thriller, Crime', 'Con l''aiuto del tenente Jim Gordon e del determinato procuratore distrettuale Harvey Dent, Batman continua a combattere il crimine organizzato che affligge Gotham City. La tregua apparente viene però spezzata dall''ascesa del Joker, una mente criminale psicopatica e anarchica che sprofonda la metropoli nel terrore e costringe il Cavaliere Oscuro a camminare sul filo sottile che divide l''eroe dal vigilante.', 'https://image.tmdb.org/t/p/w500/qJ2tW6WMUDux911r6m7haRef0WH.jpg', '2026-09-30T18:52:59.049885', 'Christian Bale, Heath Ledger, Aaron Eckhart, Michael Caine, Maggie Gyllenhaal, Gary Oldman, Morgan Freeman'),
(163, 'Digger', 2020, 'Georgis Grigorakis', 'Drammatico', 'Nikitas è un padre che vive solitario in una foresta incontaminata nel nord della Grecia, resistendo con tenacia all''espansione di un colosso minerario che minaccia il suo ambiente. La sua isolata routine viene sconvolta dal ritorno improvviso di suo figlio Johnny dopo vent''anni di assenza, intenzionato a reclamare la sua parte di eredità.', 'https://image.tmdb.org/t/p/w500/rm4UZ9DLXF06npLZMOTNTBNpWhk.jpg', '2026-10-03T07:26:57.834873', 'Vangelis Mourikis, Argyris Pandazaras, Sofia Kokkali, Theo Alexander'),
(165, 'Digger', 2026, 'Alejandro González Iñárritu', 'Drammatico, Avventura', 'Incentrato sulla storia dell''uomo più potente del mondo, il quale intraprende una missione frenetica per dimostrare di essere il salvatore dell''umanità prima che la catastrofe scatenata da lui stesso distrugga ogni cosa.', 'https://image.tmdb.org/t/p/w500/1ATXKrIPJyKNwnJ6lcG088Sa6zi.jpg', '2026-10-03T07:38:16.94161', 'Tom Cruise, Sandra Hüller, Jesse Plemons, John Goodman, Riz Ahmed'),
(132, 'Spider-Man: Brand New Day', 2026, 'Destin Daniel Cretton', 'Azione, Fantascienza, Avventura', 'Dopo gli eventi di ''Spider-Man: No Way Home'', Peter Parker cerca di rifarsi una vita in una New York che ha dimenticato la sua vera identità. Dovrà bilanciare la sua nuova e solitaria quotidianità con le responsabilità di essere un supereroe di quartiere, affrontando nuove minacce.', 'https://image.tmdb.org/t/p/w500/bjiS5ipwxb9JFy3XRRN4OAilSeX.jpg', '2026-09-19T18:05:53.341805', 'Tom Holland, Zendaya'),
(6, 'Il Padrino', 1972, 'Francis Ford Coppola', 'Drammatico, Crime', 'A New York, nel 1945, Don Vito Corleone è il capo di una potente famiglia mafiosa. Dopo aver rifiutato di entrare nel business della droga proposto da un clan rivale, Don Vito subisce un grave attentato. Suo figlio minore Michael, un eroe di guerra fino ad allora estraneo alle attività criminali della famiglia, decide di intervenire per proteggere il padre e vendicarsi. Questo evento darà inizio alla sua inesorabile ascesa e trasformazione nel nuovo spietato Padrino.', 'https://image.tmdb.org/t/p/w500/3bhkrj58Vtu7enYsRolD1fZdja1.jpg', '2026-09-13T14:48:17.858553', 'Marlon Brando, Al Pacino, James Caan, Robert Duvall, Diane Keaton'),
(67, 'Robin Hood - Un uomo in calzamaglia', 1993, 'Mel Brooks', 'Commedia, Parodia, Avventura', 'Tornato in Inghilterra dopo essere fuggito da una prigione a Gerusalemme durante le crociate, il nobile Robin di Locksley trova il suo castello confiscato e il paese sotto il giogo oppressivo del vile principe Giovanni e del goffo sceriffo di Ruttingham. Deciso a ristabilire la giustizia, Robin recluta un improbabile gruppo di fuorilegge nella foresta di Sherwood, gli ''Uomini in calzamaglia''. Tra frecce telecomandate, numeri musicali e situazioni demenziali, Robin tenterà di rovesciare il tiranno e conquistare il cuore della bella Lady Marian, la quale custodisce gelosamente la propria virtù protetta da una quasi indistruttibile cintura di castità.', 'https://image.tmdb.org/t/p/w500/woexOLEkUlYsPLLuZRK6LjZaF38.jpg', '2026-09-15T18:04:05.851255', 'Cary Elwes, Richard Lewis, Roger Rees, Amy Yasbeck, Dave Chappelle, Isaac Hayes, Mel Brooks'),
(56, 'Rocky II', 1979, 'Sylvester Stallone', 'Drammatico, Sportivo', 'Dopo il durissimo incontro con il campione dei pesi massimi Apollo Creed, Rocky Balboa decide di ritirarsi dal pugilato, sposa l''amata Adriana e cerca di costruirsi una vita tranquilla lontano dal ring. Ben presto però, a causa dell''inesperienza nella gestione del denaro e delle difficoltà a trovare un impiego stabile, Rocky si ritrova in gravi difficoltà economiche. Nel frattempo, Creed, tormentato dalle critiche dei tifosi e dalla stampa che insinuano che il verdetto del precedente match sia stato immeritato, lo provoca ripetutamente per convincerlo a salire di nuovo sul ring per una rivincita. Spinto dal bisogno e dal desiderio di riscatto, e confortato dal supporto di Adriana dopo un periodo critico, Rocky riprende gli allenamenti con Mickey per affrontare un drammatico secondo scontro.', 'https://image.tmdb.org/t/p/w500/nMaiiu0CzT77U4JZkUYV7KqdAjK.jpg', '2026-09-14T13:54:32.775259', 'Sylvester Stallone, Talia Shire, Burt Young, Carl Weathers, Burgess Meredith'),
(139, 'Bullet Train', 2022, 'David Leitch', 'Azione, Commedia, Thriller', 'Un sfortunato assassino di nome Ladybug vuole svolgere una semplice missione a bordo del treno ad alta velocità più veloce del mondo in Giappone. Tuttavia, si ritrova a doversela vedere con diversi killer professionisti provenienti da tutto il mondo, tutti con obiettivi interconnessi e contrastanti.', 'https://image.tmdb.org/t/p/w500/j8szC8OgrejDQjjMKSVXyaAjw3V.jpg', '2026-09-26T15:21:16.969652', 'Brad Pitt, Joey King, Aaron Taylor-Johnson, Brian Tyree Henry, Andrew Koji, Hiroyuki Sanada, Sandra Bullock'),
(13, 'Indiana Jones e il quadrante del destino', 2023, 'James Mangold', 'Avventura, Azione, Fantastico', 'Nel 1969, l''archeologo Indiana Jones è ormai prossimo al pensionamento e vive una vita tranquilla. Tutto cambia quando viene visitato dalla sua figlioccia Helena Shaw, che è alla ricerca di un raro e potente manufatto che suo padre aveva affidato a Indy anni prima: il Quadrante di Archimede, un dispositivo capace di individuare fessure temporali. Helena ruba l''oggetto per venderlo al miglior offerente, costringendo Indy a mettersi al suo inseguimento. Nel frattempo, anche Jürgen Voller, un ex scienziato nazista che ora lavora per la NASA, è sulle tracce del Quadrante con l''obiettivo di riscrivere la storia.', 'https://image.tmdb.org/t/p/w500/Af4bXE63pVsb2FtbW8uYIyPBadD.jpg', '2026-09-13T14:53:51.980462', 'Harrison Ford, Phoebe Waller-Bridge, Mads Mikkelsen, Antonio Banderas, John Rhys-Davies, Toby Jones'),
(31, 'Indiana Jones e i predatori dell''arca perduta', 1981, 'Steven Spielberg', 'Avventura, Azione', 'Nel 1936, l''archeologo e avventuriero Indiana Jones viene incaricato dai servizi segreti dell''esercito statunitense di trovare la leggendaria Arca dell''Alleanza, lo scrigno sacro contenente i Dieci Comandamenti, prima che cada nelle mani delle forze naziste di Adolf Hitler, intenzionate a sfruttarne il presunto potere sovrannaturale per dominare il mondo. Affiancato dalla sua fiera ex compagna Marion Ravenwood e dal fidato amico Sallah, Jones affronta una pericolosa caccia al tesoro tra le montagne del Nepal e le sabbie dell''Egitto, sfidando trappole mortali e il suo rivale senza scrupoli, l''archeologo francese René Belloq.', 'https://image.tmdb.org/t/p/w500/ceG9VzoRAVGwivFU403Wc3AHRys.jpg', '2026-09-13T15:08:13.656802', 'Harrison Ford, Karen Allen, Paul Freeman, John Rhys-Davies, Ronald Lacey'),
(161, 'Lucy', 2014, 'Luc Besson', 'Fantascienza, Azione, Thriller', 'Lucy è una giovane studentessa che vive a Taipei. Viene costretta a fare da corriere della droga da un cartello coreano. Le viene inserito chirurgicamente nel ventre un pacchetto contenente una nuova droga sintetica, il CPH4. A causa di un pestaggio, il pacchetto si rompe e la sostanza viene assorbita dal suo corpo, permettendole di sbloccare progressivamente le capacità del suo cervello fino al 100%.', 'https://image.tmdb.org/t/p/w500/kRbpUTRNm6QbLQFPFWUcNC4czEm.jpg', '2026-09-30T19:35:00.986208', 'Scarlett Johansson, Morgan Freeman, Choi Min-sik, Amr Waked'),
(164, 'Il patriota', 2000, 'Roland Emmerich', 'Azione, Drammatico, Storico, Guerra', 'Nel 1776, in Carolina del Sud, il veterano di guerra Benjamin Martin decide di non prendere parte alla guerra d''indipendenza americana per accudire i suoi sette figli. Tuttavia, quando un spietato ufficiale britannico uccide uno dei suoi ragazzi e dà alle fiamme la sua casa, Benjamin prende di nuovo le armi guidando una milizia di volontari contro l''esercito inglese.', 'https://image.tmdb.org/t/p/w500/fWZd815QxUCUcrWQZwUkAp9ljG.jpg', '2026-10-03T07:28:11.755314', 'Mel Gibson, Heath Ledger, Joely Richardson, Jason Isaacs, Chris Cooper'),
(233, 'Test Import Solo Colonne Esistenti', 2024, 'Test Regista', 'Drammatico', 'Trama di prova', 'https://image.tmdb.org/t/p/w500/test.jpg', '2026-10-24T14:52:52.586583', 'Test Attore 1, Test Attore 2'),
(120, 'Spider-Man: Far From Home', 2019, 'Jon Watts', 'Azione, Fantascienza, Avventura', 'Peter Parker decide di unirsi ai suoi migliori amici per una vacanza in Europa. Tuttavia, il piano di Peter di lasciarsi i superpoteri alle spalle per qualche settimana viene sventato quando accetta di aiutare Nick Fury a svelare il mistero degli attacchi di diverse creature elementali.', 'https://image.tmdb.org/t/p/w500/4q2NNj4S5dG2RLF9CpXsej7yXl.jpg', '2026-09-18T13:15:40.475072', 'Tom Holland, Samuel L. Jackson, Zendaya, Jake Gyllenhaal, Cobie Smulders'),
(119, 'Spider-Man: Homecoming', 2017, 'Jon Watts', 'Azione, Fantascienza, Avventura', 'Il giovane Peter Parker, entusiasta della sua esperienza con gli Avengers, torna a casa dove vive con la zia May. Sotto l''occhio vigile del suo mentore Tony Stark, Peter cerca di trovare un equilibrio tra la sua vita da normale studente e la sua identità segreta di Spider-Man, ma l''arrivo del villain Avvoltoio metterà tutto a rischio.', 'https://image.tmdb.org/t/p/w500/c24sv2weTHPsmDa7jEMN0m2P3RT.jpg', '2026-09-18T13:15:40.380686', 'Tom Holland, Michael Keaton, Zendaya, Robert Downey Jr., Marisa Tomei'),
(121, 'Spider-Man: No Way Home', 2021, 'Jon Watts', 'Azione, Fantascienza, Avventura', 'Per la prima volta nella storia cinematografica di Spider-Man, viene rivelata l''identità del nostro amichevole eroe di quartiere. Quando Peter chiede aiuto al Dottor Strange per ripristinare il suo segreto, l''incantesimo squarcia un buco nel loro mondo, liberando i più potenti nemici mai affrontati da uno Spider-Man in qualsiasi universo.', 'https://image.tmdb.org/t/p/w500/or6XJBVpcEbIkma0V9zshnbEtx4.jpg', '2026-09-18T13:15:40.579867', 'Tom Holland, Zendaya, Benedict Cumberbatch, Jacob Batalon, Jon Favreau'),
(140, 'C''era una volta a New York', 2013, 'James Gray', 'Drammatico, Storico', 'Nel 1921, le sorelle polacche Ewa e Magda arrivano a Ellis Island in cerca di una vita migliore. Quando Magda viene messa in quarantena per tubercolosi, Ewa si ritrova sola e vulnerabile, finendo sotto il controllo di un ambiguo impresario che la avvia alla prostituzione.', 'https://image.tmdb.org/t/p/w500/ArWRRQYeXL3nG4jYpMOPoBvgmy9.jpg', '2026-09-27T17:50:02.764654', 'Marion Cotillard, Joaquin Phoenix, Jeremy Renner'),
(69, 'Robin Hood', 2010, 'Ridley Scott', 'Azione, Avventura, Storico, Drammatico', 'Nell''Inghilterra del XIII secolo, dopo la morte di re Riccardo Cuor di Leone, l''arciere Robin Longstride torna in patria dalla Francia. Giunto a Nottingham, assume l''identità del defunto cavaliere Robert Loxley e si innamora della vedova Marion. Di fronte alla minaccia di un''invasione francese e alla tirannia del nuovo re Giovanni, Robin unisce i baroni ribelli e il popolo per difendere il paese, gettando le basi per la nascita della leggenda di Robin Hood.', 'https://image.tmdb.org/t/p/w500/9NS5QGOfck24yL3bZqWeW06PgPC.jpg', '2026-09-15T18:14:13.404964', 'Russell Crowe, Cate Blanchett, Mark Strong, Oscar Isaac, William Hurt'),
(63, 'Robin Hood', 1922, 'Allan Dwan', 'Avventura, Azione, Muto', 'Il Conte di Huntingdon parte per la Terza Crociata insieme a Re Riccardo Cuor di Leone. Durante la loro assenza, il perfido Principe Giovanni usurpa il trono d''Inghilterra instaurando un regime di terrore ed estorsione ai danni del popolo. Informato delle ingiustizie, il Conte torna in patria sotto le spoglie del fuorilegge Robin Hood e si rifugia nella foresta di Sherwood. Insieme alla sua banda di fedeli compagni, comincia a rubare ai ricchi per dare ai poveri, combattendo il tiranno per proteggere la sua amata Lady Marian e attenderne il ritorno del legittimo re.', 'https://image.tmdb.org/t/p/w500/baqMnZbAFPsfbaAOPRU1eJlCRdj.jpg', '2026-09-15T18:04:05.143269', 'Douglas Fairbanks, Wallace Beery, Sam De Grasse, Enid Bennett, Alan Hale'),
(90, 'Rambo: Last Blood', 2019, 'Adrian Grunberg', 'Azione', 'Ormai anziano, John Rambo cerca di condurre una vita tranquilla nel ranch di famiglia in Arizona. Quando la sua giovane nipote viene rapita in Messico da un cartello della droga, Rambo si reca oltre confine scatendando un''ultima, spietata vendetta.', 'https://image.tmdb.org/t/p/w500/kTQ3J8oTTKofAVLYnds2cHUz9KO.jpg', '2026-09-16T10:28:14.334618', 'Sylvester Stallone, Paz Vega, Sergio Peris-Mencheta'),
(146, 'Blade Runner', 1982, 'Ridley Scott', 'Fantascienza, Noir', 'In una Los Angeles distopica e piovosa del 2019, l''ex poliziotto Rick Deckard viene richiamato in servizio come ''blade runner''. Il suo compito è rintracciare e ''ritirare'' quattro replicanti della serie Nexus-6, androidi indistinguibili dagli umani, fuggiti dalle colonie extra-terrestri e giunti illegalmente sulla Terra alla ricerca del loro creatore per prolungare la propria breve vita.', 'https://image.tmdb.org/t/p/w500/63N9uy8nd9j7Eog2axPQ8lbr3Wj.jpg', '2026-09-29T13:49:10.170972', 'Harrison Ford, Rutger Hauer, Sean Young, Edward James Olmos, Daryl Hannah'),
(150, 'Dune', 2021, 'Denis Villeneuve', 'Fantascienza, Avventura, Drammatico', 'In un lontano futuro dell''umanità, il duca Leto Atreides accetta la gestione del pericoloso pianeta desertico Arrakis, noto anche come Dune, l''unica fonte della sostanza più preziosa dell''universo, la "spezia". Paul Atreides, il giovane erede della dinastia, dovrà viaggiare verso il pianeta più pericoloso dell''universo per assicurare il futuro della sua famiglia e del suo popolo.', 'https://image.tmdb.org/t/p/w500/v1tRXZ4JtD2Iv6fjkPvT4GiwslV.jpg', '2026-09-29T16:32:47.707379', 'Timothée Chalamet, Rebecca Ferguson, Oscar Isaac, Josh Brolin, Zendaya, Jason Momoa'),
(153, 'Toy Story - Il mondo dei giocattoli', 1995, 'John Lasseter', 'Animazione, Avventura, Commedia', 'Woody, un classico pupazzo da cowboy, è il giocattolo preferito del piccolo Andy e il leader riconosciuto di tutti gli altri giochi della cameretta. La sua posizione viene però minacciata quando per il compleanno di Andy arriva Buzz Lightyear, un supertecnologico astronauta giocattolo convinto di essere un vero spaziotraversatore. Inizialmente rivali, Woody e Buzz si ritroveranno accidentalmente divisi da Andy e dovranno unire le forze per affrontare mille pericoli e tornare a casa.', 'https://image.tmdb.org/t/p/w500/uXDfjJbdP4ijW5hWSBrPrlKpxab.jpg', '2026-09-30T18:28:22.395285', 'Tom Hanks, Tim Allen, Don Rickles, Jim Varney, Wallace Shawn'),
(154, 'Toy Story 2 - Woody e Buzz alla riscossa', 1999, 'John Lasseter, Lee Unkrich, Ash Brannon', 'Animazione, Avventura, Commedia', 'Mentre Andy è via per il campeggio estivo, Woody viene rapito da Al McWhiggin, un gordo e avido collezionista di giocattoli deciso a venderlo a un museo di Tokyo insieme ai membri della classica serie TV ''Woody''s Roundup''. Buzz Lightyear e gli altri giocattoli di Andy partono immediatamente per una coraggiosa missione di salvataggio per riportare l''amico a casa.', 'https://image.tmdb.org/t/p/w500/4rbcp3ng8n1MKHjpeqW0L7Fnpzz.jpg', '2026-09-30T18:28:42.612191', 'Tom Hanks, Tim Allen, Joan Cusack, Kelsey Grammer, Don Rickles'),
(50, 'Avengers: Age of Ultron', 2015, 'Joss Whedon', 'Azione, Fantascienza, Avventura', 'Quando Tony Stark e Bruce Banner cercano di avviare un programma di mantenimento della pace inattivo chiamato Ultron, le cose vanno terribilmente storte e il sistema intelligenza artificiale sviluppa una coscienza divina, decidendo che l''unico modo per salvare la Terra è sterminare l''umanità. Gli Avengers devono riunirsi e stringere imprevedibili alleanze per fermare il temibile Ultron e i suoi piani di distruzione globale.', 'https://image.tmdb.org/t/p/w500/4ssDuvEDkSArWEdyBl2X5EHvYKU.jpg', '2026-09-14T13:51:07.184214', 'Robert Downey Jr., Chris Hemsworth, Mark Ruffalo, Chris Evans, Scarlett Johansson, Jeremy Renner'),
(49, 'The Avengers', 2012, 'Joss Whedon', 'Azione, Fantascienza, Avventura', 'Quando Loki, il malvagio fratellastro di Thor, minaccia la sicurezza della Terra impossessandosi del potente Tesseract, Nick Fury, direttore dell''agenzia di spionaggio S.H.I.E.L.D., decide di attivare il protocollo Avengers. Per sconfiggere la minaccia aliena, Fury riunisce una squadra di supereroi straordinari, tra cui Iron Man, Captain America, Thor, Hulk, Vedova Nera e Occhio di Falco. Nonostante le iniziali incomprensioni e i conflitti interni, il gruppo dovrà unire le forze per salvare l''umanità.', 'https://image.tmdb.org/t/p/w500/RYMX2wcKCBAr24UyPD7xwmjaTn.jpg', '2026-09-14T13:51:06.242759', 'Robert Downey Jr., Chris Evans, Mark Ruffalo, Chris Hemsworth, Scarlett Johansson, Jeremy Renner, Tom Hiddleston, Samuel L. Jackson'),
(83, 'Interstellar', 2014, 'Christopher Nolan', 'Fantascienza, Avventura, Drammatico', 'In un futuro non lontano, un''inarrestabile piaga sta distruggendo i raccolti terrestri, condannando l''umanità alla fame. Un gruppo di esploratori e scienziati, guidati dall''ex pilota della NASA Cooper, intraprende una missione interstellare attraverso un wormhole recentemente scoperto nei pressi di Saturno, nel disperato tentativo di trovare un nuovo pianeta abitabile per salvare la specie umana.', 'https://image.tmdb.org/t/p/w500/yQvGrMoipbRoddT0ZR8tPoR7NfX.jpg', '2026-09-15T19:39:43.339888', 'Matthew McConaughey, Anne Hathaway, Jessica Chastain, Michael Caine, John Lithgow, Ellen Burstyn'),
(136, 'La storia del generale Custer', 1941, 'Raoul Walsh', 'Western, Biografico, Drammatico', 'La vita romanzata di George Armstrong Custer, dalla sua giovinezza all''accademia militare di West Point, attraverso le sue eroiche imprese durante la Guerra di Secessione, fino alla sua tragica morte nella celebre battaglia di Little Bighorn.', 'https://image.tmdb.org/t/p/w500/gx8jknFwZRuQwTPooe14Dsx5uTO.jpg', '2026-09-21T20:27:04.54815', 'Errol Flynn, Olivia de Havilland, Arthur Kennedy, Charley Grapewin'),
(147, 'Mr. Crocodile Dundee', 1986, 'Peter Faiman', 'Commedia, Avventura', 'Sue Charlton, una giornalista di New York, si reca nell''outback australiano per incontrare Michael J. "Crocodile" Dundee, un leggendario cacciatore di coccodrilli. Affascinata dal suo stile di vita, lo invita a New York, dove Dundee dovrà adattarsi alla caotica vita della metropoli.', 'https://image.tmdb.org/t/p/w500/pduPduL1ub5kok3lPYT15ryC9L6.jpg', '2026-09-29T14:21:36.286935', 'Paul Hogan, Linda Kozlowski, John Meillon, David Gulpilil'),
(57, 'Pirati dei Caraibi - La maledizione della prima luna', 2003, 'Gore Verbinski', 'Avventura, Azione, Fantastico', 'Caraibi, XVII secolo. La vita del pacifico fabbro Will Turner viene sconvolta quando l''amore della sua vita, Elizabeth Swann, figlia del governatore, viene rapita dal malvagio Capitan Barbossa e dalla sua ciurma di pirati a bordo della misteriosa nave Perla Nera. Per salvarla, Will si allea con l''eccentrico e stravagante pirata Jack Sparrow, ex capitano della Perla Nera desideroso di vendetta. I due scopriranno che Barbossa e i suoi uomini sono colpiti da una terribile maledizione azteca che li condanna a vivere come non-morti, rivelando il loro vero aspetto di scheletri solo sotto la luce della luna.', 'https://image.tmdb.org/t/p/w500/poHwCZeWzJCShH7tOjg8RIoyjcw.jpg', '2026-09-14T14:11:05.971925', 'Johnny Depp, Orlando Bloom, Keira Knightley, Geoffrey Rush'),
(151, 'Dune - Parte due', 2024, 'Denis Villeneuve', 'Fantascienza, Avventura, Azione', 'Paul Atreides si unisce a Chani e ai Fremen sul sentiero della vendetta contro i cospiratori che hanno distrutto la sua famiglia. Di fronte alla scelta tra l''amore della sua vita e il destino dell''universo conosciuto, Paul intraprende una missione per impedire un futuro terribile che solo lui è in grado di prevedere.', 'https://image.tmdb.org/t/p/w500/6izwz7rsy95ARzTR3poZ8H6c5pp.jpg', '2026-09-29T16:33:43.786172', 'Timothée Chalamet, Zendaya, Rebecca Ferguson, Josh Brolin, Austin Butler, Florence Pugh, Dave Bautista, Christopher Walken, Léa Seydoux, Javier Bardem'),
(155, 'Toy Story 3 - La grande fuga', 2010, 'Lee Unkrich', 'Animazione, Avventura, Commedia, Fantastico', 'Andy, ormai cresciuto, sta per partire per il college. Woody, Buzz e gli altri giocattoli vengono accidentalmente donati a un asilo nido, il Sunnyside, che si rivelerà essere tutt''altro che un paradiso, sotto il controllo del malvagio orsetto Lotso. I giocattoli dovranno pianificare una grande fuga per tornare a casa.', 'https://image.tmdb.org/t/p/w500/AbbXspMOwdvwWZgVN0nabZq03Ec.jpg', '2026-09-30T18:29:06.156918', 'Tom Hanks, Tim Allen, Joan Cusack, Ned Beatty, Don Rickles'),
(156, 'Toy Story 4', 2019, 'Josh Cooley', 'Animazione, Avventura, Commedia, Fantastico', 'Woody, Buzz e il resto della banda vivono felici con la loro nuova bambina, Bonnie. Quando Bonnie crea un nuovo riluttante giocattolo di nome Forky da un cucchiaio-forchetta usa e getta, Woody si assume il compito di proteggerlo. Durante un viaggio di famiglia on-the-road, Woody ritrova la sua vecchia amica Bo Peep, scoprendo una nuova prospettiva su cosa significhi essere un giocattolo.', 'https://image.tmdb.org/t/p/w500/w9kR8qbmQ01HwnvK4alvnQ2ca0L.jpg', '2026-09-30T18:29:34.3281', 'Tom Hanks, Tim Allen, Annie Potts, Tony Hale'),
(157, 'Toy Story 5', 2026, 'Andrew Stanton', 'Animazione, Avventura, Commedia', 'In questo nuovo capitolo della celebre saga Pixar, i giocattoli si trovano ad affrontare una sfida del tutto moderna: la competizione con la tecnologia e i dispositivi elettronici, che catturano sempre di più l''attenzione dei bambini di oggi.', 'https://image.tmdb.org/t/p/w500/sfQtVlIHljToOwYjhe21KPGzZWK.jpg', '2026-09-30T18:29:50.711642', 'Tom Hanks, Tim Allen'),
(122, 'Matrix', 1999, 'Lana Wachowski, Lilly Wachowski', 'Fantascienza, Azione', 'Un programmatore e hacker di nome Neo scopre che la realtà che vive è una simulazione virtuale creata da macchine senzienti, unendosi a un gruppo di ribelli per liberare l''umanità.', 'https://image.tmdb.org/t/p/w500/dXNAPwY7VrqMAo51EKhhCJfaGb5.jpg', '2026-09-18T18:40:18.760253', 'Keanu Reeves, Laurence Fishburne, Carrie-Anne Moss, Hugo Weaving'),
(123, 'Matrix Reloaded', 2003, 'Lana Wachowski, Lilly Wachowski', 'Fantascienza, Azione', 'Mentre l''esercito delle macchine prepara un attacco contro Zion, Neo scopre maggiori dettagli sul suo destino come l''Eletto e affronta una minaccia crescente rappresentata dall''Agente Smith.', 'https://image.tmdb.org/t/p/w500/8xEVAe84zlL9rkfYT6dZXero4KK.jpg', '2026-09-18T18:40:18.899672', 'Keanu Reeves, Laurence Fishburne, Carrie-Anne Moss, Hugo Weaving'),
(124, 'Matrix Revolutions', 2003, 'Lana Wachowski, Lilly Wachowski', 'Fantascienza, Azione', 'L''assedio a Zion raggiunge il culmine mentre Neo stringe un patto con la città delle macchine per fermare l''Agente Smith, divenuto un virus capace di distruggere entrambi i mondi.', 'https://image.tmdb.org/t/p/w500/qEWiBXJGXK28jGBAm8oFKKTB0WD.jpg', '2026-09-18T18:40:19.005755', 'Keanu Reeves, Laurence Fishburne, Carrie-Anne Moss, Hugo Weaving'),
(125, 'Matrix Resurrections', 2021, 'Lana Wachowski', 'Fantascienza, Azione', 'Neo vive una vita ordinaria a San Francisco sotto l''identità di Thomas Anderson, finché non viene risvegliato da un nuovo gruppo di ribelli per liberare Trinity da una versione aggiornata di Matrix.', 'https://image.tmdb.org/t/p/w500/8c4a8kE7PizaGQQnditMmI1xbRp.jpg', '2026-09-18T18:40:19.107857', 'Keanu Reeves, Carrie-Anne Moss, Yahya Abdul-Mateen II, Jonathan Groff'),
(22, 'Il gladiatore invincibile', 1961, 'Antonio Momplet', 'Peplum', 'Il gladiatore Rezius viene inviato in una provincia imperiale per sedare una ribellione, ma scopre che i ribelli stanno lottando contro un tiranno corrotto. Deciderà di schierarsi dalla parte degli oppressi per riportare la giustizia.', 'https://image.tmdb.org/t/p/w500/zela8yXh9bWUBab7911vSLb9OGm.jpg', '2026-09-13T15:01:44.852302', 'Richard Harrison, Isabelle Corey, Livio Lorenzon, Leo Anchóriz, Edoardo Nevola'),
(23, 'Il gladiatore che sfidò l''impero', 1965, 'Domenico Paolella', 'Peplum, Avventura, Storico', 'Durante l''impero di Marco Aurelio, il corrotto senatore Lucio Quintilio trama per impossessarsi di un leggendario tesoro e usurpare il potere. A contrastare i suoi piani diabolici si erge il valoroso gladiatore Marco che, alleatosi con i ribelli e i fedeli all''imperatore, affronterà duri scontri e insidie nell''arena per ristabilire la giustizia e salvare l''impero.', 'https://image.tmdb.org/t/p/w500/keKrpGdwvxRPHOyKPnlrVu5dQiU.jpg', '2026-09-13T15:01:45.162067', 'Peter Lupus, Massimo Serato, Gloria Milland, Piero Lulli, Walter Brandi'),
(141, 'Lo squalo', 1975, 'Steven Spielberg', 'Thriller, Horror, Avventura', 'Un grande squalo bianco terrorizza le acque di una cittadina balneare. Per fermare il predatore, il capo della polizia locale stringe un''alleanza con un giovane biologo marino e un eccentrico cacciatore di squali.', 'https://image.tmdb.org/t/p/w500/lxM6kqilAdpdhqUl2biYp5frUxE.jpg', '2026-09-27T19:10:54.826059', 'Roy Scheider, Robert Shaw, Richard Dreyfuss, Lorraine Gary'),
(113, 'The Cloverfield Paradox', 2018, 'Julius Onah', 'Fantascienza, Horror, Thriller', 'Un gruppo di scienziati a bordo di una stazione spaziale testa un acceleratore di particelle per risolvere una crisi energetica globale, ma si ritrova in una dimensione alternativa.', 'https://image.tmdb.org/t/p/w500/vJi2ExTcWdJR3150VPKqqtdGxsT.jpg', '2026-09-17T16:00:28.606117', 'Gugu Mbatha-Raw, David Oyelowo, Daniel Brühl, Elizabeth Debicki'),
(15, 'Le avventure di Bianca e Bernie', 1977, 'Wolfgang Reitherman, John Lounsbery, Art Stevens', 'Animazione, Avventura, Commedia, Famiglia', 'All''interno delle Nazioni Unite ha sede la Società Internazionale di Salvataggio, un''organizzazione segreta composta da topi da tutto il mondo incaricata di prestare soccorso a chi ne ha bisogno. Quando viene ritrovato un messaggio in bottiglia inviato da Penny, una bambina orfana rapita, la determinata topina ungherese Bianca si offre volontaria per salvarla e sceglie come compagno di viaggio il timido e superstizioso usciere Bernie. I due scoprono che Penny è stata rapita dalla spietata Madame Medusa, intenzionata a usarla per farsi strada nelle strette cavità sotterranee della Baia del Diavolo e recuperare il diamante più grande del mondo, ''L''Occhio del Diavolo''. Con l''aiuto dell''albatros Orville, della libellula Evinrude e degli stravaganti abitanti della palude, Bianca e Bernie affronteranno alligatori e insidie per liberare la bambina.', 'https://image.tmdb.org/t/p/w500/9jpDjrRyvv9Nw0piXOpHHQTfxw9.jpg', '2026-09-13T14:58:31.623317', 'Bob Newhart, Eva Gabor, Geraldine Page, Joe Flynn, Jim Jordan')
INSERT INTO public.films ("id", "titolo", "anno", "regista", "genere", "trama", "poster_url", "creato_il", "attori") VALUES
(37, 'Arancia Meccanica', 1971, 'Stanley Kubrick', 'Drammatico, Fantascienza, Grottesco', 'In una Gran Bretagna distopica e futuristica, il giovane Alex DeLarge è il leader dei Drughi, una banda di criminali dedita ad atti brutali di ''ultraviolenza''. Dopo essere stato arrestato per omicidio e condannato al carcere, Alex accetta di sottoporsi alla ''Cura Ludovico'', un innovativo e controverso trattamento di condizionamento psicologico promosso dal governo. Il trattamento lo rende fisicamente incapace di compiere o persino di pensare ad azioni violente, ma al contempo lo priva del suo libero arbitrio, lasciandolo del tutto indifeso di fronte alla società e alla vendetta delle sue vecchie vittime.', 'https://image.tmdb.org/t/p/w500/4sHeTAp65WrSSuc05nRBKddhBxO.jpg', '2026-09-13T15:23:44.98867', 'Malcolm McDowell, Patrick Magee, Michael Bates, Warren Clarke'),
(126, 'Il buono, il brutto, il cattivo', 1966, 'Sergio Leone', 'Western', 'Durante la guerra di secessione americana, tre cinici fuorilegge - il ''Buono'' (Joe), il ''Brutto'' (Tuco) e il ''Cattivo'' (Sentenza) - cercano un tesoro nascosto contenente 200.000 dollari in oro confederato, muovendosi tra alleanze precarie, inganni e scontri mortali.', 'https://image.tmdb.org/t/p/w500/bX2xnavhMYjWDoZp1VM6VnU1xwe.jpg', '2026-09-18T18:50:54.001858', 'Clint Eastwood, Eli Wallach, Lee Van Cleef'),
(82, 'Mai dire mai', 1983, 'Irvin Kershner', 'Azione, Spionaggio, Avventura, Thriller', 'James Bond, ormai vicino all''età pensionabile e mandato in una clinica per rimettersi in forma, scopre una cospirazione ordita dall''organizzazione criminale SPECTRE. Guidato dal malvagio Maximilian Largo sotto gli ordini di Ernst Stavro Blofeld, il gruppo riesce a rubare due testate nucleari cruise della NATO per ricattare il mondo. L''agente 007 viene richiamato in servizio d''urgenza da M e si mette sulle tracce delle armi, scontrandosi con la letale assassina Fatima Blush e cercando di conquistare la fiducia della bellissima Domino Petachi, amante di Largo, per sventare l''olocausto nucleare.', 'https://image.tmdb.org/t/p/w500/zhoAL4o1STGgLbLxJ9r1ijfyHC9.jpg', '2026-09-15T19:25:47.259973', 'Sean Connery, Klaus Maria Brandauer, Kim Basinger, Barbara Carrera, Max von Sydow'),
(18, 'La nave bianca', 1941, 'Roberto Rossellini', 'Drammatico, Guerra', 'Durante la seconda guerra mondiale, un giovane marinaio imbarcato su una nave da guerra italiana rimane ferito all''addome durante uno scontro navale nel Mediterraneo. Dopo essere stato operato d''urgenza a bordo, viene trasferito sulla nave ospedale ''Arno'' (la nave bianca del titolo) per le cure successive. A bordo della nave troverà assistenza e conforto grazie alle cure di un''infermiera volontaria della Croce Rossa, la quale scoprirà essere proprio la ragazza con cui il giovane intratteneva una romantica corrispondenza epistolare senza averla mai incontrata prima.', 'https://image.tmdb.org/t/p/w500/8NdHt1zvhy249pOMbK9aiw8IHvp.jpg', '2026-09-13T14:58:32.748006', 'Augusto Basso, Equipaggio della Regia Marina'),
(148, 'Master & Commander - Sfida ai confini del mare', 2003, 'Peter Weir', 'Avventura, Azione, Storico, Drammatico', 'Durante le guerre napoleoniche, la fregata britannica HMS Surprise, guidata dal carismatico capitano Jack Aubrey, riceve l''ordine di intercettare e catturare la nave corsara francese Acheron. Dopo un devastante attacco a sorpresa da parte di quest''ultima, Aubrey decide di inseguire il nemico attraverso gli oceani, spingendosi fino a Capo Horn e alle isole Galápagos, in una caccia ossessiva che metterà a dura prova la lealtà e la sopravvivenza del suo equipaggio.', 'https://image.tmdb.org/t/p/w500/7ZUHF6P0vcA5v1Gm8NbRYyd9w4N.jpg', '2026-09-29T15:09:03.31573', 'Russell Crowe, Paul Bettany, James D''Arcy, Edward Woodall, Chris Larkin'),
(61, 'Pirati dei Caraibi - La vendetta di Salazar', 2017, 'Joachim Rønning, Espen Sandberg', 'Avventura, Fantastico, Azione, Commedia', 'Il capitano Jack Sparrow si ritrova al centro di una nuova e mortale caccia quando il terrificante capitano Armando Salazar e la sua ciurma di marinai fantasma fuggono dal Triangolo del Diavolo, decisi a sterminare tutti i pirati dei sette mari e a vendicarsi proprio di Jack. L''unica speranza di salvezza per Sparrow risiede nel leggendario Tridente di Poseidone, un potente artefatto capace di conferire il controllo totale sui mari e spezzare ogni maledizione. Per trovarlo, Jack stringe un''alleanza con Henry Turner, un giovane marinaio della Royal Navy intenzionato a liberare suo padre Will dalla maledizione dell''Olandese Volante, e Carina Smyth, una brillante e coraggiosa astronoma ingiustamente accusata di stregoneria.', 'https://image.tmdb.org/t/p/w500/6lAPOAFYFWIO3SQRemEY2wInQMC.jpg', '2026-09-14T14:11:06.775662', 'Johnny Depp, Javier Bardem, Geoffrey Rush, Brenton Thwaites, Kaya Scodelario, Kevin McNally'),
(58, 'Pirati dei Caraibi - La maledizione del forziere fantasma', 2006, 'Gore Verbinski', 'Avventura, Azione, Fantastico', 'Il capitano Jack Sparrow scopre di avere un debito di sangue con il temibile Davy Jones, sovrano degli abissi e capitano del fantasmagorico Olandese Volante. Se non riuscirà a trovare una via d''uscita, Jack sarà condannato alla servitù eterna nell''equipaggio dei dannati. Per salvarsi, Jack deve rintracciare il leggendario forziere fantasma, contenente il cuore pulsante di Jones, l''unica debolezza del capitano dei mari. Nel frattempo, il matrimonio di Will Turner ed Elizabeth Swann viene interrotto dall''arresto da parte della Compagnia delle Indie Orientali guidata da Lord Cutler Beckett, il quale ricatta Will affinché rintracci Sparrow e si impossessi della sua bussola magica. I destini dei tre protagonisti si intrecciano nuovamente in una pericolosa caccia al tesoro, minacciata dalla mostruosa creatura marina al servizio di Jones: il Kraken.', 'https://image.tmdb.org/t/p/w500/uXEqmloGyP7UXAiphJUu2v2pcuE.jpg', '2026-09-14T14:11:06.153625', 'Johnny Depp, Orlando Bloom, Keira Knightley, Bill Nighy, Jack Davenport, Stellan Skarsgård'),
(142, 'Lo squalo 2', 1978, 'Jeannot Szwarc', 'Thriller, Horror, Avventura', 'Quattro anni dopo i tragici eventi dell''isola di Amity, la cittadina cerca di tornare alla normalità. Tuttavia, quando iniziano a verificarsi nuove e misteriose sparizioni in acqua, il capo della polizia Martin Brody si convince che un altro grande squalo bianco stia terrorizzando la zona. Nonostante lo scetticismo delle autorità locali, Brody dovrà agire in fretta per salvare un gruppo di giovani velisti, tra cui i suoi stessi figli, finiti nel mirino del predatore.', 'https://image.tmdb.org/t/p/w500/cN3ijEwsn4kBaRuHfcJpAQJbeWe.jpg', '2026-09-27T19:21:15.792586', 'Roy Scheider, Lorraine Gary, Murray Hamilton, Joseph Mascolo'),
(144, 'Bastardi senza gloria', 2009, 'Quentin Tarantino', 'Guerra, Drammatico, Azione', 'Nella Francia occupata dai nazisti durante la seconda guerra mondiale, un gruppo di soldati ebrei americani guidati dal tenente Aldo Raine, noti come ''I Bastardi'', viene paracadutato per seminare il terrore tra le truppe tedesche. Le loro strade si incroceranno con quelle di Shosanna Dreyfus, una giovane ebrea sopravvissuta all''eccidio della sua famiglia per mano del spietato colonnello SS Hans Landa, che pianifica una clamorosa vendetta all''interno del proprio cinema a Parigi.', 'https://image.tmdb.org/t/p/w500/aupnPtagH9JVBuMrGEanf4iqXEQ.jpg', '2026-09-28T08:43:56.799523', 'Brad Pitt, Christoph Waltz, Mélanie Laurent, Diane Kruger, Michael Fassbender, Eli Roth, Daniel Brühl'),
(24, 'I sette gladiatori', 1962, 'Pedro Lazaga', 'Peplum, Avventura, Storico', 'Marcus, un valoroso gladiatore, fugge da Roma per fare ritorno a Sparta, la sua terra natale. Al suo arrivo scopre che il suo popolo è sottomesso alla tirannia di un governatore spietato. Per liberare la sua gente, Marcus decide di reclutare altri sei abili e forti gladiatori, unendo le forze per guidare una rivolta contro l''oppressore.', 'https://image.tmdb.org/t/p/w500/jAQg4h3AhSgOH3jLRlcRCzagFXW.jpg', '2026-09-13T15:01:45.454339', 'Richard Harrison, Loredana Nusciak, Livio Lorenzon, Gérard Tichy'),
(128, 'Giù la testa', 1971, 'Sergio Leone', 'Western / Storico', 'Durante la rivoluzione messicana, un ingenuo bandito locale e un tormentato dinamitardo irlandese uniscono le forze in una serie di rapine che si trasformeranno in gesta eroiche.', 'https://image.tmdb.org/t/p/w500/nWmAtZf83qpOai0fzehf7Hn1S3R.jpg', '2026-09-18T18:57:49.329857', 'Rod Steiger, James Coburn, Romolo Valli'),
(152, 'Poseidon', 2006, 'Wolfgang Petersen', 'Azione, Avventura, Catastrofico', 'Durante la notte di Capodanno, una gigantesca onda anomala travolge e capovolge la lussuosa nave da crociera Poseidon. Un piccolo gruppo di sopravvissuti decide di non aspettare i soccorsi e tenta una disperata fuga verso la salvezza attraverso lo scafo capovolto.', 'https://image.tmdb.org/t/p/w500/fDPdjGc8SUEDWfTwMaZlCE6NSi3.jpg', '2026-09-30T13:28:17.9258', 'Josh Lucas, Kurt Russell, Jacinda Barrett, Richard Dreyfuss, Emmy Rossum'),
(127, 'C''era una volta il West', 1968, 'Sergio Leone', 'Western', 'Una giovane vedova difende la propria terra dalle mire di un magnate delle ferrovie, aiutata da un misterioso uomo con l''armonica e da un fuorilegge romantico.', 'https://image.tmdb.org/t/p/w500/qbYgqOczabWNn2XKwgMtVrntD6P.jpg', '2026-09-18T18:57:49.249802', 'Claudia Cardinale, Henry Fonda, Charles Bronson, Jason Robards'),
(129, 'C''era una volta in America', 1984, 'Sergio Leone', 'Drammatico / Noir', 'La complessa epopea di un gruppo di gangster ebrei a New York, dall''infanzia nel ghetto negli anni ''20 fino al drammatico bilancio esistenziale negli anni ''60.', 'https://image.tmdb.org/t/p/w500/i0enkzsL5dPeneWnjl1fCWm6L7k.jpg', '2026-09-18T18:57:49.435519', 'Robert De Niro, James Woods, Elizabeth McGovern, Joe Pesci'),
(8, 'Il Padrino - Parte III', 1990, 'Francis Ford Coppola', 'Drammatico, Poliziesco', 'Ormai anziano e tormentato dai sensi di colpa per i crimini del passato, in particolare per l''omicidio del fratello Fredo, Michael Corleone cerca di legalizzare le attività della famiglia e di ripulire il proprio nome attraverso una colossale donazione alla Chiesa Cattolica. Mentre tenta di districarsi dalle trame di potere e corruzione all''interno del Vaticano, Michael deve anche gestire la successione dinastica, designando come suo erede l''irrequieto e violento nipote Vincent Mancini, figlio naturale di suo fratello Sonny.', 'https://image.tmdb.org/t/p/w500/lm3pQ2QoQ16pextRsmnUbG2onES.jpg', '2026-09-13T14:48:18.540802', 'Al Pacino, Andy García, Diane Keaton, Talia Shire, Sofia Coppola, Eli Wallach, Joe Mantegna'),
(7, 'Il Padrino - Parte II', 1974, 'Francis Ford Coppola', 'Drammatico, Poliziesco', 'Il film sviluppa due linee narrative parallele: da un lato segue la giovinezza di Vito Corleone, dalla fuga dalla Sicilia ai primi del Novecento fino alla sua ascesa come ''Padrino'' a New York; dall''altro racconta le vicende del figlio Michael negli anni ''50, intenzionato ad espandere l''impero di famiglia a Las Vegas e a Cuba, affrontando tradimenti interni, indagini governative e una progressiva disgregazione morale e familiare.', 'https://image.tmdb.org/t/p/w500/8a1lJs7mFyGhGhZZDT1azJUoQiZ.jpg', '2026-09-13T14:48:18.23254', 'Al Pacino, Robert De Niro, Robert Duvall, Diane Keaton, John Cazale, Talia Shire'),
(130, 'Love Happens - Qualcosa di speciale (noto anche come Brand New Day)', 2009, 'Brandon Camp', 'Drammatico, Sentimentale', 'Un autore di bestseller sul superamento del lutto, rimasto vedovo, tiene un seminario a Seattle. Qui incontra una fiorista disillusa dall''amore, che lo costringerà a fare i conti con il fatto che non ha ancora realmente superato la morte della moglie.', 'https://image.tmdb.org/t/p/w500/ijRJlhAZ7QMkTIVAUkIY8stWfk1.jpg', '2026-09-19T18:03:10.842143', 'Aaron Eckhart, Jennifer Aniston, Dan Fogler, Martin Sheen, Judy Greer'),
(17, 'Bianca come il latte, rossa come il sangue', 2013, 'Giacomo Campiotti', 'Drammatico, Romantico', 'Leo è un sedicenne che vive la scuola e la vita con passione, associando le sue emozioni ai colori: il bianco rappresenta il vuoto e la paura, mentre il rosso è il colore dell''amore e della passione per Beatrice, la ragazza di cui è innamorato. Quando scopre che Beatrice è gravemente malata di leucemia, il mondo di Leo crolla. Nel tentativo di aiutarla e di farla sorridere, il ragazzo intraprende un percorso di crescita personale affrontando la sofferenza, sostenuto dall''amica di sempre Silvia e da un professore di filosofia che lo stimola a trovare il proprio posto nel mondo.', 'https://image.tmdb.org/t/p/w500/eZQFj0tgsErtr6CcIkyLFXGNBGa.jpg', '2026-09-13T14:58:32.437498', 'Filippo Scicchitano, Aurora Ruffino, Gaia Weiss, Luca Argentero'),
(20, 'Gladiator', 1992, 'Rowdy Herrington', 'Drammatico', 'Un giovane di Chicago si trasferisce in un quartiere difficile e si ritrova coinvolto nel giro delle scommesse clandestine di pugilato per saldare i debiti del padre. Per uscire dal tunnel dovrà affrontare sul ring il suo amico più caro e un promotore privo di scrupoli.', 'https://image.tmdb.org/t/p/w500/w0YjBWVfu689txEXZG3xa4Aev3i.jpg', '2026-09-13T15:01:44.238371', 'James Marshall, T.E. Russell, Cuba Gooding Jr., Robert Loggia, Brian Dennehy'),
(134, 'Rocky III', 1982, 'Sylvester Stallone', 'Drammatico, Sportivo', 'Rocky Balboa, ormai campione del mondo dei pesi massimi e ricco, perde il titolo contro il brutale sfidante Clubber Lang e subisce la dolorosa perdita del suo storico allenatore Mickey. Sarà l''ex rivale Apollo Creed ad aiutarlo a ritrovare la "fame" e lo "sguardo della tigre" per prepararsi alla rivincita.', 'https://image.tmdb.org/t/p/w500/uqw16i2kmwVqkJHzjzbDU4xZ0Pl.jpg', '2026-09-19T22:19:08.502985', 'Sylvester Stallone, Talia Shire, Burt Young, Carl Weathers, Burgess Meredith, Mr. T, Hulk Hogan'),
(137, 'Ronin', 1998, 'John Frankenheimer', 'Azione, Thriller', 'Un gruppo di ex agenti segreti e mercenari provenienti da diversi paesi viene ingaggiato a Parigi per recuperare una misteriosa e pesantemente custodita valigetta. Tra tradimenti, doppi giochi e mozzafiato inseguimenti automobilistici, la squadra dovrà scoprire di chi potersi davvero fidare.', 'https://image.tmdb.org/t/p/w500/AirrhRJjHwytOV0pdLu7YZ4DEyr.jpg', '2026-09-25T20:39:37.027542', 'Robert De Niro, Jean Reno, Natascha McElhone, Stellan Skarsgård, Sean Bean, Jonathan Pryce'),
(21, 'Gladiatori di Roma', 2012, 'Iginio Straffi', 'Animazione', 'Rimasto orfano dopo l''eruzione di Pompei, il piccolo Timo viene adottato dal generale Chirone e cresciuto nell''accademia di gladiatori più famosa di Roma. Senza alcuna passione per il combattimento, dovrà trasformarsi in un vero eroe per conquistare il cuore della bella Lucilla.', 'https://image.tmdb.org/t/p/w500/9Qyx97TwsPQ1uR82wwQ2dzY0wOU.jpg', '2026-09-13T15:01:44.534361', 'Luca Argentero, Laura Chiatti, Belén Rodríguez, Massimo Corvo, Fabrizio De Flaviis'),
(10, 'Indiana Jones e il tempio maledetto', 1984, 'Steven Spielberg', 'Avventura, Azione', 'Nel 1935, l''archeologo Indiana Jones sfugge a un agguato della malavita a Shanghai e si ritrova precipitato in India insieme alla cantante Willie Scott e al piccolo Short Round. Raggiunto un povero villaggio oppresso dalla sfortuna, accetta di aiutare gli abitanti a recuperare una pietra sacra Sankara rubata e a liberare tutti i bambini rapiti. La sua missione lo porterà al palazzo di Pankot, nascondiglio della spietata setta dei Thuggee, dedita a sacrifici umani e al culto della dea Kali.', 'https://image.tmdb.org/t/p/w500/gpdVNUaa4LhRMLfJOPj1AZdhAZ3.jpg', '2026-09-13T14:53:50.633983', 'Harrison Ford, Kate Capshaw, Ke Huy Quan, Amrish Puri, Roshan Seth'),
(14, 'Bianca', 1984, 'Nanni Moretti', 'Commedia, Drammatico, Grottesco', 'Michele Apicella, un giovane e nevrotico professore di matematica con numerose manie ossessive, viene assunto presso l''atipico liceo sperimentale ''Marilyn Monroe''. Michele tende a spiare e giudicare la vita dei suoi vicini e amici, cercando una perfezione ideale nei rapporti umani. Quando inizia una storia d''amore con la nuova collega di francese, Bianca, la sua stabilità mentale viene messa a dura prova. Contemporaneamente, un commissario di polizia indaga su una serie di misteriosi omicidi che colpiscono le persone vicine a Michele.', 'https://image.tmdb.org/t/p/w500/lnXZLkJ3MFgAFAiyVJGfTUykNkU.jpg', '2026-09-13T14:58:31.211468', 'Nanni Moretti, Laura Morante, Roberto Vezzosi, Dario Cantarelli, Vincenzo Salemme'),
(28, 'Il gladiatore di Roma', 1962, 'Mario Costa', 'Peplum', 'Nell''antica Roma sotto Caracalla, la giovane erede al trono di Cilicia viene protetta da uno schiavo gladiatore che difenderà la sua vita dai traditori e dai pretendenti al trono.', 'https://image.tmdb.org/t/p/w500/bnYYCgn7hBtV6Xq4PF8GttGMvI3.jpg', '2026-09-13T15:01:46.694395', 'Gordon Scott, Wandisa Guida, Roberto Risso, Eleonora Vargas, Ombretta Colli'),
(27, 'Spartacus e i 10 gladiatori', 1964, 'Nick Nostro', 'Peplum', 'Dieci gladiatori inviati per dare la caccia al ribelle Spartacus scoprono la nobiltà della sua causa. Decideranno di unire le forze con gli schiavi in rivolta contro le legioni romane.', 'https://image.tmdb.org/t/p/w500/gZsGyRcXRCICiSlnBfyH5SecIad.jpg', '2026-09-13T15:01:46.378904', 'Dan Vadis, Helga Liné, Ursula Davis, Giovanni Di Benedetto, Giovanni Vari'),
(45, 'Agente 007 - Missione Goldfinger', 1964, 'Guy Hamilton', 'Azione, Spionaggio, Avventura', 'L''agente segreto James Bond viene incaricato di indagare sui loschi affari di Auric Goldfinger, un magnate ossessionato dal metallo prezioso. Bond scopre un diabolico piano denominato ''Operazione Grand Slam'': Goldfinger intende far esplodere una bomba atomica all''interno del deposito aureo di Fort Knox per contaminare l''oro degli Stati Uniti e far schizzare alle stelle il valore del proprio monopolio. Tra insidiosi nemici come il letale scagnozzo Oddjob e l''affascinante pilota Pussy Galore, 007 dovrà fare di tutto per sventare il catastrofico piano.', 'https://image.tmdb.org/t/p/w500/aKNFzaqQgPzsGXnsMc4kJH5hFIV.jpg', '2026-09-14T13:48:36.347752', 'Sean Connery, Honor Blackman, Gert Fröbe, Shirley Eaton, Bernard Lee'),
(34, 'Il Signore degli Anelli - Le due torri', 2002, 'Peter Jackson', 'Fantasy', 'La Compagnia si è divisa: Frodo e Sam proseguono verso Mordor guidati dalla subdola creatura Gollum, mentre Aragorn, Legolas e Gimli accorrono in aiuto del regno di Rohan. Insieme dovranno affrontare le schiere oscure di Saruman nella leggendaria battaglia del Fosso di Helm.', 'https://image.tmdb.org/t/p/w500/5VTN0pR8gcqV3EPUHHfMGnJYN9L.jpg', '2026-09-13T15:13:21.973278', 'Christopher Guard, William Squire, Michael Scholes, John Hurt, Simon Chandler'),
(32, 'Il gladiatore II', 2024, 'Ridley Scott', 'Azione, Drammatico, Storico, Avventura', 'Anni dopo aver assistito alla tragica morte del venerato eroe Massimo Decimo Meridio per mano del suo perfido zio, Lucio si ritrova costretto a fare il suo ingresso nel Colosseo. La sua patria è stata infatti conquistata dai tirannici imperatori che ora governano Roma con il pugno di ferro. Con la rabbia nel cuore e il destino dell''Impero in bilico, Lucio deve scavare nel proprio passato per trovare la forza e l''orgoglio necessari a restituire la gloria di Roma al suo popolo.', 'https://image.tmdb.org/t/p/w500/2cxhvwyEwRlysAmRH4iodkvo0z5.jpg', '2026-09-13T15:10:37.320908', 'Paul Mescal, Pedro Pascal, Denzel Washington, Connie Nielsen, Joseph Quinn, Fred Hechinger'),
(29, 'Ursus il gladiatore ribelle', 1962, 'Domenico Paolella', 'Peplum', 'Ursus accetta di combattere come gladiatore per salvare la vita della donna che ama, prigioniera di un governatore crudele. La sua forza sovrumana scatenerà una rivolta nell''arena.', 'https://image.tmdb.org/t/p/w500/hfsSMECtejxQOwJkzE1WjKqMWUw.jpg', '2026-09-13T15:01:46.997779', 'Dan Vadis, Gloria Milland, José Greci, Sergio Ciani, Andrea Aureli'),
(35, 'Il Signore degli Anelli - Il ritorno del re', 2003, 'Peter Jackson', 'Fantasy', 'L''epico scontro finale per la salvaguardia della Terra di Mezzo ha inizio. Mentre Aragorn reclami il suo trono e conduce l''esercito dei popoli liberi ai Cancelli Nero per distrarre le armate oscure, Frodo e Sam affrontano il massacrante tratto finale del viaggio verso il Monte Fato.', 'https://image.tmdb.org/t/p/w500/rCzpDGLbOoPwLjy3OAm5NUPOTrC.jpg', '2026-09-13T15:13:22.217261', 'Elijah Wood, Ian McKellen, Viggo Mortensen, Sean Astin, Andy Serkis'),
(36, 'Il Signore degli Anelli', 1978, 'Ralph Bakshi', 'Animazione', 'Adattamento animato classico realizzato tramite la tecnica del rotoscopio che ripercorre le vicende della Compagnia dell''Anello. Frodo e i suoi compagni intraprendono un lungo viaggio per sconfiggere l''oscurità che minaccia la Terra di Mezzo.', 'https://image.tmdb.org/t/p/w500/liW0mjvTyLs7UCumaHhx3PpU4VT.jpg', '2026-09-13T15:13:22.520759', 'Christopher Guard, William Squire, Michael Scholes, John Hurt, Simon Chandler'),
(33, 'Il Signore degli Anelli - La Compagnia dell''Anello', 2001, 'Peter Jackson', 'Fantasy', 'Un giovane hobbit di nome Frodo Baggins eredita un anello magico di inestimabile potere dal suo zio Bilbo. Per evitare che il Signore Oscuro Sauron lo riconquisti e sottometta la Terra di Mezzo, Frodo deve intraprendere un periglioso viaggio verso il Monte Fato insieme a una variegata compagnia di eroi.', 'https://image.tmdb.org/t/p/w500/6oom5QYQ2yQTMJIbnvbkBL9cHo6.jpg', '2026-09-13T15:13:21.613148', 'Christopher Guard, William Squire, Michael Scholes, John Hurt, Simon Chandler'),
(46, 'Casino', 1995, 'Martin Scorsese', 'Crime / Drammatico', 'Sam ''Ace'' Rothstein viene incaricato dalla mafia di gestire il casinò Tangiers a Las Vegas negli anni ''70. La sua gestione efficace viene però minacciata dall''amico d''infanzia e gangster Nikki Santoro e dalla tempestosa relazione con la moglie Ginger. Tra cupidigia, inganni e declino dell''impero mafioso, la storia ripercorre l''ascesa e la caduta dei boss nella capitale del gioco d''azzardo.', 'https://image.tmdb.org/t/p/w500/gziIkUSnYuj9ChCi8qOu2ZunpSC.jpg', '2026-09-14T13:49:13.384199', 'Robert De Niro, Sharon Stone, Joe Pesci, James Woods, Don Rickles'),
(25, 'L''ultimo gladiatore', 1964, 'Umberto Lenzi', 'Peplum, Storico, Avventura', 'Nell''antica Roma, oppressa dalla follia e dal dispotismo dell''imperatore Caligola, il valoroso gladiatore Cassio Cherone decide di ribellarsi alla tirannia. Coinvolto negli intrighi di palazzo e nelle congiure senatorie, Cassio affronta pericoli nell''arena e scontri mortali, lottando per rovesciare il sovrano crudele, proteggere la donna che ama e restituire dignità e pace al popolo romano.', 'https://image.tmdb.org/t/p/w500/lSpPctLSS2F0W4XgQCzTWrtEMl9.jpg', '2026-09-13T15:01:45.76594', 'Richard Harrison, Marilù Tolo, Philippe Hersent, Livio Lorenzon, Lisa Gastoni, Gianni Solaro'),
(26, 'Il magnifico gladiatore', 1964, 'Alfonso Brescia', 'Peplum', 'Attalo, gladiatore da tutti stimato, si trova vittima degli intrighi di palazzo dell''imperatore Gallieno. Dovrà far valere il suo valore sia nell''arena che contro i cospiratori politicamente corrotti.', 'https://image.tmdb.org/t/p/w500/7iJtohz1AiSKaV8uOp23smvnO3J.jpg', '2026-09-13T15:01:46.066865', 'Mark Forest, Marilù Tolo, Paolo Gozlino, Jolanda Modio, Franco Cobianchi'),
(48, 'Sátántangó', 1994, 'Béla Tarr', 'Drammatico', 'In un desolate e piovoso villaggio ungherese dopo la chiusura di una fattoria collettiva, gli abitanti vivono nell''apatia e nel sospetto reciproco. Il presunto ritorno del carismatico Irimiás, ritenuto morto da tutti, riaccende una labile speranza che si trasforma presto in una complessa danza di manipolazione e inganno.', 'https://image.tmdb.org/t/p/w500/y38z0v4HJ12MHiKddLEoFlvPiBt.jpg', '2026-09-14T13:49:44.315657', 'Mihály Víg, Putyi Horváth, Székely B. Miklós, Erika Bók, László feLugossy'),
(62, 'The Wolf of Wall Street', 2013, 'Martin Scorsese', 'Biografico / Drammatico / Commedia', 'Jordan Belfort è un giovane e ambizioso broker di New York che fonda la Stratton Oakmont, diventando rapidamente milionario grazie a truffe e speculazioni finanziarie spregiudicate. Immerso in un vortice di edonismo, droga e avidità sfrenata, la sua vita di eccessi attira presto l''attenzione dell''FBI. La sua inarrestabile ascesa nel mondo della finanza rischia così di trasformarsi in una rovinosa e inevitabile caduta.', 'https://image.tmdb.org/t/p/w500/kW9LmvYHAaS9iA0tHmZVq8hQYoq.jpg', '2026-09-15T17:10:35.932269', 'Leonardo DiCaprio, Jonah Hill, Margot Robbie, Matthew McConaughey, Kyle Chandler'),
(53, 'Highlander: Endgame', 2000, 'Douglas Aarniokoski', 'Azione / Fantastico', 'Duncan MacLeod e suo cugino Connor uniscono le forze per affrontare Jacob Kell, un malvagio immortale che ha accumulato un potere immenso eliminando centinaia di rivali nel corso dei secoli. Per sconfiggere un nemico apparentemente invincibile, i due guerrieri scozzesi dovranno affrontare il proprio passato e compiere la scelta più difficile della loro vita.', 'https://image.tmdb.org/t/p/w500/8Z8dptJEypuLoOQro1WugD855YE.jpg', '2026-09-14T13:51:54.04989', 'Christopher Lambert, Roxanne Hart, Clancy Brown, Sean Connery, Beatie Edney'),
(52, 'Avengers: Endgame', 2019, 'Anthony Russo, Joe Russo', 'Azione, Avventura, Fantascienza', 'Dopo gli eventi devastanti di Avengers: Infinity War, l''universo è in rovina a causa delle azioni di Thanos. Con l''aiuto degli alleati rimasti, gli Avengers superstiti si riuniscono ancora una volta per annullare le azioni del Titano Pazzo. Attraverso un rischioso viaggio nel tempo nel Regno Quantico, il gruppo tenta di recuperare le Gemme dell''Infinito nel passato per riportare in vita tutti coloro che sono scomparsi e ripristinare l''ordine nell''universo.', 'https://image.tmdb.org/t/p/w500/bR8ISy1O9XQxqiy0fQFw2BX72RQ.jpg', '2026-09-14T13:51:52.958142', 'Robert Downey Jr., Chris Evans, Mark Ruffalo, Chris Hemsworth, Scarlett Johansson, Jeremy Renner, Paul Rudd, Josh Brolin'),
(55, 'Rocky IV', 1985, 'Sylvester Stallone', 'Drammatico, Sportivo, Azione', 'Rocky Balboa accompagna l''amico fraterno ed ex rivale Apollo Creed in un match di esibizione contro il temibile e glaciale pugile sovietico Ivan Drago. Quando Apollo muore tragicamente sul ring a causa dei colpi brutali di Drago, Rocky decide di vendicare l''amico sfidando il gigante russo a Mosca il giorno di Natale. Per prepararsi, Rocky si sottopone a un durissimo allenamento tra i ghiacci della Siberia, culminando in uno scontro epico che va oltre lo sport, diventando un simbolo della Guerra Fredda.', 'https://image.tmdb.org/t/p/w500/2MHUit4H6OK5adcOjnCN6suCKOl.jpg', '2026-09-14T13:53:58.395769', 'Sylvester Stallone, Talia Shire, Burt Young, Carl Weathers, Brigitte Nielsen, Dolph Lundgren'),
(66, 'Robin Hood - Principe dei ladri', 1991, 'Kevin Reynolds', 'Avventura, Azione, Drammatico', 'Robin di Locksley ritorna in Inghilterra dopo essere fuggito dalla prigionia a Gerusalemme durante le Crociate. Trova la sua terra natale oppressa dal tirannico Sceriffo di Nottingham, che ha fatto assassinare suo padre. Rifugiatosi nella foresta di Sherwood, Robin si unisce a una banda di fuorileggi e, affiancato dal fedele amico saraceno Azeem, assume la guida della ribellione per sconfiggere lo Sceriffo, salvare la bella Lady Marian e restituire la giustizia al popolo oppresso.', 'https://image.tmdb.org/t/p/w500/hbRnWUNJkKKVN5mkcuC5ooqjE4e.jpg', '2026-09-15T18:04:05.742081', 'Kevin Costner, Morgan Freeman, Alan Rickman, Mary Elizabeth Mastrantonio, Christian Slater'),
(60, 'Pirati dei Caraibi - Oltre i confini del mare', 2011, 'Rob Marshall', 'Avventura, Azione, Fantastico', 'Jack Sparrow incontra Angelica, una donna del suo passato che lo costringe a imbarcarsi sulla Queen Anne''s Revenge, la nave del temibile pirata Barbanera. Jack si ritrova così coinvolto in una pericolosa ricerca della leggendaria Fonte della Giovinezza, dovendo fare i conti con spietate sirene, zombie e la flotta rivale spagnola e inglese guidata da Barbossa, ora al servizio del Re.', 'https://image.tmdb.org/t/p/w500/keGfSvCmYj7CvdRx36OdVrAEibE.jpg', '2026-09-14T14:11:06.59801', 'Johnny Depp, Penélope Cruz, Ian McShane, Geoffrey Rush, Kevin McNally'),
(64, 'La leggenda di Robin Hood', 1938, 'Michael Curtiz, William Keighley', 'Avventura, Azione, Romantico', 'Robin di Locksley, un nobile sassone, si ribella contro l''usurpatore Principe Giovanni, che ha preso il controllo dell''Inghilterra approfittando della prigionia di Re Riccardo Cuor di Leone. Rifugiatosi nella foresta di Sherwood con una banda di fuorilegge, Robin ruba ai ricchi normanni per dare ai poveri sassoni oppressi, conquistando anche il cuore di Lady Marian e lottando per il ritorno del legittimo sovrano.', 'https://image.tmdb.org/t/p/w500/c7LX3GMf9uXQTgVm3uxpm7E6Woc.jpg', '2026-09-15T18:04:05.337906', 'Errol Flynn, Olivia de Havilland, Basil Rathbone, Claude Rains'),
(54, 'Rocky', 1976, 'John G. Avildsen', 'Drammatico, Sportivo', 'Rocky Balboa, un pugile di poco conto di Filadelfia che vive riscuotendo crediti per un usuraio locale, ottiene una straordinaria ed inaspettata occasione: sfidare il campione del mondo dei pesi massimi, Apollo Creed. Con il duro allenamento dell''anziano Mickey e il supporto dell''amata Adriana, Rocky cercherà di riscattare la propria vita e dimostrare di non essere solo un fantoccio sul ring.', 'https://image.tmdb.org/t/p/w500/xSI0dbKLDETwhiVUy6hGE8KXUln.jpg', '2026-09-14T13:53:57.043684', 'Sylvester Stallone, Talia Shire, Burt Young, Carl Weathers, Burgess Meredith'),
(59, 'Pirati dei Caraibi - Ai confini del mondo', 2007, 'Gore Verbinski', 'Avventura, Azione, Fantastico', 'Il capitano Barbossa, Will Turner e Elizabeth Swann si alleano per liberare Jack Sparrow dalla prigionia nello Scrigno di Davy Jones. Nel frattempo, la Compagnia delle Indie Orientali, guidata da Lord Cutler Beckett e con il controllo dell''Olandese Volante, minaccia di eliminare per sempre la pirateria dai mari.', 'https://image.tmdb.org/t/p/w500/jGWpG4YhpQwVmjyHEGkxEkeRf0S.jpg', '2026-09-14T14:11:06.373565', 'Johnny Depp, Orlando Bloom, Keira Knightley, Geoffrey Rush, Chow Yun-fat, Bill Nighy'),
(86, 'Rambo', 1982, 'Ted Kotcheff', 'Azione', 'John Rambo, un reduce della guerra del Vietnam psicologicamente segnato, arriva in una piccola città alla ricerca di un vecchio amico. Ingiustamente perseguitato dallo sceriffo locale, Rambo si rifugia nei boschi scatenando una caccia all''uomo senza tregua.', 'https://image.tmdb.org/t/p/w500/a9sa6ERZCpplbPEO7OMWE763CLD.jpg', '2026-09-16T10:28:13.415074', 'Sylvester Stallone, Brian Dennehy, Richard Crenna'),
(2, 'Il Gladiatore', 2000, 'Ridley Scott', 'Storico, Azione, Drammatico', 'Il generale romano Massimo Decimo Meridio viene tradito dal perfido Commodo, figlio dell''imperatore Marco Aurelio, che usurpa il trono e fa sterminare la famiglia di Massimo. Catturato e ridotto in schiavitù, Massimo viene addestrato come gladiatore dal lanista Prossimo. La sua straordinaria abilità nell''arena lo condurrà fino al Colosseo a Roma, dove cercherà la sua vendetta contro il nuovo imperatore.', 'https://image.tmdb.org/t/p/w500/wN2xWp1eIwCKOD0BHTcErTBv1Uq.jpg', '2026-09-13T14:42:52.023756', 'Russell Crowe, Joaquin Phoenix, Connie Nielsen, Oliver Reed, Richard Harris'),
(68, 'Robin Hood - L''origine della leggenda', 2018, 'Otto Bathurst', 'Azione, Avventura', 'Tornato in Inghilterra dopo aver combattuto nelle Crociate, il nobile Robin di Loxley scopre che la sua casa è stata confiscata e che la contea di Nottingham è caduta sotto il giogo del corrotto Sceriffo. Insieme a Little John, un comandante moro conosciuto in guerra, Robin decide di combattere le ingiustizie. Addestrato nel combattimento furtivo e nell''uso dell''arco, Robin assume l''identità dell''incappucciato ''Robin Hood'' per rubare il denaro dello Sceriffo, guidare una rivolta popolare e riconquistare il suo amore, Marian.', 'https://image.tmdb.org/t/p/w500/AiRfixFcfTkNbn2A73qVJPlpkUo.jpg', '2026-09-15T18:04:06.155966', 'Taron Egerton, Jamie Foxx, Ben Mendelsohn, Eve Hewson, Jamie Dornan'),
(85, '2001: Odissea nello spazio', 1968, 'Stanley Kubrick', 'Fantascienza', 'Un misterioso monolite nero guida ed influenza i passaggi chiave dell''evoluzione umana dalla preistoria al futuro. Nel 2001, una missione spaziale diretta verso Giove a bordo della Discovery One entra in rotta di collisione con la propria intelligenza artificiale, l''infallibile e inquietante computer HAL 9000.', 'https://image.tmdb.org/t/p/w500/ve72VxNqjGM69Uky4WTo2bK6rfq.jpg', '2026-09-16T09:54:13.411935', 'Keir Dullea, Gary Lockwood, William Sylvester')
INSERT INTO public.films ("id", "titolo", "anno", "regista", "genere", "trama", "poster_url", "creato_il", "attori") VALUES
(73, 'Star Wars: Episodio I - La minaccia fantasma', 1999, 'George Lucas', 'Fantascienza', 'Due cavalieri Jedi scoprono il giovane e straordinariamente dotato Anakin Skywalker mentre tentano di sventare l''invasione del pacifico pianeta Naboo. Nel frattempo, una minaccia creduta estinta da millenni, i Sith, fa la sua ricomparsa.', 'https://image.tmdb.org/t/p/w500/iHitEFiK8udC0GcsWUU6szWzc5K.jpg', '2026-09-15T19:21:49.355409', 'Mark Hamill, Harrison Ford, Carrie Fisher, Peter Cushing, Alec Guinness'),
(74, 'Star Wars: Episodio II - L''attacco dei cloni', 2002, 'George Lucas', 'Fantascienza', 'Anakin Skywalker, ormai cresciuto, viene incaricato di proteggere la senatrice Padmé Amidala da una serie di attentati, mentre tra i due sboccia un amore proibito. Nel frattempo, Obi-Wan Kenobi scopre la creazione di un misterioso esercito di cloni pronto a combattere i separatisti.', 'https://image.tmdb.org/t/p/w500/zW4eR9utiKPnTHcIP4xuy0t09nT.jpg', '2026-09-15T19:21:49.562672', 'Mark Hamill, Harrison Ford, Carrie Fisher, Peter Cushing, Alec Guinness'),
(81, 'Guerre stellari: Episodio VI - Il ritorno dello Jedi', 1983, 'Richard Marquand', 'Fantascienza', 'Luke Skywalker e i suoi compagni salvano Han Solo dalla fortezza del malvagio Jabba the Hutt prima di affrontare la minaccia definitiva dell''Impero. I Ribelli pianificano un attacco coordinato contro una seconda e più potente Morte Nera in costruzione nei pressi della luna boscosa di Endor. Nel frattempo, Luke deve confrontarsi direttamente con l''Imperatore Palpatine e tentare di redimere suo padre Dart Fener.', 'https://image.tmdb.org/t/p/w500/fai0rspsNeJCS69wHNjOdWxcI7P.jpg', '2026-09-15T19:22:13.937672', 'Mark Hamill, Harrison Ford, Carrie Fisher, Peter Cushing, Alec Guinness'),
(100, 'Nosferatu il vampiro (Nosferatu eine Symphonie des Grauens)', 1922, 'Friedrich Wilhelm Murnau', 'Horror, Espressionismo tedesco', 'Il misterioso Conte Orlok decide di acquistare una casa a Wisborg, portando con sé la peste e il terrore. Il giovane Thomas Hutter e sua moglie Ellen cercheranno di fermare la letale minaccia.', 'https://image.tmdb.org/t/p/w500/zv7J85D8CC9qYagAEhPM63CIG6j.jpg', '2026-09-16T12:04:39.019959', 'Max Schreck, Gustav von Wangenheim, Greta Schröder'),
(72, 'Star Wars: Episodio VI - Il ritorno dello Jedi', 1983, 'Richard Marquand', 'Fantascienza', 'I Ribelli intraprendono una missione decisiva per distruggere la seconda Morte Nera e sconfiggere l''Imperatore. Luke affronta per l''ultima volta Darth Vader nel tentativo di redimere il padre caduto nel Lato Oscuro.', 'https://image.tmdb.org/t/p/w500/rMcCqpaWEUBmATmpZilDTKOyVbL.jpg', '2026-09-15T19:21:49.142052', 'Mark Hamill, Harrison Ford, Carrie Fisher, Peter Cushing, Alec Guinness'),
(75, 'Star Wars: Episodio III - La vendetta dei Sith', 2005, 'George Lucas', 'Fantascienza', 'Le Guerre dei Cloni giungono al termine e il Cancelliere Palpatine seduce Anakin con le promesse del Lato Oscuro. Traditi i Jedi, la Repubblica crolla, dando vita al tirannico Impero Galattico e alla nascita di Darth Vader.', 'https://image.tmdb.org/t/p/w500/xfSAoBEm9MNBjmlNcDYLvLSMlnq.jpg', '2026-09-15T19:21:49.766037', 'Hayden Christensen, Ewan McGregor, Natalie Portman, Ian McDiarmid, Samuel L. Jackson'),
(71, 'Star Wars: Episodio V - L''Impero colpisce ancora', 1980, 'Irvin Kershner', 'Fantascienza', 'Mentre l''Impero contrattacca duramente contro l''Alleanza Ribelle, Luke Skywalker inizia l''addestramento Jedi sotto la guida del maestro Yoda. Nel frattempo, i suoi amici vengono braccati da Darth Vader attraverso la galassia.', 'https://image.tmdb.org/t/p/w500/lGJDx7RCgyMMa3owtp150umMnnJ.jpg', '2026-09-15T19:21:48.946346', 'Peter Mayhew, Mark Hamill, Carrie Fisher, Harrison Ford, Anthony Daniels'),
(77, 'Star Wars: Gli ultimi Jedi', 2017, 'Rian Johnson', 'Fantascienza', 'Rey sviluppa le sue abilità con l''aiuto di un riluttante Luke Skywalker, tormentato dagli errori passati. Nel frattempo, la Resistenza è sull''orlo dell''annientamento totale sotto il fuoco implacabile della flotta del Primo Ordine.', 'https://image.tmdb.org/t/p/w500/kOVEVeg59E0wsnXmF9nrh6OmWII.jpg', '2026-09-15T19:21:50.17562', 'Mark Hamill, Carrie Fisher, Adam Driver, Daisy Ridley, John Boyega'),
(87, 'Rambo 2 - La vendetta', 1985, 'George P. Cosmatos', 'Azione', 'Fatto uscire di prigione per una missione ricognitiva in Vietnam, Rambo ha il compito di fotografare un campo di prigionieri americani. Violando gli ordini ricevuti, il veterano decide di intervenire per liberarli affrontando le forze nemiche.', 'https://image.tmdb.org/t/p/w500/fVwRtWqEPdsCH21BVDGqgkAQcff.jpg', '2026-09-16T10:28:13.617162', 'Sylvester Stallone, Richard Crenna, Charles Napier'),
(88, 'Rambo III', 1988, 'Peter MacDonald', 'Azione', 'Ritiratosi in un monastero in Thailandia, Rambo viene a sapere che il suo ex comandante Trautman è stato catturato dai sovietici in Afghanistan. L''ex berretto verde parte da solo per un''audace missione di salvataggio nel territorio nemico.', 'https://image.tmdb.org/t/p/w500/1eSQvGuD25ezKaiaQsyDDG3e9iN.jpg', '2026-09-16T10:28:13.815476', 'Sylvester Stallone, Richard Crenna, Marc de Jonge'),
(89, 'John Rambo', 2008, 'Sylvester Stallone', 'Azione', 'Rambo vive isolato nel nord della Thailandia finché un gruppo di missionari non lo ingaggia per guidarli in Birmania. Quando i missionari vengono catturati dalle truppe militari locali, il veterano guida un gruppo di mercenari in una sanguinosa operazione di recupero.', 'https://image.tmdb.org/t/p/w500/3mInub5c8o00H7EJ1TrjAqOzIuc.jpg', '2026-09-16T10:28:14.130412', 'Sylvester Stallone, Julie Benz, Matthew Marsden'),
(93, 'Obsession', 1949, 'Edward Dmytryk', 'Thriller', 'Un medico londinese scopre che la moglie lo tradisce e decide di attuare una macabra vendetta. Rapisce l''amante della donna e lo tiene nascosto in un garage abbandonato, pianificando di scioglierlo gradualmente nell''acido.', 'https://image.tmdb.org/t/p/w500/rEOBZMcw29R0kGQJkrUDgtXCU2Z.jpg', '2026-09-16T11:23:04.758701', 'Robert Newton, Sally Gray, Phil Brown'),
(98, 'Ben-Hur', 1959, 'William Wyler', 'Storico, Drammatico, Avventura', 'Giuda Ben-Hur, un ricco principe ebreo di Gerusalemme, viene tradito dall''amico d''infanzia Messala e inviato come schiavo sulle galere. Dopo essere sopravvissuto e aver salvato un console romano, torna in patria per vendicarsi sfidando Messala in un''epica corsa con i carri.', 'https://image.tmdb.org/t/p/w500/m4WQ1dBIrEIHZNCoAjdpxwSKWyH.jpg', '2026-09-16T12:02:51.909714', 'Charlton Heston, Jack Hawkins, Haya Harareet, Stephen Boyd, Hugh Griffith'),
(99, 'Ben-Hur', 2016, 'Timur Bekmambetov', 'Azione, Avventura, Drammatico', 'Rivisitazione moderna del classico di Lew Wallace: Giuda Ben-Hur viene accusato ingiustamente di tradimento dal fratello adottivo Messala, ufficiale dell''esercito romano. Dopo anni trascorsi in mare come schiavo, torna per cercare la resa dei conti nella grande arena dei carri.', 'https://image.tmdb.org/t/p/w500/c9CoGrBA5yw8A7YBMz0hGzfzpNq.jpg', '2026-09-16T12:02:52.020983', 'Jack Huston, Toby Kebbell, Rodrigo Santoro, Morgan Freeman, Nazanin Boniadi'),
(97, 'Ben-Hur: A Tale of the Christ', 1925, 'Fred Niblo', 'Drammatico, Storico', 'Un giovane principe ebreo viene ingiustamente accusato di aver attentato alla vita del governatore romano dal suo amico d''infanzia Messala. Ridotto in schiavitù, cercherà il riscatto e la vendetta.', 'https://image.tmdb.org/t/p/w500/aCohFCJNxPner7VzjzyNN7H8BgV.jpg', '2026-09-16T12:02:51.813455', 'Ramon Novarro, Francis X. Bushman, May McAvoy, Betty Bronson'),
(103, 'L''ultimo dei mohicani', 1992, 'Michael Mann', 'Avventura, Storico, Drammatico, Azione', 'Durante la guerra franco-indiana nel 1757, tre cacciatori, tra cui l''inglese adottato dai Mohicani Occhio di Falco, si ritrovano a proteggere le figlie di un colonnello britannico dall''attacco dei feroci Uroni guidati dal vendicativo Magua.', 'https://image.tmdb.org/t/p/w500/qzJMPWRtZveBkxXOv3ucWhoJuyj.jpg', '2026-09-16T13:01:37.493946', 'Daniel Day-Lewis, Madeleine Stowe, Russell Means, Eric Schweig, Jodhi May, Wes Studi'),
(102, 'Nosferatu', 2024, 'Robert Eggers', 'Horror, Gotico', 'Una rivisitazione gotica e terrificante della classica leggenda, incentrata sull''ossessione tra una giovane donna tormentata e il mostruoso vampiro infatuato di lei.', 'https://image.tmdb.org/t/p/w500/d0B8xDdqBZlzlPEzES8lu5LlNQn.jpg', '2026-09-16T12:04:39.222453', 'Bill Skarsgård, Nicholas Hoult, Lily-Rose Depp, Willem Dafoe'),
(95, 'Obsession', 2026, 'Curry Barker', 'Thriller / Horror', 'Un thriller psicologico ad alta tensione che esplora i confini della mente umana, le relazioni tossiche e le conseguenze estreme del desiderio inconfessabile e del possesso.', 'https://image.tmdb.org/t/p/w500/bRwnj8WEKBCvmfeUNOukJPwB43K.jpg', '2026-09-16T11:30:56.929735', 'Cooper Koch, Charithra Chandran'),
(101, 'Nosferatu, il principe della notte (Nosferatu: Phantom der Nacht)', 1979, 'Werner Herzog', 'Horror, Drammatico', 'In questo celebre remake del film di Murnau, il tormentato Conte Dracula viaggia dalla Transilvania a Wismar, diffondendo la peste e cercando ossessivamente l''amore della giovane Lucy Harker.', 'https://image.tmdb.org/t/p/w500/jHKzGYwf7P34vz8MhJBTN6cnaYD.jpg', '2026-09-16T12:04:39.122688', 'Klaus Kinski, Isabelle Adjani, Bruno Ganz'),
(96, 'The Backrooms', 2026, 'Kane Parsons', 'Horror, Fantascienza', 'Un giovane precipita accidentalmente oltre i confini della realtà ritrovandosi intrappolato nelle Backrooms, una dimensione parallela costituita da uno sconfinato e inquietante labirinto di uffici vuoti, pareti gialle, moquette umida e luci al neon ronzanti. Mentre tenta disperatamente di trovare una via d''uscita, deve eludere spietate entità ostili che cacciano all''interno di questo spazio liminale.', 'https://image.tmdb.org/t/p/w500/rhGx6E3qRNMgj3i5su2oukNHwIQ.jpg', '2026-09-16T11:55:48.732409', 'Kane Parsons, Ashwin De Silva'),
(92, 'Ossessione', 1943, 'Luchino Visconti', 'Drammatico', 'Gino, un girovago senza meta, si innamora ricambiato di Giovanna, una donna insoddisfatta sposata con il proprietario di una trattoria. La passione travolgente tra i due li spinge a eliminare il marito, ma il senso di colpa e il destino distruggeranno il loro legame.', 'https://image.tmdb.org/t/p/w500/dHB6NdsOxO0dc71ciP2hsv3nTPf.jpg', '2026-09-16T11:23:04.558884', 'Clara Calamai, Massimo Girotti, Dhia Cristiani'),
(91, 'Obsession - Complesso di colpa', 1976, 'Brian De Palma', 'Thriller', 'Un uomo d''affari di New Orleans subisce un grave trauma quando la moglie e la figlia muoiono durante un tragico tentativo di riscatto. Anni dopo, durante un viaggio a Firenze, incontra una giovane donna identica alla defunta moglie, sprofondando in un vortice di ossessione e inganni.', 'https://image.tmdb.org/t/p/w500/a0bOKTldOJVJivmPNGBHfMYJU9x.jpg', '2026-09-16T11:23:04.358105', 'Cliff Robertson, Geneviève Bujold, John Lithgow'),
(94, 'Obsession', 1997, 'Peter Sehr', 'Drammatico', 'Una giovane musicista si trova divisa tra l''amore per due uomini completamente differenti tra loro a Berlino. La situazione sfocia in un complesso triangolo amoroso guidato da passione, insicurezze e scelte dolorose.', 'https://image.tmdb.org/t/p/w500/5Z3Y42Duzwb51kIEeMnkBOgiuLk.jpg', '2026-09-16T11:23:04.967725', 'Daniel Craig, Heike Makatsch, Charles Berling'),
(112, '10 Cloverfield Lane', 2016, 'Dan Trachtenberg', 'Thriller, Fantascienza, Drammatico', 'Dopo un incidente d''auto, una giovane donna si risveglia in un bunker sotterraneo insieme a un uomo che sostiene di averle salvato la vita da un attacco chimico apocalittico.', 'https://image.tmdb.org/t/p/w500/q8A39vcBDruhvoDTJd6L8a4lnTi.jpg', '2026-09-17T16:00:28.524163', 'Mary Elizabeth Winstead, John Goodman, John Gallagher Jr.'),
(109, 'Ace Ventura - Missione Africa', 1995, 'Steve Oedekerk', 'Commedia, Avventura', 'L''acchiappanimali Ace Ventura si reca in Africa per ritrovare Chicca, un raro pipistrello bianco sacro alla tribù dei Ciakaka, la cui scomparsa rischia di scatenare una guerra tribale.', 'https://image.tmdb.org/t/p/w500/wcinCf1ov2D6M3P7BBZkzQFOiIb.jpg', '2026-09-17T12:47:38.61957', 'Jim Carrey, Ian McNeice, Simon Callow, Maynard Eziashi, Bob Gunton'),
(3, 'Cloverfield', 2008, 'Matt Reeves', 'Fantascienza, Horror, Thriller', 'Durante una festa di addio a New York per Rob, un ragazzo in partenza per il Giappone, la città viene scossa dall''attacco improvviso di un mostro gigante di origine sconosciuta. Rob e i suoi amici si avventurano tra le rovine di Manhattan per salvare Beth, la ragazza di cui Rob è innamorato, rimasta intrappolata nel suo appartamento. L''intera vicenda è raccontata attraverso il punto di vista di una videocamera amatoriale che documenta in tempo reale il caos e la sopravvivenza del gruppo.', 'https://image.tmdb.org/t/p/w500/qIegUGJqyMMCRjkKV1s7A9MqdJ8.jpg', '2026-09-13T14:43:24.360095', 'Michael Stahl-David, Odette Yustman, T.J. Miller, Jessica Lucas, Lizzy Caplan, Mike Vogel'),
(114, 'Il grande Lebowski', 1998, 'Joel Coen, Ethan Coen', 'Commedia, Noir', 'Jeffrey ''Drugo'' Lebowski, un fannullone pacifista di Los Angeles, viene scambiato per un miliardario suo omonimo. Dopo che dei sicari urinano sul suo tappeto preferito, Drugo si mette alla ricerca di un risarcimento, finendo invischiato in un bizzarro mistero tra rapimenti e nichilisti.', 'https://image.tmdb.org/t/p/w500/rRwaCTF777WaBlrVxtuBic43oqC.jpg', '2026-09-17T16:06:11.675105', 'Jeff Bridges, John Goodman, Julianne Moore, Steve Buscemi, John Turturro'),
(110, 'Braveheart - Cuore impavido', 1995, 'Mel Gibson', 'Storico, Drammatico, Azione, Biografico', 'Nel XIII secolo, dopo l''uccisione della sua amata da parte dei soldati inglesi, il patriota scozzese William Wallace guida una sanguinosa ribellione contro il tirannico re Edoardo I d''Inghilterra per conquistare la libertà della Scozia.', 'https://image.tmdb.org/t/p/w500/or1gBugydmjToAEq7OZY0owwFk.jpg', '2026-09-17T13:02:53.469105', 'Mel Gibson, Sophie Marceau, Patrick McGoohan, Catherine McCormack, Angus Macfadyen'),
(104, 'Coyote vs. Acme', 2026, 'Dave Green', 'Animazione, Commedia, Avventura', 'Wile E. Coyote decide di fare causa alla Acme Corporation per via dei suoi prodotti costantemente difettosi. Per farlo, assume un avvocato umano di scarso successo che si ritroverà a rappresentarlo in tribunale contro il potente CEO della Acme.', 'https://image.tmdb.org/t/p/w500/kYDCl2y0VPvhT5eYWbMRInPoB03.jpg', '2026-09-16T16:15:06.745926', 'Will Forte, John Cena, Lana Condor'),
(108, 'La fine di Oak Street', 2026, 'David Robert Mitchell', 'Thriller, Mistero', 'In una tranquilla e apparentemente perfetta via residenziale chiamata Oak Street, una serie di eventi inspiegabili e sparizioni misteriose scatena la paranoia tra i residenti, costringendo una madre a fare i conti con un oscuro segreto del passato per salvare la sua famiglia.', 'https://image.tmdb.org/t/p/w500/hkPxuAMEqIqo1HCtIi4sqx0GRuP.jpg', '2026-09-17T11:15:13.20051', 'Anne Hathaway, Ewan McGregor'),
(117, 'L''attimo fuggente', 1989, 'Peter Weir', 'Drammatico', 'In un rigido collegio maschile del Vermont nel 1959, l''arrivo di un nuovo professore di letteratura, John Keating, sconvolge le vite degli studenti. Con i suoi metodi d''insegnamento anticonformisti, Keating insegna ai ragazzi ad amare la poesia, a pensare con la propria testa e a cogliere l''attimo.', 'https://image.tmdb.org/t/p/w500/erzbMlcNHOdx24AXOcn2ZKA7R1q.jpg', '2026-09-18T06:39:52.384946', 'Robin Williams, Ethan Hawke, Robert Sean Leonard, Josh Charles, Gale Hansen'),
(78, 'Star Wars: L''ascesa di Skywalker', 2019, 'J.J. Abrams', 'Fantascienza, Avventura, Azione', 'Un anno dopo gli eventi de ''Gli ultimi Jedi'', i sopravvissuti della Resistenza affrontano ancora una volta il Primo Ordine. Rey, Finn e Poe Dameron guidano la battaglia finale contro il Leader Supremo Kylo Ren e il redivivo Imperatore Palpatine, giungendo alla conclusione della storica saga degli Skywalker.', 'https://image.tmdb.org/t/p/w500/3drtqLOARQEuFgEmGRlMlWpV3Eb.jpg', '2026-09-15T19:21:50.386913', 'Daisy Ridley, Adam Driver, John Boyega, Oscar Isaac, Carrie Fisher, Mark Hamill, Ian McDiarmid, Billy Dee Williams, Lupita Nyong''o, Domhnall Gleeson'),
(115, 'Pulp Fiction', 1994, 'Quentin Tarantino', 'Crime, Drammatico', 'Le vite di due killer della mafia, della moglie del loro capo, di un pugile in fuga e di una coppia di rapinatori si intrecciano in una serie di bizzarri e drammatici eventi a Los Angeles.', 'https://image.tmdb.org/t/p/w500/vQWk5YBFWF4bZaofAbv0tShwBvQ.jpg', '2026-09-17T17:53:00.977038', 'John Travolta, Samuel L. Jackson, Uma Thurman, Bruce Willis, Harvey Keitel, Tim Roth'),
(107, 'Oak Street', 2026, 'Marcus Thorne', 'Thriller psicologico', 'Un intenso thriller psicologico ambientato in una tranquilla periferia americana. Quando un''intera famiglia scompare misteriosamente dal civico 42 di Oak Street senza lasciare alcuna traccia, un investigatore in pensione decide di condurre un''indagine autonoma. Con il passare dei giorni, l''uomo porterà alla luce una complessa rete di oscuri segreti e menzogne sepolte da decenni all''interno dell''apparentemente impeccabile comunità locale.', 'https://image.tmdb.org/t/p/w500/3iJpc2rV8uN434wdDTJBE2PQwvI.jpg', '2026-09-17T11:04:33.386995', 'Elena Rostova, David Miller, Sarah Jenkins'),
(111, 'Titanic', 1997, 'James Cameron', 'Drammatico, Romance', 'Un giovane artista di umili origini e una ricca nobildonna promessa sposa si innamorano a bordo del transatlantico Titanic durante il suo tragico viaggio inaugurale nel 1912.', 'https://image.tmdb.org/t/p/w500/9xjZS2rlVxm8SFx8kPC3aIGCOYQ.jpg', '2026-09-17T13:06:24.095738', 'Leonardo DiCaprio, Kate Winslet, Billy Zane, Kathy Bates, Frances Fisher'),
(160, 'Il cavaliere oscuro - Il ritorno', 2012, 'Christopher Nolan', 'Azione, Thriller, Fantascienza', 'Otto anni dopo la morte di Harvey Dent, Gotham City vive un periodo di pace grazie alle leggi speciali del Decreto Dent. Tuttavia, l''arrivo in città di Bane, un terrorista spietato e mascherato, e della misteriosa scassinatrice Selina Kyle, costringe un Bruce Wayne ormai ritirato e debilitato a indossare nuovamente il mantello di Batman per affrontare la minaccia definitiva alla sua città.', 'https://image.tmdb.org/t/p/w500/hr0L2aueqlP2BYUblTTjmtn0hw4.jpg', '2026-09-30T18:57:43.911449', 'Christian Bale, Tom Hardy, Anne Hathaway, Michael Caine, Gary Oldman, Marion Cotillard, Joseph Gordon-Levitt, Morgan Freeman'),
(11, 'Indiana Jones e l''ultima crociata', 1989, 'Steven Spielberg', 'Avventura, Azione', 'Nel 1938, l''archeologo Indiana Jones viene contattato dal magnate Walter Donovan per ritrovare il Santo Graal, la coppa che donerebbe la vita eterna. L''incarico assume una valenza personale quando Indy apprende che il precedente capo della spedizione, misteriosamente scomparso, è suo padre, il professor Henry Jones Sr., uno studioso da sempre ossessionato dalla reliquia. Raggiunta Venezia con l''aiuto dell''affascinante dottoressa Elsa Schneider, Indy ritrova il diario del genitore e scopre che l''uomo è tenuto prigioniero dai nazisti in un castello al confine tra Germania e Austria. Dopo aver liberato il padre, padre e figlio fuggono attraverso l''Europa e il Medio Oriente, affrontando tradimenti e letali trappole millenarie all''interno del tempio segreto di Alessandretta per impedire a Hitler di impadronirsi del potere del Graal.', 'https://image.tmdb.org/t/p/w500/sizg1AU8f8JDZX4QIgE4pjUMBvx.jpg', '2026-09-13T14:53:51.047148', 'Harrison Ford, Sean Connery, Alison Doody, Denholm Elliott, John Rhys-Davies, Julian Glover'),
(12, 'Indiana Jones e il regno del teschio di cristallo', 2008, 'Steven Spielberg', 'Avventura, Azione', 'Nel 1957, in piena Guerra Fredda, l''anziano archeologo Indiana Jones viene rapito insieme al collega George McHale da agenti sovietici guidati dalla spietata Irina Spalko. Costretto ad aiutarli a penetrare in un magazzino segreto nell''Area 51 per recuperare i resti mummificati di un essere extraterrestre, Indy riesce a fuggire. Poco dopo viene avvicinato dal giovane ribelle Mutt Williams, il quale gli chiede aiuto per trovare il professor Harold Oxley e sua madre, misteriosamente rapiti in Perù. I due si mettono sulle tracce di un leggendario teschio di cristallo dai poteri sconosciuti, finendo per scontrarsi nuovamente con i sovietici lungo una pericolosa spedizione nella giungla amazzonica alla volta della mitica città di Akator.', 'https://image.tmdb.org/t/p/w500/56As6XEM1flWvprX4LgkPl8ii4K.jpg', '2026-09-13T14:53:51.55355', 'Harrison Ford, Cate Blanchett, Shia LaBeouf, Karen Allen, Ray Winstone, John Hurt'),
(162, 'The Truman Show', 1998, 'Peter Weir', 'Drammatico, Fantascienza, Commedia', 'Truman Burbank è un uomo apparentemente comune che vive in una tranquilla cittadina isolana. In realtà, la sua intera vita è uno show televisivo trasmesso in diretta mondiale 24 ore su 24, popolato da attori e scenografie, a sua totale insaputa. Quando inizia a notare delle anomalie, Truman decide di scoprire la verità e fuggire.', 'https://image.tmdb.org/t/p/w500/vuza0WqY239yBXOadKlGwJsZJFE.jpg', '2026-09-30T19:53:15.331789', 'Jim Carrey, Laura Linney, Ed Harris, Noah Emmerich, Natascha McElhone'),
(166, 'Il momento di uccidere', 1996, 'Joel Schumacher', 'Drammatico, Thriller', 'In una cittadina del Mississippi, un operaio afroamericano uccide i due uomini bianchi che hanno brutalmente violentato la sua figlioletta di dieci anni. Un giovane e ambizioso avvocato bianco decide di assumere la sua difesa, affrontando un processo ad altissima tensione razziale che risveglia le violenze del Ku Klux Klan.', 'https://image.tmdb.org/t/p/w500/w8UCke112E9jrhjKcwG32kyhTx5.jpg', '2026-10-03T07:51:04.334558', 'Matthew McConaughey, Sandra Bullock, Samuel L. Jackson, Kevin Spacey, Ashley Judd'),
(167, 'Marty Supreme', 2025, 'Josh Safdie', 'Biografico, Drammatico, Sportivo', 'Liberamente ispirato alla vita del celebre e non convenzionale giocatore di tennistavolo Marty Reisman, il film racconta le vicende, le scommesse e l''ascesa di un eccentrico campione di ping pong nell''America degli anni Cinquanta.', 'https://image.tmdb.org/t/p/w500/lYWEXbQgRTR4ZQleSXAgRbxAjvq.jpg', '2026-10-03T13:16:07.853445', 'Timothée Chalamet, Gwyneth Paltrow, Tyler, The Creator, Odessa A''zion, Penn Jillette'),
(168, 'Non è un paese per vecchi', 2007, 'Joel Coen, Ethan Coen', 'Thriller, Drammatico, Crime', 'Nel Texas del 1980, Llewelyn Moss si imbatte nei resti di uno scambio di droga finito male e decide di scappare con una valigetta contenente due milioni di dollari. Sulle sue tracce si mette Anton Chigurh, uno spietato e metodico killer psicopatico armato di un fucile da macello, mentre l''anziano sceriffo Ed Tom Bell cerca disperatamente di salvare Moss e riflette sull''inarrestabile evoluzione della violenza nel mondo moderno.', 'https://image.tmdb.org/t/p/w500/6d5XOczc226jECq0LIX0siKtgHR.jpg', '2026-10-03T13:23:23.059339', 'Tommy Lee Jones, Javier Bardem, Josh Brolin, Woody Harrelson, Kelly Macdonald'),
(169, 'Full Metal Jacket', 1987, 'Stanley Kubrick', 'Drammatico, Guerra', 'Durante la guerra del Vietnam, un gruppo di reclute dei Marines affronta un disumanizzante e brutale addestramento nel campo di Parris Island, sotto la guida dello spietato sergente Hartman. Successivamente, il soldato Joker, diventato giornalista militare, viene inviato al fronte durante l''offensiva del Têt, toccando con mano la follia e la crudeltà del conflitto.', 'https://image.tmdb.org/t/p/w500/kMKyx1k8hWWscYFnPbnxxN4Eqo4.jpg', '2026-10-03T13:27:20.929286', 'Matthew Modine, Vincent D''Onofrio, R. Lee Ermey, Adam Baldwin, Arliss Howard'),
(170, 'Independence Day', 1996, 'Roland Emmerich', 'Fantascienza, Azione', 'Alla vigilia del 4 luglio, enormi astronavi alieni posizionano sopra le principali metropoli della Terra e scatenano un attacco devastante. Un gruppo di sopravvissuti, tra cui un pilota di caccia della Marina e uno scienziato esperto in telecomunicazioni, elabora un piano disperato per sconfiggere gli invasori e salvare l''umanità dall''estinzione.', 'https://image.tmdb.org/t/p/w500/p0BPQGSPoSa8Ml0DAf2mB2kCU0R.jpg', '2026-10-03T15:02:29.959341', 'Will Smith, Bill Pullman, Jeff Goldblum, Mary McDonnell, Judd Hirsch'),
(174, 'Il primo re', 2019, 'Matteo Rovere', 'Drammatico, Storico, Azione', 'Nell''VIII secolo a.C., i fratelli pastori Romolo e Remo vengono travolti dall''esondazione del Tevere e fatti prigionieri dagli abitanti di Alba Longa. Riusciti a fuggire guidando una rivolta insieme ad altri prigionieri, i due intraprendono un viaggio guidati da Remo, che sfida la volontà degli dei finendo per scontrarsi tragicamente con Romolo, destinato a fondare la città di Roma.', 'https://image.tmdb.org/t/p/w500/dqBU63M3cKy7pfVsmhrbgY5X8iv.jpg', '2026-10-05T17:14:16.232927', 'Alessandro Borghi, Alessio Lapice, Fabricio Rongione, Massimiliano Rossi'),
(176, 'The Untouchables - Gli intoccabili', 1987, 'Brian De Palma', 'Crimine, Drammatico, Thriller', 'Durante il periodo del proibizionismo a Chicago, l''agente federale Eliot Ness crea una squadra speciale di uomini incorruttibili per fermare l''impero criminale del celebre boss mafioso Al Capone.', 'https://image.tmdb.org/t/p/w500/tPq0R4jTO4Ey8ZspFaWK9wGA4Ls.jpg', '2026-10-06T18:42:24.296083', 'Kevin Costner, Sean Connery, Robert De Niro, Andy Garcia, Charles Martin Smith'),
(178, 'King Kong (King Kong)', 1933, 'Merian C. Cooper, Ernest B. Schoedsack', 'Avventura, Fantastico', 'Una troupe cinematografica si avventura su una misteriosa isola sconosciuta, Skull Island, dove scopre un gorilla gigante venerato come un dio dai nativi. La creatura si invaghisce dell''attrice Ann Darrow, ma viene catturata e portata a New York per essere esibita al pubblico.', 'https://image.tmdb.org/t/p/w500/lHlnxKL5GbgRibyRFI7n1Ey850i.jpg', '2026-10-06T19:12:53.048706', 'Fay Wray, Robert Armstrong, Bruce Cabot'),
(180, 'King Kong (King Kong)', 2005, 'Peter Jackson', 'Avventura, Fantastico, Azione', 'Nel 1933, un regista di spettacoli sull''orlo del fallimento convince una troupe e una giovane attrice a salpare verso l''esotica e pericolosa Isola del Teschio. Lì si scontreranno con creature preistoriche e con King Kong, un gorilla gigantesco che svilupperà un profondo legame con la donna.', 'https://image.tmdb.org/t/p/w500/6a2HY6UmD7XiDD3NokgaBAXEsD2.jpg', '2026-10-06T19:12:53.434212', 'Naomi Watts, Jack Black, Adrien Brody'),
(179, 'King Kong (King Kong)', 1976, 'John Guillermin', 'Avventura, Fantastico, Azione', 'Una compagnia petrolifera organizza una spedizione su un''isola perennemente avvolta dalla nebbia. Qui trovano una gigantesca creatura antropomorfa che si invaghisce di una naufraga. Il gorilla viene catturato per scopi pubblicitari e portato nella metropoli di New York.', 'https://image.tmdb.org/t/p/w500/paYKhEwUaxKA05vmOfU7FlleTln.jpg', '2026-10-06T19:12:53.233287', 'Jeff Bridges, Jessica Lange, Charles Grodin'),
(184, 'Lo Hobbit - La battaglia delle cinque armate (The Hobbit: The Battle of the Five Armies)', 2014, 'Peter Jackson', 'Fantastico, Avventura, Azione', 'Mentre Smaug scatena la sua ira su Pontelagolungo, nani, elfi, umani e orchi si scontrano in una titanica battaglia ai piedi della Montagna Solitaria per il controllo del tesoro di Erebor.', 'https://image.tmdb.org/t/p/w500/xT98tLqatZPQApyRmlPL12LtiWp.jpg', '2026-10-09T15:04:32.343493', 'Martin Freeman, Ian McKellen, Richard Armitage, Evangeline Lilly, Luke Evans')
INSERT INTO public.films ("id", "titolo", "anno", "regista", "genere", "trama", "poster_url", "creato_il", "attori") VALUES
(181, 'Lo Hobbit (The Hobbit)', 1977, 'Arthur Rankin Jr., Jules Bass', 'Animazione, Fantastico, Avventura', 'Un pacifico hobbit di nome Bilbo Baggins viene reclutato dal mago Gandalf e da una compagnia di nani per recuperare un tesoro custodito dal drago Smaug.', 'https://image.tmdb.org/t/p/w500/2ohvyMPhvjftLrM6S6Ljr6QrL0u.jpg', '2026-10-09T15:04:31.981634', 'Orson Bean, Richard Boone, Hans Conried, John Huston'),
(182, 'Lo Hobbit - Un viaggio inaspettato (The Hobbit: An Unexpected Journey)', 2012, 'Peter Jackson', 'Fantastico, Avventura', 'Bilbo Baggins viene convinto dal mago Gandalf a unirsi a tredici nani guidati da Thorin Scudodiquercia in un''epica impresa per riconquistare il regno perduto di Erebor dal drago Smaug.', 'https://image.tmdb.org/t/p/w500/yHA9Fc37VmpUA5UncTxxo3rTGVA.jpg', '2026-10-09T15:04:32.122765', 'Martin Freeman, Ian McKellen, Richard Armitage, Ken Stott'),
(183, 'Lo Hobbit - La desolazione di Smaug (The Hobbit: The Desolation of Smaug)', 2013, 'Peter Jackson', 'Fantastico, Avventura', 'Bilbo Baggins e la compagnia di nani proseguono il loro viaggio verso la Montagna Solitaria, affrontando pericoli come ragni giganti, elfi silvani e infine il temibile drago Smaug.', 'https://image.tmdb.org/t/p/w500/xQYiXsheRCDBA39DOrmaw1aSpbk.jpg', '2026-10-09T15:04:32.239062', 'Martin Freeman, Ian McKellen, Richard Armitage, Orlando Bloom, Evangeline Lilly'),
(185, 'Avvenne domani (It Happened Tomorrow)', 1944, 'René Clair', 'Commedia, Fantastico', 'Un giovane giornalista riceve da un anziano archivista defunto copie del giornale del giorno successivo. Grazie a questa straordinaria opportunità, riesce a realizzare scoop sensazionali, ma le cose si complicano quando legge la notizia della propria morte imminente.', 'https://image.tmdb.org/t/p/w500/byWjI8SYnATh0OdnaCCKhO9nY0R.jpg', '2026-10-09T15:06:19.335568', 'Dick Powell, Linda Darnell, Jack Oakie, Edgar Kennedy, John Philliber'),
(187, 'Always (Ojik geudaeman)', 2011, 'Song Il-gon', 'Drammatico, Romantico', 'Un ex pugile dal passato tormentato, che ora lavora come guardiano di un parcheggio, incontra una ragazza non vedente ma piena di vitalità. Tra i due nasce un profondo legame d''amore, ma il passato dell''uomo tornerà a minacciare la loro felicità e la vista della donna.', 'https://image.tmdb.org/t/p/w500/7PaCGnjY87sc9088zxFf34Tamcz.jpg', '2026-10-09T15:11:20.402337', 'So Ji-sub, Han Hyo-joo, Kang Shin-il, Park Chul-min'),
(186, 'Always - Per sempre (Always)', 1989, 'Steven Spielberg', 'Drammatico, Fantastico, Romantico', 'Un audace pilota di aerei antincendio muore in un incidente di volo, ma ritorna sulla Terra sotto forma di spirito guida per aiutare un giovane pilota alle prime armi e vegliare sulla donna che amava, faticando ad accettare che lei debba rifarsi una vita senza di lui.', 'https://image.tmdb.org/t/p/w500/r7LTwkgqUPPABnHpxceVylMf8M0.jpg', '2026-10-09T15:11:20.329203', 'Richard Dreyfuss, Holly Hunter, John Goodman, Audrey Hepburn, Brad Johnson'),
(188, 'Always', 1985, 'Henry Jaglom', 'Commedia, Drammatico', 'Un regista e la sua ex moglie trascorrono insieme il fine settimana del Giorno dell''Indipendenza per formalizzare il loro divorzio, ma la convivenza temporanea riaccende vecchi sentimenti e costringe entrambi a confrontarsi con i motivi della fine del loro matrimonio.', 'https://image.tmdb.org/t/p/w500/rCYAMewiNpV6gabIK7x1ee141Y8.jpg', '2026-10-09T15:11:20.490167', 'Henry Jaglom, Patrice Townsend, Joanna Frank, Alan Rachins'),
(189, 'Harry, ti presento Sally... (When Harry Met Sally...)', 1989, 'Rob Reiner', 'Commedia, Romantico', 'Harry Burns e Sally Albright si incontrano per la prima volta nel 1977 durante un viaggio in auto da Chicago a New York. Nel corso di dodici anni si ritrovano casualmente più volte, sviluppando una profonda amicizia che mette alla prova la teoria di Harry secondo cui un uomo e una donna non possono essere amici senza che il sesso si metta di mezzo.', 'https://image.tmdb.org/t/p/w500/rFOiFUhTMtDetqCGClC9PIgnC1P.jpg', '2026-10-09T15:26:15.168656', 'Billy Crystal, Meg Ryan, Carrie Fisher, Bruno Kirby'),
(192, 'Il tempo delle mele 3 (L''étudiante)', 1988, 'Claude Pinoteau', 'Commedia, Sentimentale, Drammatico', 'Valentine è una studentessa universitaria determinata a superare i suoi esami di abilitazione all''insegnamento. La sua vita rigorosa viene sconvolta dall''incontro con Ned, un musicista jazz con ritmi di vita opposti ai suoi.', 'https://image.tmdb.org/t/p/w500/tDx9zW0Edb83qh9PAGrgP3Zh9RP.jpg', '2026-10-09T15:46:43.658535', 'Sophie Marceau, Vincent Lindon, Élisabeth Vitali, Jean-Claude Leguay'),
(190, 'Il tempo delle mele (La Boum)', 1980, 'Claude Pinoteau', 'Commedia, Sentimentale, Drammatico', 'La quattordicenne Vic affronta i primi amori, le prime feste e le difficoltà dell''adolescenza nella Parigi degli anni ''80, mentre i suoi genitori attraversano una profonda crisi coniugale.', 'https://image.tmdb.org/t/p/w500/usGV1Q7KWR0Uq4dOIppGZ0ba8kz.jpg', '2026-10-09T15:46:43.450525', 'Sophie Marceau, Claude Brasseur, Brigitte Fossey, Denise Grey, Alexandre Sterling'),
(191, 'Il tempo delle mele 2 (La Boum 2)', 1982, 'Claude Pinoteau', 'Commedia, Sentimentale', 'Vic ha ormai sedici anni e, di ritorno da un viaggio, incontra il giovane Philippe. Tra i due nasce una romantica storia d''amore che la porterà a confrontarsi con nuove gelosie e le prime vere scelte della maturità.', 'https://image.tmdb.org/t/p/w500/pbkccDoxH1H1VdqWcQYycZxHTIK.jpg', '2026-10-09T15:46:43.547859', 'Sophie Marceau, Claude Brasseur, Brigitte Fossey, Pierre Cosso, Lambert Wilson, Denise Grey'),
(194, 'L''avvocato del diavolo (The Devil''s Advocate)', 1997, 'Taylor Hackford', 'Thriller, Drammatico, Horror', 'Un giovane e imbattuto avvocato della Florida viene ingaggiato da un imponente studio legale di New York. L''uomo si rende presto conto che il suo carismatico capo, John Milton, e la societa stessa nascondono un''oscura origine demoniaca.', 'https://image.tmdb.org/t/p/w500/5ZzBGpxy55OQzHxKVY11IpY6a0o.jpg', '2026-10-09T16:27:56.501666', 'Keanu Reeves, Al Pacino, Charlize Theron, Jeffrey Jones'),
(195, 'Interceptor (Mad Max)', 1979, 'George Miller', 'Azione, Fantascienza, Thriller', 'In un''Australia distopica e violenta al collasso sociale, il poliziotto Max Rockatansky cerca vendetta contro una spietata banda di motociclisti che ha sterminato la sua famiglia.', 'https://image.tmdb.org/t/p/w500/5LrI4GiCSrChgkdskVZiwv643Kg.jpg', '2026-10-09T18:15:32.012949', 'Mel Gibson, Joanne Samuel, Hugh Keays-Byrne, Steve Bisley, Tim Burns'),
(193, 'L''avvocato del diavolo (Des Teufels Advokat)', 1977, 'Guy Green', 'Drammatico', 'Un sacerdote affetto da un male incurabile viene inviato in un piccolo paese della Calabria per indagare sulla vita e sui presunti miracoli di un uomo giustiziato nel 1944.', 'https://image.tmdb.org/t/p/w500/AbPgcdruJ9ZfNOMWOf1kpyjCUKE.jpg', '2026-10-09T16:27:56.404287', 'John Mills, Stéphane Audran, Jason Miller, Timothy West'),
(199, 'Furiosa: A Mad Max Saga', 2024, 'George Miller', 'Azione, Fantascienza, Avventura', 'Rapita da bambina dal Luogo Verde delle Molte Madri e finita nelle mani della brutale Orda di Motociclisti guidata dal Signore della Guerra Dementus, la giovane Furiosa combatte per anni per sopravvivere e trovare la via di casa.', 'https://image.tmdb.org/t/p/w500/iADOJ8Zymht2JPMoy3R7xceZprc.jpg', '2026-10-09T18:15:32.468179', 'Anya Taylor-Joy, Chris Hemsworth, Tom Burke, Alyla Browne, Lachy Hulme'),
(198, 'Mad Max: Fury Road', 2015, 'George Miller', 'Azione, Fantascienza, Avventura', 'In fuga attraverso le distese desertiche controllate dal tiranno Immortan Joe, Max unisce le forze con l''Imperatrice Furiosa per scortare cinque donne verso la libertà a bordo di una potente autocisterna.', 'https://image.tmdb.org/t/p/w500/ulcAi4dKpAjHwYGS08vNyx9H6I9.jpg', '2026-10-09T18:15:32.314993', 'Tom Hardy, Charlize Theron, Nicholas Hoult, Hugh Keays-Byrne, Rosie Huntington-Whiteley'),
(197, 'Mad Max oltre la sfera del tuono (Mad Max Beyond Thunderdome)', 1985, 'George Miller, George Ogilvie', 'Azione, Fantascienza, Avventura', 'Esiliato dall''avida dominatrice della città di Bartertown dopo essersi rifiutato di uccidere un gladiatore, Max viene salvato da una tribù di bambini sopravvissuti a un incidente aereo che lo credono il loro salvatore.', 'https://image.tmdb.org/t/p/w500/jJlxcEVVUHnrUeEkQ0077VeHQpb.jpg', '2026-10-09T18:15:32.209222', 'Mel Gibson, Tina Turner, Bruce Spence, Frank Thring, Angelo Rossitto'),
(196, 'Interceptor - Il guerriero della strada (Mad Max 2)', 1981, 'George Miller', 'Azione, Fantascienza, Avventura', 'Divenuto un vagabondo solitario nelle desolate terre post-apocalittiche, Max accetta di difendere una comunità assediata che gestisce una preziosa raffineria di petrolio da un gruppo di predoni sanguinari.', 'https://image.tmdb.org/t/p/w500/l1KVEhkGDpWRzQ0VqIhZqDDuOim.jpg', '2026-10-09T18:15:32.117824', 'Mel Gibson, Bruce Spence, Michael Preston, Max Phipps, Vernon Wells'),
(200, 'Quel pomeriggio di un giorno da cani (Dog Day Afternoon)', 1975, 'Sidney Lumet', 'Drammatico, Thriller, Biografico', 'A New York, tre rapinatori poco esperti tentano di svaligiare una filiale bancaria in un torrido pomeriggio estivo. Quando il colpo fallisce, la situazione si trasforma in un lungo assedio con ostaggi che cattura l''attenzione della polizia e dei media dell''intera nazione.', 'https://image.tmdb.org/t/p/w500/mavrhr0ig2aCRR8d48yaxtD5aMQ.jpg', '2026-10-09T21:17:12.809779', 'Al Pacino, John Cazale, Charles Durning, Chris Sarandon'),
(201, 'Soldato blu (Soldier Blue)', 1970, 'Ralph Nelson', 'Western/Drammatico', 'Dopo un massacro compiuto dai Cheyenne, gli unici due sopravvissuti, una giovane donna bianca che ha vissuto a lungo con i nativi e un giovane soldato idealista, intraprendono un difficile viaggio per raggiungere la salvezza. Lungo il cammino, si scontreranno con le rispettive visioni del mondo, fino ad assistere al brutale e tragico massacro di un villaggio indiano inerme da parte dell''esercito statunitense.', 'https://image.tmdb.org/t/p/w500/2fRfVQpdrjAhvxwytG0scOqdQOJ.jpg', '2026-10-09T21:22:31.989748', 'Candice Bergen, Peter Strauss, Donald Pleasence, John Anderson, Jorge Rivero'),
(206, 'Hunger Games - La ballata dell''usignolo e del serpente (The Hunger Games: The Ballad of Songbirds & Snakes)', 2023, 'Francis Lawrence', 'Fantascienza, Azione, Avventura', 'Decenni prima di diventare il tirannico presidente di Panem, il diciottenne Coriolanus Snow viene assegnato come mentore a Lucy Gray Baird, il tributo del Distretto 12 per i decimi Hunger Games.', 'https://image.tmdb.org/t/p/w500/mBaXZ95R2OxueZhvQbcEWy2DqyO.jpg', '2026-10-11T16:25:26.977381', 'Tom Blyth, Rachel Zegler, Peter Dinklage, Viola Davis, Jason Schwartzman, Hunter Schafer'),
(203, 'Hunger Games: La ragazza di fuoco (The Hunger Games: Catching Fire)', 2013, 'Francis Lawrence', 'Fantascienza, Azione, Avventura', 'Dopo aver vinto i settantaquattresimi Hunger Games, Katniss e Peeta diventano il simbolo della ribellione contro Capitol City e vengono costretti a partecipare all''Edizione della Memoria degli Hunger Games.', 'https://image.tmdb.org/t/p/w500/vrQHDXjVmbYzadOXQ0UaObunoy2.jpg', '2026-10-11T16:25:26.673485', 'Jennifer Lawrence, Josh Hutcherson, Liam Hemsworth, Woody Harrelson, Elizabeth Banks, Philip Seymour Hoffman'),
(202, 'Hunger Games (The Hunger Games)', 2012, 'Gary Ross', 'Fantascienza, Azione, Avventura', 'In un futuro distopico, la sedicenne Katniss Everdeen si offre volontaria al posto della sorella minore per partecipare agli Hunger Games, un brutale reality show televisivo in cui ventiquattro adolescenti combattono all''ultimo sangue.', 'https://image.tmdb.org/t/p/w500/apa5G43Hha7kH7wJG0gkkHT7FA9.jpg', '2026-10-11T16:25:26.586082', 'Jennifer Lawrence, Josh Hutcherson, Liam Hemsworth, Woody Harrelson, Elizabeth Banks, Donald Sutherland'),
(209, 'Minions', 2015, 'Pierre Coffin, Kyle Balda', 'Animazione, Commedia, Avventura', 'Evolutisi da organismi unicellulari gialli, i Minions cercano disperatamente un padrone malvagio da servire. Nel 1968, Kevin, Stuart e Bob partono per una missione che li condurrà da Scarlet Sterminator.', 'https://image.tmdb.org/t/p/w500/dr02BdCNAUPVU07aOodwPYv6HCf.jpg', '2026-10-11T16:57:54.06741', 'Sandra Bullock, Jon Hamm, Michael Keaton, Pierre Coffin'),
(207, 'Cattivissimo me (Despicable Me)', 2010, 'Pierre Coffin, Chris Renaud', 'Animazione, Commedia, Avventura', 'Il supercattivo Gru pianifica di rubare la Luna con l''aiuto dei suoi piccoli assistenti gialli, i Minions, ma il suo piano viene scompaginato dall''incontro con tre bambine orfane.', 'https://image.tmdb.org/t/p/w500/b1BT309QWjtFUlJPLmXmrcHOWEL.jpg', '2026-10-11T16:57:53.672317', 'Steve Carell, Jason Segel, Russell Brand, Pierre Coffin'),
(208, 'Cattivissimo me 2 (Despicable Me 2)', 2013, 'Pierre Coffin, Chris Renaud', 'Animazione, Commedia, Avventura', 'Gru viene reclutato dalla Lega Anti-Cattivi per indagare sulla scomparsa di un laboratorio segreto e sulla trasformazione dei suoi Minions in mostri viola indistruttibili.', 'https://image.tmdb.org/t/p/w500/5Fh4NdoEnCjCK9wLjdJ9DJNFl2b.jpg', '2026-10-11T16:57:53.867978', 'Steve Carell, Kristen Wiig, Benjamin Bratt, Pierre Coffin'),
(210, 'Cattivissimo me 3 (Despicable Me 3)', 2017, 'Pierre Coffin, Kyle Balda', 'Animazione, Commedia, Avventura', 'Dopo essere stato licenziato dalla Lega Anti-Cattivi, Gru scopre di avere un fratello gemello ricco e stravagante di nome Dru, mentre i Minions affrontano una breve ribellione.', 'https://image.tmdb.org/t/p/w500/e72KCMHNkbZ6USRJmABeqwmaJ5n.jpg', '2026-10-11T16:57:54.243381', 'Steve Carell, Kristen Wiig, Trey Parker, Pierre Coffin'),
(205, 'Hunger Games: Il canto della rivolta - Parte 2 (The Hunger Games: Mockingjay - Part 2)', 2015, 'Francis Lawrence', 'Fantascienza, Azione, Avventura', 'Con Panem in guerra totale, Katniss guida la squadra d''assalto verso Capitol City per affrontare direttamente il Presidente Snow e porre fine alla tirannia.', 'https://image.tmdb.org/t/p/w500/aQvME1wpAZpjdyg5Xfe35lINmwt.jpg', '2026-10-11T16:25:26.877919', 'Jennifer Lawrence, Josh Hutcherson, Liam Hemsworth, Woody Harrelson, Elizabeth Banks, Julianne Moore'),
(211, 'Minions 2 - Come Gru diventa cattivissimo (Minions: The Rise of Gru)', 2022, 'Kyle Balda', 'Animazione, Commedia, Avventura', 'Negli anni ''70, il dodicenne Gru tenta di entrare a far parte di un gruppo di supercattivi chiamato I Malefici 6. Quando il suo colloquio va male, i Minions intervengono per aiutarlo.', 'https://image.tmdb.org/t/p/w500/j0w5tggQs0VVtXj5OF8kWqME2WG.jpg', '2026-10-11T16:57:54.450742', 'Steve Carell, Pierre Coffin, Taraji P. Henson, Michelle Yeoh'),
(212, 'Cattivissimo me 4 (Despicable Me 4)', 2024, 'Chris Renaud', 'Animazione, Commedia, Avventura', 'Gru, Lucy e le loro figlie accolgono un nuovo membro in famiglia, Gru Jr., ma sono costretti alla fuga quando il supercriminale Maxime Le Mal evade di prigione per vendicarsi.', 'https://image.tmdb.org/t/p/w500/wWba3TaojhK7NdycRhoQpsG0FaH.jpg', '2026-10-11T16:57:54.635395', 'Steve Carell, Kristen Wiig, Will Ferrell, Sofia Vergara, Pierre Coffin'),
(213, 'Heart of the Sea - Le origini di Moby Dick (In the Heart of the Sea)', 2015, 'Ron Howard', 'Avventura, Drammatico, Storico', 'Nel inverno del 1820, la baleniera del New England Essex viene assalita da una creatura incredibile: una balena dalle dimensioni e dalla forza mastodontiche, con un senso quasi umano di vendetta. Il disastro marittimo realmente accaduto avrebbe ispirato Herman Melville a scrivere Moby Dick.', 'https://image.tmdb.org/t/p/w500/weVvNPfk6FM9vBg3BXtRtNAmiYM.jpg', '2026-10-17T15:11:52.216085', 'Chris Hemsworth, Benjamin Walker, Cillian Murphy, Tom Holland, Brendan Gleeson, Ben Whishaw'),
(214, 'Prisoners', 2013, 'Denis Villeneuve', 'Thriller, Drammatico, Mystery', 'Dopo la scomparsa della figlia di sei anni e della sua amica durante il Giorno del Ringraziamento, Keller Dover affronta il peggior incubo di ogni genitore. Il detective Loki guida le indagini e arresta l''unico sospettato, ma è costretto a rilasciarlo per mancanza di prove. Preso dalla disperazione e vedendo la polizia brancolare nel buio, Keller decide di farsi giustizia da solo, spingendosi oltre ogni limite pur di salvare le bambine.', 'https://image.tmdb.org/t/p/w500/uhviyknTT5cEQXbn6vWIqfM4vGm.jpg', '2026-10-17T17:44:48.655806', 'Hugh Jackman, Jake Gyllenhaal, Viola Davis, Maria Bello, Terrence Howard, Melissa Leo, Paul Dano'),
(216, 'La leggenda del pianista sull''oceano (The Legend of 1900)', 1998, 'Giuseppe Tornatore', 'Drammatico, Musicale', 'La storia di Danny Boodmann T.D. Lemon Novecento, un pianista straordinario nato e cresciuto a bordo del transatlantico Virginian, senza mai mettere piede sulla terraferma. La sua vita e il suo incredibile talento vengono raccontati dal suo grande amico, il trombettista Max Tooney.', 'https://image.tmdb.org/t/p/w500/iOcbJ5pxokOPDRgieVDbsFMrCc6.jpg', '2026-10-17T23:29:21.408922', 'Tim Roth, Pruitt Taylor Vince, Mélanie Thierry, Bill Nunn, Peter Vaughan, Clarence Williams III'),
(118, 'The Hateful Eight', 2015, 'Quentin Tarantino', 'Western, Giallo, Thriller', 'Qualche anno dopo la guerra civile americana, una diligenza si fa strada nel paesaggio innevato del Wyoming. I passeggeri, tra cui il cacciatore di taglie John Ruth e la sua prigioniera Daisy Domergue, cercano rifugio da una tempesta di neve in un emporio, dove si imbattono in altri loschi personaggi. La diffidenza e la tensione tra i presenti porteranno a una sanguinosa resa dei conti.', 'https://image.tmdb.org/t/p/w500/jIywvdPjia2t3eKYbjVTcwBQlG8.jpg', '2026-09-18T10:34:27.295046', 'Samuel L. Jackson, Kurt Russell, Jennifer Jason Leigh, Walton Goggins, Demián Bichir, Tim Roth, Michael Madsen, Bruce Dern'),
(44, 'Agente 007 - Licenza di uccidere', 1962, 'Terence Young', 'Spionaggio, Azione, Avventura', 'L''agente segreto britannico James Bond, noto come 007, viene inviato in Giamaica per indagare sulla misteriosa scomparsa di un suo collega, lo chef della sezione di Kingston, e della sua segretaria. Con l''aiuto dell''agente della CIA Felix Leiter e del luogo Quarrel, Bond risale le tracce fino all''isola sotterranea di Crab Key. Lì fa la conoscenza della splendida Honey Ryder e scopre il covo del sinistro Dottor No, un genio del male affiliato all''organizzazione criminale SPECTRE. Dr. No intende utilizzare un''arma a raggi atomici per deviare la rotta dei missili spaziali americani lanciati da Cape Canaveral. 007 dovrà fare affidamento sulle sue abilità e sul suo fascino per distruggere la base segreta e sventare la minaccia globale.', 'https://image.tmdb.org/t/p/w500/9zCOLJmLNst0sCPZlkW1IRoH65E.jpg', '2026-09-14T13:48:35.238938', 'Sean Connery, Ursula Andress, Joseph Wiseman, Jack Lord, Bernard Lee'),
(51, 'Avengers: Infinity War', 2018, 'Anthony e Joe Russo', 'Azione, Fantascienza, Avventura', 'Gli Avengers e i loro alleati supereroi devono essere pronti a sacrificare tutto nel tentativo di sconfiggere il potente Thanos, prima che il suo devastante attacco ponga fine all''universo. Il tiranno cosmico è alla ricerca delle sei Gemme dell''Infinito, manufatti di inimmaginabile potere, con l''obiettivo di dimezzare la popolazione dell''universo e portare un folle equilibrio.', 'https://image.tmdb.org/t/p/w500/7WsyChQLEftFiDOVTGkv3hFpyyt.jpg', '2026-09-14T13:51:08.090595', 'Robert Downey Jr., Chris Hemsworth, Mark Ruffalo, Chris Evans, Scarlett Johansson, Benedict Cumberbatch, Tom Holland, Chadwick Boseman, Josh Brolin, Zoe Saldana'),
(133, 'C''era una volta a... Hollywood', 2019, 'Quentin Tarantino', 'Drammatico, Commedia', 'Nella Los Angeles del 1969, un attore televisivo in declino e la sua controfigura e migliore amico cercano di navigare nei cambiamenti dell''industria cinematografica, mentre sullo sfondo si consumano le vicende legate alla setta di Charles Manson.', 'https://image.tmdb.org/t/p/w500/8j58iEBw9pOXFD2L0nt0ZXeHviB.jpg', '2026-09-19T19:47:16.734724', 'Leonardo DiCaprio, Brad Pitt, Margot Robbie'),
(16, 'Bianca e Bernie nella terra dei canguri', 1990, 'Hendel Butoy, Mike Gabriel', 'Animazione, Avventura, Commedia, Famiglia', 'Nell''Outback australiano, un ragazzino di nome Cody fa amicizia con Marahute, una gigantesca e rarissima aquila dorata. Quando il crudele bracconiere Percival McLeach lo scopre, rapisce Cody con l''intento di farsi rivelare l''ubicazione del nido dell''animale. La Società Internazionale di Salvataggio allerta immediatamente i due celebri agenti speciali a quattro zampe, Bianca e Bernie. Volando in Australia a bordo dell''albatros Wilbur e affiancati dalla guida locale Jake, un vivace topo saltatore, i due intraprenderanno una rischiosa missione per liberare Cody e salvare Marahute.', 'https://image.tmdb.org/t/p/w500/5koTDBmMAkJOgAe4PL4163UKjvG.jpg', '2026-09-13T14:58:32.038641', 'Bob Newhart, Eva Gabor, John Candy, George C. Scott, Tristan Rogers'),
(220, 'Quo Vadis?', 1924, 'Gabriellino D''Annunzio, Georg Jacoby', 'Storico, Drammatico', 'Imponente kolossal muto che mette in scena la follia dell''imperatore Nerone e il tragico destino dei primi cristiani a Roma, intrecciato con la storia d''amore tra Marco Vinicio e la giovane Licia.', 'https://image.tmdb.org/t/p/w500/9XznF1gIXfgqzEs6La7vXMW46sM.jpg', '2026-10-18T02:03:26.62268', 'Emil Jannings, Elena Sangro, Lillian Hall-Davis, Alfons Fryland'),
(222, 'Quo Vadis?', 1985, 'Franco Rossi', 'Storico, Drammatico', 'Adattamento televisivo del capolavoro di Henryk Sienkiewicz che racconta l''ascesa del cristianesimo nella Roma imperiale e la deriva tirannica e folle di Nerone.', 'https://www.themoviedb.org/t/p/w600_and_h900_face/4AD9VxrSItAjOUIdAkDwSD4xXDu.jpg', '2026-10-18T02:03:26.666969', 'Klaus Maria Brandauer, Frederic Forrest, Cristina Raines, Francesco Quinn'),
(47, 'Casino Royale', 2006, 'Martin Campbell', 'Azione, Spionaggio, Thriller', 'Dopo aver ottenuto lo status di agente 00 e la licenza di uccidere, James Bond viene inviato in missione per fermare Le Chiffre, un brillante e spietato banchiere che finanzia organizzazioni terroristiche internazionali. Avendo perso ingenti somme di denaro appartenenti ai suoi pericolosi clienti a causa di un attentato sventato dallo stesso Bond, Le Chiffre organizza una partita di poker Texas Hold''em ad altissima posta al Casino Royale, in Montenegro, nel tentativo disperato di recuperare i fondi. L''MI6 affida a Bond il compito di batterlo al tavolo verde per costringerlo a chiedere asilo al governo britannico in cambio di informazioni cruciali. Affiancato dall''affascinante e riservata funzionaria del Tesoro Vesper Lynd, incaricata di monitorare i fondi statali della posta in gioco, l''agente 007 si ritrova invischiato in un mortale gioco di strategia, inganni e violenza, che lo porterà a scoprire il peso emotivo del proprio mestiere e il sapore del tradimento.', 'https://image.tmdb.org/t/p/w500/lMrxYKKhd4lqRzwUHAy5gcx9PSO.jpg', '2026-09-14T13:49:14.542444', 'Daniel Craig, Eva Green, Mads Mikkelsen, Judi Dench, Jeffrey Wright'),
(116, 'Lei', 2013, 'Spike Jonze', 'Fantascienza, Drammatico, Sentimentale', 'In un futuro non troppo lontano, Theodore, un uomo solitario e introverso che scrive lettere d''amore per conto terzi, acquista un nuovo sistema operativo basato su un''intelligenza artificiale estremamente avanzata. Ben presto, tra Theodore e la voce del sistema operativo, che si autodefinisce Samantha, nasce una profonda e insolita relazione sentimentale.', 'https://image.tmdb.org/t/p/w500/8sSc94dznzIKuYMna2pWrGSW2c2.jpg', '2026-09-17T18:13:20.24262', 'Joaquin Phoenix, Scarlett Johansson, Amy Adams, Rooney Mara, Olivia Wilde'),
(30, 'L''indiana bianca', 1953, 'Ray Nazarro', 'Western', 'Nel selvaggio West, Sharon Purcell, una giovane donna per metà bianca e per metà nativa americana, vive al confine tra le due culture affrontando il disprezzo e il pregiudizio di entrambe le comunità. La situazione degenera quando un potente e avido proprietario terriero tenta con ogni mezzo di sottrarre le terre alla tribù indiana locale per espandere il proprio dominio. In mezzo alle crescenti tensioni e allo scoppio delle ostilità, Sharon cercherà disperatamente di favorire la convivenza pacifica, aiutata da un coraggioso funzionario governativo determinato a ristabilire la giustizia e a far rispettare i trattati.', 'https://image.tmdb.org/t/p/w500/awt4WEDwcKuTw4oaiLwzfh7xnt7.jpg', '2026-09-13T15:08:13.288587', 'David Brian, May Wynn, William Bishop, Nancy Hale, Robert Lowery'),
(84, 'Va'' e vedi', 1985, 'Elem Klimov', 'Guerra, Drammatico, Storico', 'Durante la seconda guerra mondiale, nella Bielorussia del 1943 occupata dalle forze naziste, il giovane Florya decide di unirsi alla resistenza partigiana contro l''invasore. Attraverso il suo tragico viaggio, il ragazzo sarà testimone diretto delle atrocità più disumane, dei massacri sistematici dei villaggi e della devastazione psicologica e fisica causata dalla guerra, perdendo prematuramente la propria innocenza in un crescendo di orrore.', 'https://image.tmdb.org/t/p/w500/qNbMsKVzigERgJUbwf8pKyZogpb.jpg', '2026-09-15T20:51:59.379926', 'Aleksej Kravčenko, Ol''ga Mironova, Liubomiras Laucevičius'),
(65, 'Robin e Marian', 1976, 'Richard Lester', 'Avventura, Drammatico, Romantico', 'Un invecchiato Robin Hood ritorna in Inghilterra dopo vent''anni trascorsi a combattere nelle Crociate al seguito di Re Riccardo. Trova la sua amata Marian che, nel frattempo, si è ritirata in convento diventando badessa. Nonostante il tempo trascorso e le ferite della vita, il loro antico amore si riaccende. Tuttavia, Robin si ritrova ben presto a dover affrontare nuovamente il suo storico avversario, lo Sceriffo di Nottingham, in un ultimo e tragico scontro che segnerà il destino dei due amanti.', 'https://image.tmdb.org/t/p/w500/y2UlVt6U8mFeegVL42rZjD5y6c7.jpg', '2026-09-15T18:04:05.581875', 'Sean Connery, Audrey Hepburn, Robert Shaw, Richard Harris, Nicol Williamson'),
(106, 'Farewell Oak Street', 1953, 'Grant McLean', 'Documentario', 'Questo documentario canadese analizza le degradate condizioni di vita nel quartiere di Regent Park a Toronto prima della sua ricostruzione. Attraverso il contrasto tra i vecchi slum di Oak Street e i nuovi complessi di edilizia popolare, l''opera illustra l''impatto positivo che una pianificazione urbana moderna e alloggi dignitosi hanno sulla salute, sulla sicurezza e sul benessere sociale delle famiglie.', 'https://image.tmdb.org/t/p/w500/1YHZU9dKVch25GChAg22hiYEdR9.jpg', '2026-09-17T11:01:31.104209', 'Lamont Tilden (voce narrante)'),
(217, 'The Book of Boba Fett', 2021, 'Robert Rodriguez, Jon Favreau, Bryce Dallas Howard, Dave Filoni', 'Fantascienza, Azione, Avventura', 'Il leggendario cacciatore di taglie Boba Fett e la mercenaria Fennec Shand tornano sulle sabbie di Tatooine per rivendicare il territorio un tempo controllato da Jabba the Hutt e dal suo sindacato criminale.', 'https://www.themoviedb.org/t/p/w600_and_h900_face/lQqbnWsGt9RBGBWrmUKUOXZkl7N.jpg', '2026-10-18T00:57:36.992966', 'Temuera Morrison, Ming-Na Wen, Pedro Pascal'),
(76, 'Star Wars: Il risveglio della Forza', 2015, 'J.J. Abrams', 'Fantascienza', 'Trent''anni dopo la caduta dell''Impero, sorge una nuova minaccia nota come Primo Ordine guidata da Kylo Ren. Una giovane orfana di nome Rey scopre la sua potente connessione con la Forza e parte alla ricerca dello scomparso Luke Skywalker.', 'https://image.tmdb.org/t/p/w500/uEDFRwKiTOsIsN5dkEPCj1laIAK.jpg', '2026-09-15T19:21:49.969942', 'Mark Hamill, Harrison Ford, Carrie Fisher, Peter Cushing, Alec Guinness'),
(80, 'Guerre stellari: Episodio V - L''Impero colpisce ancora', 1980, 'Irvin Kershner', 'Fantascienza', 'Dopo la distruzione della Morte Nera, le forze imperiali inseguono implacabilmente i Ribelli attraverso la galassia. Mentre Han Solo e Leila sfuggono alla flotta nemica rifugiandosi nella Città delle Nuvole, Luke si reca sul pianeta Dagobah per addestrarsi con il maestro Yoda. Lo scontro imminente con Dart Fener porterà alla luce una sconvolgente verità sul suo passato.', 'https://image.tmdb.org/t/p/w500/nNAeTmF4CtdSgMDplXTDPOpYzsX.jpg', '2026-09-15T19:22:13.819762', 'Mark Hamill, Harrison Ford, Carrie Fisher, Billy Dee Williams, Anthony Daniels'),
(204, 'Hunger Games: Il canto della rivolta - Parte 1 (The Hunger Games: Mockingjay - Part 1)', 2014, 'Francis Lawrence', 'Fantascienza, Azione, Avventura', 'Katniss si ritrova nel Distretto 13 dopo aver distrutto l''arena. Guidata dalla Presidente Coin, accetta di diventare la Ghiandaia Imitatrice, simbolo della rivoluzione contro Panem.', 'https://image.tmdb.org/t/p/w500/9LZSYohDOJkLU2TyRvPM1zIo62e.jpg', '2026-10-11T16:25:26.778038', 'Jennifer Lawrence, Josh Hutcherson, Liam Hemsworth, Woody Harrelson, Elizabeth Banks, Julianne Moore')
INSERT INTO public.films ("id", "titolo", "anno", "regista", "genere", "trama", "poster_url", "creato_il", "attori") VALUES
(223, 'Quo Vadis', 2001, 'Jerzy Kawalerowicz', 'Storico, Drammatico', 'Produzione polacca ad alto budget altamente fedele al romanzo originale, centrata sul contrasto tra la decadenza edonistica della Roma di Nerone e la nascente fede dei primi cristiani.', 'https://image.tmdb.org/t/p/w500/rzePNmvU9Kczxu60TUoyzVED5xy.jpg', '2026-10-18T02:03:26.692321', 'Pawel Delag, Magdalena Mielcarz, Boguslaw Linda, Michal Bajor'),
(221, 'Quo Vadis', 1951, 'Mervyn LeRoy', 'Storico, Drammatico, Kolossal', 'Di ritorno dalle campagne militari, il comandante romano Marco Vinicio si innamora della cristiana Licia. Quando l''imperatore Nerone incendia Roma e accusa i cristiani, la coppia viene travolta dalle persecuzioni.', 'https://image.tmdb.org/t/p/w500/dqF1dattMNiwGjPSphu2VSi558Q.jpg', '2026-10-18T02:03:26.648582', 'Robert Taylor, Deborah Kerr, Peter Ustinov, Leo Genn'),
(219, 'Quo Vadis?', 1913, 'Enrico Guazzoni', 'Storico, Drammatico', 'Nella Roma dell''imperatore Nerone, il giovane tribuno Marco Vinicio si innamora della cristiana Licia. Tra intrighi di corte, l''incendio della città e il martirio dei primi cristiani, il loro amore affronterà terribili prove.', 'https://image.tmdb.org/t/p/w500/xbA8ljsXMgOnbkN3X5li9UzFSvf.jpg', '2026-10-18T02:03:26.575471', 'Amleto Novelli, Gustavo Serena, Lea Giunchi, Bruto Castellani'),
(224, 'Spartacus', 1960, 'Stanley Kubrick', 'Storico, Drammatico, Avventura', 'Nel I secolo a.C., il gladiatore trace Spartaco guida una vasta ribellione di schiavi contro la Repubblica romana. Dopo aver sconfitto diverse legioni e radunato migliaia di seguaci in cerca di libertà, l''esercito dei ribelli si scontra con le ambizioni politiche del patrizio Marco Licinio Crasso, determinato a schiacciare la rivolta per consolidare il proprio potere su Roma.', 'https://image.tmdb.org/t/p/w500/nqU4xAn3ygWA4fvXSBufRwdGhpr.jpg', '2026-10-18T13:31:43.100209', 'Kirk Douglas, Laurence Olivier, Jean Simmons, Charles Laughton, Peter Ustinov, John Gavin, Tony Curtis'),
(232, 'Home Sweet Home Alone - Mamma, ho perso l''aereo (Home Sweet Home Alone)', 2021, 'Dan Mazer', 'Commedia, Film per famiglie', 'Il giovanissimo Max Mercer viene accidentalmente lasciato a casa da solo quando la sua famiglia parte per il Giappone. Deve proteggere la sua abitazione da una coppia di coniugi in difficoltà finanziarie che tenta di recuperare un prezioso cimelio di famiglia.', 'https://image.tmdb.org/t/p/w500/fP3VvqUjEBjawxZHL4sYCq2ZdJD.jpg', '2026-10-23T13:14:06.720403', 'Archie Yates, Ellie Kemper, Rob Delaney, Aisling Bea, Kenan Thompson'),
(227, 'Mamma, ho perso l''aereo (Home Alone)', 1990, 'Chris Columbus', 'Commedia, Film per famiglie', 'Il piccolo Kevin McCallister viene sbadatamente dimenticato a casa dalla famiglia in partenza per le vacanze di Natale a Parigi. Rimasto solo, deve difendere la propria abitazione da due maldestri ladri d''appartamento usando ingegnose trappole.', 'https://image.tmdb.org/t/p/w500/onTSipZ8R3bliBdKfPtsDuHTdlL.jpg', '2026-10-23T13:14:06.497613', 'Macaulay Culkin, Joe Pesci, Daniel Stern, Catherine O''Hara, John Heard'),
(234, 'Ultima notte a Soho', 2021, 'Edgar Wright', 'Horror, Mistero, Thriller', 'Eloise, ventenne cresciuta con la nonna dopo il suicidio della madre, arriva a Londra con il sogno di diventare stilista. Ha il mito della Swingin'' London e della musica anni ''60, che ascolta continuamente su vecchi 33 giri portatili. Dopo un''infelice esperienza nello studentato della scuola di moda in cui è stata ammessa, si trasferisce in un appartamento di Soho affittato da un''anziana signora. Qui, durante lunghe notti agitate, Eloise sogna di tornare nel passato, nella Londra che ama di più, dove incontra Sandie, un''aspirante cantante che vive il glamour di una città colorata ed esaltante. Poco alla volta, però, Eloise confonde la propria personalità con quella di Sandie e ne scopre la vita in realtà miserabile, scivolando tra realtà e incubo in un''esperienza spaventosa.', 'https://image.tmdb.org/t/p/w500/mNuXKuiywifooo8LnAzMy0W4ZiK.jpg', '2026-10-24T14:57:49.238234', 'Thomasin McKenzie, Anya Taylor-Joy, Matt Smith, Rita Tushingham, Michael Ajao, Synnøve Karlsen, Pauline McLynn'),
(225, 'L''ultimo samurai (The Last Samurai)', 2003, 'Edward Zwick', 'Azione, Drammatico, Storico', 'Nel 1876 il veterano della guerra civile americana Nathan Algren viene assoldato dall''imperatore giapponese per addestrare il nuovo esercito secondo i metodi occidentali e sedare la ribellione guidata dal samurai Katsumoto. Catturato dai ribelli, Algren scopre il loro stile di vita e il codice d''onore dei samurai, finendo per abbracciare la loro causa contro la modernizzazione forzata e spietata del Paese.', 'https://image.tmdb.org/t/p/w500/hHYbOZVogfOIVg4FEF2Hs2UUNHs.jpg', '2026-10-21T20:28:35.78698', 'Tom Cruise, Ken Watanabe, Koyuki, Hiroyuki Sanada, Shin Koyamada, Timothy Spall, Billy Connolly'),
(226, 'L''ultimo samurai (Ôkami yo rakujitsu o)', 1974, 'Kenji Misumi', 'Azione, Drammatico, Storico', 'Durante il periodo del Bakumatsu e il declino dello shogunato Tokugawa, un maestro di spada fedele alla tradizione samurai si trova diviso tra amicizia, dovere e il turbine dei conflitti sanguinosi che segnano la nascita del Giappone moderno.', 'https://image.tmdb.org/t/p/w500/o4WHApeJWxu3QVYRbDzg1cEtGfd.jpg', '2026-10-21T20:28:35.826744', 'Hideki Takahashi, Ken Ogata, Keiko Matsuzaka, Kiwako Taichi, Teruhiko Aoi'),
(230, 'Mamma, ho allagato la casa (Home Alone 4: Taking Back the House)', 2002, 'Rod Daniel', 'Commedia, Film per famiglie', 'Kevin McCallister trascorre il Natale nella villa super tecnologica della nuova fidanzata del padre. Lì dovrà impedire il rapimento di un giovane principe da parte del suo vecchio nemico Marv e della sua nuova complice.', 'https://image.tmdb.org/t/p/w500/zfm0UYbIpOpL8ak9tf655h3GWS2.jpg', '2026-10-23T13:14:06.654706', 'Mike Weinberg, French Stewart, Missi Pyle, Barbara Babcock'),
(229, 'Mamma, ho preso il morbillo (Home Alone 3)', 1997, 'Raja Gosnell', 'Commedia, Film per famiglie', 'Il piccolo Alex è costretto a rimanere a casa con il morbillo. Si troverà a dover affrontare quattro pericolosi criminali internazionali intenzionati a recuperare un prezioso microchip militare nascosto all''interno di un''auto radiocomandata finita per sbaglio nelle sue mani.', 'https://image.tmdb.org/t/p/w500/s1PwvbnNicaxT6wdlMZJqrW0yQt.jpg', '2026-10-23T13:14:06.612786', 'Alex D. Linz, Olek Krupa, Rya Kihlstedt, Scarlett Johansson'),
(228, 'Mamma, ho riperso l''aereo - Mi sono smarrito a New York (Home Alone 2: Lost in New York)', 1992, 'Chris Columbus', 'Commedia, Film per famiglie', 'Durante la confusione dell''imbarco per le vacanze natalizie in Florida, Kevin si imbarca per errore su un volo diretto a New York. Nella grande mela si ritroverà ad affrontare nuovamente i ladri Harry e Marv, evasi nel frattempo dal carcere.', 'https://image.tmdb.org/t/p/w500/eYKQJmrEyANdUcE7nJ7PQ6XARaO.jpg', '2026-10-23T13:14:06.551817', 'Macaulay Culkin, Joe Pesci, Daniel Stern, Catherine O''Hara, Tim Curry'),
(231, 'Mamma, ho visto i fantasmi! (Home Alone: The Holiday Heist)', 2012, 'Peter Hewitt', 'Commedia, Film per famiglie', 'Finn si trasferisce con la famiglia in una nuova casa nel Maine che crede infestata dai fantasmi. Quando i genitori rimangono bloccati fuori città, Finn deve proteggere la dimora da una banda di tre ladri d''arte a caccia di un dipinto dal valore inestimabile.', 'https://image.tmdb.org/t/p/w500/nsRl6M33UjKNpHDIRoGW81WX89H.jpg', '2026-10-23T13:14:06.677956', 'Christian Martyn, Jodelle Ferland, Malcolm McDowell, Debi Mazar'),
(235, 'Mamma ho perso il lavoro', 2008, 'Vince Di Meglio', 'Commedia, Dramma, Romance', 'After he''s fired from his job, an everyday guy faces pressure from his wife to have a baby and from his mom, who has decided to move in with the young couple.', 'https://image.tmdb.org/t/p/w500/2vLLJG71kmrCcTbnIztn13NHKZF.jpg', '2026-10-24T15:53:17.012565', 'Diane Keaton, Dax Shepard, Liv Tyler, Ken Howard, Jerry Lambert, Selma Stern, Mike White'),
(236, 'L''esercito delle 12 scimmie', 1995, 'Terry Gilliam', 'Fantascienza, Thriller, Mistero', 'L''Esercito delle 12 scimmie è un piccolo gioiellino fantascientifico del 1995 che si focalizza sulla disperazione di un singolo uomo, condannato a essere il prescelto per trovare un rimedio alla situazione disastrosa dell''umanità, in un futuro ormai abitato da una razza umana rassegnata. Nel 2035 gli esseri umani vivono nel sottosuolo, terrorizzati dall''ambiente esterno, portatore di un virus mortale che li ha decimati, rendendo il pianeta Terra un luogo dove i prigionieri sono diventati loro stessi. Anche se solo in modo approssimativo, gli scienziati di quel terribile futuro hanno reso possibile il viaggio nel tempo, unica possibilità per poter mettere le mani sul virus e crearne una cura.', 'https://image.tmdb.org/t/p/w500/9WfkdEGHO8K0AF8ahbc34zMzM4e.jpg', '2026-10-24T15:59:00.865215', 'Bruce Willis, Madeleine Stowe, Brad Pitt, Christopher Plummer, David Morse, Jon Seda, Christopher Meloni'),
(79, 'Guerre stellari: Episodio IV - Una nuova speranza', 1977, 'George Lucas', 'Fantascienza', 'Il giovane Luke Skywalker entra in possesso di droidi contenenti i piani segreti della Morte Nera, la potente arma dell''Impero Galattico. Guidato dal saggio maestro Jedi Obi-Wan Kenobi e affiancato dal contrabbandiere Han Solo, Luke intraprende un''audace missione per salvare la Principessa Leila. Insieme, guideranno l''Alleanza Ribelle nel disperato tentativo di distruggere la stazione imperiale.', 'https://image.tmdb.org/t/p/w500/fVqKwpvobwWy0P1UImZWIDuw4RI.jpg', '2026-09-15T19:22:13.623129', 'Mark Hamill, Harrison Ford, Carrie Fisher, Peter Cushing, Alec Guinness'),
(238, 'L''esorcista', 1973, 'William Friedkin', 'Horror', 'In un quartiere tranquillo, in una casa dotata di tutti i moderni comfort, una ragazzina modello cade ammalata. La madre non può aiutarla. I medici non riescono ad elaborare una diagnosi. Temendo che le crisi di cui soffre la figlia non riguardino solo la sfera fisica, ma anche quella spirituale, la donna si rivolge a un sacerdote. L''uomo però dubita della presenza del diavolo in quella casa, in quel corpo e la debolezza delle sue convinzioni non farà altro che rendere più forte il maligno.', 'https://image.tmdb.org/t/p/w500/49uIBJqG4ugL7KC2yBhz0nCLeHG.jpg', '2026-10-25T08:34:21.259526', 'Ellen Burstyn, Linda Blair, Jason Miller, Max von Sydow, Lee J. Cobb, William O''Malley, Kitty Winn'),
(239, 'Halloween - La notte delle streghe', 1978, 'John Carpenter', 'Horror, Thriller', 'Micheal, a soli 6 anni ammazza la sorella e viene internato ma dopo 15 anni fugge per recarsi al suo paese. E'' il 31 Ottobre, e secondo l''antica tradizione americana è la notte in cui si esorcizzano le streghe, grazie a questa concomitanza Micheal può mietere altre vittime.', 'https://image.tmdb.org/t/p/w500/uxLqrN38fSQEUVpM4S1suhnW3X.jpg', '2026-10-25T12:31:42.720576', 'Donald Pleasence, Jamie Lee Curtis, Nancy Kyes, P. J. Soles, Charles Cyphers, Kyle Richards, Brian Andrews'),
(240, 'It - Capitolo uno', 2017, 'Andy Muschietti', 'Horror, Thriller, Dramma', 'Ottobre 1988, nella cittadina di Derry. Il piccolo Georgie esce di casa nella pioggia per far navigare la barchetta di carta preparatagli dal fratello maggiore Billy, costretto a casa dall''influenza. La barchetta scorre per i rivoli lungo i marciapiedi, ma finisce in uno scolo che conduce alla rete fognaria. Georgie, contrariato, si china a guardare nella feritoia e incontra lo sguardo del bizzarro clown che abita nelle fogne, Pennywise. Per quanto strano sia trovare un clown in quel luogo, Georgie si intrattiene con lui sin quando il clown non lo addenta e lo cattura portandolo giù con sé. Giugno 1989. A Derry vige il coprifuoco a causa delle numerose sparizioni di persone, soprattutto bambini.', 'https://image.tmdb.org/t/p/w500/ru0gDnxKzBjzrPxfRyZIuse9hfu.jpg', '2026-10-25T12:35:25.301766', 'Jaeden Martell, Jeremy Ray Taylor, Sophia Lillis, Finn Wolfhard, Chosen Jacobs, Jack Dylan Grazer, Wyatt Oleff')
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza") VALUES
(764, 144, '00:46:25', 'Continuità / Oggetti di scena', 'Durante il primo incontro tra Shosanna e il Maggiore Hellstrom nel ristorante, la posizione del piattino, la quantità di panna sullo strudel e la sigaretta nel posacenere cambiano tra le inquadrature frontali e quelle di controcampo.', TRUE, '2026-09-28T10:37:29.693506', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(765, 144, '01:12:10', 'Continuità / Abbigliamento', 'Nella scena della taverna ''La Louisiane'', il nastro della decorazione militare sul petto del sergente Wilhelm cambia orientamento e inclinazione svariate volte durante la conversazione tesa al tavolo.', TRUE, '2026-09-28T10:37:29.693506', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(766, 144, '01:24:35', 'Continuità / Posizione', 'Sempre durante il confronto nella taverna, il livello di scotch nel bicchiere impugnato da Archie Hicox (Michael Fassbender) oscilla tra quasi vuoto e parzialmente riempito tra stacchi di montaggio consecutivi senza che lui beva o verser da bere.', TRUE, '2026-09-28T10:37:29.693506', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(767, 144, '01:52:15', 'Continuità / Costumi e Trucco', 'L''ingessatura alla gamba di Bridget von Hammersmark (Diane Kruger) varia visibilmente in spessore e modellatura tra la scena della medicazione privata e l''arrivo nel foyer del cinema per la première.', TRUE, '2026-09-28T10:37:29.693506', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(768, 144, '02:14:10', 'Continuità / Trucco', 'Nella cabina di proiezione, dopo che Shosanna spara a Frederick Zoller, la posizione del corpo di Zoller a terra e la disposizione delle macchie di sangue sulla sua uniforme cambiano nel momento in cui la donna si avvicina per voltarlo.', TRUE, '2026-09-28T10:37:29.693506', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(769, 144, '02:22:50', 'Continuità / Trucco e Posizione', 'Nella sequenza finale nel bosco, le rivoli di sangue che scendono dal taglio a forma di svastica sulla fronte di Hans Landa (Christoph Waltz) cambiano traiettoria e densità tra il primo piano dell''incisione e l''ultima inquadratura dall''alto.', TRUE, '2026-09-28T10:37:29.693506', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(763, 144, '00:31:10', 'Continuità / Trucco', 'La svastica incisa sulla fronte del soldato Butz da Aldo Raine mostra una forma, una profondità di taglio e una quantità di sangue nettamente differenti tra la scena dell''interrogatorio nel bosco e il successivo flashback nello studio di Hitler.', TRUE, '2026-09-28T10:37:29.693506', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(755, 143, '00:12:15', 'Incongruenza scientifica / Audio', 'Durante le scene con i delfini Cindy e Sandy, si sentono chiaramente i loro tipici versi mentre sono sott''acqua. Nella realtà, i delfini non producono quel tipo di vocalizzazioni udibili all''orecchio umano in quel modo sott''acqua senza rilasciare bolle d''aria.', TRUE, '2026-09-28T06:24:16.525723', NULL, 0, 0, 'lrscrm73@gmail.com', 'ia'),
(757, 143, '00:52:10', 'Errori di scena / Oggetti', 'Durante la cattura del piccolo squalo bianco, si vede chiaramente che l''animale utilizzato in alcune inquadrature ravvicinate è un modello di gomma completamente rigido, privo di qualsiasi movimento naturale delle branchie o della bocca, che galleggia in modo innaturale.', TRUE, '2026-09-28T06:24:16.525723', NULL, 0, 0, 'lrscrm73@gmail.com', 'ia'),
(758, 143, '01:18:25', 'Effetti speciali / Errori visivi', 'Nella famosa scena in cui lo squalo gigante nuota verso la vetrata della sala di controllo subacquea, l''animale è completamente immobile. Si tratta di un elemento bidimensionale che viene semplicemente ingrandito per simulare l''avvicinamento, rendendo l''effetto visivo estremamente piatto e privo di dinamismo.', TRUE, '2026-09-28T06:24:16.525723', NULL, 0, 0, 'lrscrm73@gmail.com', 'ia'),
(759, 143, '01:22:15', 'Incongruenza fisica / Audio', 'Mentre lo squalo attacca la struttura subacquea, si sente un ruggito cupo e minaccioso provenire dal predatore. Gli squali non possiedono corde vocali né polmoni, rendendo biologicamente impossibile l''emissione di qualsiasi tipo di verso, specialmente sott''acqua.', TRUE, '2026-09-28T06:24:16.525723', NULL, 0, 0, 'lrscrm73@gmail.com', 'ia'),
(760, 143, '01:26:45', 'Errori di montaggio / Continuità', 'Quando Philip FitzRoyce (Simon MacCorkindale) si trova all''interno della bocca dello squalo, la dimensione della bocca del predatore cambia drasticamente tra le inquadrature in primo piano (dove lo spazio interno appare enorme) e i campi medi (dove l''attore è visibilmente incastrato in un modello molto più stretto).', TRUE, '2026-09-28T06:24:16.525723', NULL, 0, 0, 'lrscrm73@gmail.com', 'ia'),
(756, 143, '00:35:40', 'Errori di montaggio / Continuità', 'Quando Mike Brody (Dennis Quaid) emerge dall''acqua dopo un''immersione, i suoi capelli sono completamente bagnati e tirati all''indietro. Nell''inquadratura immediatamente successiva, mentre parla sulla banchina, i suoi capelli sono parzialmente asciutti e perfettamente pettinati.', TRUE, '2026-09-28T06:24:16.525723', NULL, 0, 0, 'lrscrm73@gmail.com', 'ia'),
(84, 35, '01:12:05', 'Continuity', 'La cicatrice sul volto di Frodo provocata da Gollum cambia guancia e orientamento più volte durante le scene all''interno della torre di Cirith Ungol.', TRUE, '2026-09-13T15:13:22.290648', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(85, 35, '02:45:30', 'Crew & Equipment', 'Durante il combattimento contro Shelob, in un''inquadratura dal basso si scorgono i cavi di sicurezza di metallo collegati alla cintura dell''attore Sean Astin.', TRUE, '2026-09-13T15:13:22.392965', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(86, 36, '00:52:10', 'Continuity', 'Durante la sequenza del Gran Consiglio, il vestito del personaggio di Boromir cambia improvvisamente colore dal marrone scuro al blu polvere da un fotogramma all''altro.', TRUE, '2026-09-13T15:13:22.594544', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(87, 37, '00:15:30', 'Errori di scena / Posizione', 'Durante l''aggressione nella casa dello scrittore Frank Alexander, la striscia di nastro adesivo applicata sulla bocca della moglie cambia chiaramente posizione e inclinazione tra le inquadratura frontali e quelle di taglio.', TRUE, '2026-09-13T15:23:45.086249', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(657, 127, '01:56:50', 'Troupe o microfoni visibili', 'Mentre Frank e i suoi uomini raggiungono a cavallo la carrozza ferroviaria di Morton rimasta isolata tra le gole rocciose, sulla sabbia del terreno desertico in basso a destra sono perfettamente riconoscibili i solchi dei moderni pneumatici dei veicoli di produzione della troupe, non cancellati prima del ciak.', TRUE, '2026-09-19T18:08:29.015384', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(658, 127, '02:27:35', 'Errori di scena / Posizione', 'Nel celebre duello finale tra Armonica (Charles Bronson) e Frank (Henry Fonda), la direzione e la lunghezza delle ombre proiettate dai due contendenti sul terreno cambiano repentinamente tra i primissimi piani degli occhi e i campi lunghi d''insieme, tradendo il fatto che la scena è stata filmata nell''arco di diverse ore con il sole in posizioni assai differenti nel cielo.', TRUE, '2026-09-19T18:08:29.015384', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(770, 145, '00:08:45', 'Continuità', 'Nella scena in auto in cui Mr. White guida cercando di rassicurare Mr. Orange ferito a morte, lo specchietto retrovisore interno e i poggiatesta dei sedili appaiono e scompaiono a seconda che l''inquadratura sia dal cofano o dall''interno dell''abitacolo.', TRUE, '2026-09-28T17:20:35.262633', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(771, 145, '00:15:12', 'Errore di troupe / Ombra visibile', 'Mentre Mr. Pink corre lungo il vicolo per sfuggire alla polizia subito dopo la rapina finita male, è chiaramente visibile l''ombra della telecamera e dell''operatore proiettata sul muro dell''edificio a sinistra.', TRUE, '2026-09-28T17:20:35.262633', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(772, 145, '00:22:30', 'Continuità / Trucco', 'La quantità e la forma della macchia di sangue sulla camicia bianca di Mr. Orange (Tim Roth) variano continuamente mentre giace sul pavimento del magazzino, passando da macchia fresca e fluida a chiazza più scura e quasi asciutta da un''inquadratura all''altra.', TRUE, '2026-09-28T17:20:35.262633', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(773, 145, '00:26:40', 'Continuità / Posizione', 'Quando Mr. Blonde (Michael Madsen) tira fuori dal bagagliaio il poliziotto Marvin Nash, questi ha le mani ammanettate dietro la schiena. Durante alcune inquadrature successive del pestaggio, le mani ammanettate appaiono improvvisamente davanti al suo corpo per poi tornare dietro.', TRUE, '2026-09-28T17:20:35.262633', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(774, 145, '00:34:15', 'Continuità / Oggetti di scena', 'Quando Mr. Blonde rientra nel magazzino tenendo in mano un bicchiere di soda di un fast food, l''orientamento della cannuccia e il livello del coperchio cambiano posizione ad ogni stacco di montaggio.', TRUE, '2026-09-28T17:20:35.262633', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(775, 145, '01:14:05', 'Anacronismo / Oggetti di scena', 'Durante il flashback dell''addestramento sotto copertura di Mr. Orange, nella stanza è visibile un poster di una band e un pacchetto di sigarette con una grafica promozionale pubblicata solo anni dopo l''epoca in cui si svolge la storia.', TRUE, '2026-09-28T17:20:35.262633', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(776, 145, '01:32:18', 'Errore di montaggio / Effetti speciali', 'Durante lo stallo messicano finale, si vede la carica esplosiva di finto sangue (squib) sul petto di Eddie il Bello detonare prima che Mr. White riesca a ruotare la sua pistola e sparargli effettivamente.', TRUE, '2026-09-28T17:20:35.262633', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(777, 146, '00:07:40', 'Errore di continuità', 'Nella scena iniziale in cui Deckard mangia al banco nel quartiere cinese, la quantità di noodles nella sua ciotola e la posizione delle bacchette cambiano ripetutamente tra un''inquadratura e l''altra.', TRUE, '2026-09-29T14:16:41.047807', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(778, 146, '00:11:15', 'Incongruenza di sceneggiatura', 'Il capitano Bryant dice a Deckard che sei replicanti sono fuggiti e che uno è rimasto folgorato cercando di entrare alla Tyrell Corporation. Subito dopo, però, afferma che ci sono ancora quattro replicanti a piede libero, commettendo un evidente errore di calcolo matematico (6 - 1 dovrebbe fare 5).', TRUE, '2026-09-29T14:16:41.047807', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(779, 146, '00:18:25', 'Errore tecnico / Attrezzatura visibile', 'Durante il volo dello Spinner della polizia tra i grattacieli della Los Angeles futuristica, in alcune inquadrature controluce sono chiaramente visibili i sottili cavi di sospensione utilizzati per muovere il modellino del veicolo.', TRUE, '2026-09-29T14:16:41.047807', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(780, 146, '00:52:10', 'Errore di continuità / Trucco', 'Dopo il violento scontro con Leon, Deckard presenta una ferita sanguinante sul lato sinistro del volto. Quando sale in auto con Rachael, la ferita cambia forma, posizione e intensità del sangue tra i vari controcampi.', TRUE, '2026-09-29T14:16:41.047807', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(781, 146, '01:12:30', 'Controfigura visibile', 'Durante la fuga di Zhora, quando la replicante sfonda le vetrate dei negozi sotto gli spari di Deckard, è evidente che l''attrice Joanna Cassidy è stata sostituita da una controfigura (la stuntwoman Lee Pulford) che indossa una parrucca visibilmente diversa.', TRUE, '2026-09-29T14:16:41.047807', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(782, 146, '01:33:45', 'Controfigura visibile', 'Durante lo scontro nell''appartamento di J.F. Sebastian, quando Pris attacca Deckard compiendo delle capriole acrobatiche all''indietro, si nota chiaramente che l''acrobata è un ginnasta maschio con una parrucca bionda, con una corporatura molto diversa da quella di Daryl Hannah.', TRUE, '2026-09-29T14:16:41.047807', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(783, 146, '01:47:10', 'Incongruenza di montaggio / Illuminazione', 'Nel momento in cui Roy Batty muore e la colomba vola via dalle sue mani, l''inquadratura del cielo mostra uno sfondo diurno, azzurro e luminoso. Questo contrasta nettamente con l''ambientazione notturna, cupa e piovosa della scena immediatamente precedente e di quella successiva.', TRUE, '2026-09-29T14:16:41.047807', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(9, 2, '01:22:15', 'Crew & Equipment', 'Durante la rievocazione della battaglia di Zama nel Colosseo, una biga si ribalta contro la parete dell''arena e per diversi fotogrammi è chiaramente visibile una bombola di gas compresso nera installata nel retro del carro, usata per far rialzare o ribaltare il mezzo.', TRUE, '2026-09-13T14:42:52.166414', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(10, 2, '00:38:10', 'Anacronismo', 'Nelle scene in cui Massimo cammina attraverso i campi di grano o mentre si trova in Spagna, si possono notare sullo sfondo le linee di aratura simmetriche lasciate chiaramente da un moderno trattore.', TRUE, '2026-09-13T14:42:52.31543', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(11, 2, '01:05:40', 'Crew & Equipment', 'Durante un combattimento in arena, alla destra dello schermo è visibile per un istante un membro della troupe cinematografica che indossa jeans e una maglietta chiara tra la folla in costume.', TRUE, '2026-09-13T14:42:52.421124', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(12, 2, '00:26:00', 'Fattuale / Storico', 'Nel film l''imperatore Marco Aurelio viene soffocato a morte dal figlio Commodo. Nella realtà storica, Marco Aurelio morì per cause naturali (probabilmente peste o tumore) a Vindobona (l''odierna Vienna) nel 180 d.C.', TRUE, '2026-09-13T14:42:52.501079', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(751, 142, '01:08:10', 'Effetti speciali / Cavi visibili', 'Nella drammatica scena in cui lo squalo attacca e rovescia l''elicottero di soccorso, in un fotogramma illuminato dal sole sono chiaramente visibili i cavi d''acciaio utilizzati dalla troupe per ribaltare la carcassa del velivolo in acqua.', TRUE, '2026-09-28T06:16:30.26034', NULL, 0, 0, 'lrscrm73@gmail.com', 'ia'),
(752, 142, '01:21:05', 'Discontinuità meteorologica / Luce', 'Durante il lungo assedio alle barche a vela dei ragazzi, la copertura nuvolosa e la posizione del sole cambiano repentinamente: si passa da un cielo completamente cupo e nuvoloso a una luce solare diretta e nitida nel giro di pochi secondi di dialogo.', TRUE, '2026-09-28T06:16:30.26034', NULL, 0, 0, 'lrscrm73@gmail.com', 'ia'),
(690, 65, '00:08:15', 'Errori storici o fattuali', 'La morte di Re Riccardo Cuor di Leone viene collocata temporalmente e visivamente in modo impreciso. Storicamente, Riccardo morì nel 1199 all''età di 41 anni a causa di una ferita infetta, mentre nel film viene rappresentato come un uomo molto più anziano e la dinamica del ferimento è romanzata per esigenze drammatiche.', TRUE, '2026-09-22T20:36:28.422194', NULL, 0, 1, 'mrtlsn07@gmail.com', 'ia'),
(691, 65, '00:24:40', 'Errori di scena / Posizione', 'Quando Robin e Little John incontrano Marian per la prima volta nel convento, la posizione del velo da badessa di Marian (Audrey Hepburn) cambia tra i primi piani e i campi medi, rivelando più o meno capelli sulla fronte a seconda dell''inquadratura.', TRUE, '2026-09-22T20:36:28.422194', NULL, 1, 0, 'mrtlsn07@gmail.com', 'ia'),
(692, 65, '00:42:10', 'Anacronismi', 'Nelle riprese esterne della foresta (effettuate principalmente nella regione della Navarra, in Spagna), si possono notare sullo sfondo specie di alberi e vegetazione non compatibili con la flora dell''Inghilterra medievale del XII secolo, oltre a leggeri segni di pneumatici moderni sul terreno battuto.', TRUE, '2026-09-22T20:36:28.422194', NULL, 1, 0, 'mrtlsn07@gmail.com', 'ia'),
(744, 141, '01:21:15', 'Attrezzatura di scena visibile', 'Quando Quint spara il primo arpione e aggancia il barile giallo allo squalo, in un fotogramma in cui la pinna riaffiora è chiaramente visibile il cavo d''acciaio sottostato che traina la pinna meccanica.', TRUE, '2026-09-27T20:43:10.736812', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(784, 147, '00:14:25', 'Incongruenza / Liquidi', 'Nel pub di Walkabout Creek, durante la conversazione iniziale, il livello della birra nel bicchiere di Mick sale e scende inspiegabilmente tra i vari stacchi di montaggio senza che lui beva.', TRUE, '2026-09-29T14:45:36.15182', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(785, 147, '00:24:50', 'Errore di scena / Oggetti', 'Quando Mick mostra a Sue come affrontare il serpente, in un''inquadratura ravvicinata si nota chiaramente che il rettile utilizzato è un modello finto di gomma, rigido e privo di qualsiasi movimento naturale.', TRUE, '2026-09-29T14:45:36.15182', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(786, 147, '00:32:15', 'Incongruenza / Montaggio', 'Durante la scena dell''attacco del coccodrillo, quando Mick salva Sue, i capelli di lei sono completamente bagnati e inzuppati d''acqua. Nell''inquadratura immediatamente successiva, mentre camminano sulla riva, i suoi capelli sono quasi del tutto asciutti e in piega.', TRUE, '2026-09-29T14:45:36.15182', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(787, 147, '00:41:15', 'Incongruenza / Abbigliamento', 'Durante la traversata nel bush australiano, le macchie di sudore e polvere sulla camicia beige di Sue cambiano forma, dimensione e intensità da un''inquadratura all''altra, scomparendo quasi del tutto in alcuni momenti.', TRUE, '2026-09-29T14:45:36.15182', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(788, 147, '00:52:10', 'Incongruenza / Oggetti', 'Nella camera d''albergo a New York, Mick si rade usando il suo enorme coltello Bowie. La disposizione e la quantità di schiuma da barba sulle sue guance cambiano vistosamente tra i primi piani e i piani medi.', TRUE, '2026-09-29T14:45:36.15182', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(789, 147, '01:12:40', 'Errore di scena / Attrezzatura', 'Mentre Mick cammina per le affollate strade di New York, nel riflesso della vetrina di un negozio sulla sinistra è chiaramente visibile per un istante la troupe cinematografica con una telecamera montata e un pannello riflettente.', TRUE, '2026-09-29T14:45:36.15182', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(790, 147, '01:18:05', 'Incongruenza / Posizione', 'Nella celebre scena del tentato borseggio (''Questo non è un coltello...''), la posizione dei tre malviventi rispetto a Mick e Sue cambia repentinamente tra i piani larghi e i primi piani ravvicinati.', TRUE, '2026-09-29T14:45:36.15182', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia')
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza") VALUES
(791, 148, '00:13:40', 'Continuità', 'Durante il primo attacco a sorpresa dell''Acheron nella nebbia, Jack Aubrey viene ferito alla spalla e al collo da alcune schegge. Nelle inquadrature successive, la quantità di sangue che gli macchia la camicia e cola sulla clavicola varia vistosamente tra primi piani e campi medi, riducendosi per poi riapparire più estesa.', TRUE, '2026-09-29T15:13:52.315198', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(792, 148, '00:27:15', 'Sincronizzazione audio/video', 'Mentre Aubrey e Maturin eseguono un duetto nella cabina del capitano, i movimenti dell''archetto e le diteggiature sulla tastiera del violino di Russell Crowe non combaciano con il fraseggio e le note che si ascoltano nella traccia audio.', TRUE, '2026-09-29T15:13:52.315198', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(793, 148, '00:38:22', 'Continuità / Oggetti di scena', 'Durante la trapanazione cranica eseguita da Stephen Maturin sul marinaio ferito, l''orientamento della moneta d''argento da inserire e la disposizione dei ferri chirurgici sul vassoio cambiano posizione tra l''inquadratura di dettaglio e il piano medio successivo.', TRUE, '2026-09-29T15:13:52.315198', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(794, 148, '00:53:45', 'Continuità', 'Nel pieno della furiosa tempesta a Capo Horn, quando Aubrey è costretto ad abbattere le sartie dell''albero caduto per evitare che la Surprise affondi, i suoi capelli e gli abiti fradici cambiano disposizione a ogni stacco: in un''inquadratura ha ciocche incollate sulla fronte, nello stacco successivo sono raccolte e scostate dal viso.', TRUE, '2026-09-29T15:13:52.315198', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(795, 148, '01:14:10', 'Errori di scena / Anacronismi', 'Nell''equipaggiamento scientifico che Maturin utilizza per catalogare e conservare i campioni botanici e zoologici si notano flaconi e morsetti con filettature meccaniche e finiture metalliche prodotte a macchina, tipiche della produzione industriale del tardo Ottocento e non del 1805.', TRUE, '2026-09-29T15:13:52.315198', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(796, 148, '01:34:50', 'Continuità', 'Durante l''esplorazione a terra alle Isole Galápagos, mentre Maturin cerca il cormorano attero tra le rocce vulcaniche, l''ombra proiettata dal suo corpo e la luce solare sul paesaggio mutano drasticamente da un''inquadratura all''altra, indicando che i frammenti della stessa sequenza sono stati girati a diverse ore di distanza.', TRUE, '2026-09-29T15:13:52.315198', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(797, 148, '01:52:15', 'Continuità / Trucco e costumi', 'Nel culmine dell''arrembaggio finale contro l''Acheron, la giacca dell''uniforme di Aubrey subisce evidenti tagli e bruciature di polvere da sparo durante il combattimento corpo a corpo; tuttavia, pochi secondi dopo, quando avanza sottocoperta, il tessuto della manica risulta integro e nettamente più pulito.', TRUE, '2026-09-29T15:13:52.315198', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(798, 128, '00:12:45', 'Anacronismo', 'La motocicletta guidata da John Mallory (James Coburn) è un modello Triumph risalente alla fine degli anni ''20, mentre le vicende del film sono ambientate durante la Rivoluzione Messicana, precisamente nel 1913.', TRUE, '2026-09-29T16:26:57.287589', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(799, 128, '00:32:15', 'Errore di montaggio / Continuità', 'Nella scena in cui Juan e John parlano all''interno della taverna, la camicia di Juan appare vistosamente bagnata di sudore e sporca di polvere. Al cambio d''inquadratura, la camicia risulta improvvisamente molto più pulita e asciutta, per poi tornare bagnata nell''inquadratura successiva.', TRUE, '2026-09-29T16:26:57.287589', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(800, 128, '00:55:30', 'Errore di scena / Posizione', 'Quando John prepara i candelotti di dinamite sul tavolo per pianificare il colpo alla banca di Mesa Verde, la disposizione e il numero dei candelotti cambiano vistosamente tra il primo piano dettagliato e l''inquadratura più larga.', TRUE, '2026-09-29T16:26:57.287589', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(801, 128, '01:15:20', 'Anacronismo', 'Negli uffici governativi e all''interno della banca di Mesa Verde sono visibili alcune bandiere messicane che presentano lo stemma dell''aquila in una versione grafica che è stata adottata ufficialmente solo a partire dal 1968.', TRUE, '2026-09-29T16:26:57.287589', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(802, 128, '01:42:10', 'Anacronismo / Armi', 'Durante la celebre battaglia sul ponte, i soldati dell''esercito regolare messicano utilizzano una mitragliatrice pesante che è chiaramente una MG42 tedesca (o una sua variante ravvicinata), un''arma prodotta a partire dal 1942 e quindi inesistente nel 1913.', TRUE, '2026-09-29T16:26:57.287589', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(803, 128, '02:02:15', 'Errore tecnico / Elementi di produzione', 'Durante la spettacolare scena dello scontro e dell''esplosione del treno, nell''angolo sinistro dell''inquadratura in campo largo è possibile scorgere per una frazione di secondo la sagoma di una seconda cinepresa protetta da pannelli e un membro della troupe.', TRUE, '2026-09-29T16:26:57.287589', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(804, 128, '02:18:40', 'Errore di continuità / Trucco', 'Nelle drammatiche sequenze finali, dopo l''esplosione che ferisce mortalmente John, i tagli, le bruciature e le tracce di sangue sul suo volto cambiano posizione e intensità tra i diversi primi piani ravvicinati mentre dialoga con Juan.', TRUE, '2026-09-29T16:26:57.287589', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(15, 2, '00:41:20', 'Anacronismo', 'Nella scuola di gladiatori di Proximo in Nord Africa, le porte di alcune gabbie e stalle sono assicurate con lucchetti in metallo con serratura a chiave di concezione moderna.', TRUE, '2026-09-13T14:42:52.837227', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(805, 149, '00:04:15', 'Incongruenza visiva / Continuità', 'Durante la gara di autocross iniziale, le vetture dei protagonisti cambiano livello di sporco e fango sulla carrozzeria da un''inquadratura all''altra, passando da essere completamente ricoperte di fango a quasi pulite nel giro di pochi secondi.', TRUE, '2026-09-29T16:30:54.346567', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(806, 149, '00:18:30', 'Errore di montaggio / Continuità', 'Nella celebre scena della sfida a ''birra e salsicce'' nel locale, il numero di salsicce rimaste nei piatti di Kid e Ben oscilla in modo incoerente tra i primi piani e i campi larghi, aumentando e diminuendo senza che i personaggi le abbiano effettivamente consumate.', TRUE, '2026-09-29T16:30:54.346567', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(807, 149, '00:35:12', 'Controfigura evidente', 'Durante la rissa nella palestra, quando Terence Hill compie le spettacolari acrobazie sulle sbarre e sugli attrezzi ginnici, in diverse inquadrature dinamiche è chiaramente visibile il volto della controfigura acrobatica al posto di quello dell''attore.', TRUE, '2026-09-29T16:30:54.346567', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(808, 149, '00:52:45', 'Incongruenza / Equipaggiamento', 'Durante l''inseguimento in moto nel bosco, le motociclette utilizzate dagli scagnozzi cambiano tipo di pneumatici: in alcune scene di inseguimento montano gomme tassellate da fuoristrada, mentre nelle inquadrature di scivolata su asfalto presentano gomme lisce stradali.', TRUE, '2026-09-29T16:30:54.346567', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(809, 149, '01:02:10', 'Errore di scena / Oggettistica', 'Mentre il killer si prepara a sparare a Ben durante le prove del coro, il mirino telescopico del suo fucile di precisione appare montato al contrario in una delle inquadrature di dettaglio, per poi tornare orientato correttamente nell''inquadratura successiva.', TRUE, '2026-09-29T16:30:54.346567', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(810, 149, '01:18:15', 'Trucco / Effetti speciali', 'Nella rissa finale all''interno del locale pieno di palloncini, quando Bud Spencer colpisce uno scagnozzo facendolo volare contro una colonna, si nota chiaramente per una frazione di secondo il materasso di protezione scuro posizionato a terra per attutire la caduta dello stuntman.', TRUE, '2026-09-29T16:30:54.346567', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(811, 149, '01:26:40', 'Incongruenza / Continuità', 'Nel finale, quando una delle due nuove dune buggy rosse prende fuoco dopo la collisione, l''incendio divampa istantaneamente su tutta la vettura. Tuttavia, nell''inquadratura successiva, i danni da bruciatura sono visibili solo sul retro, lasciando la parte anteriore e la cappottina gialla inspiegabilmente intatte.', TRUE, '2026-09-29T16:30:54.346567', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(696, 64, '00:14:22', 'Anacronismi', 'Nelle scene girate nella foresta di Sherwood (in realtà Bidwell Park in California), si possono chiaramente notare sullo sfondo diversi alberi di eucalipto. Questa specie vegetale è originaria dell''Australia ed è stata introdotta nel continente americano solo nel XIX secolo, rendendo la sua presenza del tutto impossibile nell''Inghilterra del XII secolo.', TRUE, '2026-09-22T21:12:39.728883', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia'),
(65, 26, '00:44:05', 'Continuity', 'La macchia di sangue e il taglio sulla spalla del gladiatore cambiano braccio tra un''inquadratura e la successiva.', TRUE, '2026-09-13T15:01:46.17144', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(812, 152, '00:32:15', 'Incongruenza fisica / Effetti speciali', 'Durante la scena del capovolgimento della nave, quando il salone principale si ribalta, si può notare un pianoforte a coda che scivola sul soffitto. In alcune inquadrature ravvicinate, il pianoforte si muove in una direzione, ma nel totale successivo si muove nella direzione opposta rispetto all''inclinazione della stanza.', TRUE, '2026-09-30T14:07:31.59787', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(813, 152, '00:48:10', 'Incongruenza di montaggio / Continuità', 'Mentre il gruppo guidato da Dylan attraversa il condotto dell''ascensore in fiamme, i capelli e i vestiti di Maggie (Jacinda Barrett) appaiono completamente bagnati e arruffati. Nell''inquadratura immediatamente successiva, i suoi capelli sono visibilmente asciutti e parzialmente pettinati, per poi tornare bagnati subito dopo.', TRUE, '2026-09-30T14:07:31.59787', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(814, 152, '01:02:45', 'Errori di scena / Oggetti', 'Durante l''attraversamento del condotto d''aria allagato, le torce elettriche utilizzate dai sopravvissuti continuano a funzionare perfettamente sott''acqua. Tuttavia, si tratta di normali torce non subacquee che avrebbero dovuto subire un cortocircuito immediato una volta immerse.', TRUE, '2026-09-30T14:07:31.59787', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(815, 152, '01:12:30', 'Incongruenza di montaggio', 'Quando Elena (Mía Maestro) rimane incastrata con il vestito nel condotto e rischia di annegare, la posizione della sua testa e dei suoi capelli cambia drasticamente tra i primi piani (in cui i capelli le coprono il viso) e i campi medi (in cui il viso è completamente libero).', TRUE, '2026-09-30T14:07:31.59787', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(816, 152, '01:22:15', 'Errori di scena / Posizione', 'Quando Robert Ramsey (Kurt Russell) tenta di azionare la valvola di emergenza per invertire la rotazione delle eliche, lo si vede girare la manovella in senso orario. Nell''inquadratura successiva, da un''angolazione diversa, la sta girando chiaramente in senso antiorario.', TRUE, '2026-09-30T14:07:31.59787', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(817, 152, '01:28:40', 'Incongruenza di trucco', 'Nelle scene finali all''interno del compartimento delle eliche, le ferite e i tagli sul volto di Richard Nelson (Richard Dreyfuss) cambiano visibilmente di intensità e posizione: un profondo graffio sulla guancia destra scompare in un''inquadratura ravvicinata per poi riapparire più sfumato subito dopo.', TRUE, '2026-09-30T14:07:31.59787', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(818, 152, '01:31:10', 'Incongruenza fisica / Effetti speciali', 'Quando i sopravvissuti si lanciano in acqua per sfuggire all''esplosione finale della nave, l''enorme elica di prua smette improvvisamente di girare e poi riprende a ruotare a piena velocità tra due inquadrature consecutive, senza che nessuno abbia toccato i comandi in quel lasso di tempo.', TRUE, '2026-09-30T14:07:31.59787', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(819, 4, '00:08:00', 'Continuità', 'Quando Ace rientra nel suo appartamento con il cane appena salvato, sul tavolo si nota una scatola di cartone. L''aletta superiore della scatola cambia ripetutamente posizione, passando dall''essere aperta a completamente chiusa tra un''inquadratura e l''altra.', TRUE, '2026-09-30T14:13:27.336261', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(820, 4, '00:21:00', 'Continuità', 'Quando Ace trova la pietra arancione dell''anello dei Dolphins nel filtro della vasca di Snowflake, la gemma appare inizialmente piccola e di forma triangolare. Nelle inquadrature successive, quando la esamina da vicino, la pietra è visibilmente più grande e di forma rettangolare.', TRUE, '2026-09-30T14:13:27.336261', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(821, 4, '00:35:00', 'Continuità', 'Durante la scena a casa di Melissa, la porta a vetri scorrevole che conduce al balcone è chiaramente aperta in un''inquadratura a figura intera, ma risulta completamente chiusa nel controcampo successivo, senza che nessuno si sia avvicinato per toccarla.', TRUE, '2026-09-30T14:13:27.336261', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(822, 4, '00:44:00', 'Incongruenza storica', 'Nel filmato d''archivio del Super Bowl XVII (disputato nel 1983) che mostra il calcio fallito da Ray Finkle, i caschi e le divise dei Miami Dolphins presentano il logo e il design dei primi anni ''90, anacronistici rispetto all''epoca in cui si sarebbe svolto l''evento.', TRUE, '2026-09-30T14:13:27.336261', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(823, 4, '00:48:00', 'Incongruenza', 'Quando Ace visita la casa dei genitori di Ray Finkle e osserva le foto d''infanzia del giocatore, in una di esse il piccolo Ray indossa una t-shirt con un logo commerciale moderno che non esisteva negli anni ''60 o ''70, periodo in cui Finkle era bambino.', TRUE, '2026-09-30T14:13:27.336261', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(824, 4, '00:55:00', 'Continuità', 'Durante la telefonata nell''ufficio di Lois Einhorn, l''antenna del telefono cellulare della donna appare completamente sollevata in alcune inquadrature e totalmente abbassata in altre, alternandosi repentinamente durante il dialogo.', TRUE, '2026-09-30T14:13:27.336261', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(825, 4, '01:02:00', 'Elementi di scena visibili', 'Nella celebre sequenza in cui Ace scivola sul pavimento del manicomio di Shady Acres indossando il tutù rosa, durante l''inquadratura rallentata si possono chiaramente notare le ginocchiere protettive color carne sotto le sue calze chiare.', TRUE, '2026-09-30T14:13:27.336261', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(697, 64, '00:27:45', 'Errori di scena / Posizione', 'Durante il combattimento con i bastoni sul tronco sopra il torrente tra Robin Hood e Little John, Robin cade in acqua ed è completamente bagnato. Nella scena immediatamente successiva, quando risale sulla riva per parlare con gli uomini della foresta, i suoi abiti e la sua capigliatura appaiono visibilmente asciutti e perfettamente riordinati.', TRUE, '2026-09-22T21:12:39.728883', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia'),
(698, 64, '00:43:10', 'Troupe o microfoni visibili', 'Durante l''imboscata nella foresta ai danni del convoglio del Principe Giovanni e di Lady Marian, in un''inquadratura dal basso di uno dei fuorilegge che si lancia da un ramo, è chiaramente visibile l''imbracatura di sicurezza con il cavo di sostegno che fuoriesce da sotto la casacca dell''attore.', TRUE, '2026-09-22T21:12:39.728883', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia'),
(826, 157, '00:14:22', 'Errore di continuità', 'Durante la scena nella nuova cameretta, il pulsante del laser sul braccio di Buzz Lightyear cambia colore da verde a rosso tra un''inquadratura ravvicinata e una a mezzo busto.', TRUE, '2026-09-30T18:30:32.591797', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(827, 157, '00:32:15', 'Errore di rendering / Clipping', 'Quando Woody si nasconde frettolosamente dietro lo zaino sul pavimento, la sua mano destra attraversa visibilmente il tessuto dello zaino, rivelando un errore nel calcolo delle collisioni dei modelli 3D.', TRUE, '2026-09-30T18:30:32.591797', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(828, 157, '00:48:50', 'Errore di posizionamento', 'La scritta sotto lo stivale destro di Woody mostra brevemente il nome ''Bonnie'', ma nella scena successiva riappare il nome del nuovo bambino, coerentemente con la trama del film.', TRUE, '2026-09-30T18:30:32.591797', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(694, 65, '01:32:15', 'Errori di scena / Posizione', 'Durante il duello finale tra Robin Hood e lo Sceriffo di Nottingham, le ferite e le macchie di sangue sulla camicia bianca di Robin cambiano forma, intensità e posizione esatta tra un''inquadratura e l''altra durante i tagli di montaggio più rapidi.', TRUE, '2026-09-22T20:36:28.422194', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia'),
(699, 64, '01:02:15', 'Errori storici o fattuali', 'Nella sequenza del torneo di tiro con l''arco, diversi cavalieri e guardie indossano elementi completi di armature a piastre di metallo. Storicamente, alla fine del XII secolo (sotto il regno di Riccardo Cuor di Leone), le truppe indossavano prevalentemente giachi di maglia di ferro (usberghi); le armature a piastre articolate si diffusero soltanto a partire dal XIV secolo.', TRUE, '2026-09-22T21:12:39.728883', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia'),
(245, 51, '00:25:30', 'Errori di scena / Posizione', 'A bordo della nave Q-Ship di Ebony Maw, la pettinatura di Doctor Strange passa da visibilmente arruffata e disordinata a perfettamente composta nel giro di poche inquadrature ravvicinate.', TRUE, '2026-09-14T13:51:08.269075', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(829, 157, '01:05:12', 'Errore di illuminazione', 'Mentre i giocattoli attraversano il giardino di notte, l''ombra di Rex viene proiettata verso sinistra, mentre quelle di Buzz e Woody vanno verso destra, indicando una gestione errata delle sorgenti di luce virtuali.', TRUE, '2026-09-30T18:30:32.591797', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(830, 157, '01:22:05', 'Errore di animazione fisica', 'Quando Woody tira la sua cordicella per parlare, l''anello di plastica rimane teso all''esterno della schiena per tutta la durata della frase preregistrata, invece di riavvolgersi progressivamente.', TRUE, '2026-09-30T18:30:32.591797', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(831, 157, '01:35:40', 'Errore di continuità', 'Slinky si trova in fondo al gruppo vicino alla porta d''ingresso, ma nell''inquadratura immediatamente successiva appare in prima fila accanto a Buzz, senza che ci sia stato il tempo fisico per spostarsi.', TRUE, '2026-09-30T18:30:32.591797', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(832, 157, '01:42:18', 'Errore di scena', 'Il cappello di Woody cade a terra durante l''inseguimento finale e si sporca visibilmente di fango. Quando Buzz lo raccoglie pochi secondi dopo, il cappello è completamente pulito e lucido.', TRUE, '2026-09-30T18:30:32.591797', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia')
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza") VALUES
(833, 153, '00:09:15', 'Continuity / Errori di oggetti', 'Durante la riunione di emergenza sul tappeto di Andy, l''orologio Topolino appeso alla parete cambia l''ora mostrata dalle lancette in modo incoerente tra un campo e un controcampo, avanzando di circa 20 minuti per poi tornare indietro.', TRUE, '2026-09-30T18:32:59.256786', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(834, 153, '00:23:45', 'Continuity / Posizionamento', 'Nella scena in cui Woody spinge accidentalmente Buzz fuori dalla finestra, la posizione dei pennarelli, della lavagna e della lampada sulla scrivania di Andy cambia radicalmente tra l''inquadratura dall''alto e il primo piano.', TRUE, '2026-09-30T18:32:59.256786', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(835, 153, '00:32:10', 'Errore di continuità', 'Alla stazione di servizio Dinoco, durante la zuffa tra Woody e Buzz sotto il camion della Pizza Planet, la quantità di sporco sulle gomma posteriore del camion cambia drasticamente tra un stacco e l''altro.', TRUE, '2026-09-30T18:32:59.256786', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(836, 153, '00:48:30', 'Errore di scena / Posizione', 'Nella stanza di Sid, quando Woody viene intrappolato sotto la cassetta del latte, la pesante cassetta degli attrezzi appoggiata sopra di essa cambia orientamento e distanza dal bordo tra le diverse inquadrature.', TRUE, '2026-09-30T18:32:59.256786', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(837, 153, '00:55:12', 'Continuity / Oggetti', 'Dopo che Buzz tenta di volare e si stacca il braccio cadendo dalle scale nella casa di Sid, il braccio sinistro staccato si trova a distanze diverse dal corpo tra l''inquadratura dall''alto e quella in cui arriva la sorellina Hannah.', TRUE, '2026-09-30T18:32:59.256786', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(700, 64, '01:08:35', 'Errori di scena / Posizione', 'Quando Robin esegue il famoso tiro che spacca la freccia di Philip di Arras, nel primo piano del bersaglio la freccia originale viene spaccata esattamente a metà in modo simmetrico. Nel campo lungo successivo, la freccia appare invece spezzata in modo irregolare, con una scheggia pendente nettamente verso sinistra.', TRUE, '2026-09-22T21:12:39.728883', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia'),
(733, 139, '01:38:50', 'Errori storici o fattuali', 'Quando Tangerine viene spinto fuori dal treno in corsa e rimane aggrappato al finestrino esterno mentre il treno viaggia a oltre 300 km/h, riesce a rompere il vetro e a rientrare. Fisicamente, a quella velocità, la pressione dell''aria e la resistenza aerodinamica renderebbero impossibile per un essere umano rimanere aggrappato alla carrozzeria liscia o muoversi con tale agilità senza essere spazzato via all''istante.', TRUE, '2026-09-26T15:22:11.065646', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(743, 141, '00:48:30', 'Continuità', 'Nella famosa scena dell''attacco al piccolo Alex Kintner, le ombre sulla spiaggia e la posizione delle persone attorno a Brody variano drasticamente da un''inquadratura all''altra, rivelando che le riprese sono avvenute in momenti diversi della giornata.', TRUE, '2026-09-27T20:43:10.736812', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(745, 141, '01:39:50', 'Controfigure e incongruenze', 'Durante la sequenza dell''attacco alla gabbia subacquea, nelle riprese reali con lo squalo bianco (girate in Australia) si nota chiaramente che la persona nella gabbia è la controfigura rimpicciolita/manichino e non Richard Dreyfuss, oltre al fatto che lo squalo reale è nettamente più piccolo del modello animatronico usati nel film.', TRUE, '2026-09-27T20:43:10.736812', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(746, 141, '01:55:05', 'Effetti speciali visibili', 'Nel momento culminante in cui lo squalo balza sulla poppa dell''Orca affondandola parzialmente, sotto la pancia dell''animatronic ''Bruce'' è chiaramente visibile la piattaforma idraulica grigia utilizzata per sollevare la struttura.', TRUE, '2026-09-27T20:43:10.736812', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(838, 153, '01:08:40', 'Continuity / Dettagli', 'Quando Buzz è legato al razzo ''Big One'' con il nastro adesivo nero, il numero di giri del nastro attorno al suo torso e la larghezza dello stesso variano visibilmente tra i primi piani e i campi lunghi.', TRUE, '2026-09-30T18:32:59.256786', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(839, 153, '01:14:25', 'Errore di continuità / Props', 'Durante il rocambolesco inseguimento del camion del trasloco, l''antenna sul telecomando della macchina radiocomandata (RC) cambia lunghezza ed è piegata in alcune inquadrature, per poi apparire perfettamente dritta e svettante in altre.', TRUE, '2026-09-30T18:32:59.256786', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(267, 53, '00:15:40', 'Errori di scena / Posizione', 'Durante il flashback ambientato nel XVI secolo, la fodera della spada sulla schiena di Connor MacLeod passa dal lato destro al lato sinistro della spalla tra due inquadrature contigue.', TRUE, '2026-09-14T13:51:54.162455', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(840, 158, '00:03:45', 'Errore di continuità', 'Quando il padre di Bruce scende nel pozzo per salvarlo dopo la caduta, la corda di sicurezza cambia posizione sulle sue spalle e intorno al corpo tra un''inquadratura e l''altra.', TRUE, '2026-09-30T18:58:55.018001', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(841, 158, '00:14:10', 'Errore di continuità', 'Durante l''allenamento con le spade sul ghiaccio tra Bruce e Ducard, la quantità di neve accumulata sulle spalle e sul cappotto di Ducard varia vistosamente e repentinamente tra i tagli di montaggio.', TRUE, '2026-09-30T18:58:55.018001', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(842, 158, '00:26:30', 'Errore di continuità', 'Nella scena in cui Bruce affronta Carmine Falcone nel suo locale, il livello del liquore nel bicchiere di Falcone sale e scende inspiegabilmente tra un''inquadratura e l''altra, senza che lui ne beva.', TRUE, '2026-09-30T18:58:55.018001', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(843, 158, '01:02:15', 'Errore di continuità', 'Mentre Lucius Fox mostra a Bruce i prototipi della Wayne Enterprises, Bruce esamina il cappuccio di Batman tenendolo con la mano sinistra, ma nell''inquadratura successiva lo sta reggendo con la mano destra.', TRUE, '2026-09-30T18:58:55.018001', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(844, 158, '01:18:40', 'Errore di scena / Equipaggiamento', 'Quando Batman solleva uno dei criminali di Falcone attraverso il lucernario bagnato dalla pioggia, per un breve istante sono visibili i cavi di sicurezza neri utilizzati per sollevare l''attore.', TRUE, '2026-09-30T18:58:55.018001', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(845, 158, '01:35:10', 'Errore di continuità', 'Durante lo spettacolare inseguimento con la Batmobile (Tumbler), una delle auto della polizia che si scontra perde completamente il paraurti anteriore. Nella sequenza immediatamente successiva, lo stesso veicolo mostra il paraurti di nuovo intatto.', TRUE, '2026-09-30T18:58:55.018001', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(846, 158, '01:48:25', 'Errore di continuità', 'Quando Rachel si trova nella Batcaverna dopo essere stata intossicata dal gas dello Spauracchio, la disposizione dei suoi capelli bagnati sul viso cambia radicalmente tra i primi piani e le inquadrature più larghe.', TRUE, '2026-09-30T18:58:55.018001', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(747, 141, '02:01:40', 'Membri della troupe visibili', 'Mentre Brody si trova sull''albero della nave che affonda e tenta di sparare alla bombola nella bocca dello squalo, sullo sfondo tra le onde a sinistra della barca è visibile la prua di un''imbarcazione di supporto della troupe cinematografica.', TRUE, '2026-09-27T20:43:10.736812', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(847, 162, '00:02:45', 'Errore di continuità / Oggetti', 'Quando il riflettore con la scritta ''Sirius'' cade dal cielo sulla strada vicino a Truman, i frammenti di vetro e la posizione del faro sull''asfalto cambiano visibilmente tra l''inquadratura ravvicinata e quella successiva più ampia.', TRUE, '2026-09-30T19:53:41.113228', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia'),
(848, 162, '00:32:15', 'Errore di continuità / Posizione', 'Mentre Truman è bloccato nel traffico e ascolta la frequenza radio della regia che descrive i suoi movimenti, le auto dietro di lui cambiano colore, modello e distanza istantaneamente tra le inquadrature interne all''abitacolo e quelle esterne.', TRUE, '2026-09-30T19:53:41.113228', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia'),
(849, 162, '00:46:30', 'Errore di continuità', 'Nella scena dell''agenzia di viaggi, l''impiegata che accoglie Truman ha inizialmente una spilla dorata sul colletto sinistro della camicia. Nei controcampi successivi la spilla scompare, per poi riapparire alla fine della conversazione.', TRUE, '2026-09-30T19:53:41.113228', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia'),
(850, 162, '01:12:40', 'Errore di continuità / Oggetti', 'Durante la tesa discussione in cucina, Meryl promuove il cacao ''Mococoa''. La posizione del barattolo e l''orientamento dell''etichetta verso la telecamera cambiano ripetutamente tra i vari stacchi di montaggio, nonostante lei lo tenga fermo con entrambe le mani.', TRUE, '2026-09-30T19:53:41.113228', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia'),
(851, 162, '01:19:15', 'Errore di continuità', 'Sulla superstrada interrotta, Marlon offre a Truman una birra presa da una confezione da sei. Il livello della schiuma e il modo in cui Marlon tiene la lattina cambiano istantaneamente tra le inquadrature frontali e quelle riprese alle spalle dei personaggi.', TRUE, '2026-09-30T19:53:41.113228', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia'),
(852, 162, '01:22:50', 'Errore di continuità / Posizione', 'Nel momento drammatico in cui Truman si ricongiunge con il padre creduto morto in mezzo alla nebbia artificiale, la posizione delle mani del padre sulle spalle e sulla schiena di Truman cambia bruscamente tra i primi piani e i campi medi.', TRUE, '2026-09-30T19:53:41.113228', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia'),
(853, 162, '01:31:25', 'Errore di scena / Attrezzatura', 'Durante la tempesta nel mare artificiale, mentre Truman è sulla barca ''Santa Maria'', i suoi capelli e la sua camicia appaiono completamente fradici in un''inquadratura, ma visibilmente più asciutti e meno appiccicati al corpo nel taglio successivo, per poi tornare bagnati subito dopo.', TRUE, '2026-09-30T19:53:41.113228', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia'),
(748, 142, '00:14:30', 'Discontinuità / Errore di montaggio', 'Durante la sequenza iniziale con i due subacquei che fotografano il relitto della Orca, la posizione della fotocamera subacquea e l''orientamento della lampada stroboscopica cambiano drasticamente tra il campo lungo e il primo piano.', TRUE, '2026-09-28T06:16:30.26034', NULL, 0, 0, 'lrscrm73@gmail.com', 'ia'),
(854, 165, '00:14:32', 'Discontinuità / Oggetti', 'Durante la conversazione tesa tra il personaggio di Tom Cruise e quello di Sandra Hüller al diner, la quantità di caffè nella tazza di Tom Cruise cambia improvvisamente tra un''inquadratura e l''altra: prima è quasi vuota, poi è piena a metà, senza che nessuno l''abbia riempita.', TRUE, '2026-10-03T07:41:01.605739', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(855, 165, '00:38:15', 'Anacronismo / Oggetti di scena', 'Nello sfondo della scena ambientata nel deserto, quando Jesse Plemons scende dal pickup, è chiaramente visibile per qualche secondo uno smartphone moderno con schermo acceso nella tasca posteriore dei suoi jeans, nonostante la storia sia ambientata nei primi anni 2000.', TRUE, '2026-10-03T07:41:01.605739', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(856, 165, '01:02:45', 'Riflessi / Equipaggiamento di produzione', 'Nel momento in cui John Goodman chiude con forza lo sportello della sua berlina nera, sul vetro del finestrino posteriore si nota chiaramente il riflesso del microfono a boom e di un fonico di cabina.', TRUE, '2026-10-03T07:41:01.605739', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(857, 165, '01:24:10', 'Errori di costume / Continuità', 'Durante il complesso piano sequenza nella tempesta di sabbia, la giacca di pelle indossata da Tom Cruise presenta vistose macchie di fango sulla spalla sinistra. Nell''inquadratura immediatamente successiva, la giacca appare perfettamente pulita e asciutta.', TRUE, '2026-10-03T07:41:01.605739', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(858, 165, '01:45:02', 'Discontinuità / Posizione degli attori', 'Mentre Riz Ahmed parla al telefono davanti alla mappa del cantiere, la sua mano destra tiene la cornetta all''orecchio. Al cambio di campo istantaneo, la cornetta passa alla mano sinistra, mentre la destra è improvvisamente appoggiata al tavolo.', TRUE, '2026-10-03T07:41:01.605739', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(859, 165, '02:08:19', 'Errori di montaggio / Sincronizzazione audio', 'Durante il monologo drammatico di Sandra Hüller, si nota un evidente errore di labiale: le labbra dell''attrice continuano a muoversi per circa un secondo dopo che la battuta audio è già terminata.', TRUE, '2026-10-03T07:41:01.605739', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(860, 165, '02:22:50', 'Effetti speciali / VFX', 'Nella scena del crollo del capannone, la cravatta di John Goodman vola verso sinistra spinta dallo spostamento d''aria, ma la polvere CGI generata attorno a lui si muove nella direzione opposta, rivelando una mancata coerenza nella simulazione fisica.', TRUE, '2026-10-03T07:41:01.605739', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(861, 166, '00:23:15', 'Anacronismo / Oggetti di scena', 'Durante la scena della sparatoria nel tribunale, Carl Lee spara diversi colpi con il fucile d''assalto M16. Nonostante spari a raffica continua, il selettore di fuoco dell''arma è visibilmente impostato su ''SEMI'' (semiautomatico) nei primi piani del fucile.', TRUE, '2026-10-03T07:51:46.524331', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(862, 166, '00:48:10', 'Continuità / Abbigliamento', 'Quando Jake Brigance (Matthew McConaughey) parla con Ellen Roark (Sandra Bullock) nel suo studio, le ampie macchie di sudore sulla sua camicia azzurra cambiano continuamente forma e dimensione tra le inquadrature strette e quelle larghe.', TRUE, '2026-10-03T07:51:46.524331', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(863, 166, '01:12:45', 'Continuità / Posizione', 'Durante la violenta manifestazione del Ku Klux Klan all''esterno del tribunale, la bandiera confederata tenuta da uno dei manifestanti in prima fila cambia mano e inclinazione tra due stacchi di camera consecutivi.', TRUE, '2026-10-03T07:51:46.524331', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(864, 166, '01:35:20', 'Errore di montaggio / Audio', 'Mentre il procuratore Rufus Buckley (Kevin Spacey) interroga un testimone in aula, il movimento delle sue labbra non corrisponde al doppiaggio/audio originale: le sue labbra continuano a muoversi anche dopo che la frase è terminata.', TRUE, '2026-10-03T07:51:46.524331', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(865, 166, '01:52:05', 'Continuità / Oggetti di scena', 'Durante l''attentato dinamitardo e l''incendio alla casa di Jake, il porticato appare completamente avvolto dalle fiamme in una ripresa esterna da lontano, ma nell''inquadratura immediatamente successiva dall''interno la struttura del portico risulta quasi intatta.', TRUE, '2026-10-03T07:51:46.524331', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(866, 166, '02:14:30', 'Continuità / Trucco', 'Nella celebre arringa finale di Jake Brigance in tribunale, i ciocchi di capelli sulla sua fronte appaiono completamente inzuppati di sudore e appiccicati nella ripresa frontale, mentre nei controcampi laterali sono visibilmente più asciutti e riordinati.', TRUE, '2026-10-03T07:51:46.524331', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(867, 166, '02:22:15', 'Attrezzatura di ripresa visibile', 'Nella scena nel corridoio del tribunale prima della lettura del verdetto della giuria, sulla parte superiore del riquadro è brevemente visibile l''ombra del microfono a pertica (boom mic) che si muove sopra la testa degli attori.', TRUE, '2026-10-03T07:51:46.524331', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(749, 142, '00:38:15', 'Equipaggiamento / Elementi di produzione visibili', 'Durante l''attacco alla sciatrice nautica, in un''inquadratura dall''alto dell''acqua è visibile per un secondo la piattaforma di supporto e la slitta idraulica usata per spingere lo squalo meccanico verso la superficie.', TRUE, '2026-09-28T06:16:30.26034', NULL, 0, 0, 'lrscrm73@gmail.com', 'ia'),
(868, 167, '00:14:32', 'Anacronismo / Oggetti', 'Durante la scena di allenamento nel palazzetto ambientata negli anni ''50, sullo sfondo è visibile per un secondo un cartellone pubblicitario contenente un codice QR parzialmente coperto da un telo.', TRUE, '2026-10-03T13:16:45.130492', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(750, 142, '00:52:40', 'Discontinuità di costumi e oggetti', 'Quando Lo Sceriffo Brody esamina la carcassa dell''orca sulla spiaggia, la macchia di bagnato sulla sua camicia cambia forma e dimensione in modo incoerente tra i vari controcampi.', TRUE, '2026-09-28T06:16:30.26034', NULL, 0, 0, 'lrscrm73@gmail.com', 'ia'),
(869, 167, '00:38:15', 'Errori di continuità', 'Quando il personaggio di Timothée Chalamet si prepara al servizio decisivo, nell''inquadratura frontale impugna la racchetta con la presa classica (shakehand), ma nel controcampo immediato la sta impugnando con la presa a penna (penholder).', TRUE, '2026-10-03T13:16:45.130492', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(870, 167, '00:52:40', 'Attrezzatura visibile', 'Durante la concitata discussione nello spogliatoio tra i personaggi interpretati da Chalamet e Gwyneth Paltrow, nella parte superiore dell''inquadratura compare distintamente l''ombra del microfono a giraffa (boom mic).', TRUE, '2026-10-03T13:16:45.130492', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(871, 167, '01:12:05', 'Errori di scena / Posizione', 'Nella scena del bar, il livello della bevanda nel bicchiere di Tyler, The Creator aumenta visibilmente tra due inquadrature staccate di pochi secondi, senza che nessuno gli versi altro liquido.', TRUE, '2026-10-03T13:16:45.130492', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(872, 167, '01:35:50', 'Anacronismo / Costumi', 'Tra la folla degli spettatori al torneo finale, una comparso in terza fila indossa un paio di scarpe da ginnastica con suola moderna ed elementi riflettenti, del tutto inesistenti all''epoca della narrazione.', TRUE, '2026-10-03T13:16:45.130492', NULL, 0, 0, 'mrtrrt@libero.it', 'ia')
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza") VALUES
(873, 167, '01:48:12', 'Errori di continuità / Trucco e Parrucco', 'Nel pieno del match decisivo, il protagonista mostra la maglietta completamente bagnata di sudore e i capelli scompigliati. Nella ripresa ravvicinata subito successiva, i capelli sono di nuovo perfettamente pettinati e la maglia appare asciutta.', TRUE, '2026-10-03T13:16:45.130492', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(874, 167, '02:04:18', 'Riflessi / Troupe', 'Mentre l''automobile d''epoca si allontana lungo la strada, nel paraurti cromato posteriore è chiaramente visibile il riflesso del cameraman con lo Steadicam e dell''operatore della ripresa.', TRUE, '2026-10-03T13:16:45.130492', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(875, 168, '00:04:30', 'Errore di continuità', 'Durante la scena in cui Anton Chigurh strangola il vice sceriffo con le manette, la scia di sangue sul pavimento e i segni neri lasciati dalle scarpe della vittima cambiano posizione e intensità tra le diverse inquadrature ravvicinate e quelle larghe.', TRUE, '2026-10-03T13:23:56.237925', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(876, 168, '00:12:40', 'Errore di continuità / Posizione', 'Quando Llewelyn Moss si avvicina al camioncino nel deserto e trova l''uomo messicano ferito, la mano dell''uomo sul volante cambia posizione tra l''inquadratura dall''esterno e quella dall''interno dell''abitacolo.', TRUE, '2026-10-03T13:23:56.237925', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(877, 168, '00:22:15', 'Anacronismo', 'Sebbene il film sia ambientato nel 1980, in diverse scene di sfondo si possono notare automobili e camioncini prodotti alla fine degli anni ''90 o nei primi anni 2000, come un modello di Ford F-150 chiaramente visibile sullo sfondo di una strada.', TRUE, '2026-10-03T13:23:56.237925', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(878, 168, '00:38:10', 'Errore di scena / Oggetti', 'Nella stanza del motel, quando Moss svita la grata della presa d''aria per nascondere la valigetta con i soldi, le viti che ha rimosso e appoggiato sul pavimento cambiano disposizione e distanza tra loro nei tagli di montaggio successivi.', TRUE, '2026-10-03T13:23:56.237925', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(879, 168, '00:48:15', 'Errore di continuità', 'Nella casa di Moss, quando Chigurh si siede sul divano e beve dal bicchiere di latte, il livello del liquido all''interno del bicchiere sale e scende inspiegabilmente tra i cambi di inquadratura prima che lui finisca di bere.', TRUE, '2026-10-03T13:23:56.237925', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(880, 168, '00:55:30', 'Anacronismo', 'Quando Moss utilizza una cabina telefonica pubblica per effettuare una chiamata, il telefono a gettoni mostra un adesivo con un logo moderno della compagnia telefonica e un design del vano di restituzione delle monete che non esistevano ancora nel 1980.', TRUE, '2026-10-03T13:23:56.237925', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(881, 168, '01:12:05', 'Errore di continuità', 'Durante lo scontro a fuoco nel motel, quando Moss viene ferito e scappa in strada, la quantità di sangue sulla sua camicia e la forma della macchia ematica cambiano visibilmente da un''inquadratura all''altra mentre corre.', TRUE, '2026-10-03T13:23:56.237925', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(701, 64, '01:21:40', 'Errori storici o fattuali', 'I tabelloni utilizzati come bersagli durante la gara di tiro con l''arco presentano i classici anelli colorati concentrici (bianco, nero, blu, rosso, oro). Questo tipo di bersaglio regolamentare è stato introdotto e codificato solo nell''era moderna (XVIII-XIX secolo), mentre nel Medioevo si utilizzavano bersagli di paglia grezza, rocchetti o pioli di legno.', TRUE, '2026-09-22T21:12:39.728883', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia'),
(882, 169, '00:06:15', 'Anacronismo / Equipaggiamento', 'Durante l''addestramento a Parris Island (ambientato nel 1967), le reclute impugnano fucili M16A2. Questa specifica variante dell''M16 è stata adottata dal corpo dei Marines solo a partire dal 1982.', TRUE, '2026-10-03T13:27:46.941474', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(883, 169, '00:28:40', 'Continuità / Oggetti di scena', 'Durante la scena del ''panno di sapone'' in cui la squadra punisce Pyle di notte, la disposizione delle coperte sul suo letto e la posizione delle calze cambiano visibilmente tra i campi lunghi e i primi piani.', TRUE, '2026-10-03T13:27:46.941474', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(884, 169, '00:43:10', 'Continuità / Effetti speciali', 'Nella scena nei bagni della camerata, quando Pyle spara al Sergente Maggiore Hartman, lo schizzo di sangue e il pattern sulla parete bianca alle sue spalle cambiano forma e densità tra l''istante dell''impatto e la sequenza in cui cade all''indietro.', TRUE, '2026-10-03T13:27:46.941474', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(885, 169, '00:52:30', 'Continuità / Vestiario', 'La celebre scritta ''Born to Kill'' presente sull''elmetto del soldato Joker cambia inclinazione, spessore del tratto e dimensione del font tra la scena iniziale della redazione di Stars and Stripes e le successive scene di pattugliamento.', TRUE, '2026-10-03T13:27:46.941474', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(886, 169, '01:14:20', 'Errore di ambientazione', 'Nelle scene ambientate nella città di Huế (girate nella Bexton Gasworks vicino a Londra), in varie inquadrature sullo sfondo si scorgono elementi architettonici tipicamente industriali britannici e il fogliame delle palme fìnte importate mostra i sostegni di plastica alla base.', TRUE, '2026-10-03T13:27:46.941474', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(887, 169, '01:38:45', 'Continuità / Posizione', 'Quando il medico Doc Jay viene colpito dal cecchino, la posizione del suo corpo a terra, le braccia e l''inclinazione della testa cambiano in modo incoerente tra il campo largo e il campo stretto.', TRUE, '2026-10-03T13:27:46.941474', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(888, 169, '01:46:10', 'Errore di troupe', 'Durante l''avanzamento finale della squadra verso il rifugio del cecchino tra le macerie in fiamme, nell''angolo inferiore sinistro dello schermo è visibile per un secondo l''ombra di un operatore di ripresa con la cinepresa a mano.', TRUE, '2026-10-03T13:27:46.941474', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(889, 164, '00:43:15', 'Errore di continuità', 'Dopo aver salvato Gabriel e aver massacrato i soldati inglesi con il tomahawk, Benjamin Martin è coperto di sangue. Nelle inquadrature successive, mentre abbraccia i figli, la disposizione e la quantità di sangue sul suo viso e sulla camicia cambiano vistosamente tra un taglio e l''altro.', TRUE, '2026-10-03T15:01:57.581376', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(890, 164, '00:41:10', 'Anacronismo / Equipaggiamento', 'Durante l''imboscata nella foresta, quando Benjamin Martin spara con la sua pistola a pietra focaia in primo piano, non si vede alcuna fiammata o fumo provenire dallo scodellino della focaia, rivelando che si tratta di un''arma di scena non caricata realmente.', TRUE, '2026-10-03T15:01:57.581376', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(891, 164, '01:12:30', 'Errore di continuità', 'Durante la scena in cui il Generale Cornwallis discute con i suoi ufficiali, la parrucca di Cornwallis cambia leggermente posizione e livello di ordine tra i primi piani e i campi medi.', TRUE, '2026-10-03T15:01:57.581376', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(892, 164, '01:50:25', 'Anacronismo / Oggetti di scena', 'In un''inquadratura panoramica in cui le truppe britanniche marciano lungo un sentiero di campagna, sono chiaramente visibili sul terreno fangoso i solchi degli pneumatici lasciati dai moderni camion della produzione cinematografica.', TRUE, '2026-10-03T15:01:57.581376', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(893, 164, '02:15:40', 'Errore di continuità / Bandiera', 'Durante la battaglia finale, la bandiera americana portata dai coloni mostra la disposizione delle stelle a cerchio (stile Betsy Ross). Tuttavia, in un''inquadratura ravvicinata molto rapida, la disposizione delle stelle cambia temporaneamente in una griglia più moderna.', TRUE, '2026-10-03T15:01:57.581376', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(894, 164, '02:22:15', 'Errore di continuità', 'Nel duello finale tra Benjamin Martin e il Colonnello Tavington, la giacca verde di quest''ultimo appare coperta di fango e polvere. Nei successivi primi piani ravvicinati, il colletto e la spalla della giacca sono improvvisamente molto più puliti.', TRUE, '2026-10-03T15:01:57.581376', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(895, 164, '00:35:20', 'Anacronismo / Trucco', 'Nonostante l''ambientazione sia il tardo XVIII secolo, molti dei personaggi principali e delle comparse (inclusi i bambini di Martin) mostrano una dentatura perfettamente bianca, dritta e curata con moderni standard odontoiatrici, del tutto improbabile per l''epoca.', TRUE, '2026-10-03T15:01:57.581376', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(702, 64, '01:34:50', 'Errori di scena / Posizione', 'Durante lo scontro finale all''interno del castello tra Robin Hood e Sir Guy di Gisborne, l''ombra dei due duellanti proiettata sulle colonne di pietra cambia repentinamente direzione e angolazione tra un piano sequenza e l''altro, tradendo un differente posizionamento dei proiettori di luce durante i diversi take del montaggio.', TRUE, '2026-09-22T21:12:39.728883', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia'),
(720, 138, '00:22:45', 'Errori di scena / Posizione', 'Nella scena in cui Ordell e Louis conversano nel soggiorno di Melanie mentre guardano la TV, la posizione delle gambe di Melanie sul divano e l''altezza del liquido nel suo bicchiere cambiano visibilmente ad ogni cambio di inquadratura tra i campi e i controcampi.', TRUE, '2026-09-26T14:36:06.948712', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(721, 138, '00:36:10', 'Errori di scena / Posizione', 'Quando Max Cherry accoglie Jackie all''uscita dalla prigione e vanno al bar, la sigaretta che Max tiene in mano varia ripetutamente di lunghezza: in un piano sequenza appare quasi consumata, mentre al controcampo successivo torna ad essere significativamente più lunga.', TRUE, '2026-09-26T14:36:06.948712', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(722, 138, '00:52:30', 'Troupe o microfoni visibili', 'Durante la tensione nell''appartamento di Jackie quando Ordell la sorprende al buio, al momento dell''accensione della lampada da tavolo è visibile per diversi secondi l''ombra proiettata dal microfono a giraffa (boom mic) sulla parte alta della parete a destra.', TRUE, '2026-09-26T14:36:06.948712', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(723, 138, '01:14:15', 'Anacronismi', 'L''opera è esplicitamente ambientata nel 1995 (come indicato sui documenti di viaggio e sulle carte d''identità dei personaggi). Tuttavia, nella sequenza del centro commerciale Del Amo, si scorge nel parcheggio una vettura il cui restyling del modello è stato commercializzato soltanto a partire dalla fine del 1996.', TRUE, '2026-09-26T14:36:06.948712', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(724, 138, '01:42:10', 'Errori di scena / Posizione', 'Nella sequenza del camerino di Billingsley al Del Amo Fashion Center durante lo scambio della borsa, il sacchetto giallo con i soldi sporge dalla borsa della spesa in modo diverso tra l''inquadratura in soggettiva di Jackie e l''inquadratura frontale su Melanie.', TRUE, '2026-09-26T14:36:06.948712', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(896, 57, '02:12:15', 'Membri della troupe visibili', 'Sulla sinistra dell''inquadratura, dietro la spalla di Jack Sparrow a bordo della Black Pearl, si può chiaramente notare un membro della troupe cinematografica che indossa una maglietta bianca, occhiali da sole e un cappello da cowboy, decisamente fuori contesto per l''epoca.', TRUE, '2026-10-03T17:19:16.19067', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(897, 57, '00:16:30', 'Incongruenza fisica / Continuità', 'Dopo che Jack Sparrow si tuffa in mare per salvare Elizabeth che sta annegando, i suoi capelli e i suoi vestiti appaiono completamente bagnati. Tuttavia, pochi istanti dopo, quando viene catturato dalle guardie sulla banchina, i suoi capelli sono quasi completamente asciutti e perfettamente acconciati.', TRUE, '2026-10-03T17:19:16.19067', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(898, 57, '00:11:45', 'Continuità', 'Durante il duello nella fucina tra Jack Sparrow e Will Turner, le macchie di fuliggine e sporco sul viso di Will cambiano forma, intensità e posizione tra un''inquadratura e l''altra.', TRUE, '2026-10-03T17:19:16.19067', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(899, 57, '01:22:10', 'Continuità', 'Durante la scena del sacrificio sull''Isla de Muerta, Barbossa taglia la mano di Elizabeth per bagnare il medaglione d''oro. Nelle inquadrature successive, la quantità di sangue sulla mano di Elizabeth e sul medaglione varia vistosamente, scomparendo quasi del tutto in alcuni tagli.', TRUE, '2026-10-03T17:19:16.19067', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(900, 57, '02:04:30', 'Errori di scena / Posizione', 'Quando Barbossa viene colpito e muore, lascia cadere la mela che teneva in mano. Nelle inquadrature dall''alto la mela si trova a pochi centimetri dalla sua mano destra, mentre nelle inquadrature successive più ravvicinate la mela è posizionata molto più lontano.', TRUE, '2026-10-03T17:19:16.19067', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(901, 57, '00:09:15', 'Anacronismo / Oggetti di scena', 'Sulla bandana di Jack Sparrow, in alcune inquadrature ravvicinate all''inizio del film quando arriva al porto di Port Royal, è visibile una piccola etichetta bianca con il logo del marchio moderno ''Adidas'', parzialmente coperta ma non del tutto rimossa dal reparto costumi.', TRUE, '2026-10-03T17:19:16.19067', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(902, 57, '00:48:20', 'Incongruenza di montaggio', 'Durante l''attacco della Black Pearl a Port Royal, un cannone della fortezza viene colpito ed esplode volando via. Nel fotogramma immediatamente successivo, lo stesso cannone è di nuovo integro nella sua posizione originale prima di sparire definitivamente nella scena seguente.', TRUE, '2026-10-03T17:19:16.19067', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(903, 58, '00:03:45', 'Continuità', 'Durante la scena iniziale sotto la pioggia torrenziale in cui Elizabeth viene arrestata da Cutler Beckett, le ciocche di capelli sul viso della donna cambiano continuamente disposizione e livello di bagnato tra i primi piani e i controcampi.', TRUE, '2026-10-03T17:23:47.864222', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(904, 58, '00:33:10', 'Continuità', 'Sull''isola dei Pelegosto, mentre Jack Sparrow cerca di scappare legato al lungo palo di bambù, la quantità e la disposizione dei frutti infilzati alle estremità del palo cambiano vistosamente tra le inquadrature larghe e i piani ravvicinati.', TRUE, '2026-10-03T17:23:47.864222', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(905, 58, '00:39:40', 'Errori di scena / Attrezzatura', 'Quando Will Turner e la ciurma fanno oscillare le gabbie sferiche di ossa per scalare il dirupo, in un''inquadratura dal basso è visibile un cavo di sicurezza in acciaio moderno che sostiene la gabbia oltre alle corde sceniche.', TRUE, '2026-10-03T17:23:47.864222', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(906, 58, '01:04:20', 'Continuità', 'Durante la partita a dadi bugiardi tra Will Turner e Davy Jones a bordo dell''Olandese Volante, la configurazione e la posizione dei dadi sul tavolo cambiano tra il momento in cui la tazza viene sollevata e il cambio di angolazione successivo.', TRUE, '2026-10-03T17:23:47.864222', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(907, 58, '01:54:30', 'Continuità', 'Nel celebre duello sulla ruota del mulino a Isla Cruces, Jack Sparrow si ritrova all''interno della ruota: la sua spada passa istantaneamente dall''essere impugnata a essere infilata nel fodero e poi di nuovo in mano tra stacchi consecutivi, senza che lui compia il gesto di rinfoderarla o estrarla.', TRUE, '2026-10-03T17:23:47.864222', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(908, 58, '01:59:15', 'Oggetti di scena', 'Sulla spiaggia di Isla Cruces, durante la contesa per la chiave del forziere fantasma, la chiave stessa cambia visibilmente dimensione e proporzioni nei dettagli dell''impugnatura tra le sequenze con gli stuntman e le inquadrature a fuoco stretto sui protagonisti.', TRUE, '2026-10-03T17:23:47.864222', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(909, 58, '02:11:05', 'Continuità', 'Durante il primo grande assalto del Kraken alla Perla Nera, un enorme tentacolo spazza via e frantuma completamente la ringhiera del ponte superiore; nell''inquadratura panoramica successiva, la stessa ringhiera è nuovamente intatta prima di essere distrutta un''altra volta.', TRUE, '2026-10-03T17:23:47.864222', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(725, 138, '01:54:05', 'Errori di scena / Posizione', 'Nel parcheggio sotterraneo e poi esterno dove Louis e Melanie cercano il furgone, le macchine parcheggiate intorno alla loro vettura cambiano modello e colore tra l''inquadratura larga e il totale registrato dalla prospettiva opposta.', TRUE, '2026-09-26T14:36:06.948712', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(726, 138, '02:20:40', 'Errori storici o fattuali', 'Nella resa dei conti finale all''interno dell''ufficio di Max Cherry, la posizione del cane della pistola impugnata da Ordell varia inquadratura dopo inquadratura, passando dall''essere armato (arretrato) all''essere a riposo (abbassato), senza che l''attore compia alcun movimento di riarmo.', TRUE, '2026-09-26T14:36:06.948712', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(910, 174, '00:04:12', 'Continuità', 'Durante la sequenza iniziale dell''inondazione del Tevere, la quantità di fango e detriti sui volti e sui corpi di Romolo e Remo varia vistosamente tra i primi piani e le inquadrature a figura intera.', TRUE, '2026-10-05T17:18:54.999891', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(911, 174, '00:19:45', 'Trucco e costumi', 'Durante la prigionia nel campo dei Sabini, una profonda ferita da taglio sul costato di Romolo appare fresca e sanguinante in un''inquadratura, per poi risultare quasi completamente rimarginata e opaca nello stacco successivo.', TRUE, '2026-10-05T17:18:54.999891', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(912, 174, '00:36:20', 'Anacronismo / Dettagli di scena', 'In un primo piano ravvicinato di uno dei guerrieri della tribù durante il confronto nel bosco, si intravede chiaramente un''otturazione moderna in amalgama scura su uno dei molari inferiori.', TRUE, '2026-10-05T17:18:54.999891', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(913, 174, '00:51:30', 'Continuità', 'Il fuoco sacro trasportato dalla vestale Tefnie presenta una fiamma alta e fumosa nel campo lungo, ma al controcampo ravvicinato la brace è quasi del tutto spenta e produce pochissimo fumo.', TRUE, '2026-10-05T17:18:54.999891', NULL, 0, 0, 'IA (Sistema)', 'ia')
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza") VALUES
(914, 174, '01:08:14', 'Errori di scena / Posizione', 'Nel corso della marcia nella palude, Remo impugna la lancia nella mano destra; a seguito di un cambio di prospettiva immediato, l''arma si trova saldamente nella mano sinistra senza alcun movimento intermedio.', TRUE, '2026-10-05T17:18:54.999891', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(915, 174, '01:24:50', 'Attrezzatura tecnica visibile', 'Durante la fuga tra la fitta vegetazione e le radici, per una frazione di secondo nell''angolo inferiore sinistro dell''inquadratura si scorge un cavo nero di sicurezza o alimentazione parzialmente interrato sotto il fogliame.', TRUE, '2026-10-05T17:18:54.999891', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(916, 174, '01:43:05', 'Continuità', 'Durante lo scontro finale e drammatico tra Romolo e Remo, il sangue che copre il petto di Remo cambia disegno e consistenza: prima forma tre rivoli distinti, poi, senza che nessuno lo tocchi, si presenta come un''unica grande chiazza uniforme.', TRUE, '2026-10-05T17:18:54.999891', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(917, 180, '00:32:15', 'Errore di continuità', 'Nella cabina della nave Venture, mentre Jack Driscoll scrive sulla sua macchina da scrivere, il foglio inserito nel rullo cambia visibilmente lunghezza e quantità di testo scritto tra i primi piani e i campi medi, senza che lui abbia effettivamente digitato così tanto.', TRUE, '2026-10-06T19:44:34.973473', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(918, 180, '00:45:12', 'Incongruenza / Continuità', 'Durante la prima esplorazione di Skull Island, l''abito di Ann Darrow si sporca vistosamente di fango. Nelle inquadrature successive, prima che abbia la possibilità di lavarsi, il vestito appare improvvisamente molto più pulito e le macchie rimaste cambiano posizione.', TRUE, '2026-10-06T19:44:34.973473', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(919, 180, '01:12:30', 'Errore di montaggio / CGI', 'Durante la scena della fuga dei brontosauri, la posizione dei personaggi umani rispetto alle zampe dei dinosauri giganti cambia bruscamente tra un taglio e l''altro. In un''inquadratura Jack Driscoll è sul punto di essere calpestato, ma nel taglio successivo si trova a diversi metri di distanza in totale sicurezza.', TRUE, '2026-10-06T19:44:34.973473', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(920, 180, '01:45:22', 'Errore di scena / Trucco', 'Durante lo scontro tra Kong e i tre V-Rex, Ann Darrow viene sballottata all''interno di una fitta vegetazione e nel fango. Nonostante i violenti scossoni, la sua acconciatura bionda rimane perfettamente ordinata e il trucco sul viso non presenta alcuna sbavatura tra un''inquadratura e l''altra.', TRUE, '2026-10-06T19:44:34.973473', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(921, 180, '02:10:45', 'Incongruenza fisica / Proporzioni', 'Quando Kong viene catturato e trasportato sulla nave Venture, le dimensioni della stiva che lo ospita per il viaggio verso New York appaiono geometricamente impossibili e sproporzionate rispetto alle reali dimensioni esterne dello scafo della nave mostrate in precedenza.', TRUE, '2026-10-06T19:44:34.973473', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(922, 180, '02:40:10', 'Errore di continuità', 'Nella scena in cui Kong e Ann scivolano sul laghetto ghiacciato a Central Park, lo spessore del ghiaccio e la quantità di neve fresca accumulata sui bordi cambiano drasticamente tra le riprese grandangolari (in CGI) e i primi piani degli attori ricostruiti in studio.', TRUE, '2026-10-06T19:44:34.973473', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(923, 180, '02:52:30', 'Anacronismo storico', 'Durante l''attacco finale sull''Empire State Building, i biplani militari Curtiss F8C-5 Helldiver presentano alcune insegne e dettagli della cabina di pilotaggio che non corrispondono storicamente ai modelli in uso nel 1933, anno in cui è ambientata la pellicola.', TRUE, '2026-10-06T19:44:34.973473', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(727, 139, '00:12:35', 'Errori storici o fattuali', 'Il treno Shinkansen mostrato nel film (che viaggia da Tokyo a Kyoto) presenta interni con scompartimenti privati spaziosi e una carrozza bar/lounge lussuosa. Nella realtà, i treni della linea Tokaido Shinkansen (N700S) non dispongono di scompartimenti privati di questo tipo né di carrozze bar così ampie, ma solo di file standard di sedili e carrelli mobili per il servizio ristoro.', TRUE, '2026-09-26T15:22:11.065646', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(924, 182, '00:28:15', 'Errore di continuità', 'Durante la caotica cena a Casa Baggins, la disposizione del cibo sul tavolo, in particolare i formaggi, le fette di carne e le pagnotte di pane, cambia ripetutamente posizione e quantità tra le inquadrature strette sui nani e quelle larghe della stanza.', TRUE, '2026-10-09T15:05:48.403226', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(925, 182, '00:38:40', 'Errore di continuità / Oggetti', 'Quando Bilbo corre fuori da Casa Baggins con il contratto firmato, tiene il foglio arrotolato saldamente nella mano destra. Nell''inquadratura immediatamente successiva, mentre corre lungo il sentiero della Contea, il contratto si trova improvvisamente nella mano sinistra.', TRUE, '2026-10-09T15:05:48.403226', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(926, 182, '01:12:10', 'Errore di continuità', 'Nella scena in cui i troll catturano Bilbo, la spada Pungolo (ancora non rinominata) è chiaramente infilata nella cintura dei suoi pantaloni. Nello stacco successivo la spada scompare del tutto, per poi riapparire misteriosamente quando i troll lo sollevano in aria.', TRUE, '2026-10-09T15:05:48.403226', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(927, 182, '01:35:25', 'Errore di continuità / Posizione', 'Durante l''inseguimento dei mannari (Warg) con la slitta di Radagast, la disposizione e il numero dei conigli di Rhosgobel che trainano la slitta variano vistosamente tra le inquadrature ravvicinate dal vivo e quelle digitali a lungo raggio.', TRUE, '2026-10-09T15:05:48.403226', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(928, 182, '02:02:15', 'Errore di continuità', 'Nella scena degli indovinelli nell''oscurità tra Bilbo e Gollum, l''Anello cade dalla tasca di quest''ultimo. La posizione dell''Anello sul terreno sabbioso cambia nettamente tra il primo piano dettagliato e l''inquadratura successiva in cui Bilbo si china a raccoglierlo.', TRUE, '2026-10-09T15:05:48.403226', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(929, 182, '02:25:30', 'Errore di continuità / Oggetti', 'Durante la rocambolesca fuga dalle caverne dei Goblin, la spada di Thorin, Orcrist, appare completamente coperta di sporco e sangue nero di goblin in un''inquadratura, ma nel taglio successivo, senza che sia stata pulita, brilla perfettamente lucida.', TRUE, '2026-10-09T15:05:48.403226', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(930, 182, '02:38:10', 'Errore di continuità / Trucco', 'Quando Thorin affronta Azog sulla collina alla fine del film, i graffi e le ferite di sangue sul viso di Thorin cambiano forma, intensità e posizione tra i vari primi piani ravvicinati durante il drammatico scontro.', TRUE, '2026-10-09T15:05:48.403226', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(931, 185, '00:12:40', 'Incongruenza / Montaggio', 'Quando Larry riceve per la prima volta il giornale del giorno dopo da Pop Benson, la disposizione del testo e la data sulla testata del quotidiano cambiano visibilmente tra il primo piano e l''inquadratura successiva a mezzo busto.', TRUE, '2026-10-09T15:07:02.550997', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(932, 185, '00:28:15', 'Continuità / Costumi', 'Durante la scena della pioggia battente in strada, il cappotto di Larry è completamente inzuppato d''acqua. Tuttavia, nell''inquadratura immediatamente successiva all''interno dell''ufficio, il cappotto appare solo leggermente umido sulle spalle.', TRUE, '2026-10-09T15:07:02.550997', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(933, 185, '00:42:10', 'Anacronismo / Scenografia', 'Nonostante il film sia ambientato negli anni ''90 dell''Ottocento (1890s), sullo sfondo della hall del teatro è visibile un interruttore della luce elettrica a parete con un design tipico degli anni ''40, periodo di produzione del film.', TRUE, '2026-10-09T15:07:02.550997', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(934, 185, '00:55:30', 'Errori di scena / Posizione', 'Durante la cena al ristorante tra Larry e Sylvia, la bottiglia di vino sul tavolo cambia orientamento tra un''inquadratura e l''altra: l''etichetta è prima rivolta verso la telecamera e poi ruotata di lato, senza che nessuno l''abbia toccata.', TRUE, '2026-10-09T15:07:02.550997', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(935, 185, '01:02:15', 'Errore di produzione / Ombre', 'Durante la concitata scena dell''inseguimento nei vicoli, l''ombra del microfono a giraffa (boom mic) è chiaramente visibile per un paio di secondi sulla parete di mattoni a sinistra dello schermo.', TRUE, '2026-10-09T15:07:02.550997', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(936, 185, '01:14:45', 'Continuità / Oggetti', 'Quando Larry conta i soldi vinti alle corse dei cavalli, la mazzetta di banconote cambia spessore e disposizione tra il dettaglio ravvicinato delle sue mani e l''inquadratura più ampia che mostra anche il suo volto.', TRUE, '2026-10-09T15:07:02.550997', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(937, 185, '00:18:50', 'Anacronismo / Costumi', 'In una scena di strada affollata, alcune comparse femminili sullo sfondo indossano scarpe con tacchi e acconciature che riflettono la moda degli anni ''40 anziché la rigorosa ricostruzione storica dell''epoca tardo-vittoriana.', TRUE, '2026-10-09T15:07:02.550997', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(938, 189, '00:08:15', 'Incongruenza / Capelli', 'Durante il viaggio in auto verso New York, i capelli di Sally cambiano continuamente aspetto tra un''inquadratura e l''altra: in alcune scene sono visibilmente spettinati dal vento, mentre in quelle immediatamente successive sono perfettamente in ordine.', TRUE, '2026-10-09T15:27:00.329313', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(939, 189, '00:28:40', 'Incongruenza / Oggetti di scena', 'Nella scena in cui Harry e Sally camminano per Central Park in autunno, la sciarpa di Harry cambia il modo in cui è annodata intorno al collo diverse volte tra i cambi di inquadratura.', TRUE, '2026-10-09T15:27:00.329313', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(940, 189, '00:34:50', 'Microfono / Attrezzatura', 'Mentre Harry e Sally parlano al telefono guardando la televisione (la scena di Casablanca), nella parte superiore dello schermo, sul muro sopra la testa di Harry, è visibile per un breve istante l''ombra del microfono a giraffa che si muove.', TRUE, '2026-10-09T15:27:00.329313', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(941, 189, '00:45:30', 'Incongruenza / Cibo e Bevande', 'Nella celebre scena del finto orgasmo al ristorante ''Katz''s Delicatessen'', il panino di Sally cambia posizione sul piatto e la quantità di cibo rimasta varia inspiegabilmente tra i primi piani e i campi medi.', TRUE, '2026-10-09T15:27:00.329313', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(942, 189, '00:52:15', 'Incongruenza / Bicchieri', 'Durante la scena del doppio appuntamento a quattro, il livello del vino bianco nel bicchiere di Marie sale e scende ripetutamente senza che lei ne beva effettivamente.', TRUE, '2026-10-09T15:27:00.329313', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(943, 189, '01:02:10', 'Incongruenza / Recitazione', 'Nella scena del museo dove Harry parla con l''accento strano (''pepper'' monologue), l''espressione di Sally passa istantaneamente da un sorriso divertito a una faccia seria e annoiata tra due inquadrature consecutive, senza transizione temporale.', TRUE, '2026-10-09T15:27:00.329313', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(944, 189, '01:12:10', 'Incongruenza / Posizione', 'Durante la discussione sul tavolino a forma di ruota di carro tra Jess e Marie, la scatola di cartone sullo sfondo cambia posizione e orientamento tra un taglio e l''altro della telecamera.', TRUE, '2026-10-09T15:27:00.329313', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(945, 189, '01:29:05', 'Incongruenza / Abbigliamento', 'Alla festa di Capodanno finale, quando Harry corre per dichiararsi a Sally, il colletto della sua camicia e la sua cravatta cambiano posizione (prima slacciata e storta, poi sistemata) tra le inquadrature ravvicinate e quelle più larghe.', TRUE, '2026-10-09T15:27:00.329313', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(946, 194, '00:11:45', 'Incongruenza / Continuità', 'Durante il primo processo (il caso Gettys), la posizione delle mani di Kevin Lomax mentre tiene i fogli delle prove cambia repentinamente tra le inquadrature strette e quelle larghe, passando dall''essere tenuti con una sola mano a due mani sollevate.', TRUE, '2026-10-09T16:31:26.565729', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(947, 194, '00:42:10', 'Incongruenza / Continuità', 'Sulla terrazza dell''edificio di Milton, il forte vento spettina visibilmente i capelli di Kevin, mentre i capelli di Milton (Al Pacino) rimangono quasi immobili o si muovono in direzioni opposte a seconda dell''inquadratura, rivelando l''uso di barriere antivento posizionate solo per uno degli attori.', TRUE, '2026-10-09T16:31:26.565729', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(948, 194, '01:15:35', 'Incongruenza / Continuità', 'Quando Mary Ann (Charlize Theron) mostra a Kevin il suo nuovo taglio di capelli corto, la lunghezza e la simmetria delle ciocche cambiano visibilmente tra i primi piani e le inquadrature medie, segno che la parrucca o il taglio sono stati ritoccati tra i vari ciak.', TRUE, '2026-10-09T16:31:26.565729', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(949, 194, '01:38:22', 'Errore fattuale / Logistica', 'Nella scena della metropolitana di New York, il treno su cui sale Kevin mostra un numero di carrozza esterno che non corrisponde alla linea effettiva che sta percorrendo. Inoltre, gli interni cambiano modello di carrozza (da sedili arancioni a sedili blu/grigi) tra il momento dell''imbarco e il viaggio.', TRUE, '2026-10-09T16:31:26.565729', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(950, 194, '01:52:10', 'Attrezzatura visibile', 'Nelle pareti di marmo nero lucido e altamente riflettente dell''attico di Milton, mentre Kevin cammina lungo il corridoio principale, è possibile scorgere per un breve istante il riflesso di un operatore della troupe con una telecamera montata su steadicam.', TRUE, '2026-10-09T16:31:26.565729', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(951, 194, '02:08:40', 'Sincronizzazione audio/video', 'Durante il celebre monologo finale di John Milton nell''ufficio, in un paio di inquadrature di profilo il movimento delle sue labbra non coincide con le parole pronunciate nella traccia audio originale, indicando che è stata utilizzata una ripresa alternativa (alternate take) sovrapposta al montaggio sonoro definitivo.', TRUE, '2026-10-09T16:31:26.565729', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(952, 194, '02:14:15', 'Incongruenza / Oggetti', 'Durante lo scontro finale, quando l''ufficio inizia a subire mutamenti e fiamme, la disposizione dei fogli, dei libri e dei bicchieri sulla scrivania di Milton cambia drasticamente da un''inquadratura all''altra senza che nessuno li tocchi, svelando il reset della scena tra i diversi ciak degli effetti speciali.', TRUE, '2026-10-09T16:31:26.565729', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(728, 139, '00:18:15', 'Errori di scena / Posizione', 'Nelle scene in cui Prince (Joey King) manipola il giovane Kimura, tiene in mano un libro. La posizione delle sue dita tra le pagine e il punto esatto in cui il libro è aperto cambiano repentinamente tra un''inquadratura frontale e quella da sopra la spalla, rivelando che le riprese sono state effettuate in momenti diversi.', TRUE, '2026-09-26T15:22:11.065646', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(729, 139, '00:22:10', 'Errori storici o fattuali', 'Nella scena in cui Ladybug sperimenta le funzioni del water tecnologico giapponese, il getto d''acqua continua a spruzzare verso l''alto con forza anche dopo che lui si è alzato. Nella realtà, i sanitari Washlet giapponesi sono dotati di sensori di pressione sul sedile che interrompono istantaneamente l''erogazione dell''acqua non appena l''utente si alza, per evitare allagamenti.', TRUE, '2026-09-26T15:22:11.065646', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(953, 199, '00:18:45', 'Continuità / Trucco e costumi', 'Durante la cattura della giovane Furiosa da parte degli scagnozzi di Dementus, le striature di fango e terra sul volto della bambina cambiano forma e densità tra i primi piani e le inquadrature a mezzo busto.', TRUE, '2026-10-09T18:21:32.14648', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(954, 199, '00:42:10', 'Continuità / Oggetti di scena', 'L''orsacchiotto di pezza legato all''armatura di Dementus durante i negoziati alla Cittadella cambia orientamento: in un''inquadratura pende verso il lato sinistro con le zampe piegate, mentre al controcampo successivo è perfettamente dritto e le cinghie di fissaggio sono allacciate diversamente.', TRUE, '2026-10-09T18:21:32.14648', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(955, 199, '01:12:35', 'Continuità / Danni ai veicoli', 'Nel corso dell''attacco aereo dei Mortiflyer guidati dall''Octoboss contro la War Rig, uno dei lati della cisterna viene squarciato e perforato da arpioni; nelle inquadrature dal basso subito seguenti, lo stesso pannello metallico appare liscio e privo di fori.', TRUE, '2026-10-09T18:21:32.14648', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(956, 199, '01:29:50', 'Continuità / Armi e oggetti', 'Durante lo scontro a Bullet Farm con Praetorian Jack e Furiosa, il conteggio dei colpi sparati dal fucile non corrisponde al numero di bossoli espulsi: in un cambio di angolazione, una camera di scoppio precedentemente vuota riappare carica senza che il personaggio abbia effettuato il ricaricamento.', TRUE, '2026-10-09T18:21:32.14648', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(957, 199, '01:54:12', 'Continuità / Trucco e protesi', 'Nel momento in cui Furiosa fugge dopo aver perso l''avambraccio, la fasciatura emostatica e l''estensione del moncherino mostrano discrepanze anatomiche evidenti tra il campo lungo in cui si trascina nella sabbia e il primo piano successivo.', TRUE, '2026-10-09T18:21:32.14648', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(958, 199, '02:08:40', 'Continuità / Costumi', 'Durante l''inseguimento finale nella desolazione, il mantello di Dementus passa dall''essere pesantemente strappato, sporco e ingrigito dalla polvere a una tonalità notevolmente più pulita e accesa nelle inquadrature ravvicinate subito dopo lo schianto della sua vettura.', TRUE, '2026-10-09T18:21:32.14648', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(959, 199, '02:18:25', 'Errori di scena / Posizione', 'Nel faccia a faccia culminante tra Furiosa e Dementus, la pistola lasciata cadere nella sabbia si sposta di oltre un metro rispetto ai piedi di Dementus tra l''inquadratura dall''alto e il controcampo a livello del suolo, senza che nessuno dei due l''abbia calciata.', TRUE, '2026-10-09T18:21:32.14648', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(960, 200, '00:35:15', 'Incongruenza / Continuità', 'Le chiazze di sudore sulla camicia blu di Sonny (Al Pacino) cambiano continuamente di forma e dimensione tra un''inquadratura e l''altra durante le trattative all''esterno della banca, scomparendo quasi del tutto in alcune scene per poi riapparire più estese subito dopo.', TRUE, '2026-10-09T21:20:04.937473', NULL, 0, 0, 'mrrtgrg11@gmail.com', 'ia')
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza") VALUES
(961, 200, '00:42:10', 'Incongruenza / Trucco e Parrucco', 'I capelli di Sonny appaiono completamente bagnati di sudore e scompigliati in un''inquadratura ravvicinata, ma nel controcampo immediatamente successivo sono visibilmente più asciutti e ordinati.', TRUE, '2026-10-09T21:20:04.937473', NULL, 0, 0, 'mrrtgrg11@gmail.com', 'ia'),
(962, 200, '00:48:15', 'Apparecchiature visibili', 'Durante la celebre scena in cui Sonny arringa la folla gridando ''Attica! Attica!'', nel riflesso dei vetri della banca e di un''auto parcheggiata è possibile scorgere per un breve istante la sagoma di un operatore con la cinepresa e un pannello riflettente per le luci.', TRUE, '2026-10-09T21:20:04.937473', NULL, 0, 0, 'mrrtgrg11@gmail.com', 'ia'),
(963, 200, '00:55:30', 'Errore di continuità / Oggetti', 'L''orologio da parete all''interno della banca mostra orari incoerenti rispetto allo scorrere reale del tempo della narrazione. In alcune sequenze l''orario salta avanti e indietro di oltre dieci minuti tra inquadrature consecutive dello stesso dialogo.', TRUE, '2026-10-09T21:20:04.937473', NULL, 0, 0, 'mrrtgrg11@gmail.com', 'ia'),
(964, 200, '01:12:05', 'Incongruenza / Oggetti di scena', 'Alcune auto della polizia di New York posizionate fuori dalla banca cambiano misteriosamente il numero identificativo sulla carrozzeria o presentano diversi modelli di lampeggianti sul tetto tra le riprese dall''alto e quelle a livello della strada.', TRUE, '2026-10-09T21:20:04.937473', NULL, 0, 0, 'mrrtgrg11@gmail.com', 'ia'),
(965, 200, '01:22:40', 'Errore di scena / Posizione', 'Nella scena in cui vengono consegnate le pizze per gli ostaggi, il modo in cui Sonny afferra e tiene i cartoni cambia istantaneamente tra i tagli di montaggio: prima li sostiene con entrambe le mani dal basso, poi improvvisamente ne tiene uno sotto il braccio sinistro.', TRUE, '2026-10-09T21:20:04.937473', NULL, 0, 0, 'mrrtgrg11@gmail.com', 'ia'),
(966, 200, '01:35:10', 'Errore di scena / Posizione', 'Sal (John Cazale) tiene il suo fucile puntato in direzioni diverse tra i primi piani e i campi medi. In un''inquadratura l''arma è appoggiata sulla sua gamba, ma nel taglio successivo è immediatamente puntata verso gli ostaggi, senza che lui abbia compiuto il movimento.', TRUE, '2026-10-09T21:20:04.937473', NULL, 0, 0, 'mrrtgrg11@gmail.com', 'ia'),
(730, 139, '00:31:15', 'Errori di scena / Posizione', 'Durante lo scontro letale tra Ladybug (Brad Pitt) e il Lupo (Bad Bunny), il coltello di quest''ultimo si conficca profondamente nella valigetta metallica. Nei cambi di inquadratura successivi, l''inclinazione del coltello e la profondità della lama penetrata nella valigetta variano visibilmente tra i piani ravvicinati e i campi medi.', TRUE, '2026-09-26T15:22:11.065646', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(967, 202, '00:16:45', 'Continuità / Acconciatura', 'Durante la scena della Mietitura nel Distretto 12, quando Katniss si offre volontaria al posto della sorella Prim, la sua treccia cambia posizione più volte tra la spalla sinistra, la spalla destra e la schiena a seconda dell''inquadratura.', TRUE, '2026-10-11T16:28:20.885381', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(968, 202, '00:43:10', 'Continuità / Posizione', 'Durante la sfilata dei Tributi sulle bighe a Capitol City, la mano di Peeta attorno alla vita di Katniss cambia posizione tra i campi lunghi e i primi piani, passando dal fianco alla schiena.', TRUE, '2026-10-11T16:28:20.885381', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(969, 202, '00:49:25', 'Errori di scena / Oggetti', 'Quando Katniss scaglia la freccia contro la mela nella bocca del maiale davanti ai Favoriti, il punto d''impatto e l''inclinazione della freccia nella mela cambiano tra il momento dell''impatto e la vista d''insieme.', TRUE, '2026-10-11T16:28:20.885381', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(970, 202, '01:18:15', 'Continuità / Trucco', 'Dopo che Katniss viene punta dalle Aghi Killer (Tracker Jackers), le pustole e il gonfiore da veleno sul suo collo e sul viso cambiano dimensione e disposizione tra un''inquadratura e l''altra.', TRUE, '2026-10-11T16:28:20.885381', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(971, 202, '01:26:40', 'Continuità / Oggetti di scena', 'Nella scena della morte di Rue, Katniss circonda il corpo della bambina con dei fiori. La quantità, la tipologia e la disposizione esatta dei fiori cambiano tra il primo piano e la visuale dall''alto.', TRUE, '2026-10-11T16:28:20.885381', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(972, 202, '01:33:50', 'Continuità / Trucco', 'Quando Katniss ritrova Peeta mimetizzato sulle rive del fiume, il fango e la pittura mimetica sulla guancia e sulla fronte di Peeta cambiano forma e densità prima ancora che Katniss glieli pulisca.', TRUE, '2026-10-11T16:28:20.885381', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(973, 202, '02:08:10', 'Continuità / Oggetti di scena', 'Nel momento culminante in cui Katniss e Peeta minacciano di ingerire le bacche velenose (Morsoserrato), la quantità e la disposizione delle bacche nel palmo della mano di Katniss variano tra il campo stretto e il controcampo.', TRUE, '2026-10-11T16:28:20.885381', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(974, 213, '00:24:15', 'Continuità', 'Durante la prima violenta tempesta che colpisce la Essex, la giacca di Owen Chase passa dall''essere completamente zuppa e aderente a visibilmente meno bagnata e asciutta sulle spalle tra due stacchi di montaggio consecutivi.', TRUE, '2026-10-17T15:13:31.17943', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(975, 213, '00:47:30', 'Continuità / Oggetti', 'Durante la caccia alla prima balena, la cima attaccata all''arpione lanciato da Chase si trova a sinistra del bordo della lancia, ma nel controcampo ravvicinato la fune scorre direttamente al centro della prua senza che nessuno l''abbia spostata.', TRUE, '2026-10-17T15:13:31.17943', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(976, 213, '01:03:50', 'Errori di scena / Danni', 'Quando il gigantesco capodoglio bianco sperona la Essex la prima volta, le tavole dello scafo vengono sfondate verso l''interno. Nella successiva scena sottocoperta, i frammenti di legno e le assi spezzate appaiono orientati diversamente e la falla presenta dimensioni notevolmente ridotte rispetto all''esterno.', TRUE, '2026-10-17T15:13:31.17943', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(977, 213, '01:19:20', 'Anacronismo / Trucco', 'Dopo settimane alla deriva in mare aperto con razionamento estremo e forte disidratazione, i denti di Owen Chase e del capitano Pollard rimangono perfettamente allineati, bianchi e senza alcun segno visibile di scorbuto o deterioramento gengivale tipico dell''epoca e della situazione.', TRUE, '2026-10-17T15:13:31.17943', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(978, 213, '01:31:05', 'Continuità', 'Sull''isola di Henderson, mentre Matthew Joy è disteso sulla sabbia visibilmente debilitato, la quantità di sabbia e il livello di ustioni sulla sua guancia destra cambiano tra il primo piano e la vista d''insieme.', TRUE, '2026-10-17T15:13:31.17943', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(979, 213, '01:44:40', 'Anacronismo / Oggetti di scena', 'In un''inquadratura ravvicinata del sartiame di una delle scialuppe di salvataggio alla deriva, è visibile una cima con trama a calza intrecciata moderna di materiale sintetico, anziché la tradizionale cima ritorta in fibra di canapa dell''inizio del XIX secolo.', TRUE, '2026-10-17T15:13:31.17943', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(980, 213, '01:53:10', 'Continuità', 'Nel confronto finale tra Chase e la balena bianca, il protagonista impugna l''arpione con le nocche sporche di sangue scuro incrostato; nell''inquadratura successiva, quando decide di non colpirla e abbassa il braccio, le sue mani sono bagnate ma completamente pulite dal sangue.', TRUE, '2026-10-17T15:13:31.17943', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(731, 139, '00:54:40', 'Errori di scena / Posizione', 'Durante la frenetica lotta nella carrozza ristoro tra Ladybug e Tangerine (Aaron Taylor-Johnson), Ladybug subisce un taglio sulla spalla e sul braccio. Nelle inquadrature immediatamente successive, la macchia di sangue sulla sua maglietta bianca cambia forma, dimensione e intensità di colore diverse volte senza una logica temporale.', TRUE, '2026-09-26T15:22:11.065646', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(732, 139, '01:12:05', 'Errori di scena / Posizione', 'La valigetta d''argento contenente il riscatto subisce numerosi urti, graffi e ammaccature durante il film. In particolare, dopo lo scontro con Lemon, i vistosi graffi sulla superficie metallica della valigetta appaiono e scompaiono o cambiano lato a seconda dell''inquadratura speculare utilizzata nel montaggio.', TRUE, '2026-09-26T15:22:11.065646', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(39, 10, '00:15:20', 'Continuity', 'Durante l''inseguimento in auto a Shanghai, la posizione del vestito e della sciarpa di Willie cambia drasticamente tra i primi piani interni e le riprese esterne della vettura.', TRUE, '2026-09-13T14:53:50.74232', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(40, 10, '01:12:05', 'Crew & Equipment', 'Nella celebre sequenza dei carrelli della miniera, in diverse inquadrature ravvicinate ad alta velocità si notano chiaramente i modellini in miniatura e i pupazzi di stop-motion utilizzati per gli effetti speciali.', TRUE, '2026-09-13T14:53:50.84008', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(41, 11, '00:48:30', 'Fattuale / Storico', 'Durante il rogo dei libri a Berlino, la marcia militare suonata dalla banda è ''Königgrätzer Marsch'', ma gli ufficiali indossano uniformi della SS con dettagli ed elmetti introdotti solo diversi anni più tardi.', TRUE, '2026-09-13T14:53:51.250368', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(351, 68, '00:08:15', 'Anacronismi', 'La lettera di arruolamento che Robin riceve presenta una carta estremamente liscia, bianca e dai bordi perfettamente tagliati a macchina, tipica della produzione industriale moderna. Inoltre, i caratteri stampati sembrano realizzati con una pressa a caratteri mobili o addirittura con un font digitale moderno, secoli prima dell''invenzione della stampa di Gutenberg.', TRUE, '2026-09-15T18:05:31.609342', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(16, 3, '00:18:25', 'Continuity', 'L''icona dello stato della batteria sul display della videocamera passa da una sola tacca rossa a tre tacche verdi in diverse inquadrature nel corso della notte, senza che Hud abbia mai la possibilità di ricaricarla o sostituirla.', TRUE, '2026-09-13T14:43:24.454115', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(17, 3, '00:27:50', 'Fattuale / Storico', 'Durante la fuga sul ponte di Brooklyn, la testa della Statua della Libertà che vaga per le strade cade in una direzione e con un''angolazione topograficamente impossibile rispetto alla posizione reale di Liberty Island e Manhattan.', TRUE, '2026-09-13T14:43:24.547987', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(18, 3, '00:41:10', 'Continuity', 'Le macchie di sangue e la lacerazione sulla maglietta di Marlena cambiano forma, dimensione e posizione esatta tra il momento dell''attacco nel tunnel e l''arrivo al campo medico militare.', TRUE, '2026-09-13T14:43:24.589337', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(21, 4, '00:03:15', 'Continuity', 'Nella sequenza d''apertura in cui Ace impersona un corriere, i danni, i tagli e la posizione del nastro adesivo sulla scatola cambiano visibilmente tra un''inquadratura e l''altra mentre la maltratta lungo il corridoio e nell''ascensore.', TRUE, '2026-09-13T14:44:03.572178', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(22, 4, '00:24:10', 'Crew & Equipment', 'Mentre Ace guida la sua auto con la testa fuori dal finestrino a causa del parabrezza distrutto, nel riflesso sulla carrozzeria e sugli occhiali da sole sono chiaramente visibili le luci di scena e la troupe sul camion di supporto.', TRUE, '2026-09-13T14:44:03.687442', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(23, 4, '00:45:30', 'Continuity', 'Durante la festa a casa di Ronald Camp, il livello del drink nel bicchiere di Ace e la posizione dei vari stuzzichini sul suo piatto continuano a cambiare da pieni a quasi vuoti ad ogni cambio di inquadratura.', TRUE, '2026-09-13T14:44:03.773975', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(24, 4, '01:02:15', 'Fattuale / Storico', 'Nella sequenza in cui Ace cade nella vasca dello squalo, l''animale emette dei versi acustici avvertibili sott''acqua. In realtà gli squali sono totalmente privi di organi vocali e non possono emettere alcun tipo di ruggito o suono.', TRUE, '2026-09-13T14:44:03.873502', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(25, 4, '01:18:40', 'Continuity', 'Nello scontro finale al molo, la pettinatura iconica di Ace passa dall''essere completamente sfatta, arruffata e bagnata di sudore ad essere perfettamente sistemata e asciutta nei vari controcampi.', TRUE, '2026-09-13T14:44:03.918097', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(30, 6, '01:25:10', 'Continuity', 'Nella celebre scena in cui Sonny picchia Carlo per strada, Sonny sferra un pugno che manca nettamente il volto di Carlo di diversi centimetri. Nonostante ciò, si sente l''effetto sonoro del colpo e Carlo reagisce come se fosse stato colpito in pieno.', TRUE, '2026-09-13T14:48:17.949248', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(981, 214, '00:23:15', 'Continuità / Meteo', 'Quando Keller e Franklin cercano le bambine per strada sotto la pioggia, la quantità di neve fusa e gocce d''acqua sul parabrezza dell''auto di Keller cambia drasticamente tra la visuale dall''interno e le inquadrature esterne consecutive.', TRUE, '2026-10-17T17:46:08.029438', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(982, 214, '00:41:10', 'Errori di scena / Posizione', 'Durante il primo interrogatorio di Alex Jones alla stazione di polizia, la posizione del colletto della camicia del Detective Loki cambia tra un controcampo e l''altro, coprendo e scoprendo alternativamente il tatuaggio sul collo.', TRUE, '2026-10-17T17:46:08.029438', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(983, 214, '01:02:45', 'Continuità / Oggetti', 'Quando Keller affronta Alex nei pressi del parcheggio e lo afferra per la giacca, la posizione delle sue mani sul bavero di Alex cambia istantaneamente da un''inquadratura all''altra.', TRUE, '2026-10-17T17:46:08.029438', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(984, 214, '01:28:30', 'Continuità / Oggetti di scena', 'Nella scena del bagno dell''edificio abbandonato, il martello impugnato da Keller cambia orientamento (con la testa della battuta rivolta prima verso l''alto e poi verso il basso) senza che lui lo ruoti visibilmente tra i dettagli e i campi medi.', TRUE, '2026-10-17T17:46:08.029438', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(985, 214, '01:48:15', 'Errori di scena / Posizione', 'Durante la perquisizione a casa di Bob Taylor, la disposizione dei fogli disegnati con i labirinti e della penna sul tavolo si modifica tra l''inquadratura dall''alto e il piano ravvicinato sul detective Loki.', TRUE, '2026-10-17T17:46:08.029438', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(986, 214, '02:14:05', 'Continuità / Trucco', 'Durante la drammatica corsa in auto verso l''ospedale sotto la neve, il flusso di sangue sulla fronte del Detective Loki altera la sua traiettoria e densità tra le varie riprese dall''interno dell''abitacolo.', TRUE, '2026-10-17T17:46:08.029438', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(987, 214, '02:22:40', 'Errori di scena / Posizione', 'Nella scena finale nel cortile dei Jones, la posizione del fischietto rosso sepolto vicino alla buca cambia leggermente orientamento rispetto alle foglie secche tra il primo piano e l''inquadratura più ampia.', TRUE, '2026-10-17T17:46:08.029438', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(31, 6, '02:14:05', 'Anacronismo', 'Durante le riprese ambientate in Sicilia nel paesino di Savoca alla fine degli anni ''40, sullo sfondo sono chiaramente visibili diverse antenne televisive posizionate sui tetti delle case, tecnologia del tutto assente all''epoca nell''isola.', TRUE, '2026-09-13T14:48:18.035703', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(32, 7, '00:45:20', 'Crew & Equipment', 'Durante la sequenza della festa di San Gennaro a Little Italy nella parte dedicata al giovane Vito, nel riflesso del finestrino di un''auto d''epoca si nota nitidamente l''ombra di un operatore di ripresa con la macchina da presa.', TRUE, '2026-09-13T14:48:18.269067', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(33, 7, '02:32:15', 'Fattuale / Storico', 'Nelle scene ambientate a L''Avana durante la notte di Capodanno del 1958, compaiono tra il traffico della città alcune automobili americane prodotte soltanto nel 1959, mesi dopo gli avvenimenti narrati.', TRUE, '2026-09-13T14:48:18.341919', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(34, 8, '02:38:40', 'Continuity', 'Sulla scalinata del Teatro Massimo di Palermo, la macchia di sangue sulla camicia di Mary Corleone cambia forma, dimensione e posizione tra i primi piani e le inquadrature a figura intera.', TRUE, '2026-09-13T14:48:18.579126', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(35, 8, '01:12:05', 'Continuity', 'Durante la drammatica sparatoria in elicottero nella sala riunioni di Atlantic City, la giacca della giacca di Michael appare completamente sbottonata in un''inquadratura per poi risultare perfettamente abbottonata nel controcampo successivo.', TRUE, '2026-09-13T14:48:18.647442', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(42, 11, '01:15:22', 'Continuity', 'Durante la lunga lotta sopra il carro armato nel deserto, la quantità di polvere e fango sulla giacca e sul viso di Harrison Ford varia continuamente da un secondo all''altro.', TRUE, '2026-09-13T14:53:51.356777', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(43, 12, '00:22:15', 'Anacronismo', 'Quando Indy e Mutt arrivano in Perù, la musica di sottofondo è una versione del brano ''Bandstand Boogie'' incisa negli anni ''70, non compatibile con l''ambientazione del 1957.', TRUE, '2026-09-13T14:53:51.654872', NULL, 0, 0, 'IA (Sistema)', 'ia')
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza") VALUES
(44, 12, '00:54:10', 'Continuity', 'Nella scena del cimitero di Nazca, le ragnatele che si attaccano ai vestiti e ai capelli di Mutt scompaiono e riappaiono tra varie inquadrature ravvicinate.', TRUE, '2026-09-13T14:53:51.762687', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(45, 13, '00:18:40', 'Fattuale / Storico', 'Nella sequenza iniziale del 1944, il treno merci tedesco mostra marcature e codici di serie ferroviari entrati in uso formale solo nei primi anni ''50.', TRUE, '2026-09-13T14:53:52.073872', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(46, 13, '01:05:12', 'Continuity', 'Durante l''inseguimento a Tangeri a bordo dei tuk-tuk, lo specchietto retrovisore del veicolo guidato da Indy risulta spezzato dopo un urto, ma torna integro nel campo lungo successivo.', TRUE, '2026-09-13T14:53:52.184805', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(988, 221, '00:14:35', 'Anacronismo / Oggetti di scena', 'Durante l''ingresso trionfale delle legioni romane lungo la Via Appia, sullo sfondo si intravedono i tralicci della corrente e le sagome di pali telegrafici moderni.', TRUE, '2026-10-18T02:08:04.645341', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(989, 221, '00:38:12', 'Errore di continuità / Posizione', 'Durante la scena del banchetto palazzo di Nerone, il calice d''oro impugnato da Nerone (Peter Ustinov) passa dalla mano destra alla mano sinistra tra due inquadrature contigue del medesimo dialogo.', TRUE, '2026-10-18T02:08:04.645341', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(990, 221, '01:02:45', 'Anacronismo / Costumi', 'Quando Marco Vinicio (Robert Taylor) solleva il braccio per redarguire i suoi uomini, da sotto il parabraccio in cuoio emerge chiaramente il cinturino di un orologio da polso moderno.', TRUE, '2026-10-18T02:08:04.645341', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(991, 221, '01:28:10', 'Membri della troupe / Attrezzatura visibile', 'Mentre Nerone decanta i suoi versi osservando il plastico di Roma, sulla colonna alla sua sinistra si nota nettamente l''ombra del microfono a braccio (boom mic) in movimento.', TRUE, '2026-10-18T02:08:04.645341', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(992, 221, '01:54:20', 'Errore di continuità / Trucco e Parrucco', 'Durante la fuga dall''incendio di Roma, i capelli di Licia (Deborah Kerr) cambiano acconciatura tra il campo lungo (sciolti e arruffati) e il primo piano immediatamente successivo (mantenuti in una pettinatura ordinata).', TRUE, '2026-10-18T02:08:04.645341', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(993, 221, '02:15:05', 'Errore di continuità / Posizione', 'Nella sequenza dell''arena col toro, la corda che lega Licia al palo di legno risulta stretta attorno alle sue spalle nel campo stretto, ma scivolata all''altezza della vita nelle inquadrature ampie.', TRUE, '2026-10-18T02:08:04.645341', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(994, 221, '02:32:40', 'Anacronismo / Costumi', 'Quando un soldato della guardia pretoriana viene spinto a terra durante la rivolta finale, la suola dei suoi calzari rivela una finitura in gomma vulcanizzata con disegno antiscivolo moderno.', TRUE, '2026-10-18T02:08:04.645341', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(50, 15, '00:52:10', 'Anacronismo', 'Sul cruscotto dell''idroscivolo di Madame Medusa compare un moderno orologio digitale a segmenti, un dettaglio anacronistico rispetto all''ambientazione temporale della storia.', TRUE, '2026-09-13T14:58:31.824978', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(52, 16, '00:41:05', 'Continuity', 'Il pettine che Jake tiene nel taschino scompare e riappare improvvisamente durante il dialogo intorno al fuoco.', TRUE, '2026-09-13T14:58:32.247132', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(53, 17, '00:15:30', 'Continuity', 'Durante la partita di calcetto, i calzettoni di Leo risultano tirati su fino al ginocchio nell''inquadratura frontale, ma sono totalmente abbassati sulle caviglie nel controcampo immediato.', TRUE, '2026-09-13T14:58:32.539327', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(54, 17, '00:58:40', 'Crew & Equipment', 'Nel riflesso del vetro della finestra della camera di Leo è visibile per alcuni secondi la sagoma di un operatore di macchina intento a girare.', TRUE, '2026-09-13T14:58:32.636603', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(55, 18, '00:22:15', 'Fattuale / Storico', 'Nelle riprese sul ponte dell''incrociatore sono visibili targhe tecniche di artiglieria con numerazioni e specifiche entrate in uso nella Marina Militare soltanto in un periodo successivo.', TRUE, '2026-09-13T14:58:32.845547', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(58, 20, '00:42:10', 'Continuity', 'Durante l''incontro di pugilato, il taglio sulla guancia del protagonista cambia forma e quantità di sangue visibile tra un campo medio e il primo piano.', TRUE, '2026-09-13T15:01:44.330759', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(59, 20, '01:15:22', 'Crew & Equipment', 'Nella parte superiore dello schermo entra brevemente nell''inquadratura il microfono a spugna dell''operatore audio.', TRUE, '2026-09-13T15:01:44.369792', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(995, 232, '00:18:45', 'Continuità', 'Quando Jeff e Pam arrivano davanti alla casa dei Mercer, la disposizione della neve sul viale d''ingresso e sulle piante cambia visibilmente tra la ripresa panoramica dall''alto e il primo piano dei personaggi.', TRUE, '2026-10-23T13:15:21.256663', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(996, 232, '00:28:10', 'Errori di scena / Posizione', 'Durante la scena in cui Max si abbuffa di cibo spazzatura da solo a casa, le macchie di cibo e gelato sul suo maglione cambiano forma, estensione e posizione tra una ripresa e l''altra.', TRUE, '2026-10-23T13:15:21.256663', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(997, 232, '00:42:15', 'Anacronismi / Errore di logica', 'Quando Carol (la madre di Max) chiama dal Giappone, l''orario mostrato sullo schermo del suo smartphone e la luce del sole fuori dalla finestra indicano un fuso orario del tutto incoerente rispetto all''orario notturno di Chicago.', TRUE, '2026-10-23T13:15:21.256663', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(60, 21, '00:25:40', 'Continuity', 'Durante la scena dell''allenamento, il mantello di Timo scompare tra un fotogramma e l''altro subito dopo essere caduto per terra.', TRUE, '2026-09-13T15:01:44.642885', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(998, 232, '00:54:30', 'Continuità', 'Nella sequenza del giardino con le trappole, Jeff viene colpito da farina e proiettili di ghiaccio. Nel campo lungo la sua giacca è completamente imbrattata di bianco, ma nell''inquadratura stretta subito successiva la quantità di polvere sui vestiti è visibilmente ridotta.', TRUE, '2026-10-23T13:15:21.256663', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(999, 232, '01:03:50', 'Troupe / Attrezzatura visibile', 'Durante il tentativo di intrusione dalla finestra laterale, sul vetro riflettente dell''auto di Jeff si intravede chiaramente la sagoma di un pannello riflettente e di un operatore della troupe.', TRUE, '2026-10-23T13:15:21.256663', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1000, 232, '01:11:20', 'Errori di scena / Oggetti di scena', 'Quando Pam recupera la rara bambola ''Cotto'', la posizione delle braccia e l''orientamento del tessuto della bambola cambiano posizione da sola tra un controcampo e l''altro senza che la donna la muova.', TRUE, '2026-10-23T13:15:21.256663', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1001, 232, '01:18:05', 'Continuità', 'Nella scena finale del chiarimento dell''equivoco, i capelli di Max appaiono arruffati e sudati in un''inquadratura, per poi diventare perfettamente asciutti e pettinati nella ripresa immediatamente successiva.', TRUE, '2026-10-23T13:15:21.256663', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(61, 22, '00:33:15', 'Anacronismo', 'Sullo sfondo della straduzza di campagna, durante l''inseguimento dei carri, si scorgono i solchi lasciati dai pneumatici dei camion della troupe.', TRUE, '2026-09-13T15:01:44.950579', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(62, 23, '00:51:00', 'Crew & Equipment', 'Sulla spalla di un cavallo in corsa si nota chiaramente l''ombra proiettata dalla macchina da presa montata sulla gru.', TRUE, '2026-09-13T15:01:45.254151', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(63, 24, '00:19:30', 'Continuity', 'L''elsa della spada impugnata dal protagonista passa dall''essere dritta a curva nel passaggio dal primo piano al totale.', TRUE, '2026-09-13T15:01:45.560088', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(64, 25, '01:02:14', 'Anacronismo', 'Un centurione romano sullo sfondo alza il braccio sinistro rivelando un orologio da polso moderno sotto l''armatura.', TRUE, '2026-09-13T15:01:45.866621', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(88, 37, '00:26:45', 'Errori di scena / Posizione', 'Nella famosa scena del negozio di dischi, quando Alex approccia le due ragazze, i vinili esposti nei rastrellieri sullo sfondo cambiano disposizione e ordine d''inclinazione da un montaggio all''altro.', TRUE, '2026-09-13T15:23:45.181714', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1002, 234, '00:22:15', 'Anacronismi', 'Quando Eloise compie il suo primo viaggio nel tempo e arriva a Piccadilly Circus, il cinema Odeon espone il cartellone di ''Thunderball'' (Operazione tuono), film uscito nelle sale britanniche il 29 dicembre 1965. Tuttavia, la folla per strada indossa abiti primaverili/estivi leggeri e la vegetazione circostante non corrisponde minimamente al pieno inverno londinese di fine anno.', TRUE, '2026-10-24T15:28:27.637727', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(89, 37, '00:32:10', 'Troupe o microfoni visibili', 'Nella sequenza in cui Alex spinge i suoi Drughi nel canale d''acqua dopo il litigio, in un campo lungo si nota chiaramente l''ombra della macchina da presa e dell''operatore proiettata sul bordo in cemento del canale.', TRUE, '2026-09-13T15:23:45.218919', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(90, 37, '00:48:20', 'Errori di scena / Posizione', 'Nel scontro a casa della signora dei gatti, la grande scultura fallica bianca usata come arma del delitto cambia orientamento sul pavimento tra il momento prima dell''impatto e il momento subito successivo alla caduta della donna.', TRUE, '2026-09-13T15:23:45.286256', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(91, 37, '01:05:10', 'Errori storici o fattuali', 'Durante la dimostrazione della cura Ludovico con i divaricatori oculari, gli occhi di Malcolm McDowell mostrano una fisiologia errata: l''uso prolungato di tali clip senza idratazione farmacologica continua e anestetico locale causerebbe lesioni corneali immediate e permanente slargamento pupillare incongruo con le reazioni visibili nell''attore.', TRUE, '2026-09-13T15:23:45.32596', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1003, 234, '00:30:45', 'Errori di scena / Posizione', 'Durante la complessa coreografia al Café de Paris, in cui Sandie ed Eloise si scambiano continuamente mentre ballano con Jack, la posizione della mano di Jack sulla schiena della partner si sposta repentinamente: in campo medio è appoggiata aperta all''altezza della scapola, mentre nello stacco ravvicinato successivo si trova molto più in basso sui fianchi.', TRUE, '2026-10-24T15:28:27.637727', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1004, 234, '00:16:10', 'Errori di scena / Posizione', 'Durante la prima lezione al London College of Fashion, Eloise realizza un bozzetto sul suo blocco. Nelle inquadrature strette sul foglio il colletto del vestito disegnato a matita è già chiaramente rifinito e sfumato, ma nell''inquadratura più ampia successiva il foglio torna a mostrare soltanto un abbozzo incompleto delle linee principali.', TRUE, '2026-10-24T15:28:27.637727', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1006, 234, '01:08:40', 'Errori di scena / Posizione', 'Alla festa di Halloween nel locale, durante la conversazione tesa tra Eloise e John, il bicchiere di birra che il ragazzo tiene in mano si riempie magicamente: inizialmente la schiuma è quasi sparita e il bicchiere è mezzo vuoto, ma allo stacco successivo il livello della birra sale di diversi centimetri senza che John abbia bevuto o rabboccato.', TRUE, '2026-10-24T15:28:27.637727', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1007, 234, '01:42:15', 'Errori di scena / Posizione', 'Nello scontro finale all''interno della camera in fiamme, le macchie di sangue e fuliggine sulle mani e sulle guance di Eloise cambiano continuamente intensità e distribuzione tra i primi piani e le inquadrature a figura intera.', TRUE, '2026-10-24T15:28:27.637727', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1005, 234, '00:46:25', 'Errori storici o fattuali', 'In una delle sequenze notturne ambientate negli anni ''60 nei vicoli di Soho, vicino al bordo del marciapiede è chiaramente visibile la pavimentazione tattile a rilievo per non vedenti (blister paving), un''infrastruttura urbana standardizzata e introdotta nel Regno Unito solo a partire dagli anni ''90.', TRUE, '2026-10-24T15:28:27.637727', NULL, 0, 1, 'IA (Sistema)', 'ia'),
(92, 37, '01:38:00', 'Errori di scena / Posizione', 'Quando Alex torna a casa dei genitori dopo la prigione e trova l''affittuario Joe, il livello del tè nelle tazze sul tavolo e la posizione dei biscotti cambiano visibilmente tra il primo piano e il campo medio.', TRUE, '2026-09-13T15:23:45.392667', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(762, 118, '00:00:00', 'Anacronismi', 'prova salvataggio', TRUE, '2026-09-28T07:09:09.830548', NULL, 0, 0, 'lrscrm73@gmail.com', 'utente'),
(1008, 233, '00:14:22', 'Errori di scena / Posizione', 'Durante il primo confronto verbale tra Test Attore 1 e Test Attore 2, una cartella di documenti aperta sulla scrivania si richiude improvvisamente tra un controcampo e il successivo senza che nessuno l''abbia toccata.', TRUE, '2026-10-24T15:34:44.070248', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1009, 233, '00:28:45', 'Troupe o microfoni visibili', 'Nel corridoio, mentre la cinepresa segue il movimento dei personaggi all''indietro, nell''angolo in alto a destra compare visibilmente l''estremità della spugna antivento di un microfono a giraffa.', TRUE, '2026-10-24T15:34:44.070248', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1010, 233, '00:45:10', 'Errori di scena / Posizione', 'Durante la sequenza in cucina, Test Attore 1 afferra una tazza con la mano destra nel piano medio, ma nello stacco successivo in primo piano la tazza si trova già saldamente nella mano sinistra.', TRUE, '2026-10-24T15:34:44.070248', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1011, 233, '01:02:18', 'Troupe o microfoni visibili', 'Nel riflesso del finestrino dell''automobile in sosta, mentre Test Attore 2 sale a bordo, si può notare l''operatore alla macchina da presa con addosso un giubbotto scuro e un pannello riflettente.', TRUE, '2026-10-24T15:34:44.070248', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1012, 233, '01:18:05', 'Errori storici o fattuali', 'Sullo schermo del computer mostrato in dettaglio ravvicinato, l''interfaccia di rete visualizza un indirizzo IP con segmenti numerici superiori a 255, rendendo la stringa di configurazione tecnicamente impossibile.', TRUE, '2026-10-24T15:34:44.070248', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1013, 233, '01:31:40', 'Anacronismi', 'Nella sequenza flashback ambientata nel passato, sullo sfondo della strada cittadina transita per un istante un modello di automobile commerciale entrato in produzione solo svariati anni dopo.', TRUE, '2026-10-24T15:34:44.070248', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(93, 37, '01:52:15', 'Troupe o microfoni visibili', 'Nella scena in cui Alex è immerso nella vasca da bagno a casa dello scrittore e canta ''Singin'' in the Rain'', nello specchio retrostante si intravede per un istante il riflesso dell''asta del microfono boom seguire i suoi movimenti.', TRUE, '2026-09-13T15:23:45.48664', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1014, 234, '00:14:45', 'Errori di scena / Posizione', 'Nel primo incontro tra Eloise e la signora Collins nella sua stanza in affitto, la tazza di tè sul tavolino cambia orientamento tra le inquadrature: prima il manico è rivolto chiaramente verso destra rispetto allo spettatore, poi, nel controcampo ravvicinato, è girato esattamente verso sinistra senza che nessuno l''abbia toccato.', TRUE, '2026-10-24T15:35:51.422226', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1015, 234, '00:36:20', 'Troupe o microfoni visibili', 'Nei camerini del locale quando Sandie si siede davanti alla specchiera a tre ante, muovendosi verso destra: per una frazione di secondo, nell''angolo in alto a sinistra dello specchio laterale, è chiaramente visibile la parte terminale dell''asta di un microfono boom della troupe che viene ritirata in fretta verso l''alto.', TRUE, '2026-10-24T15:35:51.422226', NULL, 0, 0, 'IA (Sistema)', 'ia')
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza") VALUES
(1016, 234, '00:46:10', 'Anacronismi', 'Durante una delle passeggiate di Sandie e Jack a Soho, tra le auto parcheggiate lungo la strada si nota una vettura con targa britannica che reca il suffisso alfabetico finale ''E''. Questo sistema di datazione per la lettera ''E'' entrò in vigore solo all''inizio del 1967, mentre gli eventi di quella parte della trama si svolgono nel 1965.', TRUE, '2026-10-24T15:35:51.422226', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1017, 234, '01:03:15', 'Errori di scena / Posizione', 'Nella biblioteca universitaria, mentre Eloise consulta con crescente angoscia il lettore di microfilm per trovare notizie storiche di cronaca nera, il fotogramma del quotidiano proiettato sullo schermo salta di posizione tra il piano medio e il primissimo piano: un titolo di colonna che prima era al centro dell''area visiva risulta completamente fuori quadro nel taglio successivo.', TRUE, '2026-10-24T15:35:51.422226', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1018, 234, '01:13:50', 'Errori di scena / Posizione', 'Subito dopo essersi fatta tingere i capelli di biondo, quando Eloise esce dal salone e scende i gradini sul marciapiede, l''acconciatura cambia sensibilmente: nell''inquadratura dall''interno del negozio la frangia è ordinata e perfettamente liscia sulla fronte, mentre nell''inquadratura esterna controluce è visibilmente divisa in due ciocche laterali più mosse e disordinate.', TRUE, '2026-10-24T15:35:51.422226', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1019, 234, '01:28:40', 'Errori storici o fattuali', 'Durante il flashback drammatico nella camera con gli avventori del club, Jack posa sul comò alcune banconote di cartamoneta per il pagamento: le banconote mostrate appartengono alla serie ''D'' della Bank of England, emessa a partire dal 1970 con l''introduzione della decimalizzazione, del tutto anacronistica rispetto al sistema monetario britannico pre-decimale (fatto di sterline, scellini e pence) dell''epoca.', TRUE, '2026-10-24T15:35:51.422226', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(94, 37, '02:08:40', 'Errori di scena / Posizione', 'Nel finale in ospedale, quando il Ministro nutre Alex con l''imboccatura di cibo, la quantità presente sul cucchiaio e la posizione del vassoio rispetto alle lenzuola cambiano ad ogni stacco di camera.', TRUE, '2026-09-13T15:23:45.522883', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(165, 44, '00:04:15', 'Troupe o microfoni visibili', 'Durante l''agguato iniziale a Strangways ad opera dei tre finti ciechi, sulla parete dell''edificio a sinistra proiettata nitidamente si scorge l''ombra del braccio di un tecnico della troupe che sostiene la giraffa del microfono.', TRUE, '2026-09-14T13:48:35.31824', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(166, 44, '00:15:22', 'Errori di scena / Posizione', 'Quando Bond entra nell''ufficio del Governatore della Giamaica, appoggia il suo cappello Trilby sul tavolo con la falda rivolta verso l''alto; nelle inquadrature successive dal campo controcampo, il cappello risulta ruotato di 180 gradi e posizionato diversamente.', TRUE, '2026-09-14T13:48:35.398186', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(167, 44, '00:24:10', 'Errori storici o fattuali', 'Bond corregge il cameriere sul Dom Pérignon del 1953 affermando che sarebbe un errore berlo a una temperatura superiore a 4 gradi Celsius, tuttavia servirlo a quella temperatura anestetizzerebbe le papille gustative rovinando lo Champagne.', TRUE, '2026-09-14T13:48:35.503417', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(168, 44, '00:33:05', 'Errori di scena / Posizione', 'Nel corso dell''inseguimento automobilistico con la limousine del finto autista, i vetri della vettura di Bond variano continuamente da completamente trasparenti e puliti a visibilmente impolverati e scuri a seconda se la ripresa sia dal vivo o con schermo di retroproiezione.', TRUE, '2026-09-14T13:48:35.611151', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(169, 44, '00:41:18', 'Troupe o microfoni visibili', 'Nella tensione della stanza d''albergo in cui la tarantola striscia sul corpo di Bond, nel momento in cui 007 la colpisce con la scarpa vicino al letto si vede chiaramente il cavo della telecamera d''angolo riflesse sulla superficie lucida del comodino.', TRUE, '2026-09-14T13:48:35.70451', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(170, 44, '00:52:40', 'Errori di scena / Posizione', 'Durante l''interrogatorio e la successiva eliminazione del Professor Dent, l''arma impugnata da James Bond passa alternativamente da una Walther PPK con silenziatore a una Browning 1910 a seconda dei cambi di angolazione dell''inquadratura.', TRUE, '2026-09-14T13:48:35.796741', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(171, 44, '01:05:12', 'Anacronismi', 'Mentre Bond ed Felix Leiter consultano le mappe e le rotte verso Crab Key, si nota sullo sfondo un calendario con la tabella dei giorni settimanali che presenta incoerenze rispetto al reale calendario del 1962.', TRUE, '2026-09-14T13:48:35.839461', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(172, 44, '01:14:30', 'Errori di scena / Posizione', 'Quando Honey Ryder emerge dall''oceano cantando con le conchiglie in mano, l''allineamento della cinghia del suo coltello e il posizionamento delle conchiglie nella sacca cambiano drasticamente fra il primo piano e la panoramica.', TRUE, '2026-09-14T13:48:35.926872', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(173, 44, '01:22:15', 'Errori storici o fattuali', 'Il ''carro armato drago'' utilizzato dagli uomini del Dr. No viene descritto come un veicolo cingolato corazzato, ma al momento dello scontro si notano chiaramente le ruote in gomma di un telaio modificato da jeep da cui spuntano i finti cingoli staccati dal terreno.', TRUE, '2026-09-14T13:48:36.03921', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(174, 44, '01:35:40', 'Errori di scena / Posizione', 'Nella scena della decontaminazione radioattiva, Honey e Bond vengono lavati abbondantemente sotto docce ad alta pressione; nell''inquadratura immediatamente successiva dentro gli alloggi i capelli di Honey sono perfettamente asciutti e acconciati.', TRUE, '2026-09-14T13:48:36.11158', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(176, 45, '00:03:10', 'Errori di scena / Posizione', 'Nella celebre sequenza di apertura prima dei titoli di testa, il gabbiano finto posizionato sopra la testa della tuta da sub di 007 cambia inclinato verso sinistra quando si trova nell''acqua, per poi apparire dritto appena approda sulla banchina.', TRUE, '2026-09-14T13:48:36.418433', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(177, 45, '00:12:45', 'Anacronismi', 'Mentre Goldfinger gioca a carte a piscina barando via auricolare, l''orologio da polso indossato dal magnate mostra le 11:15 in un primo piano, ma segna le 12:20 nel fotogramma successivo ambientato pochi secondi dopo.', TRUE, '2026-09-14T13:48:36.51498', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(178, 45, '00:22:30', 'Troupe o microfoni visibili', 'Nella tragica e famosa scena in cui Jill Masterson viene trovata morta e ricoperta di vernice dorata sul letto, nello specchio sopra la testiera del letto si riflette nitidamente l''ombra della cinepresa in movimento.', TRUE, '2026-09-14T13:48:36.622951', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1020, 231, '00:14:35', 'Errori di scena / Posizione', 'Quando Finn parla con la sorella mentre gioca ai videogiochi, la posizione del controller nelle sue mani cambia drasticamente tra un campo e un controcampo: prima lo tiene con entrambe le mani sollevate, poi improvvisamente è appoggiato sulle gambe.', TRUE, '2026-10-24T15:36:29.469711', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(179, 45, '00:35:50', 'Anacronismi', 'L''Aston Martin DB5 fornita da Q possiede uno schermo radar con tracciamento digitale a mappe sovrapposte all''interno dell''abitacolo, una tecnologia di tracciamento GPS miniaturizzata che non esisteva assolutamente nel 1964.', TRUE, '2026-09-14T13:48:36.722352', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(48, 14, '01:12:05', 'Crew & Equipment', 'Mentre Michele cammina lungo la spiaggia riflettendo, nell''angolo in alto a destra della ripresa è chiaramente visibile l''ombra del microfono a giraffa.', TRUE, '2026-09-13T14:58:31.416427', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(180, 45, '00:48:12', 'Errori di scena / Posizione', 'Durante l''inseguimento sulle strade di montagna svizzere, la ruota tagliente dell''Aston Martin squarcia la fiancata e le gomme della Ford Mustang di Tilly Masterson, ma nelle inquadrature successive il danno varia di forma e la carrozzeria appare meno danneggiata.', TRUE, '2026-09-14T13:48:36.761098', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(181, 45, '00:59:04', 'Errori di scena / Posizione', 'Quando il sicario Oddjob mostra la sua letalità lanciando il cappello a cilindro con le falde d''acciaio contro la statua di marmo, la testa della statua si stacca un istante prima che il cappello l''abbia effettivamente colpita.', TRUE, '2026-09-14T13:48:36.830956', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(182, 45, '01:12:20', 'Troupe o microfoni visibili', 'Durante il riassunto del piano Grand Slam ai gangster riuniti attorno al plastico meccanico, nella parte superiore dell''inquadratura spunta chiaramente un microfono a giraffa per la registrazione dell''audio.', TRUE, '2026-09-14T13:48:36.928893', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(183, 45, '01:24:55', 'Errori storici o fattuali', 'Goldfinger spiega che la bomba sporca utilizzerà Cobalto 60 per rendere l''oro di Fort Knox radioattivo per 57 anni. Dal punto di vista della fisica nucleare, l''isotopo Cobalto-60 ha un''emivita di circa 5,27 anni, il che rende il calcolo scientificamente errato.', TRUE, '2026-09-14T13:48:36.96564', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(184, 45, '01:36:10', 'Errori di scena / Posizione', 'All''interno del caveau di Fort Knox, il timer della bomba atomica mostra i numeri scorrere a una velocità non costante: alcuni secondi durano molto più a lungo di un secondo reale per far coincidere la battuta finale dell''agente 007.', TRUE, '2026-09-14T13:48:37.037919', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(185, 45, '01:43:00', 'Errori di scena / Posizione', 'Quando il gas nervino viene sganciato su Fort Knox e le guardie svengono, diverse comparse sdraiate a terra muovono chiaramente gli occhi e la testa per osservare l''aereo che sorvola la zona prima di riposizionarsi.', TRUE, '2026-09-14T13:48:37.137378', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(186, 45, '01:50:15', 'Troupe o microfoni visibili', 'Nella sequenza finale a bordo del jet dove si rompe il finestrino e Goldfinger viene risucchiato fuori, nei fotogrammi in cui il corpo attraversa l''oblò si intravedono i cavi di sicurezza d''acciaio che tirano lo stuntman verso l''esterno.', TRUE, '2026-09-14T13:48:37.234357', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(187, 46, '00:00:35', 'Errori di scena / Posizione', 'Durante la drammatica scena iniziale dell''esplosione dell''auto di Ace Rothstein, la vettura usata per lo stunt presenta una carrozzeria nettamente differente dal modello guidato da Robert De Niro pochi secondi prima, ed è chiaramente visibile un manichino al posto dell''attore.', TRUE, '2026-09-14T13:49:13.568485', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(188, 46, '00:15:20', 'Errori di scena / Posizione', 'Nel primo incontro tra Ace e Ginger al tavolo da gioco, la disposizione e il colore delle fiches cambiano visibilmente tra il campo e il controcampo senza che nessuno le abbia toccate.', TRUE, '2026-09-14T13:49:13.646551', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(189, 46, '00:28:45', 'Troupe o microfoni visibili', 'Durante un dialogo all''esterno sotto il sole di Las Vegas tra Ace e Nikki, sugli occhiali da sole a specchio di De Niro si riflettono chiaramente il cameraman e un pannello riflettente della troupe.', TRUE, '2026-09-14T13:49:13.694516', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(190, 46, '00:42:10', 'Anacronismi', 'Nella sequenza ambientata nei primi anni ''70, sullo sfondo del parcheggio del casinò si nota un modello di autovettura equipaggiato con una terza luce di arresto posteriore, caratteristica obbligatoria negli USA solo a partire dal 1986.', TRUE, '2026-09-14T13:49:13.81385', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(191, 46, '00:55:00', 'Errori di scena / Posizione', 'Quando il baro viene punito nel retrobottega spezzandogli la mano con un martello, la posizione del braccio dell''uomo sul tavolo cambia tra le inquadrature ravvicinate e quelle ad angolo largo.', TRUE, '2026-09-14T13:49:13.905088', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(192, 46, '01:08:15', 'Errori storici o fattuali', 'Vengono descritte dettagliatamente le procedure di controllo delle licenze di gioco da parte della Gaming Control Board del Nevada, ma le tempistiche e la burocrazia mostrate differiscono sensibilmente dalla reale legislazione dell''epoca.', TRUE, '2026-09-14T13:49:14.008969', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(194, 46, '01:39:12', 'Troupe o microfoni visibili', 'Nella parte superiore dello schermo, durante la riunione segreta tra i boss mafiosi nel retrobottega, è visibile per un paio di secondi il microfono a giraffa (boom mic) che cala dall''alto.', TRUE, '2026-09-14T13:49:14.145845', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(195, 46, '01:52:30', 'Errori di scena / Posizione', 'Durante il litigio domestico tra Sam e Ginger, l''acconciatura della donna appare prima scompigliata, poi perfettamente ordinata e infine di nuovo spettinata nel giro di pochissimi secondi.', TRUE, '2026-09-14T13:49:14.209226', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(196, 46, '02:05:15', 'Anacronismi', 'Durante una ripresa panoramica della Strip di Las Vegas che dovrebbe svolgersi a metà anni ''70, sullo sfondo si nota l''insegna di un hotel con un logo moderno adottato dalla catena soltanto a metà degli anni ''90.', TRUE, '2026-09-14T13:49:14.312099', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(198, 46, '02:38:20', 'Errori di scena / Posizione', 'Durante il drammatico incontro nel deserto tra Nikki e i suoi scagnozzi, l''altezza delle ombre proiettate sui personaggi varia drasticamente tra un piano d''ascolto e l''altro, rivelando che le riprese si sono svolte in diverse ore della giornata.', TRUE, '2026-09-14T13:49:14.450997', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(199, 47, '00:08:15', 'Errori di scena / Posizione', 'Durante lo spettacolare inseguimento a piedi nel cantiere in Madagascar, la quantità di fango e macchie di polvere sulla camicia e sui pantaloni di Bond aumenta e diminuisce in modo incoerente da un''inquadratura all''altra.', TRUE, '2026-09-14T13:49:14.614325', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(200, 47, '00:22:40', 'Troupe o microfoni visibili', 'Nella sequenza dell''inseguimento all''aeroporto di Miami, nel riflesso dei vetri delle porte scorrevoli del terminal è chiaramente visibile il carrello della macchina da presa insieme al cameraman.', TRUE, '2026-09-14T13:49:14.710388', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(13, 2, '02:24:10', 'Continuity', 'Durante il duello finale tra Massimo e Commodo nel Colosseo, la posizione delle ferite da taglio e la quantità di sangue sulle spalle e sulla corazza di Massimo cambiano visibilmente tra le varie inquadrature.', TRUE, '2026-09-13T14:42:52.620774', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1021, 231, '00:28:10', 'Troupe o microfoni visibili', 'Durante la scena in cui i tre ladri osservano la casa dall''interno del furgone, nel riflesso del vetro del finestrino laterale è chiaramente visibile la sagoma di un operatore della troupe con la videocamera.', TRUE, '2026-10-24T15:36:29.469711', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(201, 47, '00:37:10', 'Errori storici o fattuali', 'Il treno ad alta velocità su cui viaggiano Bond e Vesper mostra la livrea e il logo delle ferrovie nazionali ceche (ČD), poiché la scena è stata girata nella Repubblica Ceca; tuttavia in Montenegro non esiste alcuna linea ferroviaria ad alta velocità di quel tipo.', TRUE, '2026-09-14T13:49:14.742954', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(202, 47, '00:51:25', 'Errori di scena / Posizione', 'Al tavolo da poker del Casino Royale, la disposizione e la quantità di fiches impilate davanti a Le Chiffre cambiano nettamente tra i primi piani del personaggio e le inquadrature a figura intera.', TRUE, '2026-09-14T13:49:14.834055', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(203, 47, '01:05:00', 'Errori storici o fattuali', 'Durante la mano finale di Texas Hold''em, la gestione dell''ordine delle puntate e la risposta del croupier al momento dell''all-in violano diverse regole ufficiali dei tornei internazionali di poker professionistico.', TRUE, '2026-09-14T13:49:14.924411', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(204, 47, '01:18:30', 'Errori di scena / Posizione', 'Quando Bond viene avvelenato e corre verso la sua Aston Martin per somministrarsi l''antidoto, le macchie di sudore sul suo vestito appaiono vistosamente estese, poi quasi del tutto scomparse quando entra nell''abitacolo.', TRUE, '2026-09-14T13:49:15.019238', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(205, 47, '01:32:15', 'Anacronismi', 'Lo smartphone utilizzato da James Bond mostra un software con funzionalità di tracciamento satellitare e grafica ad alta risoluzione non ancora disponibili sul mercato all''epoca dell''uscita del film nel 2006.', TRUE, '2026-09-14T13:49:15.121363', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(206, 47, '01:45:50', 'Troupe o microfoni visibili', 'Nel momento in cui l''Aston Martin DBS si ribalta a gran velocità, si può chiaramente scorgere sotto la scocca dell''auto il cannone pneumatico a pistone adibito a far cappottare il veicolo per lo stunt.', TRUE, '2026-09-14T13:49:15.157981', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(207, 47, '01:58:10', 'Errori di scena / Posizione', 'Durante la convulsa sequenza nel palazzo affondante a Venezia, il nodo della cravatta di Bond cambia forma e grado di allentamento mentre tenta di salvare Vesper intrappolata nell''ascensore.', TRUE, '2026-09-14T13:49:15.228363', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(208, 47, '02:10:45', 'Errori di scena / Posizione', 'I tagli e le macchie di sangue sul viso di James Bond nella scena finale sulla spiaggia variano di posizione, forma ed intensità tra una ripresa ravvicinata e l''altra.', TRUE, '2026-09-14T13:49:15.263887', NULL, 0, 0, 'IA (Sistema)', 'ia')
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza") VALUES
(209, 47, '02:22:30', 'Errori storici o fattuali', 'La velocità di affondamento dell''intero palazzo veneziano dovuta alla rottura dei palloni di galleggiamento è idrodinamicamente e strutturalmente impossibile per un edificio storico in pietra e muratura.', TRUE, '2026-09-14T13:49:15.334908', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(210, 48, '00:18:22', 'Errori di scena / Posizione', 'Durante la camminata iniziale di Futaki nel fango, le macchie di fango sui suoi pantaloni e sugli stivali cambiano visibilmente disposizione e densità tra il campo lungo e il campo medio successivo.', TRUE, '2026-09-14T13:49:44.414725', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(211, 48, '00:45:10', 'Troupe o microfoni visibili', 'Durante la lunga carrellata che segue il dottore all''esterno, nell''angolo superiore destro dell''inquadratura è brevemente visibile l''estremità dell''asta del microfono d''ambiente mentre si abbassa per pochi secondi.', TRUE, '2026-09-14T13:49:44.510998', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(212, 48, '01:12:05', 'Errori di scena / Posizione', 'Nella scena in cui il dottore prende appunti al tavolo, il livello del liquido nella bottiglia di pálinka sale di un paio di centimetri tra due inquadrature contigue, senza che nessuno ne abbia versata altra.', TRUE, '2026-09-14T13:49:44.610825', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(213, 48, '01:58:40', 'Anacronismi', 'Sullo sfondo della desolata campagna durante il cammino della piccola Estike, si intravede un traliccio dell''alta tensione moderno con cavi e componenti non compatibili con il periodo di ambientazione rurale della fine dell''era comunista.', TRUE, '2026-09-14T13:49:44.645639', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(214, 48, '02:30:15', 'Errori di scena / Posizione', 'Durante la tragica sequenza della bambina con il gatto, la posizione delle zampe del felino rispetto alla ciotola sul pavimento varia in modo incoerente nel passaggio tra l''inquadratura dall''alto e quella ad altezza occhi.', TRUE, '2026-09-14T13:49:44.721355', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(215, 48, '03:15:00', 'Troupe o microfoni visibili', 'Durante la scorta del camion sotto la pioggia battente, sulla superficie bagnata del finestrino laterale si riflettono nitidamente la sagoma della macchina da presa su carrello e le luci di schiarita della troupe.', TRUE, '2026-09-14T13:49:44.755576', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(216, 48, '03:52:10', 'Errori di scena / Posizione', 'Nella celebre e prolungata scena del tango nella locanda, il cappello di Schmidt cambia inclinazione sulla sua testa svariate volte durante le virate della danza senza che egli vi metta mai mano.', TRUE, '2026-09-14T13:49:44.82401', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(217, 48, '04:20:30', 'Errori storici o fattuali', 'Su un foglio di registro mostrato dall''ufficiale governativo è visibile un timbro burocratico della Repubblica d''Ungheria introdotto ufficialmente soltanto dopo il 1992, incoerente con l''epoca di svolgimento del racconto.', TRUE, '2026-09-14T13:49:44.925678', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(218, 48, '04:55:18', 'Errori di scena / Posizione', 'Mentre Irimiás arringa la folla all''aperto, l''intensità della pioggia passa repentinamente da un rovescio battente a una debole pioggerellina nel giro di un singolo stacco di montaggio.', TRUE, '2026-09-14T13:49:45.022081', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(219, 48, '05:30:45', 'Troupe o microfoni visibili', 'In un lungo piano sequenza a seguire sulle spalle di Petrina mentre cammina controvento nel campo, l''ombra del cameraman e della rig di supporto si proietta chiaramente sulla parte inferiore del suo cappotto.', TRUE, '2026-09-14T13:49:45.065195', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(220, 48, '06:10:12', 'Errori di scena / Posizione', 'Quando i contadini preparano i propri bagagli per la partenza, le cinghie in cuoio di una valigia risultano affibbiate nell''inquadratura generale ma completamente slacciate nel dettaglio successivo.', TRUE, '2026-09-14T13:49:45.12985', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(221, 48, '06:45:00', 'Anacronismi', 'Lungo il ciglio della strada sterrata si nota a terra un tappo di plastica a vite per bottiglie PET di tipo moderno, oggetto del tutto irreperibile nelle campagne ungheresi dell''epoca raffigurata.', TRUE, '2026-09-14T13:49:45.225467', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(222, 48, '07:05:30', 'Errori di scena / Posizione', 'Nel finale, quando il dottore inchioda le assi di legno alla finestra per chiudersi nel buio, l''inclinazione della terza asse inserita cambia visibilmente angolo tra il momento dell''impatto del martello e il totale conclusivo.', TRUE, '2026-09-14T13:49:45.326761', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(223, 49, '00:08:15', 'Errori di scena / Posizione', 'Durante la scena in cui Steve Rogers si allena con il sacco da boxe, la catena che sostiene il sacco si rompe e questo cade a terra. Nella ripresa successiva da un''altra angolazione, la posizione del sacco e dei pezzi di catena sparsi sul pavimento è visibilmente cambiata.', TRUE, '2026-09-14T13:51:06.335883', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(224, 49, '00:18:40', 'Errori di scena / Posizione', 'Quando Nick Fury parla con il Consiglio di Sicurezza Mondiale tramite ologrammi, la sua mano sinistra è inizialmente appoggiata al tavolo, ma nel cambio di inquadratura si trova istantaneamente lungo il fianco.', TRUE, '2026-09-14T13:51:06.436657', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(225, 49, '00:24:10', 'Errori di scena / Posizione', 'Nel dialogo tra Tony Stark e Loki nell''attico della Stark Tower, Tony versa del drink in un bicchiere e lo tiene in mano. Nell''inquadratura da dietro Loki, il bicchiere è appoggiato sul bancone, per poi ritornare nella mano di Tony nella ripresa frontale.', TRUE, '2026-09-14T13:51:06.528553', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(302, 56, '00:15:22', 'Errori di scena / Posizione', 'Durante il confronto verbale all''ospedale dove Apollo irrompe chiedendo la rivincita, il livello del succo d''arancia e dell''acqua sul comodino accanto al letto di Rocky varia inspiegabilmente tra il campo e il controcampo.', TRUE, '2026-09-14T13:54:32.974807', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(303, 56, '00:28:10', 'Troupe o microfoni visibili', 'Quando Rocky acquista la Pontiac Trans Am nera e parte sgommando davanti al concessionario, nella parte superiore dell''inquadratura è chiaramente visibile per qualche secondo l''ombra del microfono a pertica (boom mic).', TRUE, '2026-09-14T13:54:33.012448', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(67, 28, '00:37:45', 'Fattuale / Storico', 'Vengono citati decreti ed editti storici attribuiti a Caracalla che in realtà vennero promulgati diversi decenni più tardi.', TRUE, '2026-09-13T15:01:46.792075', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(226, 49, '00:35:42', 'Errori di scena / Posizione', 'Durante l''interrogatorio a bordo dell''Helicarrier, il taglio sulla fronte di Bruce Banner cambia dimensione, nitidezza e quantità di sangue raggrumato tra i vari primi piani della sequenza.', TRUE, '2026-09-14T13:51:06.570101', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(227, 49, '00:48:20', 'Troupe o microfoni visibili', 'Durante lo scontro nella foresta tra Thor, Iron Man e Capitan America, nell''angolo inferiore sinistro dello schermo per un breve istante è visibile l''ombra della telecamera e del braccio meccanico dell''operatore.', TRUE, '2026-09-14T13:51:06.643396', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(228, 49, '01:02:15', 'Errori di scena / Posizione', 'Mentre Black Widow parla con Loki chiuso nella cella di vetro, la ciocca di capelli rossi sul lato sinistro del suo viso passa ripetutamente da davanti all''orecchio a completamente dietro ad ogni cambio di campo.', TRUE, '2026-09-14T13:51:06.734151', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(229, 49, '01:18:05', 'Errori di scena / Posizione', 'Dopo l''esplosione causata dalle guardie controllate da Occhio di Falco sull''Helicarrier, la tuta di Capitan America presenta uno strappo vistoso sul lato addominale sinistro. Nelle scene immediatamente successive, lo strappo appare notevolmente ridotto e privo di bruciature.', TRUE, '2026-09-14T13:51:06.771093', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(230, 49, '01:32:40', 'Errori storici o fattuali', 'Durante la battaglia di New York, un idrante viene sradicato e spruzza un getto d''acqua continuo ad altissima pressione. Tuttavia, con la strada completamente spaccata al di sotto, la conduttura idrica sottostante appare visibilmente intatta e priva di collegamenti fisici reali al manicotto.', TRUE, '2026-09-14T13:51:06.845916', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(231, 49, '01:45:12', 'Errori di scena / Posizione', 'Quando Iron Man precipita attraverso il portale e viene afferrato da Hulk, i graffi sulla piastra pettorale dell''armatura e la sporcizia sul viso di Tony Stark cambiano disposizione tra il momento dell''impatto a terra e il momento del risveglio.', TRUE, '2026-09-14T13:51:06.940643', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(232, 49, '01:52:30', 'Anacronismi', 'Nel display heads-up (HUD) dell''armatura di Iron Man compare brevemente un codice di diagnostica di sistema che fa riferimento a una revisione software pubblicata e standardizzata solo anni dopo la produzione del film.', TRUE, '2026-09-14T13:51:06.983417', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(233, 49, '02:05:18', 'Errori di scena / Posizione', 'Nella scena finale al parco dove la squadra saluta Thor e Loki, il contenitore sferico del Tesseract tenuto da Thor e Loki ruota la propria posizione tra le loro mani da un montaggio all''altro senza che nessuno lo manovri.', TRUE, '2026-09-14T13:51:07.052223', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(234, 50, '00:05:40', 'Errori di scena / Posizione', 'Nella sequenza d''apertura nella foresta innevata della Sokovia, lo scudo di Capitan America accumula neve sulla superficie frontale; la neve scompare e riappare improvvisamente tra un secondo di inquadratura e l''altro.', TRUE, '2026-09-14T13:51:07.256638', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(235, 50, '00:18:22', 'Errori di scena / Posizione', 'Durante la festa alla Stark Tower, il livello dell''alcol all''interno del bicchiere da cui beve Thor varia in modo incoerente tra le inquadrature frontali e quelle di profilo, senza che il personaggio abbia versato altro liquido.', TRUE, '2026-09-14T13:51:07.385478', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(236, 50, '00:32:15', 'Troupe o microfoni visibili', 'Nel momento in cui la prima versione grezza di Ultron interrompe il party, sullo sfondo a destra si scorge chiaramente il cavo di sicurezza nero collegato all''imbragatura dello stuntman prima di essere sbalzato a terra.', TRUE, '2026-09-14T13:51:07.460901', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(237, 50, '00:47:50', 'Errori di scena / Posizione', 'Quando Pietro Maximoff afferra un proiettile al rallentatore, l''orientamento delle dita della sua mano varia tra il primo piano della mano e il campo lungo in cui si vede tutto il corpo.', TRUE, '2026-09-14T13:51:07.555946', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(238, 50, '01:05:30', 'Errori storici o fattuali', 'Le coordinate geografiche visualizzate sui monitor del Quinjet per localizzare il cantiere navale di Ulysses Klaue sulla costa sudffricana indicano in realtà un punto collocato all''interno dell''entroterra desertico.', TRUE, '2026-09-14T13:51:07.593787', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(239, 50, '01:21:10', 'Errori di scena / Posizione', 'Nella fattoria di Occhio di Falco, la cerniera della felpa indossata da Clint Barton è completamente aperta mentre parla con la moglie, ma risulta alzata fino al collo nella ripresa successiva senza alcuna interruzione nell''azione.', TRUE, '2026-09-14T13:51:07.667271', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(240, 50, '01:35:45', 'Anacronismi', 'Sullo schermo di analisi genetica nel laboratorio di Seoul appare una sequenza temporale di scansione con la dicitura di un protocollo USB 3.1 con datazione e identificativi incoerenti con lo sviluppo tecnologico dell''anno del film.', TRUE, '2026-09-14T13:51:07.759481', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(241, 50, '01:50:20', 'Errori di scena / Posizione', 'Il rigolo di sangue sull''angolo sinistro della bocca di Wanda Maximoff scompare del tutto quando la ragazza entra all''interno della chiesa della Sokovia per affrontare i robot di Ultron.', TRUE, '2026-09-14T13:51:07.80182', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(242, 50, '02:02:15', 'Errori di scena / Posizione', 'Durante la battaglia finale attorno al nucleo di attivazione della città volante, la posizione delle macchie di polvere sul costume di Vedova Nera cambia continuamente tra un piano sequenza e l''altro.', TRUE, '2026-09-14T13:51:07.871547', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(243, 50, '02:14:00', 'Troupe o microfoni visibili', 'Mentre la massa terrestre sokoviana precipita verso la Terra, in una ripresa dal basso di un veicolo che si stacca dalla carreggiata si nota brevemente la struttura rigida di supporto del pistone pneumatico usato per ribaltare l''auto sul set.', TRUE, '2026-09-14T13:51:07.964362', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1022, 231, '00:45:20', 'Errori di scena / Posizione', 'Nella scena all''esterno durante la neve, la quantità di fiocchi sulle spalle del cappotto di Finn cambia continuamente tra un''inquadratura e l''altra: prima ne è completamente ricoperto, nel campo successivo appare pulito e poi di nuovo imbiancato.', TRUE, '2026-10-24T15:36:29.469711', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(324, 60, '00:11:45', 'Errori storici o fattuali', 'Nelle scene ambientate a Londra compare ripetutamente la bandiera del Regno Unito (Union Jack) nella sua versione moderna, comprensiva della croce di San Patrizio (la diagonale rossa). Tuttavia, la pellicola è ambientata nel 1750 circa durante il regno di Giorgio II, mentre la croce di San Patrizio fu integrata nella bandiera solo con l''Atto di Unione del 1801.', TRUE, '2026-09-14T14:11:51.434478', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(197, 46, '02:21:00', 'Errori storici o fattuali', 'La moneta da un dollaro lanciata sul tavolo da gioco in una scena d''azzardo mostra il conio commemorativo Eisenhower Bicentennial, prodotto solo tra il 1975 e il 1976, mentre la scena è cronologicamente ambientata nel 1971.', TRUE, '2026-09-14T13:49:14.401863', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(244, 51, '00:11:05', 'Errori di scena / Posizione', 'Mentre Tony Stark fa jogging con Pepper Potts a Central Park, la felpa sportiva legata attorno alle sue spalle cambia annodamento e posizione della manica tra le riprese frontali e quelle da dietro.', TRUE, '2026-09-14T13:51:08.176184', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(246, 51, '00:41:12', 'Troupe o microfoni visibili', 'All''interno della navicella dei Guardiani della Galassia, mentre Groot gioca con il videogioco portatile, nella parte superiore dell''inquadratura sbalza leggermente dentro il campo visivo il microfono a spugna panoramico.', TRUE, '2026-09-14T13:51:08.384518', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(247, 51, '00:58:40', 'Errori storici o fattuali', 'Durante le fasi di riattivazione della stella di neutroni a Nidavellir, gli impatti delle macerie e la forgia metallica generano boati udibili ed echeggianti nello spazio aperto, violando la legge fisica dell''assenza di propagazione del suono nel vuoto.', TRUE, '2026-09-14T13:51:08.495736', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(248, 51, '01:12:18', 'Errori di scena / Posizione', 'Durante l''agguato a Edimburgo, la ferita da pugnalata sul petto di Visione proietta una scia di luce dorata che cambia angolazione e intensità a seconda dell''ampiezza dell''inquadratura.', TRUE, '2026-09-14T13:51:08.588232', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(249, 51, '01:30:45', 'Anacronismi', 'Quando Peter Parker cita il classico del cinema ''Aliens'' per sconfiggere Ebony Maw, pronuncia una frase citando la dicitura esatta di un adattamento televisivo americano arrivato nei canali via cavo anni dopo e non la versione cinematografica originale del 1986.', TRUE, '2026-09-14T13:51:08.683086', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(250, 51, '01:48:22', 'Errori di scena / Posizione', 'Durante il combattimento su Titan, i graffi e le incisioni presenti sul Guanto dell''Infinito indossato da Thanos scompaiono completamente nei primi piani dedicati al posizionamento delle singole gemme.', TRUE, '2026-09-14T13:51:08.784005', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(251, 51, '02:01:10', 'Errori di scena / Posizione', 'Mentre Doctor Strange duella con Thanos moltiplicando la sua immagine, il mantello della levitazione reale posizionato sulle sue spalle cambia la chiusura attorno al collo tra un''immagine e l''altra.', TRUE, '2026-09-14T13:51:08.826536', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(252, 51, '02:15:35', 'Errori di scena / Posizione', 'Nella battaglia del Wakanda, le macchie di fango sul viso e sulla barba di Capitan America variano visibilmente forma prima e subito dopo la carica iniziale contro l''esercito degli Outriders.', TRUE, '2026-09-14T13:51:08.898097', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(253, 51, '02:24:50', 'Errori di scena / Posizione', 'Thor colpisce Thanos al petto piantandogli la scure Stormbreaker. Quando Thanos usa la Gemma del Tempo e dello Spazio per ritirarsi, lo squarcio sulla sua armatura e sul petto cambia forma e posizione di qualche centimetro.', TRUE, '2026-09-14T13:51:08.999866', NULL, 0, 0, 'IA (Sistema)', 'ia')
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza") VALUES
(254, 52, '00:02:15', 'Errori di scena / Posizione', 'Durante la scena iniziale in cui Clint Barton insegna a sua figlia a usare l''arco, la quantità di frecce presenti all''interno della faretra cambia continuamente da tre a quattro tra una ripresa e l''altra.', TRUE, '2026-09-14T13:51:53.032537', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(255, 52, '00:19:40', 'Errori di scena / Posizione', 'Quando Thor decapita Thanos nella sua capanna sul pianeta giardino, la posizione del corpo di Thanos sul pavimento cambia bruscamente tra la visuale dall''alto e l''inquadratura frontale ravvicinata.', TRUE, '2026-09-14T13:51:53.154092', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(256, 52, '00:32:10', 'Troupe o microfoni visibili', 'Mentre Scott Lang mangia il suo taco fuori dal quartier generale degli Avengers, nel riflesso dei vetri dell''autovettura scura parcheggiata sullo sfondo è chiaramente visibile l''ombra della parabola di illuminazione del set.', TRUE, '2026-09-14T13:51:53.231196', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(257, 52, '00:45:12', 'Anacronismi', 'Nella sequenza ambientata nel 1970 all''interno della base militare di Camp Lehigh, sul muro di uno dei corridoi sotterranei si nota una moderna videocamera di sorveglianza digitale a circuito chiuso, del tutto inesistente in quell''epoca.', TRUE, '2026-09-14T13:51:53.327941', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(258, 52, '00:58:30', 'Errori storici o fattuali', 'Durante il viaggio nel passato a New York nel 2012, Bruce Banner cita la dinamica della traiettoria di caduta di un oggetto in assenza di gravità usando formule fisiche errate e invertendo i vettori di accelerazione.', TRUE, '2026-09-14T13:51:53.440314', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(259, 52, '01:12:05', 'Errori di scena / Posizione', 'Nella scena in cui Tony Stark parla con suo padre Howard Stark nel 1970, la lunghezza e la piega della cravatta di Tony cambiano visibilmente ad ogni cambio di inquadratura.', TRUE, '2026-09-14T13:51:53.533437', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(260, 52, '01:28:45', 'Errori di scena / Posizione', 'Sul pianeta Vormir, durante il combattimento tra Vedova Nera e Occhio di Falco per decidere chi debba sacrificarsi, i tagli e le macchie di sporco sul viso di Natasha cambiano forma e posizione.', TRUE, '2026-09-14T13:51:53.575178', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(261, 52, '01:41:20', 'Errori di scena / Posizione', 'Mentre i vendicatori indossano le tute bianche quantiche per prepararsi al viaggio nel tempo, i guanti di Ant-Man appaiono sfilati nella visuale panoramica ma sono regolarmente indossati nel primo piano successivo.', TRUE, '2026-09-14T13:51:53.646835', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(344, 62, '00:48:30', 'Errori storici o fattuali', 'Nel film, Jordan Belfort afferma che la rivista Forbes lo ha soprannominato ''Il lupo di Wall Street'' nell''articolo a lui dedicato. In realtà, il famoso articolo di Forbes del 1991 era intitolato ''Stealing from the Rich'' e lo descriveva come una sorta di Robin Hood al contrario; il soprannome ''Lupo'' è stato coniato dallo stesso Belfort solo anni dopo per la sua autobiografia.', TRUE, '2026-09-15T17:15:16.830593', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(345, 62, '01:14:15', 'Errori di scena / Posizione', 'Durante la festa nella villa negli Hamptons dove Jordan parla per la prima volta con Naomi, il livello del drink nel bicchiere di Jordan varia continuamente tra i vari stacchi di inquadratura, passando da quasi pieno a metà senza che lui ne beva un sorso.', TRUE, '2026-09-15T17:15:16.907955', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(175, 44, '01:44:00', 'Troupe o microfoni visibili', 'Durante il drammatico scontro finale al reattore nucleare, nell''angolo in alto a destra dello schermo entra brevemente in campo la parte superiore di un pannello di illuminazione da set.', TRUE, '2026-09-14T13:48:36.216421', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(347, 62, '02:07:45', 'Errori di scena / Posizione', 'Nella sequenza dell''effetto ritardato dei Quaalude Lemmon 714, mentre Jordan striscia sui gradini del club per raggiungere la sua Lamborghini, la cravatta cambia posizione tra un''inquadratura e l''altra: prima è completamente ribaltata dietro la spalla, poi pende sul davanti e infine torna sul lato.', TRUE, '2026-09-15T17:15:17.13477', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(348, 62, '02:22:15', 'Anacronismi', 'Durante la presentazione delle calzature di Steve Madden negli uffici della Stratton Oakmont (scena ambientata nel 1993), sullo sfondo compaiono modelli di scarpe con zeppa in gomma nera (come le celebri ciabatte ''Slinky'') che Steve Madden avrebbe disegnato e commercializzato solo a partire dal 1995/1996.', TRUE, '2026-09-15T17:15:17.206365', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(350, 62, '02:44:05', 'Errori storici o fattuali', 'Nella sequenza dell''affondamento dello yacht ''Naomi'' al largo della Sardegna, l''imbarcazione viene mostrata mentre si allaga rapidamente a causa di un guasto meccanico e del mare tempestoso. Nella realtà, il naufragio del 1996 fu causato dalla decisione diretta di Belfort di forzare il capitano a salpare con mare forza 8, provocando la rottura del portellone di poppa a causa delle onde giganti che travolsero l''imbarcazione.', TRUE, '2026-09-15T17:15:17.440341', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(262, 52, '02:04:15', 'Errori di scena / Posizione', 'Clamoroso errore di continuità nella battaglia finale: Ant-Man (in forma gigante) si vede sullo sfondo mentre sferra un pugno a un leviatano alieno, ma nello stesso istante è mostrato in versione normale dentro il furgone con Wasp per riattivare il tunnel quantico.', TRUE, '2026-09-14T13:51:53.736757', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(263, 52, '02:12:40', 'Errori di scena / Posizione', 'Dopo che Thanos spezza a metà lo scudo in vibranio di Captain America, in un''inquadratura successiva a largo campo durante la radunata degli eroi lo scudo appare per pochi frame miracolosamente integro sul braccio di Steve Rogers.', TRUE, '2026-09-14T13:51:53.776962', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(264, 52, '02:20:55', 'Errori di scena / Posizione', 'Nel momento in cui Tony Stark ruba le Gemme dell''Infinito a Thanos e le trasferisce sulla sua armatura, la Gemma della Mente e la Gemma dello Spazio si scambiano di posizione sulla mano prima dello schiocco finale.', TRUE, '2026-09-14T13:51:53.850679', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(265, 52, '02:32:10', 'Errori di scena / Posizione', 'Durante il funerale di Tony Stark, la posizione dei personaggi posizionati lungo il pontile del lago (in particolare Spider-Man e Captain Marvel) varia notevolmente tra la ripresa con il drone e i primi piani.', TRUE, '2026-09-14T13:51:53.948501', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(266, 53, '00:06:12', 'Troupe o microfoni visibili', 'Durante il combattimento iniziale all''interno del cimitero, nella parte superiore dello schermo è visibile per diversi secondi il microfono a spugna (boom mic) della troupe che segue i movimenti dei personaggi.', TRUE, '2026-09-14T13:51:54.088269', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(268, 53, '00:27:05', 'Anacronismi', 'Nelle riprese di un ricordo storico ambientato nel XVIII secolo nelle campagne scozzesi, sullo sfondo in alto a destra si nota chiaramente la scia di condensazione lasciata dal passaggio di un aereo di linea moderno.', TRUE, '2026-09-14T13:51:54.257261', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(269, 53, '00:39:20', 'Errori di scena / Posizione', 'Durante l''incontro al santuario, il livello di consumo delle candele poste sul tavolo centrale passa dall''essere quasi del tutto esaurito ad essere quasi nuovo nell''arco di un singolo cambio di campo.', TRUE, '2026-09-14T13:51:54.35121', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(270, 53, '00:51:15', 'Troupe o microfoni visibili', 'Quando Duncan viene scagliato con forza contro il muro di mattoni durante il duello nel vicolo notturno, si intravede chiaramente il bordo del materasso di protezione posizionato a terra per ammortizzare la caduta dello stuntman.', TRUE, '2026-09-14T13:51:54.390658', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(271, 53, '01:03:40', 'Errori storici o fattuali', 'La spada cerimoniale utilizzata dai guerrieri nella scena del flashback medievale presenta rifiniture meccaniche moderne e viti con testa a brugola, elementi metallurgici del tutto inesistenti all''epoca.', TRUE, '2026-09-14T13:51:54.460216', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(349, 62, '02:35:50', 'Errori di scena / Posizione', 'Durante la scena dell''arresto di Jordan sul set della sua televendita, il microfono ad archetto che indossa varia posizione, inclinazione e distanza dalle labbra ad ogni stacco di montaggio prima ancora che gli agenti dell''FBI si avvicinino per ammanettarlo.', TRUE, '2026-09-15T17:15:17.306914', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(272, 53, '01:14:50', 'Errori di scena / Posizione', 'Nel corso dello scontro decisivo, le ferite da taglio e i rivoli di sangue sul volto di Duncan MacLeod cambiano forma, densità e posizione a seconda che l''inquadratura sia frontale o di profilo.', TRUE, '2026-09-14T13:51:54.493929', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(273, 53, '01:21:10', 'Errori di scena / Posizione', 'Durante una violenta parata di spade, la lama in acciaio dell''antagonista si piega visibilmente rivelando di essere una protesi scenica di gomma morbida, per poi tornare perfettamente rigida nel primo piano successivo.', TRUE, '2026-09-14T13:51:54.56605', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(274, 53, '01:29:35', 'Troupe o microfoni visibili', 'Nel riflesso degli occhiali da sole indossati da uno dei seguaci di Kell è visibile la sagoma dell''operatore di ripresa assieme al pannello riflettente usato per l''illuminazione della scena.', TRUE, '2026-09-14T13:51:54.659213', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(275, 53, '01:34:20', 'Errori di scena / Posizione', 'Nell''ultima sequenza girata sul tetto dell''edificio, l''orientamento delle ombre proiettate dai protagonisti indica momenti della giornata completamente differenti (mattina e tardo pomeriggio) tra il campo lungo e il primo piano.', TRUE, '2026-09-14T13:51:54.698553', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(276, 54, '00:04:12', 'Errori di scena / Posizione', 'Durante il combattimento iniziale nella chiesa sconsacrata contro Spider Rico, la ferita sopra l''occhio sinistro di Spider varia visibilmente di forma e flusso di sangue tra i primi piani e le inquadrature a figura intera.', TRUE, '2026-09-14T13:53:57.14188', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(277, 54, '00:15:40', 'Troupe o microfoni visibili', 'Nella scena in cui Rocky cammina di notte lungo le strade buie di Philadelphia parlando con se stesso, nella parte superiore dello schermo appare chiaramente per diversi secondi la spugna del microfono panoramico.', TRUE, '2026-09-14T13:53:57.248344', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(278, 54, '00:23:15', 'Errori di scena / Posizione', 'Nel negozio di animali in cui lavora Adriana, la gabbietta dei pappagalli e le confezioni di cibo sullo sfondo cambiano disposizione improvvisamente al passaggio tra la ripresa frontale e il controcampo.', TRUE, '2026-09-14T13:53:57.342252', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(279, 54, '00:35:08', 'Anacronismi', 'Durante la prima sessione di allenamento all''alba, in un''inquadratura esterna sullo sfondo si nota un modello di automobile parcheggiata lungo la via che è stato immesso sul mercato solo alla fine del 1976, mentre la storia è ambientata a fine 1975.', TRUE, '2026-09-14T13:53:57.447688', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(280, 54, '00:44:22', 'Errori di scena / Posizione', 'A casa di Paulie, la bottiglia di whisky posizionata sul tavolo della cucina passa dall''essere quasi vuota ad essere piena per un terzo nel giro di due stacchi di montaggio consecutivi.', TRUE, '2026-09-14T13:53:57.560564', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(281, 54, '00:52:10', 'Troupe o microfoni visibili', 'Quando Mickey si reca nel piccolo appartamento di Rocky per proporsi come suo manager, nel vetro della finestra della porta d''ingresso si riflette distintamente l''ombra dell''operatore con la macchina da presa.', TRUE, '2026-09-14T13:53:57.651067', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(282, 54, '01:03:45', 'Errori storici o fattuali', 'Durante la conferenza stampa di presentazione del match, viene mostrato un banner pubblicitario recante un logo aziendale che la società promotrice ha ufficialmente registrato e adottato solo alcuni anni dopo.', TRUE, '2026-09-14T13:53:57.757431', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(283, 54, '01:12:30', 'Errori di scena / Posizione', 'Durante la celebre corsa di Rocky verso il Philadelphia Museum of Art, l''asciugamano grigio che porta arrotolato intorno al collo scompare e riappare tra una ripresa e l''altra.', TRUE, '2026-09-14T13:53:57.857336', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(284, 54, '01:21:05', 'Anacronismi', 'Nella sequenza dell''allenamento al macello in cui Rocky colpisce i quarti di bue, sullo sfondo compare un cartello segnaletico aziendale con un formato di codice zip introdotto negli Stati Uniti solo negli anni ''80.', TRUE, '2026-09-14T13:53:57.94755', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(285, 54, '01:34:50', 'Errori di scena / Posizione', 'Sul ring prima della prima ripresa, la striscia decorativa del mantello da zito di Apollo Creed risulta sbottonata sulla spalla destra nei campi lunghi, ma perfettamente allacciata nei primi piani.', TRUE, '2026-09-14T13:53:58.051742', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(286, 54, '01:42:18', 'Errori storici o fattuali', 'La grafica televisiva e i cartellini mostrati dai giudici di gara indicano l''assegnazione dei punteggi con un sistema d''assegnazione dei punti che non corrisponde al regolamento effettivo della WBA vigente nel 1975.', TRUE, '2026-09-14T13:53:58.086223', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(287, 54, '01:50:40', 'Troupe o microfoni visibili', 'Durante l''intervallo tra il quattordicesimo e il quindicesimo round, all''angolo di Rocky si intravede brevemente nell''angolo inferiore sinistro la mano di un tecnico di scena che spruzza finta acqua di sudore sul petto di Stallone.', TRUE, '2026-09-14T13:53:58.163329', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(288, 54, '01:57:12', 'Errori di scena / Posizione', 'Nel caotico finale sul ring, quando Adriana si fa strada tra la folla e abbraccia Rocky, il berretto rosso che indossa scompare improvvisamente tra un fotogramma e l''altro senza che lei si sia mossa per toglierlo.', TRUE, '2026-09-14T13:53:58.25892', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(289, 55, '00:08:15', 'Errori di scena / Posizione', 'Alla festa di compleanno di Paulie, il bicchiere di champagne tenuto in mano da Rocky si svuota e si riempie nuovamente senza che nessuno versi altro liquido tra una ripresa e l''altra.', TRUE, '2026-09-14T13:53:58.465384', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(290, 55, '00:18:40', 'Errori storici o fattuali', 'Durante lo show d''ingresso di Apollo Creed a Las Vegas, la bandiera dell''Unione Sovietica mostrata sullo sfondo presenta il simbolo della falce e martello posizionato in modo speculare e storicamente errato rispetto alla bandiera ufficiale dell''URSS.', TRUE, '2026-09-14T13:53:58.574363', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(291, 55, '00:26:05', 'Errori di scena / Posizione', 'Quando Apollo crolla a terra esanime dopo i devastanti colpi di Drago, la posizione delle sue braccia cambia notevolmente tra la vista dall''alto e la ripresa al livello del pavimento del ring.', TRUE, '2026-09-14T13:53:58.676303', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(292, 55, '00:34:20', 'Troupe o microfoni visibili', 'Durante la tesa conferenza stampa tra Rocky e l''entourage di Drago a New York, un microfono a spugna è chiaramente visibile nella parte superiore centrale dell''inquadratura per circa tre secondi.', TRUE, '2026-09-14T13:53:58.771054', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(293, 55, '00:45:10', 'Anacronismi', 'All''arrivo dell''aeroplano di Rocky in Unione Sovietica, sullo sfondo della pista di atterraggio è visibile un mezzo di servizio aeroportuale che sfoggia una livrea commerciale introdotta solo nei primi anni ''90.', TRUE, '2026-09-14T13:53:58.874933', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(294, 55, '00:54:30', 'Errori di scena / Posizione', 'Nella sequenza dell''isolato capanno nella neve, la quantità di legna tagliata e cataste svariate nel cortile cambia visibilmente prima ancora che Rocky inizi la sua sessione di spacco dei tronchi.', TRUE, '2026-09-14T13:53:58.913655', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(295, 55, '01:02:15', 'Anacronismi', 'Durante il montaggio degli allenamenti high-tech di Ivan Drago, gli schermi dei computer mostrano grafiche vettoriali ad alta risoluzione e parametri biomedici avanzati non disponibili sulla tecnologia informatica sovietica del 1985.', TRUE, '2026-09-14T13:53:59.014323', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(296, 55, '01:11:00', 'Troupe o microfoni visibili', 'Quando Rocky corre sulla neve inseguito dall''auto degli agenti del KGB, sul cofano lucido dell''automobile scura si riflette nitidamente la struttura di metallo dell''auto-camera (camera car) che precede la scena.', TRUE, '2026-09-14T13:53:59.082726', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(297, 55, '01:18:45', 'Errori storici o fattuali', 'Prima dell''inizio dell''incontro a Mosca, la melodia eseguita per l''inno nazionale sovietico contiene un errore nell''arrangiamento orchestrale ufficiale dell''era di Mikhail Gorbaciov.', TRUE, '2026-09-14T13:53:59.190297', NULL, 0, 0, 'IA (Sistema)', 'ia')
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza") VALUES
(298, 55, '01:25:30', 'Errori di scena / Posizione', 'Nel corso dei primi round del match, il grande taglio sul sopracciglio sinistro di Ivan Drago scompare misteriosamente nel round successivo per poi ricomparire più marcato nel round undici.', TRUE, '2026-09-14T13:53:59.287137', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(299, 55, '01:32:10', 'Troupe o microfoni visibili', 'Durante l''intervallo tra le riprese all''angolo di Rocky, nel riflesso del secchio d''acqua in metallo si distingue chiaramente la luce circolare di uno faretto di illuminazione della troupe.', TRUE, '2026-09-14T13:53:59.322252', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(300, 55, '01:39:50', 'Errori di scena / Posizione', 'Alla fine dell''incontro, quando Rocky pronuncia il suo celebre discorso al pubblico sovietico con la bandiera americana sulle spalle, i suoi guantoni e il volto passano dall''essere coperti di sangue e sudore all''essere quasi del tutto puliti.', TRUE, '2026-09-14T13:53:59.392445', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(301, 56, '00:04:15', 'Errori di scena / Posizione', 'Nelle primissime scene in cui Rocky viene trasportato in ambulanza subito dopo l''incontro del primo film, i tagli e i gonfiori sul suo volto cambiano forma, dimensione e quantità di sangue finto tra un primo piano e l''altro.', TRUE, '2026-09-14T13:54:32.874155', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(304, 56, '00:36:45', 'Errori di scena / Posizione', 'Nella scena romantica in cui Rocky chiede ad Adrian di sposarlo al parco sotto la neve, l''accumulo di fiocchi di neve sulle spalle dei loro cappotti scompare e ricompare drasticamente ad ogni cambio di angolazione della telecamera.', TRUE, '2026-09-14T13:54:33.075927', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(305, 56, '00:48:30', 'Anacronismi', 'Durante una passeggiata in quartiere, si nota sullo sfondo un''automobile parcheggiata che mostra sul parabrezza un bollino di ispezione e immatricolazione risalente al 1979, mentre la storia nella finzione cinematografica si svolge tra il 1976 e il 1977.', TRUE, '2026-09-14T13:54:33.176911', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(306, 56, '01:02:18', 'Errori di scena / Posizione', 'Quando Rocky lavora al macello insieme a Paulie, la posizione dei ganci da carne dietro di lui e le macchie di sangue sul suo grembiule bianco cambiano posizione tra un secondo e l''altro.', TRUE, '2026-09-14T13:54:33.218861', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(307, 56, '01:14:05', 'Troupe o microfoni visibili', 'All''interno della palestra di Mickey, mentre Rocky si allena al sacco da boxe e l''allenatore gli grida le istruzioni, sul vetro della finestra sullo sfondo si intravede il riflesso dell''operatore con la cinepresa.', TRUE, '2026-09-14T13:54:33.285153', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(308, 56, '01:25:50', 'Errori di scena / Posizione', 'Durante le scene in cui Adrian è in coma in ospedale in seguito al parto complicato, la cannula dell''ossigeno applicata al suo viso cambia posizione e i tubicini sono disposti in modo diverso da un''inquadratura all''altra.', TRUE, '2026-09-14T13:54:33.378086', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(309, 56, '01:38:12', 'Errori storici o fattuali', 'Nella celebre sequenza di allenamento in cui Rocky corre per Philadelphia seguito da una folla di bambini, il percorso seguito è geograficamente assurdo: salta da un quartiere all''altro della città percorrendo oltre 30 miglia in un''unica sessione di corsa continua.', TRUE, '2026-09-14T13:54:33.418329', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(310, 56, '01:42:00', 'Errori di scena / Posizione', 'Arrivato in cima alla scalinata del Philadelphia Museum of Art, la felpa grigia di Rocky passa da essere totalmente inzuppata di sudore sul petto a quasi perfettamente asciutta nella ripresa aerea successiva.', TRUE, '2026-09-14T13:54:33.495886', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(311, 56, '01:51:30', 'Troupe o microfoni visibili', 'All''ingresso dei pugili nel palazzetto per l''incontro finale, durante la visuale dal basso dell''angolo di Apollo Creed, nella parte altissima dello schermo spunta per un attimo l''estremità del microfono della troupe audio.', TRUE, '2026-09-14T13:54:33.594051', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(312, 56, '01:58:40', 'Errori di scena / Posizione', 'Tra un round e l''altro del match finale, il profondo taglio sull''occhio destro di Rocky viene medicato e coperto di vaselina, ma nel fotogramma successivo all''inizio del round successivo il taglio appare posizionato più in alto verso il sopracciglio.', TRUE, '2026-09-14T13:54:33.686631', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(313, 56, '02:05:15', 'Errori storici o fattuali', 'Nel 15° round, quando sia Rocky che Apollo crollano a terra stremati, il conteggio dell''arbitro dura in realtà quasi 14 secondi effettivi al cronometro anziché i regolamentari 10 secondi previsti dal regolamento ufficiale del pugilato.', TRUE, '2026-09-14T13:54:33.729484', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(314, 56, '02:12:00', 'Errori di scena / Posizione', 'Durante il celebre discorso della vittoria in cui Rocky urla ''Yo Adrian, I did it!'', i lacci del guantone sinistro del pugile appaiono sciolti in una ripresa, per poi tornare perfettamente stretti e allacciati nella ripresa successiva.', TRUE, '2026-09-14T13:54:33.794325', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(315, 61, '00:08:15', 'Anacronismi', 'Durante la sequenza dell''inaugurazione della banca a Saint Martin, viene mostrato un caveau dotato di una moderna cassaforte con serratura a combinazione meccanica e ingranaggi complessi. Le casseforti con serrature a combinazione di questo tipo sono state inventate solo nella seconda metà del XIX secolo, mentre il film è ambientato intorno alla metà del XVIII secolo.', TRUE, '2026-09-14T14:11:22.133547', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(316, 61, '00:14:40', 'Errori storici o fattuali', 'Nella scena dell''inseguimento con la banca trainata dai cavalli, l''intero edificio in mattoni e pietra viene trascinato intatto per le vie della città. Dal punto di vista della fisica e dell''architettura dell''epoca, una struttura in muratura non armata si sarebbe sbriciolata istantaneamente appena strappata dalle sue fondamenta.', TRUE, '2026-09-14T14:11:22.254175', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(432, 90, '00:23:10', 'Errori di scena / Posizione', 'Quando Gabrielle guida verso il Messico per cercare suo padre, la sporcizia sul parabrezza della sua auto scompare e riappare tra i primi piani dall''interno del veicolo e le riprese esterne dall''alto.', TRUE, '2026-09-16T10:29:42.0926', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(319, 61, '00:48:50', 'Troupe o microfoni visibili', 'Durante l''attacco degli squali fantasma di Salazar, quando Jack e Henry cercano di raggiungere la riva sulla scialuppa, in un''inquadratura ravvicinata del movimento dei remi è visibile per un istante il cavo di sicurezza in acciaio agganciato alla parte inferiore dello scafo della barca per guidarne il movimento sul set.', TRUE, '2026-09-14T14:11:22.544946', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(320, 61, '01:02:15', 'Anacronismi', 'Carina Smyth fa riferimento a coordinate astronomiche legate al pianeta Urano per decifrare il diario. Tuttavia, il pianeta Urano è stato scoperto da William Herschel solo nel 1781, un periodo nettamente successivo rispetto all''epoca in cui sono ambientate le avventure del film.', TRUE, '2026-09-14T14:11:22.634471', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(321, 61, '01:18:40', 'Errori storici o fattuali', 'Sulle navi della Marina Reale britannica viene mostrata la bandiera Union Jack che include la croce rossa diagonale di San Patrizio (rappresentante l''Irlanda). Questa versione della bandiera fu adottata ufficialmente solo con l''Atto di Unione del 1801, mentre nel XVIII secolo la bandiera britannica non conteneva ancora la croce irlandese.', TRUE, '2026-09-14T14:11:22.743895', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(322, 61, '01:31:10', 'Errori di scena / Posizione', 'Quando Barbossa si trova a bordo per affrontare la minaccia di Salazar, la posizione della sua gamba di legno e delle relative cinghie varia tra le inquadrature: nei tagli frontali la cinghia di supporto sulla coscia appare allacciata sopra i pantaloni, mentre nei controcampi ripresi da dietro risulta posizionata sotto la giacca o diversamente ancorata.', TRUE, '2026-09-14T14:11:22.839615', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(323, 61, '02:01:05', 'Errori di scena / Posizione', 'Nella sequenza finale dell''ancora calata nella fenditura marina, la quantità di fango e macchie d''acqua sui vestiti di Henry e Carina cambia visibilmente tra le inquadrature successive, passando da abiti completamente inzuppati e sporchi a capi quasi puliti e asciutti durante i primi piani emotivi.', TRUE, '2026-09-14T14:11:22.876661', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(346, 62, '01:38:10', 'Errori di scena / Posizione', 'Nella scena a bordo del volo privato verso la Svizzera, quando il gruppo festeggia disordinatamente, le linee di sostanza bianca disposte sul tavolino di cristallo cambiano forma, lunghezza e numero ad ogni cambio di inquadratura della telecamera.', TRUE, '2026-09-15T17:15:17.006303', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(325, 60, '00:20:15', 'Anacronismi', 'Durante la rocambolesca fuga in carrozza di Jack Sparrow per le vie di Londra, sul muro di un edificio e lungo il selciato si intravedono elementi di conduttura in metallo e grate di scolo in ghisa tipiche della tarda epoca vittoriana (seconda metà dell''Ottocento), del tutto assenti a metà del Settecento.', TRUE, '2026-09-14T14:11:51.547637', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(326, 60, '00:37:40', 'Errori di scena / Posizione', 'Durante l''ammutinamento sulla Queen Anne''s Revenge, la sporcizia sul viso di Jack Sparrow e la disposizione delle sue treccine sul pettorale variano visibilmente da un''inquadratura all''altra nell''arco di pochi secondi di dialogo con Angelica.', TRUE, '2026-09-14T14:11:51.620239', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(327, 60, '00:41:20', 'Troupe o microfoni visibili', 'Quando Barbanera usa la spada magica per controllare le corde e la sartiame della nave contro i marinai ribelli, in un fotogramma in cui un marinaio viene sollevato a mezz''aria è chiaramente visibile il cavo di metallo dell''imbracatura di sicurezza utilizzato dallo stuntman.', TRUE, '2026-09-14T14:11:51.753514', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(328, 60, '00:54:10', 'Errori di scena / Posizione', 'Durante il drammatico attacco delle sirene a Whitecap Bay, Jack Sparrow finisce completamente immerso in acqua. Nella scena immediatamente successiva, quando si arrampica sulla torretta del faro per far esplodere la polvere da sparo, i suoi abiti e la giacca risultano visibilmente asciutti.', TRUE, '2026-09-14T14:11:51.836377', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(329, 60, '01:04:30', 'Errori di scena / Posizione', 'Quando la sirena Syrena viene trasportata nella cassa di vetro riempita d''acqua, il livello del liquido ed il modo in cui i suoi capelli bagnati le coprono le spalle e il volto cambiano vistosamente tra le inquadrature frontali e quelle laterali dei marinai che la trasportano.', TRUE, '2026-09-14T14:11:51.929835', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(330, 60, '01:16:45', 'Errori storici o fattuali', 'All''interno del vascello incagliato ''Santiago'', appartenuto all''esploratore Juan Ponce de León, si notano elementi d''arredo, armi da fuoco e carte geografiche risalenti alla fine del XVII o inizio XVIII secolo. Storicamente, Ponce de León è deceduto nel 1521, quindi la nave avrebbe dovuto contenere strumentazioni ed equipaggiamenti di inizio XVI secolo.', TRUE, '2026-09-14T14:11:52.026864', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(331, 60, '01:21:10', 'Errori di scena / Posizione', 'Nella cabina di Ponce de León, Jack Sparrow e Barbossa cercano i due calici d''argento. Prima che la nave cominci ad oscillare sul dirupo, la posizione dei calici sul letto cambia spontaneamente tra due stacchi di montaggio ravvicinati.', TRUE, '2026-09-14T14:11:52.062928', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(332, 60, '01:42:15', 'Troupe o microfoni visibili', 'Durante la marcia delle truppe spagnole verso il tempio della Fonte della Giovinezza, in una ripresa dal basso con movimento di macchina verso l''alto, nell''angolo inferiore sinistro dello schermo proiettato sulle rocce è brevemente visibile l''ombra della gru di ripresa (Jib/Jimmy Jib) e del paraluce della telecamera.', TRUE, '2026-09-14T14:11:52.136141', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(333, 60, '01:53:50', 'Errori di scena / Posizione', 'Nella sequenza finale presso la Fonte della Giovinezza, quando Angelica si ferisce la mano per raccogliere il veleno della spada, la macchia di sangue sul suo palmo e sul vestito cambia dimensione, forma e densità di colore nei vari primi piani mentre parla con Jack.', TRUE, '2026-09-14T14:11:52.228799', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(343, 62, '00:12:45', 'Anacronismi', 'Nelle scene ambientate nel 1987, durante le inquadrature esterne lungo le strade di Wall Street, si possono notare sullo sfondo alcuni modelli di automobili e taxi con linee aerodinamiche e targhe di stile della fine degli anni ''90 e primi anni 2000.', TRUE, '2026-09-15T17:15:16.732795', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(335, 59, '00:26:40', 'Errori di scena / Posizione', 'Durante la battaglia nello stabilimento balneare di Sao Feng, Elizabeth Swann impugna due spade. In un''inquadratura ravvicinata ne perde una che cade in acqua a sinistra, ma nel controcampo immediatamente successivo la si vede chiaramente mentre la impugna di nuovo senza aver avuto il tempo materiale per riprenderla.', TRUE, '2026-09-14T14:15:11.743441', 'Pirati dei Caraibi - Ai confini del mondo Durante la battaglia nello stabilimento balneare di Sao mistake error', 0, 0, 'IA (Sistema)', 'ia'),
(336, 59, '00:43:15', 'Errori di scena / Posizione', 'Nel Cimitero di Davy Jones, quando Jack Sparrow si trova da solo sulla Perla Nera incagliata nel deserto e parla con le allucinazioni di sé stesso, la macchia di fuliggine sulla sua guancia sinistra cambia forma, dimensione e intensità tra le varie inquadrature ravvicinate e i campi medi.', TRUE, '2026-09-14T14:15:11.778757', 'Pirati dei Caraibi - Ai confini del mondo Nel Cimitero di Davy Jones quando Jack Sparrow mistake error', 0, 0, 'IA (Sistema)', 'ia'),
(433, 90, '00:43:50', 'Errori di scena / Posizione', 'Dopo essere stato brutalmente pestato dagli uomini del cartello guidati dai fratelli Martinez, i tagli e le macchie di sangue sul viso di Rambo cambiano visibilmente forma e posizione tra l''inquadratura a terra e il momento in cui viene soccorso da Carmen.', TRUE, '2026-09-16T10:29:42.0926', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(68, 29, '01:12:00', 'Continuity', 'Le pesanti catene ai polsi del protagonista appaiono spezzate dopo la lotta, ma nella scena immediatamente successiva tornano integre.', TRUE, '2026-09-13T15:01:47.103086', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(338, 59, '01:39:20', 'Troupe o microfoni visibili', 'Nella scena del parley sulla lingua di sabbia tra Lord Beckett, Davy Jones, Will, Elizabeth, Barbossa e Jack, sulla sabbia bianca a destra dello schermo è visibile per un istante l''ombra della gru della macchina da presa e di un pannello riflettente usati dalla troupe per illuminare gli attori.', TRUE, '2026-09-14T14:15:11.944556', 'Pirati dei Caraibi - Ai confini del mondo Nella scena del parley sulla lingua di sabbia mistake error', 0, 0, 'IA (Sistema)', 'ia'),
(339, 59, '02:05:10', 'Errori di scena / Posizione', 'Durante la grande battaglia finale nel Maelstrom, mentre Barbossa celebra il matrimonio tra Will ed Elizabeth sotto una pioggia battente, i capelli di Elizabeth cambiano continuamente stato: nei campi lunghi sono completamente inzuppati e appiccicati al viso, mentre nei primi piani della promessa nuziale risultano solo leggermente umidi e ben acconciati.', TRUE, '2026-09-14T14:15:12.018362', 'Pirati dei Caraibi - Ai confini del mondo Durante la grande battaglia finale nel Maelstrom mentre mistake error', 0, 0, 'IA (Sistema)', 'ia'),
(340, 59, '02:17:45', 'Troupe o microfoni visibili', 'Quando Jack Sparrow si lancia con una corda tra gli alberi della nave per recuperare lo scrigno di Davy Jones, sotto il suo giacchetto si nota chiaramente la tensione e la sagoma dell''imbracatura di sicurezza moderna e il cavo d''acciaio di supporto collegato alla schiena dell''attore.', TRUE, '2026-09-14T14:15:12.165398', 'Pirati dei Caraibi - Ai confini del mondo Quando Jack Sparrow si lancia con una corda mistake error', 0, 0, 'IA (Sistema)', 'ia'),
(341, 59, '02:28:30', 'Errori di scena / Posizione', 'Nel climax della battaglia sul ponte dell''Olandese Volante, Jack tiene la chiave del cuore di Davy Jones nella mano sinistra prima di minacciare Jones. Nel stacco di montaggio immediato sul pugno di Jones, la chiave si trova improvvisamente nella mano destra di Jack.', TRUE, '2026-09-14T14:15:12.237948', 'Pirati dei Caraibi - Ai confini del mondo Nel climax della battaglia sul ponte dellOlandese Volante mistake error', 0, 0, 'IA (Sistema)', 'ia'),
(353, 68, '00:15:30', 'Anacronismi', 'Durante gli scontri in Terra Santa, i soldati nemici e successivamente le guardie di Nottingham utilizzano balestre a ripetizione che funzionano come fucili d''assalto automatici, dotate di caricatori verticali e sistemi di ricarica rapida a pompa. Questo tipo di tecnologia bellica è totalmente anacronistica per l''epoca medievale.', TRUE, '2026-09-15T18:05:31.76036', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(354, 68, '00:38:45', 'Errori di scena / Posizione', 'Durante la sequenza di addestramento in cui Little John insegna a Robin a tirare rapidamente con l''arco, la posizione delle frecce scagliate sul bersaglio cambia repentinamente tra un''inquadratura e l''altra. In un fotogramma ravvicinato le frecce sono raggruppate al centro, mentre nel campo lungo successivo sono disposte in modo diverso e alcune sono sparite.', TRUE, '2026-09-15T18:05:31.809659', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(355, 68, '00:52:10', 'Errori storici o fattuali', 'Le miniere di carbone di Nottingham sono rappresentate come un immenso complesso industriale siderurgico della fine del XIX secolo, con passerelle metalliche sospese, carrelli su rotaie d''acciaio e fumi industriali. Nel XII secolo, l''estrazione del carbone era estremamente rudimentale e non esistevano strutture metalliche di tale portata ingegneristica.', TRUE, '2026-09-15T18:05:31.877319', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(356, 68, '01:10:15', 'Anacronismi', 'I costumi dei personaggi, in particolare le giacche di pelle trapuntate di Robin e gli abiti dello Sceriffo di Nottingham, presentano cuciture a macchina perfette, cerniere lampo nascoste e tagli di sartoria moderna stile streetwear contemporaneo. Anche i tessuti sintetici utilizzati per i cappucci e le fodere sono palesemente moderni.', TRUE, '2026-09-15T18:05:31.96689', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(357, 68, '01:28:30', 'Errori di scena / Posizione', 'Durante la rivolta finale nei pressi delle miniere, le ferite da taglio e le macchie di fuliggine sul volto di Robin Hood cambiano forma, intensità e posizione esatta tra i primi piani e le inquadrature più larghe, rivelando una scarsa continuità nel trucco di scena tra i vari ciak.', TRUE, '2026-09-15T18:05:32.064608', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(358, 68, '01:35:20', 'Anacronismi', 'Durante lo scontro finale tra i ribelli e le guardie dello Sceriffo, queste ultime si schierano utilizzando scudi antisommossa metallici e tattiche di contenimento della folla che replicano fedelmente quelle della polizia moderna. Gli scudi hanno persino feritoie visive e impugnature ergonomiche del tutto estranee al medioevo.', TRUE, '2026-09-15T18:05:32.106971', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(359, 69, '00:12:15', 'Errori di scena / Posizione', 'Durante l''assedio del castello di Chalus-Chabrol, Robin si prepara a tirare con l''arco. In un''inquadratura ravvicinata, le frecce nella sua faretra sono disposte in modo disordinato e con le piume rivolte verso l''alto. Nel taglio successivo, le frecce sono perfettamente allineate e orientate diversamente, per poi tornare disordinate subito dopo.', TRUE, '2026-09-15T18:19:14.513235', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(360, 69, '00:18:40', 'Errori storici o fattuali', 'Re Riccardo Cuor di Leone viene colpito al collo da un dardo di balestra scagliato da un cuoco francese e muore quasi istantaneamente sul campo di battaglia. Storicamente, Riccardo fu effettivamente ferito alla spalla/collo durante l''assedio di Châlus-Chabrol nel marzo 1199, ma morì ben undici giorni dopo a causa della gangrena sopraggiunta, non sul colpo.', TRUE, '2026-09-15T18:19:14.56688', NULL, 0, 0, 'IA (Sistema)', 'ia')
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza") VALUES
(361, 69, '00:42:10', 'Errori di scena / Posizione', 'Quando Robin e i suoi compagni arrivano a Londra via fiume per consegnare la corona reale, si vede un''inquadratura grandangolare del Tamigi con una forte corrente e barche che oscillano vistosamente. Nel primo piano immediatamente successivo, mentre attraccano, l''acqua è improvvisamente calmissima e piatta, priva di qualsiasi increspatura coerente con la scena precedente.', TRUE, '2026-09-15T18:19:14.653349', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(362, 69, '01:15:30', 'Anacronismi', 'Nelle scene ambientate a Nottingham e nelle campagne circostanti, si possono notare diversi strumenti agricoli, tra cui forconi a tre punte interamente in ferro e pale con bordi rinforzati con leghe metalliche moderne. Nel 1199, la maggior parte degli attrezzi agricoli dei contadini era rudimentale, realizzata quasi esclusivamente in legno sagomato a causa dell''altissimo costo del ferro.', TRUE, '2026-09-15T18:19:14.756378', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(363, 69, '01:38:25', 'Errori storici o fattuali', 'La trama si sviluppa fortemente attorno a una ''Carta delle Libertà'' scritta dal padre di Robin, che anticipa la Magna Carta, e che Re Giovanni promette di firmare per unire il paese contro i francesi. Storicamente, la Magna Carta fu redatta e imposta a Re Giovanni d''Inghilterra dai baroni ribelli solo nel 1215 a Runnymede, senza alcun legame con un''invasione francese sulle spiagge o con la figura di un arciere di nome Robin.', TRUE, '2026-09-15T18:19:14.859254', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(422, 85, '02:05:40', 'Errori di scena / Posizione', 'All''interno della stanza della memoria logica di HAL 9000, Dave Bowman procede alla disattivazione dei blocchi di memoria. L''utensile speciale utilizzato per svitare le schede trasparenti passa dalla mano destra alla mano sinistra tra due stacchi di montaggio consecutivi senza che l''astronauta lo abbia mai scambiato di mano.', TRUE, '2026-09-16T10:00:42.101711', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(364, 69, '01:55:10', 'Troupe o microfoni visibili', 'Durante la caotica sequenza della battaglia finale sulla spiaggia, nell''angolo inferiore sinistro dello schermo, durante una rapida carrellata che segue la carica dei cavalieri inglesi, è possibile scorgere per una frazione di secondo la testa di un operatore della troupe munito di cuffie antirumore moderne e parte del braccio meccanico di una telecamera coperto da un telo scuro.', TRUE, '2026-09-15T18:19:14.962285', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(365, 69, '02:02:15', 'Anacronismi', 'Le truppe francesi tentano lo sbarco sulle coste inglesi utilizzando imbarcazioni a fondo piatto dotate di una rampa frontale apribile per facilitare la discesa dei soldati. Questo design è un evidente anacronismo, poiché ricalca fedelmente i moderni mezzi di sbarco (come i famosi Higgins Boats utilizzati nel D-Day della Seconda Guerra Mondiale). All''inizio del XIII secolo, gli sbarchi avvenivano tramite normali navi da trasporto o scialuppe, costringendo i soldati a scavalcare le paratie laterali.', TRUE, '2026-09-15T18:19:15.065278', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(366, 69, '02:08:40', 'Errori di scena / Posizione', 'Nello scontro finale in acqua tra Robin e Godfrey, la cotta di maglia e la tunica di Robin appaiono completamente inzuppate d''acqua, infangate e appesantite dal bagnasciuga. Pochi secondi dopo, quando Robin si rialza e osserva la ritirata dei francesi, la sua tunica è visibilmente asciutta nella parte superiore e priva delle vistose macchie di fango bagnato viste nell''inquadratura precedente.', TRUE, '2026-09-15T18:19:15.165888', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(367, 69, '01:58:12', 'Anacronismi', 'Durante la battaglia finale sulla spiaggia, i francesi sbarcano utilizzando imbarcazioni dotate di rampe anteriori ribaltabili. Questo design è un evidente anacronismo, poiché ricalca fedelmente i mezzi da sbarco (Higgins Boats) impiegati durante la seconda guerra mondiale, del tutto inesistenti nel XII secolo.', TRUE, '2026-09-15T18:23:51.652663', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(352, 68, '00:12:40', 'Errori storici o fattuali', 'La rappresentazione della Terza Crociata in Arabia è palesemente modellata sulla moderna guerra urbana in Medio Oriente. Gli edifici sembrano fatti di cemento armato moderno con tondini di ferro, e i soldati utilizzano tattiche di pattugliamento e copertura da cecchini tipiche delle forze speciali contemporanee, del tutto estranee alle strategie militari del XII secolo.', TRUE, '2026-09-15T18:05:31.682269', NULL, 0, 1, 'IA (Sistema)', 'ia'),
(669, 133, '01:12:35', 'Anacronismi', 'Quando Sharon Tate si reca al cinema Bruin per vedere se stessa nel film ''The Wrecking Crew'', si possono notare sullo sfondo dei parchimetri stradali a tariffa oraria digitale e con scritte moderne, incompatibili con i modelli interamente meccanici in uso a Los Angeles nel 1969.', TRUE, '2026-09-19T19:47:51.941973', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(368, 69, '00:42:15', 'Anacronismi', 'Diversi soldati francesi e cavalieri inglesi indossano componenti di armatura a piastre e celate (come i bacinetti) tipiche del XIV e XV secolo. Nel 1199, epoca in cui è ambientato il film, l''equipaggiamento militare era quasi esclusivamente composto da usberghi in maglia di ferro (chainmail) e cervelliere o elmi con nasale.', TRUE, '2026-09-15T18:23:51.757054', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(369, 69, '00:11:04', 'Errori di scena / Posizione', 'Durante l''assedio del castello di Châlus-Chabrol, quando Robin si prepara a scoccare una freccia contro il cuoco francese sulle mura, la freccia è inizialmente posizionata sul lato sinistro dell''arco. Nel cambio d''inquadratura successivo, la freccia si trova sul lato destro dell''arco, per poi tornare a sinistra nel momento del tiro.', TRUE, '2026-09-15T18:23:51.853354', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(370, 69, '00:26:40', 'Troupe o microfoni visibili', 'Nella scena dell''imboscata nella foresta ai danni dei cavalieri che trasportano la corona del re, sul terreno fangoso ai lati del sentiero principale si possono chiaramente notare i solchi paralleli lasciati dagli pneumatici dei fuoristrada della troupe cinematografica, incompatibili con il passaggio di soli carri e cavalli dell''epoca.', TRUE, '2026-09-15T18:23:51.949333', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(371, 69, '02:02:10', 'Errori di scena / Posizione', 'Quando Marion cade in acqua durante lo scontro finale sulla spiaggia e viene soccorsa da Robin, i suoi capelli appaiono completamente bagnati, intrisi di fango e appiccicati al viso. Pochi secondi dopo, mentre osserva la ritirata dei francesi, i suoi capelli sono improvvisamente asciutti, puliti e vaporosi.', TRUE, '2026-09-15T18:23:52.050002', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(372, 69, '00:54:30', 'Errori di scena / Posizione', 'Quando Robin consegna la corona di Re Riccardo a Giovanna d''Inghilterra e alla Regina Madre, la tiene inizialmente con le punte rivolte verso il basso. Nell''inquadratura successiva in primo piano, la corona è improvvisamente ruotata di 180 gradi, con le gemme principali orientate diversamente rispetto alla presa precedente.', TRUE, '2026-09-15T18:23:52.152446', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(373, 69, '01:52:00', 'Errori storici o fattuali', 'Il film mostra re Filippo II di Francia che guida personalmente un massiccio sbarco sulle coste inglesi prima della firma della Magna Carta (1215). Storicamente, Filippo II non invase mai l''Inghilterra in quel modo; fu suo figlio, il principe Luigi (futuro Luigi VIII), a sbarcare nel Kent nel 1216 su invito dei baroni ribelli inglesi, ben dopo la firma del celebre documento.', TRUE, '2026-09-15T18:23:52.268275', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(374, 67, '00:24:40', 'Errori di scena / Posizione', 'Durante il duello sul tronco sospeso tra Robin Hood e Little John, quest''ultimo cade nel torrente sottostante. Nelle inquadrature immediatamente successive, mentre i due stringono amicizia, i vestiti e i capelli di Little John appaiono bagnati in modo del tutto incoerente: in alcuni tagli sono completamente inzuppati, mentre in altri sono quasi asciutti, specialmente sulle spalle e sul petto.', TRUE, '2026-09-15T18:28:25.278334', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(375, 67, '00:35:10', 'Anacronismi', 'Quando viene mostrata la cintura di castità di Lady Marian, si può notare chiaramente che è dotata di una moderna serratura a combinazione e presenta il logo della nota marca sportiva ''Everlast'' impresso sul metallo. Sebbene il film sia una parodia deliberata, questo costituisce un evidente anacronismo tecnologico e commerciale rispetto al XII secolo.', TRUE, '2026-09-15T18:28:25.362101', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(376, 67, '00:42:15', 'Anacronismi', 'Prima del combattimento contro gli scagnozzi dello Sceriffo di Rottingham, Ahchoo si ferma per gonfiare le sue scarpe da ginnastica, che sono delle evidenti ''Reebok Pump'' nere e bianche, un modello di calzatura sportiva introdotto sul mercato solo alla fine degli anni ''80.', TRUE, '2026-09-15T18:28:25.462177', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(703, 63, '00:18:45', 'Errori di scena / Posizione', 'Durante il torneo iniziale di giostra, la lancia del Conte di Huntingdon cambia impugnatura e orientamento tra la ripresa a campo largo e il primo piano immediatamente successivo prima dell''impatto.', TRUE, '2026-09-25T19:09:14.246576', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(377, 67, '00:52:05', 'Errori di scena / Posizione', 'Nella tana della strega Latrina, mentre quest''ultima sta preparando una pozione per lo Sceriffo di Rottingham, la disposizione degli oggetti sul tavolo da lavoro cambia continuamente tra un''inquadratura e l''altra. In particolare, un teschio e un''ampolla di vetro blu si spostano da destra a sinistra senza che nessuno li tocchi.', TRUE, '2026-09-15T18:28:25.563859', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(378, 67, '01:18:30', 'Errori di scena / Posizione', 'Durante la celebre gara di tiro con l''arco, quando Robin scocca la freccia che ne fende in due un''altra già conficcata nel bersaglio, la posizione dei frammenti di legno cambia drasticamente. Nel primo piano ravvicinato la freccia è spaccata perfettamente a metà in senso longitudinale, mentre nell''inquadratura successiva a campo largo i pezzi di legno sono disposti in modo diverso e l''angolazione d''impatto sul bersaglio è mutata.', TRUE, '2026-09-15T18:28:25.665096', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(659, 129, '00:28:15', 'Errori di scena / Posizione', 'Durante la celebre scena in cui il giovane Noodles spia Deborah che danza nel retrobottega, la disposizione dei sacchi di farina e degli oggetti sugli scaffali cambia visibilmente tra le inquadrature strette e quelle larghe. Inoltre, la quantità di polvere di farina sul viso e sui capelli di Deborah varia inspiegabilmente da un''inquadratura all''altra.', TRUE, '2026-09-19T19:44:18.773942', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(379, 67, '01:22:10', 'Troupe o microfoni visibili', 'Durante la caotica scena del tentativo di impiccagione di Robin Hood, quando la folla inizia a ribellarsi e a combattere contro le guardie dello Sceriffo, sul lato sinistro dello schermo, parzialmente coperto da una finta colonna del castello, è possibile scorgere per un paio di fotogrammi un operatore della troupe cinematografica con indosso una maglietta scura moderna e un cappellino da baseball.', TRUE, '2026-09-15T18:28:25.766337', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(380, 67, '01:31:15', 'Errori storici o fattuali', 'All''arrivo di Re Riccardo, il sovrano indossa un''armatura a piastre completa e una corona con un design tipico del XV secolo. Storicamente, Riccardo Cuor di Leone visse alla fine del XII secolo (morì nel 1199), un''epoca in cui i cavalieri indossavano principalmente usberghi di maglia di ferro e non armature a piastre articolate, che si diffusero solo oltre due secoli dopo.', TRUE, '2026-09-15T18:28:25.864591', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(381, 66, '00:21:30', 'Errori storici o fattuali', 'Dopo essere sbarcati sulle coste meridionali dell''Inghilterra (nei pressi di Dover), Robin e Azeem si incamminano verso Nottingham affermando che saranno lì ''entro sera''. Tuttavia, durante il tragitto vengono mostrati mentre camminano lungo il Vallo di Adriano, che si trova a centinaia di chilometri più a nord, vicino al confine scozzese. È geograficamente impossibile passare di lì per andare da Dover a Nottingham, e ancor meno farlo a piedi in un solo giorno.', TRUE, '2026-09-15T18:33:00.354191', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(382, 66, '00:37:45', 'Anacronismi', 'Azeem mostra a Robin un cannocchiale tascabile per osservare i soldati dello Sceriffo in lontananza. Il film è ambientato nel 1194, durante la Terza Crociata, ma il cannocchiale non fu inventato prima dell''inizio del XVII secolo (intorno al 1608, ad opera di Hans Lippershey nei Paesi Bassi).', TRUE, '2026-09-15T18:33:00.431151', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(383, 66, '00:49:15', 'Errori di scena / Posizione', 'Durante il celebre scontro sul tronco d''albero tra Robin Hood e Little John, Robin cade ripetutamente nell''acqua profonda del fiume. Nelle inquadrature immediatamente successive, mentre i due ridono e fanno amicizia, i vestiti e i capelli di Robin appaiono completamente asciutti e in perfetto ordine, per poi tornare bagnati nel cambio di inquadratura successivo.', TRUE, '2026-09-15T18:33:00.507847', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(384, 66, '01:41:30', 'Anacronismi', 'Azeem utilizza la polvere da sparo per creare sofisticati ordigni esplosivi durante la preparazione della battaglia finale. Sebbene la polvere da sparo fosse già nota in Cina, il suo utilizzo militare sotto forma di bombe a mano ed esplosivi da lancio non era assolutamente diffuso né disponibile nell''Inghilterra del XII secolo.', TRUE, '2026-09-15T18:33:00.611397', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(385, 66, '02:01:40', 'Errori di scena / Posizione', 'Durante la cerimonia di matrimonio forzato tra Lady Marian e lo Sceriffo di Nottingham, la posizione del velo da sposa di Marian cambia continuamente tra i cambi di inquadratura. In alcuni primi piani il velo le copre parzialmente il viso, mentre nei campi medi è tirato completamente all''indietro, senza che nessuno lo abbia toccato.', TRUE, '2026-09-15T18:33:00.712559', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(386, 66, '02:05:10', 'Troupe o microfoni visibili', 'Durante la caotica scena dell''esecuzione pubblica in cui Robin e i suoi uomini intervengono per salvare i prigionieri dal patibolo, in diverse inquadrature rallentate dei saltatori e delle controfigure che si lanciano dalle mura del castello sono chiaramente visibili i cavi di sicurezza d''acciaio che sorreggono gli stuntman.', TRUE, '2026-09-15T18:33:00.81919', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(387, 66, '02:11:15', 'Errori di scena / Posizione', 'Nel duello finale tra Robin e lo Sceriffo di Nottingham, lo Sceriffo ferisce Robin alla mano e al braccio con la spada. Tuttavia, nelle inquadrature successive, la ferita scompare misteriosamente: non c''è traccia di sangue sulla manica o sulla pelle, e Robin continua a impugnare la spada e a combattere con incredibile vigore usando entrambe le mani senza mostrare alcun segno di dolore.', TRUE, '2026-09-15T18:33:00.91746', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(395, 82, '00:18:45', 'Errori di scena / Posizione', 'Alla clinica Shrublands, durante la violenta colluttazione tra James Bond e Lippe nel laboratorio, vari flaconi e provette sul bancone cambiano posizione tra le inquadrature prima ancora di essere urtati. Inoltre, le tracce di sangue sul volto di Lippe e la posizione delle schegge di vetro sul pavimento variano bruscamente nei raccordi di montaggio.', TRUE, '2026-09-15T19:26:19.839631', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(396, 82, '00:27:12', 'Troupe o microfoni visibili', 'Durante la sequenza in cui Fatima Blush provoca l''incidente d''auto mortale di Jack Petachi gettandogli una vipera nell''abitacolo, sul riflesso dei vetri e sulla fiancata metallica della vettura che sbanda si possono scorgere le luci del set e l''intelaiatura dell''attrezzatura per la cinepresa montata sul veicolo di ripresa.', TRUE, '2026-09-15T19:26:19.901087', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(397, 82, '00:46:18', 'Errori di scena / Posizione', 'Durante l''immersione subacquea alle Bahamas, quando Bond viene attaccato dallo squalo dopo essere stato intrappolato da Fatima, l''attrezzatura subacquea dell''agente 007 cambia configurazione: nei campi lunghi (interpretati dallo stuntman) le cinghie dell''imbragatura e il modello delle bombole differiscono visibilmente rispetto ai primi piani registrati con Sean Connery.', TRUE, '2026-09-15T19:26:19.996879', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(398, 82, '01:14:35', 'Errori di scena / Posizione', 'Durante l''inseguimento in moto nelle strade della Costa Azzurra, le calzature di Fatima Blush passano inspiegabilmente da eleganti scarpe con il tacco a stivali con suola piatta da motociclista durante le manovre più spericolate con la controfigura, per poi ritornare calzature coi tacchi alti non appena si ferma nel magazzino.', TRUE, '2026-09-15T19:26:20.092325', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(399, 82, '01:21:40', 'Errori di scena / Posizione', 'Nel corso della sfida al videogioco ''Domination'' tra Bond e Maximilian Largo al Casinò di Monte Carlo, lo stato della mappa olografica, i punteggi parziali e l''indicatore delle scosse elettriche mostrano valori incoerenti tra i controcampi sui due contendenti e le inquadrature fisse dello schermo di gioco.', TRUE, '2026-09-15T19:26:20.196922', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(400, 82, '01:45:12', 'Errori di scena / Posizione', 'Durante la rocambolesca fuga dalla fortezza di Palmyra, Bond e Domino si gettano con il cavallo da un alto bastione direttamente in mare. Il cavallo montato prima del salto presenta macchie e sfumature sul muso visibilmente diverse rispetto all''animale che nuota e riemerge dalle onde subito dopo l''impatto.', TRUE, '2026-09-15T19:26:20.297306', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(401, 82, '02:04:30', 'Errori storici o fattuali', 'Nello scontro finale subacqueo nella grotta delle ''Lacrime di Allah'', gli arpioni sparati dai fucili subacquei e dalle armi montate sui propulsori viaggiano a velocità supersonica con traiettorie perfettamente rettilinee su lunghe distanze, ignorando del tutto la resistenza fluidodinamica e la densità dell''acqua marina che frenerebbero drasticamente tali dardi entro pochi metri.', TRUE, '2026-09-15T19:26:20.398459', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(402, 84, '00:15:30', 'Anacronismi', 'Il velivolo da ricognizione tedesco Focke-Wulf Fw 189 ''Uhu'' che sorvola ripetutamente la zona è in realtà un aereo civile cecoslovacco Aero Ae-45 modificato per assomigliare al modello bellico. Le proporzioni della cabina di pilotaggio vetrata e la forma delle code gemelle rivelano la diversa natura del velivolo rispetto all''originale della Luftwaffe del 1943.', TRUE, '2026-09-15T20:53:33.12038', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(403, 84, '00:34:40', 'Troupe o microfoni visibili', 'Durante la drammatica sequenza del bombardamento d''artiglieria nella foresta, in cui i pini vengono spezzati dalle esplosioni, per una frazione di secondo sono visibili i cavi elettrici di innesco delle cariche pirotecniche che corrono lungo i tronchi degli alberi destinati a saltare in aria.', TRUE, '2026-09-15T20:53:33.256564', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(444, 89, '01:21:10', 'Errori di scena / Posizione', 'Mentre il cecchino ''Schoolboy'' fornisce copertura dall''alto con il suo fucile di precisione Barrett M82, i bossoli accumulati a terra accanto alla sua posizione cambiano disposizione e numero in maniera illogica tra i dettagli ravvicinati e le riprese più ampie.', TRUE, '2026-09-16T10:32:34.330245', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(404, 84, '00:42:15', 'Errori di scena / Posizione', 'Quando Flyora rientra nella sua casa ormai deserta e trova le bambole di pezza sul pavimento, la loro disposizione cambia nettamente tra l''inquadratura panoramica della stanza e il successivo primo piano dettagliato. Una delle bambole appare girata a pancia in giù, mentre prima era chiaramente rivolta verso l''alto.', TRUE, '2026-09-15T20:53:33.356493', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(405, 84, '00:52:15', 'Errori di scena / Posizione', 'Durante la faticosa traversata della palude, il fango sul viso e sui capelli di Glasha cambia continuamente consistenza, densità e posizione tra le inquadrature ravvicinate e i campi medi. In un fotogramma ha la guancia sinistra quasi pulita, mentre nel secondo successivo è completamente ricoperta di melma scura.', TRUE, '2026-09-15T20:53:33.506151', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(406, 84, '01:12:05', 'Errori storici o fattuali', 'Alcuni fucili Mosin-Nagant utilizzati dai partigiani bielorussi presentano cinghie di trasporto in tela e passanti metallici tipici delle versioni prodotte o modificate nel secondo dopoguerra (anni ''50), non conformi ai modelli standard in uso durante l''occupazione nazista del 1943.', TRUE, '2026-09-15T20:53:33.562939', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(407, 84, '01:42:10', 'Errori storici o fattuali', 'Molti dei camion utilizzati dalle truppe d''occupazione tedesche durante il massacro nel villaggio non sono veicoli d''epoca della Wehrmacht (come gli Opel Blitz), bensì camion sovietici del dopoguerra GAZ-63 e GAZ-51 camuffati. I mozzi delle ruote e la forma del telaio tradiscono la loro reale origine industriale degli anni ''50.', TRUE, '2026-09-15T20:53:33.678907', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(465, 86, '01:25:10', 'Troupe o microfoni visibili', 'Nelle battute finali all''interno della stazione di polizia, quando Rambo spara verso il soffitto per colpire lo sceriffo Teasle sul tetto, l''ombra del braccio del microfono boom si proietta chiaramente sulla parete di legno a sinistra dello schermo.', TRUE, '2026-09-16T10:45:07.709217', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(466, 86, '00:09:45', 'Errori di scena / Posizione', 'Durante la scena del tentativo di rasatura nella stazione di polizia, la quantità di schiuma da barba sul volto di Rambo varia vistosamente tra un cambio d''inquadratura e l''altro, e la posizione del taglio da rasoio sulla guancia cambia altezza prima che la lama lo tocchi.', TRUE, '2026-09-16T11:10:18.290089', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(467, 86, '00:14:40', 'Errori di scena / Posizione', 'Durante l''inseguimento in moto lungo il percorso ferrato, il pneumatico posteriore della Yamaha XT250 di Rambo cambia battistrada: passa da una gomma stradale a una da enduro tassellata per permettere allo stuntman di eseguire i salti in sicurezza.', TRUE, '2026-09-16T11:10:18.290089', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(468, 86, '00:28:15', 'Troupe o microfoni visibili', 'Quando il sergente Galt si sporge dall''elicottero per sparare a Rambo bloccato sulla parete rocciosa, nell''inquadratura dal basso verso l''alto si scorge chiaramente il cavo metallico di sicurezza dell''imbragatura dello stuntman fissato al telaio dell''aeromobile.', TRUE, '2026-09-16T11:10:18.290089', NULL, 0, 0, 'IA (Sistema)', 'ia')
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza") VALUES
(469, 86, '01:02:10', 'Errori storici o fattuali', 'Un ragazzo della Guardia Nazionale spara con un lanciarazzi M72 LAW contro l''ingresso della miniera. Un compagno si trova posizionato esattamente dietro il tubo di lancio: nella realtà la fiammata posteriore (backblast) dell''arma lo avrebbe ucciso o gravemente ustionato all''istante.', TRUE, '2026-09-16T11:10:18.290089', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(470, 86, '01:10:05', 'Troupe o microfoni visibili', 'Mentre Rambo guida il camion militare M35 sottratto alla Guardia Nazionale per fare ritorno in città, durante la curva a gomito prima del ponte è visibile il supporto tubolare metallico della cinepresa fissato sotto la fiancata del veicolo.', TRUE, '2026-09-16T11:10:18.290089', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(408, 84, '02:16:30', 'Errori di scena / Posizione', 'Nella celebre sequenza finale in cui Flyora spara ripetutamente al ritratto di Hitler immerso nella pozzanghera, il livello dell''acqua e la quantità di fango che copre il dipinto variano in modo non lineare tra i tagli di montaggio. In alcuni fotogrammi il ritratto è quasi totalmente visibile, mentre in altri è sommerso, prima ancora che i colpi ne alterino la posizione.', TRUE, '2026-09-15T20:53:33.767073', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(409, 84, '00:14:35', 'Anacronismi', 'Nel campo dei partigiani, tra i vari equipaggiamenti si possono notare alcuni zaini a sacco (''Veshmeshok'') nella versione da fanteria sovietica post-bellica (anni ''50/''60), riconoscibili dai passanti e dal tipo di fibbie metalliche, diversi dal modello semplificato utilizzato durante la seconda guerra mondiale.', TRUE, '2026-09-15T20:57:26.955057', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(410, 84, '00:38:12', 'Errori di scena / Posizione', 'Durante la celebre sequenza della pioggia nella foresta tra Flyora e Glasha, la disposizione del fango e delle foglie bagnate sul viso e sui capelli di Glasha cambia visibilmente tra i primi piani stretti e le inquadrature più larghe, rivelando molteplici ciak effettuati in momenti diversi.', TRUE, '2026-09-15T20:57:27.133981', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(411, 84, '01:12:45', 'Errori storici o fattuali', 'Il veicolo semicingolato tedesco utilizzato dalle truppe d''occupazione durante il rastrellamento è in realtà un OT-810 di fabbricazione cecoslovacca del dopoguerra, impiegato come sostituto del Sd.Kfz. 251. Si differenzia dall''originale tedesco per la forma del vano motore e la copertura superiore modificata.', TRUE, '2026-09-15T20:57:27.23419', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(412, 84, '00:48:22', 'Errori di scena / Posizione', 'Quando Flyora torna alla sua casa natale e trova la tavola ancora imbandita con il cibo abbandonato, la posizione delle mosche, delle ciotole e della bambola di pezza sul tavolo varia sensibilmente tra l''inquadratura soggettiva iniziale e il successivo piano sequenza in cui il ragazzo realizza la tragedia.', TRUE, '2026-09-15T20:57:27.434863', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(413, 84, '00:31:15', 'Troupe o microfoni visibili', 'Durante l''improvviso e devastante bombardamento d''artiglieria nella foresta, in un''inquadratura dal basso che segue la caduta di un grosso pino, nell''angolo inferiore sinistro dello schermo è visibile per una frazione di secondo parte della barriera protettiva in plexiglass utilizzata per proteggere l''operatore di macchina dai detriti delle cariche pirotecniche.', TRUE, '2026-09-15T20:57:27.477643', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(414, 84, '02:12:05', 'Errori di scena / Posizione', 'Nella drammatica scena in cui Flyora viene costretto a posare per una foto con una pistola puntata alla tempia, la quantità di fango sul lato sinistro del suo volto cambia drasticamente: nella scena dinamica ha il viso quasi completamente coperto di terra bagnata, mentre nello scatto fotografico finale (mostrato come fermo immagine) la tempia è molto più pulita per rendere visibile l''espressione terrorizzata.', TRUE, '2026-09-15T20:57:27.546485', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(415, 84, '01:02:10', 'Anacronismi', 'I volantini di propaganda tedesca che vengono mostrati mentre cadono dal cielo presentano caratteri tipografici cirillici con glifi e spaziature tipiche delle macchine da stampa sovietiche degli anni ''70 e ''80, incongruenti con i caratteri d''epoca utilizzati dalle stamperie mobili della Wehrmacht o del Ministero della Propaganda nel 1943.', TRUE, '2026-09-15T20:57:27.750578', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(416, 84, '01:48:30', 'Errori storici o fattuali', 'Alcuni soldati della Wehrmacht e delle SS impegnati nel massacro del villaggio imbracciano fucili d''assalto Sturmgewehr 44 (StG 44). Sebbene lo sviluppo dell''arma fosse già iniziato, nel 1943 (periodo in cui è ambientato il film) l''arma era nota come MP43 ed era distribuita in numeri estremamente limitati solo sul fronte orientale per test sul campo, rendendo storicamente improbabile la sua presenza massiccia in un''unità di retroguardia o anti-partigiana in Bielorussia.', TRUE, '2026-09-15T20:57:27.859457', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(417, 85, '00:34:20', 'Errori storici o fattuali', 'Durante il volo a bordo dello shuttle Aries verso la Stazione Spaziale, il Dr. Heywood Floyd beve cibo liquido con una cannuccia da un contenitore aspirante. Quando smette di aspirare, si nota il liquido scendere di nuovo verso il basso all''interno della cannuccia. In condizioni di microgravità nello spazio, il liquido non tornerebbe indietro verso il recipiente senza una forza di gravità che lo tiri verso il basso.', TRUE, '2026-09-16T10:00:41.199914', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(418, 85, '00:54:10', 'Errori di scena / Posizione', 'Durante la visita al monolito TMA-1 nel cratere lunare Tycho, le ombre proiettate dagli astronauti e dalla struttura del monolito procedono in direzioni visibilmente divergenti. Sulla Luna l''unica sorgente di luce diretta è il Sole, quindi le ombre dovrebbero essere perfettamente parallele; la divergenza rivela l''uso di molteplici proiettori di luce sul set cinematografico.', TRUE, '2026-09-16T10:00:41.399046', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(419, 85, '01:17:45', 'Errori storici o fattuali', 'Durante la partita a scacchi tra Frank Poole e il computer HAL 9000, quest''ultimo comunica a voce le mosse dicendo ''Regina in Alfiere 3'' e annunciando un checkmate forzato in due mosse. Tuttavia, guardando la disposizione dei pezzi sulla scacchiera mostrata a schermo, la mossa reale della Regina corrisponde a Alfiere 6 e Poole avrebbe avuto una mossa difensiva per evitare il matto immediato.', TRUE, '2026-09-16T10:00:41.616172', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(420, 85, '01:43:50', 'Troupe o microfoni visibili', 'Quando il braccio del pod controllato da HAL recide il tubo dell''ossigeno di Frank Poole inviandolo alla deriva nello spazio, il corpo dell''astronauta oscilla in modo innaturale. Durante la rotazione della figura nello spazio, per pochi fotogrammi sono visibili i cavi di sospensione dell''imbracatura dello stuntman illuminati dai riflettori di scena.', TRUE, '2026-09-16T10:00:41.795099', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(421, 85, '01:57:15', 'Errori di scena / Posizione', 'Nella drammatica sequenza in cui Dave Bowman si espelle dal pod d''emergenza privo di casco per rientrare nella Discovery 1, l''orientamento della valvola manuale di pressurizzazione del portello di emergenza cambia posizione in modo incoerente tra il campo largo dell''esplosione e il primo piano di Bowman che afferra i comandi.', TRUE, '2026-09-16T10:00:41.998998', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(423, 85, '02:19:30', 'Errori di scena / Posizione', 'Nella sequenza finale all''interno della stanza in stile neoclassico/vittoriano, il Dave Bowman anziano fa cadere involontariamente un bicchiere di vetro dalla tavola imbandita, frantumandolo al suolo. Nel campo lungo si vede il bicchiere rompersi a ridosso delle gambe del tavolo, ma nel dettaglio inquadrato subito dopo i cocci e la macchia di liquido si trovano a notevole distanza, vicino alla sedia.', TRUE, '2026-09-16T10:00:42.204629', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(424, 85, '00:08:45', 'Errori di scena / Posizione', 'Nella sequenza ''L''alba dell''uomo'', durante l''attacco del leopardo agli ominidi, negli occhi dell''animale si possono notare due distinti riflessi puntiformi proiettati dai proiettori di scena del set, tradendo la presenza di luci artificiali invece della sola luce solare naturale.', TRUE, '2026-09-16T10:21:59.98746', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(425, 85, '00:34:12', 'Troupe o microfoni visibili', 'Nella scena a bordo della navetta Orion in cui la hostess si muove a gravità zero per recuperare la penna fluttuante di Floyd, per un istante è visibile il dischetto di nastro biadesivo trasparente utilizzato dalla troupe per fissare la penna alle dita del guanto dell''attrice.', TRUE, '2026-09-16T10:21:59.98746', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(426, 85, '00:52:30', 'Errori di scena / Posizione', 'Durante la discesa degli astronauti nella fossa dello scavo lunare verso il monolito TMA-1, le ombre proiettate dalle tute sul terreno divergono in varie direzioni anziché essere perfettamente parallele, rivelando l''uso di molteplici punti luce da studio invece dell''unica sorgente solare.', TRUE, '2026-09-16T10:21:59.98746', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(427, 85, '01:18:05', 'Errori storici o fattuali', 'Durante l''intervista della BBC trasmessa a bordo della Discovery One, il segnale video e le risposte tra la Terra e l''astronave (in rotta verso Giove) avvengono in tempo reale senza alcun ritardo di trasmissione, ignorando le leggi della fisica che richiederebbero decine di minuti per coprire tale distanza spaziale.', TRUE, '2026-09-16T10:21:59.98746', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(428, 85, '01:24:40', 'Troupe o microfoni visibili', 'Mentre Frank Poole fa allenamento correndo all''interno della centrifuga rotante, nella parte superiore dell''inquadratura ad ampio campo è possibile scorgere per un momento l''ombra del supporto del rig della telecamera, ancorato al centro del tamburo girevole.', TRUE, '2026-09-16T10:21:59.98746', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(429, 85, '02:02:15', 'Errori di scena / Posizione', 'Nella drammatica sequenza in cui Dave Bowman rientra dall''airlock d''emergenza senza casco, l''orientamento delle leve manuali sul pannello della porta e la posizione delle targhette indicatrici cambiano tra il totale dell''esplosione e il primo piano in cui aziona i comandi.', TRUE, '2026-09-16T10:21:59.98746', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(430, 85, '02:09:50', 'Anacronismi', 'Nella stanza in stile neoclassico in cui si ritrova Bowman al termine del viaggio attraverso il wormhole, il grande orologio a pendolo presenta cifre romane disposte con un orientamento errato e un movimento delle lancette a scatto continuo tipico dei meccanismi al quarzo moderni, incongruo con un arredo d''epoca o con la manifattura settecentesca.', TRUE, '2026-09-16T10:21:59.98746', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(431, 90, '00:07:45', 'Errori di scena / Posizione', 'Mentre John Rambo addestra i cavalli nel ranch, la posizione della corda sulla recinzione cambia tra i vari piani sequenza: prima è avvolta in modo disordinato sulla trave, mentre nell''inquadratura successiva appare perfettamente arrotolata.', TRUE, '2026-09-16T10:29:42.0926', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(434, 90, '00:52:15', 'Anacronismi', 'Nella scena in cui Rambo controlla le mappe e i sistemi di sorveglianza per pianificare la sua vendetta, viene mostrata un''interfaccia digitale con icone e font grafici anacronistici, basati su mockup operativi futuri non ancora disponibili all''epoca dell''ambientazione.', TRUE, '2026-09-16T10:29:42.0926', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(435, 90, '01:04:30', 'Troupe o microfoni visibili', 'Durante l''infiltrazione notturna di Rambo nella casa di Victor Martinez, nella parte superiore dello schermo, mentre si muove lungo il corridoio d''ingresso, è visibile l''ombra del microfono a giraffa proiettata sulla parete in alto.', TRUE, '2026-09-16T10:29:42.0926', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(69, 30, '00:24:15', 'Continuity', 'Durante il teso confronto all''interno del saloon, la posizione della bandana di Bob cambia di lato e di allacciatura tra i primi piani e i campi lunghi.', TRUE, '2026-09-13T15:08:13.351775', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(511, 103, '00:52:10', 'Errori storici o fattuali', 'La collocazione geografica di Fort William Henry nel film è errata. Viene mostrato adagiato ai piedi di imponenti e ripide montagne rocciose (le Blue Ridge Mountains della Carolina del Nord, dove il film è stato effettivamente girato). Nella realtà storica, il forte sorgeva sulle sponde pianeggianti e boscose del Lago George, nello stato di New York, un paesaggio collinare molto meno aspro.', TRUE, '2026-09-16T13:02:08.462231', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(436, 90, '01:16:20', 'Errori storici o fattuali', 'Durante la sequenza dell''imboscata nei tunnel sotto il ranch, le cariche artigianali al C4 preparate da Rambo detonano con effetti e tempi di propagazione incompatibili con i sistemi di innesco a filo e cavo elettrico mostrati nel montaggio.', TRUE, '2026-09-16T10:29:42.0926', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(437, 90, '01:23:45', 'Errori di scena / Posizione', 'Nel sanguinoso scontro finale con Hugo Martinez contro la parete del fienile, la quantità di sangue sul mantello del coltello e sulle mani di Rambo varia drasticamente tra il primo piano del colpo decisivo e l''inquadratura successiva a figura intera.', TRUE, '2026-09-16T10:29:42.0926', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(438, 89, '00:14:25', 'Errori di scena / Posizione', 'Durante la scena in cui i missionari tentano di convincere Rambo ad accompagnarli lungo il fiume, il posizionamento del cappello di Michael e il livello di umidità sui capelli di Rambo cambiano visibilmente tra un''inquadratura e l''altra durante il dialogo.', TRUE, '2026-09-16T10:32:34.330245', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(439, 89, '00:23:40', 'Errori di scena / Posizione', 'Quando i pirati abbordano la barca di Rambo e quest''ultimo reagisce estraendo la pistola, la ferita da arma da fuoco sul collo del capo dei pirati cambia dimensione e quantità di sangue visibile tra il primo piano e la successiva inquadratura ad angolo largo mentre cade in acqua.', TRUE, '2026-09-16T10:32:34.330245', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(440, 89, '00:41:10', 'Errori storici o fattuali', 'Rambo trova nella giungla un ordigno inesploso risalente alla Seconda Guerra Mondiale. Le bombe di quel tipo inutilizzate per oltre sessant''anni in un clima tropicale ad alta umidità avrebbero subito un deterioramento dei componenti chimici della spoletta tale da renderle del tutto inerti o estremamente instabili al minimo tocco, rendendo irrealistico il funzionamento perfetto della trappola improvvisata.', TRUE, '2026-09-16T10:32:34.330245', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(441, 89, '00:58:15', 'Troupe o microfoni visibili', 'Durante la fuga nel bosco, nell''esplosione che investe i soldati birmani inseguitori, per un istante è chiaramente visibile il cavo di sicurezza di acciaio agganciato alla schiena dello stuntman per scaraventarlo all''indietro.', TRUE, '2026-09-16T10:32:34.330245', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(442, 89, '01:08:30', 'Errori di scena / Posizione', 'Durante la sequenza del salvataggio notturno sotto la pioggia, le macchie di fango e i segni di sangue sul viso e sulla canottiera nera di Rambo variano in modo inconsistente: in alcuni stacchi appare quasi completamente pulito, per poi tornare ricoperto di fango nell''inquadratura subito successiva.', TRUE, '2026-09-16T10:32:34.330245', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(443, 89, '01:15:45', 'Errori storici o fattuali', 'Nella battaglia finale, Rambo prende il controllo della mitragliatrice pesante calibro .50 M2 Browning montata sul camion. L''arma spara una raffica continua di centinaia di colpi senza interruzione da un unico nastro di munizioni contenuto in una scatola standard, la quale fisicamente non potrebbe contenere più di 100-200 colpi al massimo.', TRUE, '2026-09-16T10:32:34.330245', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(445, 88, '00:09:40', 'Errori storici o fattuali', 'Gli elicotteri d''attacco sovietici presentati nel film come temibili Mi-24 Hind sono in realtà elicotteri di fabbricazione francese Aérospatiale SA 330 Puma, modificati con ali alari e finti lanciamissili. Poiché i velivoli militari sovietici reali erano inaccessibili per le produzioni hollywoodiane dell''epoca a causa della Guerra Fredda, si ricorse a questo camuffamento.', TRUE, '2026-09-16T10:34:41.919862', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(446, 88, '00:15:25', 'Errori di scena / Posizione', 'Durante la sequenza iniziale del combattimento con i bastoni in Thailandia, le chiazze di sudore, sporcizia e sangue sul petto e sul volto di Rambo variano continuamente di forma, posizione e intensità tra i diversi stacchi di montaggio, rivelando che le riprese si sono svolte in giorni differenti.', TRUE, '2026-09-16T10:34:41.919862', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(447, 88, '00:42:10', 'Troupe o microfoni visibili', 'Durante l''attacco aereo delle forze sovietiche al villaggio afghano, in una ripresa dall''alto che mostra una serie di esplosioni sul terreno, è chiaramente visibile per un istante nell''angolo inferiore sinistro dello schermo un membro della troupe cinematografica con una maglietta azzurra e un treppiede.', TRUE, '2026-09-16T10:34:41.919862', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(448, 88, '01:08:15', 'Errori di scena / Posizione', 'Dopo che Rambo viene ferito da una scheggia al fianco, la posizione dello squarcio e la macchia di sangue sulla maglietta cambiano visibilmente: inizialmente la ferita sembra trovarsi quasi sulla schiena, ma nella famosa scena in cui Rambo estrae la scheggia e cauterizza la lesione con la polvere da sparo, la ferita si trova nettamente sulla parte anteriore destra dell''addome.', TRUE, '2026-09-16T10:34:41.919862', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(449, 88, '01:21:50', 'Anacronismi', 'I carri armati impiegati dalle truppe sovietiche nella base non sono modelli russi originali (come i T-62 o T-72), bensì cacciacarri inglesi FV433 Abbot e carri statunitensi M41 Walker Bulldog ridipinti e camuffati con insegne sovietiche, veicoli incompatibili con l''esercito dell''URSS negli anni ''80.', TRUE, '2026-09-16T10:34:41.919862', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(450, 88, '01:33:05', 'Troupe o microfoni visibili', 'Nella sequenza della fuga attraverso i cunicoli sotterranei della fortezza sovietica, mentre Rambo si muove vicino alle pareti rocciose, nella parte superiore dello schermo proietta un''ombra nettamente distinguibile la testa del microfono a giraffa (boom mic) che segue i dialoghi.', TRUE, '2026-09-16T10:34:41.919862', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(451, 88, '01:39:40', 'Errori di scena / Posizione', 'Nel climax dello scontro finale, Rambo guida un carro armato scontrandosi frontalmente con l''elicottero del Colonnello Zaysen. Guardando la scena al rallentatore, la palla di fuoco dell''esplosione si innesca fra le cariche pirotecniche con un paio di fotogrammi di anticipo rispetto al reale impatto fisico tra la canna del carro e il muso del velivolo.', TRUE, '2026-09-16T10:34:41.919862', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(452, 87, '00:23:45', 'Errori di scena / Posizione', 'Durante il lancio col paracadute, l''imbracatura di Rambo si impiglia e il comandante Murdock ordina di tagliare i cavi. Rambo recide la cinghia perdendo la maggior parte dell''equipaggiamento pesante. Tuttavia, una volta a terra nella giungla, possiede ancora miracolosamente l''arco composito con tutte le frecce esplosive e la custodia completa.', TRUE, '2026-09-16T10:41:21.384636', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(453, 87, '00:38:20', 'Anacronismi', 'Nelle apparecchiature di tracciamento visibili nella base americana di Murdock sono presenti schermi con grafica digitale avanzata e tecnologie di posizionamento ad alta risoluzione che risultano anacronistiche per l''epoca in cui è ambientata la vicenda.', TRUE, '2026-09-16T10:41:21.384636', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(454, 87, '00:51:10', 'Errori storici o fattuali', 'Il temibile elicottero d''attacco sovietico identificato nel film come un Mil Mi-24 Hind è in realtà un elicottero di fabbricazione francese Aérospatiale SA 330 Puma, modificato in modo evidente con l''aggiunta di ali laterali e finti lanciamissili per simulare il velivolo russo.', TRUE, '2026-09-16T10:41:21.384636', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(455, 87, '01:03:15', 'Errori di scena / Posizione', 'Durante la scena della tortura elettrica coordinata dal colonnello Podovsky, la posizione dei cavi con i morsetti applicati al corpo di Rambo cambia tra i primi piani e le inquadrature ampie. Inoltre, il cinturino in pelle sul suo polso destro appare ben affibbiato in una ripresa e completamente slacciato nel controcampo successivo.', TRUE, '2026-09-16T10:41:21.384636', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(456, 87, '01:12:30', 'Troupe o microfoni visibili', 'Quando Rambo prende il controllo dell''elicottero UH-1 Huey dalla base nemica e aziona i comandi di decollo, sul vetro curvo del parabrezza si nota chiaramente il riflesso di un pannello riflettente della troupe e la sagoma del cameraman a bordo pista.', TRUE, '2026-09-16T10:41:21.384636', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(457, 87, '01:18:05', 'Errori storici o fattuali', 'Rambo spara un colpo di lanciarazzi RPG-7 dall''interno dell''abitacolo chiuso dell''elicottero per distruggere il velivolo nemico. Nella realtà, la vampata posteriore (backblast) dell''arma all''interno di uno spazio ristretto avrebbe saturato la cabina di gas ad altissima temperatura, uccidendo gli occupanti e distruggendo la strumentazione.', TRUE, '2026-09-16T10:41:21.384636', NULL, 0, 0, 'IA (Sistema)', 'ia')
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza") VALUES
(458, 87, '01:21:40', 'Errori di scena / Posizione', 'Nella scena in cui Rambo devasta la sala di comando di Murdock sparando con la mitragliatrice M60, il nastro delle munizioni inserito nell''arma cambia lunghezza in modo incoerente: passa dall''essere quasi terminato con pochissimi proiettili a essere nuovamente lungo fino a toccare il pavimento nel secondo successivo.', TRUE, '2026-09-16T10:41:21.384636', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(459, 86, '00:12:30', 'Errori di scena / Posizione', 'Durante la scena nella stazione di polizia, quando lo sceriffo Teasle e i suoi vice arrestano Rambo e lo ammanettano, i capelli del protagonista cambiano bruscamente posizione tra le diverse inquadrature: prima sono totalmente spettinati e cadono bagnati sulla fronte, mentre nel controcampo immediato risultano ordinati e pettinati all''indietro.', TRUE, '2026-09-16T10:45:07.709217', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(460, 86, '00:23:15', 'Errori di scena / Posizione', 'Durante l''inseguimento in auto lungo la strada sterrata, quando la vettura dello sceriffo Teasle sbanda e si ribalta giù dal dirupo, si nota chiaramente la rampa di metallo montata artificialmente sotto il veicolo, usata dagli stuntman per far decollare e cappottare l''auto.', TRUE, '2026-09-16T10:45:07.709217', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(461, 86, '00:35:40', 'Troupe o microfoni visibili', 'Nella famosa sequenza in cui Rambo si lancia dalla parete rocciosa per sfuggire ai colpi di fucile sparati dall''elicottero, in un fotogramma al rallentatore mentre sbatte contro i rami degli alberi è nettamente visibile il cavo di sicurezza in acciaio collegato all''imbracatura dello stuntman.', TRUE, '2026-09-16T10:45:07.709217', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(462, 86, '00:48:10', 'Errori di scena / Posizione', 'Dopo che Rambo si ricuce la ferita al braccio con ago e filo improvvisati, la medicazione e la quantità di sangue presente sulla manica e sulla pelle variano continuamente nelle scene successive di caccia nella foresta, apparendo prima vistosamente insanguinata, poi quasi pulita e infine di nuovo coperta di sangue secco.', TRUE, '2026-09-16T10:45:07.709217', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(463, 86, '01:06:50', 'Errori storici o fattuali', 'Quando Rambo si impossessa del camion militare e recupera la mitragliatrice M60, la quantità di proiettili sparati a raffica senza mai ricaricare o sostituire il nastro supera di gran lunga la capacità fisica effettivo del nastro di cartucce agganciato all''arma.', TRUE, '2026-09-16T10:45:07.709217', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(464, 86, '01:18:25', 'Errori di scena / Posizione', 'Rambo fa esplodere la stazione di servizio per creare un diversivo in città. Subito dopo l''esplosione, il parabrezza del camion da lui guidato risulta visibilmente sfondato e ricoperto di fuliggine, ma nella sequenza immediatamente successiva in cui sfreccia lungo la via principale, il vetro appare intatto e pulito.', TRUE, '2026-09-16T10:45:07.709217', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(471, 86, '01:17:30', 'Anacronismi', 'All''interno del centralino della stazione di polizia di Hope, appare un modello di radio ricetrasmittente con display LED verde a sintesi di frequenza che non era ancora entrato in produzione nel periodo di ambientazione della pellicola.', TRUE, '2026-09-16T11:10:18.290089', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(472, 86, '01:21:15', 'Errori storici o fattuali', 'Nella sequenza finale Rambo devasta la cittadina sparando con l''M60. Il nastro di munizioni calibro 7.62mm che porta a tracolla contiene visibilmente non più di 40-50 colpi, ma l''arma spara a raffica continua per decine di secondi senza che il nastro finisca o venga ricaricato.', TRUE, '2026-09-16T11:10:18.290089', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(483, 96, '00:58:04', 'Errori di scena / Posizione', 'Mentre i due personaggi fuggono dall''Entità nel Livello 1, le impronte di fango bagnato sulla moquette gialla scompaiono completamente nel campo controcampo quando la mdp inquadra i loro piedi da un''angolazione opposta.', TRUE, '2026-09-16T11:56:08.67314', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(484, 96, '01:15:22', 'Troupe o microfoni visibili', 'Nella drammatica sequenza in cui la protagonista cerca di comunicare attraverso la parete, l''ombra del microfono a boom proiettata sulla carta da parati monotona è visibile nell''angolo superiore destro dell''inquadratura per circa tre secondi.', TRUE, '2026-09-16T11:56:08.67314', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(482, 96, '00:41:12', 'Anacronismi', 'Nella scena ambientata nel 1996, un ricercatore della A-Async consulta un dispositivo di misurazione portatile sullo sfondo che mostra un display OLED a colori a matrice attiva con interfaccia USB-C, tecnologia del tutto inesistente all''epoca.', TRUE, '2026-09-16T11:56:08.67314', NULL, 0, 1, 'IA (Sistema)', 'ia'),
(481, 96, '00:24:30', 'Troupe o microfoni visibili', 'Durante la carrellata all''indietro lungo il corridoio infinito con le luci a fluorescenza, nella copertura di plastica dell''ottavo plafone sul soffitto si nota chiaramente il riflesso dell''operatore con la Steadycam.', TRUE, '2026-09-16T11:56:08.67314', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(70, 30, '00:48:30', 'Crew & Equipment', 'Nell''angolo in alto a sinistra dell''inquadratura durante la galoppata di fuga, è chiaramente visibile l''ombra del microfono a giraffa e del braccio del fonico.', TRUE, '2026-09-13T15:08:13.445569', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(485, 96, '01:31:45', 'Errori storici o fattuali', 'Durante la spiegazione teorica del ''noclip'', il fisico fa riferimento all''ipotesi dei wormhole di Maldacena e alla corrispondenza AdS/CFT citando una pubblicazione del 1991, mentre in realtà il celebre articolo scientifico di Juan Maldacena è stato pubblicato solo alla fine del 1997.', TRUE, '2026-09-16T11:56:08.67314', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(486, 96, '01:46:10', 'Errori di scena / Posizione', 'Il taglio profondo sulla spalla sinistra della giacca di jeans del protagonista cambia lato nella scena dell''ascensore, apparendo chiaramente sulla spalla destra per tutta la durata dell''inquadratura successiva.', TRUE, '2026-09-16T11:56:08.67314', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(487, 98, '00:32:15', 'Anacronismi', 'Nelle scene in cui i soldati romani cavalcano scortando i prigionieri, si nota l''uso delle staffe agganciate alle selle. Le staffe per l''equitazione non furono introdotte nell''Impero Romano né in Europa prima di diversi secoli dopo l''epoca in cui è ambientata la vicenda.', TRUE, '2026-09-16T12:03:22.545091', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(488, 98, '00:54:40', 'Errori di scena / Posizione', 'Quando Giuda Ben-Hur si trova al remo sulla galera romana durante l''ispezione di Quinto Arrio, la posizione delle catene ai suoi polsi e la disposizione dei suoi capelli bagnati sul viso cambia in modo incoerente nel passaggio dai primi piani ai campi medi.', TRUE, '2026-09-16T12:03:22.545091', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(489, 98, '01:28:10', 'Anacronismi', 'Sulle bardature dei quattro cavalli bianchi dello Sceicco Ilderim è chiaramente mostrata la Stella di David. L''uso dell''esagramma come simbolo identitario religioso ebraico si è diffuso soltanto a partire dal Medioevo, risultando del tutto anacronistico per il I secolo d.C.', TRUE, '2026-09-16T12:03:22.545091', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(490, 98, '02:12:05', 'Anacronismi', 'In diverse inquadrature ad angolo aperto durante la celebre corsa dei carri nell''arena di Gerusalemme, sul terreno sabbioso si possono notare le trincee e le nitide impronte di battistrada lasciate dagli pneumatici della camera car impiegata per le riprese dinamiche.', TRUE, '2026-09-16T12:03:22.545091', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(491, 98, '02:24:35', 'Errori di scena / Posizione', 'Durante il duello ravvicinato tra il carro di Ben-Hur e quello di Messala, le micidiali lame dentate montate sui mozzi delle ruote del carro di Messala cambiano lunghezza, forma e stato di danneggiamento tra i controcampi consecutivi prima dell''impatto finale.', TRUE, '2026-09-16T12:03:22.545091', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(492, 98, '02:35:50', 'Errori storici o fattuali', 'Nella drammatica scena nell''infermeria dopo l''incidente di Messala, il medico parla dell''imminente amputazione delle gambe del tribuno. Nel I secolo d.C. la chirurgia romana non eseguiva amputazioni di quel livello a causa della mancanza di emostatici e anestetici efficaci, che portava a morte certa per shock o emorragia prima del termine dell''intervento.', TRUE, '2026-09-16T12:03:22.545091', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(493, 98, '03:18:20', 'Errori di scena / Posizione', 'Durante la sequenza della Crocifissione e del violento temporale finale, lo sporco di fango sul volto di Ben-Hur e il livello di inzuppamento delle sue vesti variano costantemente tra un''inquadratura in primo piano e il campo lungo successivo.', TRUE, '2026-09-16T12:03:22.545091', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(494, 102, '00:14:22', 'Anacronismi', 'Durante una delle inquadrature esterne nelle strade di Wisborg, sullo sfondo a sinistra è visibile un moderno pluviale di scolo in metallo zincato con giunzioni industriali, un dettaglio architettonico del tutto anacronistico per l''ambientazione del 1838.', TRUE, '2026-09-16T12:05:02.470094', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(495, 102, '00:38:45', 'Errori di scena / Posizione', 'Durante la cena tra Thomas Hutter e il Conte Orlok nel castello, il livello del vino nel calice di Hutter cambia vistosamente tra i cambi di inquadratura. Nel piano medio il bicchiere è quasi vuoto, ma nel primo piano successivo risulta riempito a metà, senza che nessuno abbia versato altro liquido.', TRUE, '2026-09-16T12:05:02.470094', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(496, 102, '00:52:10', 'Errori storici o fattuali', 'Nella scena dello studio in cui vengono consultati alcuni antichi testi cartografici, uno dei volumi aperti sul tavolo mostra caratteri tipografici e una rilegatura industriale tipica della fine del XIX secolo (circa 1880), incompatibile con l''anno di ambientazione della storia (1838).', TRUE, '2026-09-16T12:05:02.470094', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(497, 102, '01:12:05', 'Troupe o microfoni visibili', 'Durante la sequenza ad alto contrasto nel corridoio buio in cui Ellen cammina con una candela, l''ombra della sagoma di una telecamera montata su gimbal e la punta di un microfono a giraffa vengono proiettate brevemente sulla parete di pietra a destra, a causa del posizionamento errato delle luci di scena.', TRUE, '2026-09-16T12:05:02.470094', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(498, 102, '01:28:30', 'Errori di scena / Posizione', 'Quando la nave Empusa entra nel porto, la disposizione delle vele e delle sartiame cambia improvvisamente tra la ripresa aerea a distanza e l''inquadratura ravvicinata sul ponte. Alcune cime che prima erano visibilmente arrotolate e fissate appaiono improvvisamente sciolte e sparse sul ponte.', TRUE, '2026-09-16T12:05:02.470094', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(499, 102, '01:45:15', 'Errori storici o fattuali', 'Il microscopio in ottone utilizzato per analizzare i campioni presenta un sistema di messa a fuoco micrometrica a slitta che fu brevettato e introdotto sul mercato solo diversi decenni dopo il 1838, rendendo lo strumento scientifico storicamente inaccurato per l''epoca.', TRUE, '2026-09-16T12:05:02.470094', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(500, 102, '02:02:40', 'Errori di scena / Posizione', 'Nella drammatica scena finale nella camera da letto di Ellen, la posizione delle macchie di sangue sul colletto della sua camicia da notte cambia tra i tagli di montaggio: prima appaiono come due colate distinte sul lato sinistro, poi si fondono in un''unica grande macchia centrale nel primo piano successivo.', TRUE, '2026-09-16T12:05:02.470094', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(501, 100, '00:15:22', 'Errori di scena / Posizione', 'Durante il viaggio di Hutter verso il castello del Conte Orlok, la carrozza che lo trasporta cambia improvvisamente dettagli strutturali tra un''inquadratura e l''altra. In particolare, la disposizione delle lanterne esterne e la forma dei finimenti dei cavalli non coincidono nel passaggio dal campo lungo al piano medio.', TRUE, '2026-09-16T12:06:47.641971', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(502, 100, '00:18:45', 'Troupe o microfoni visibili', 'Durante la sequenza della carrozza fantasma che corre verso il castello, nella parte inferiore destra dell''inquadratura è possibile scorgere per un breve istante l''ombra della cinepresa a manovella e dell''operatore (Fritz Arno Wagner) proiettata sui cespugli a bordo strada a causa dell''angolazione della luce solare.', TRUE, '2026-09-16T12:06:47.641971', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(503, 100, '00:22:10', 'Errori di scena / Posizione', 'Quando Hutter scrive la lettera a sua moglie Ellen dal castello, l''inquadratura ravvicinata mostra il testo scritto con una grafia elegante e fluida. Tuttavia, nel piano medio successivo, la posizione della penna nella mano di Hutter e la porzione di foglio già compilata non corrispondono a quanto mostrato nel dettaglio precedente.', TRUE, '2026-09-16T12:06:47.641971', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(504, 100, '00:28:15', 'Errori di scena / Posizione', 'L''orologio del castello scocca la mezzanotte. Tuttavia, nell''inquadratura ravvicinata del quadrante dell''orologio ornamentale, le lancette non sono perfettamente allineate sulle ore 12:00, ma mostrano un''orario leggermente sfasato, nonostante il meccanismo a rintocchi sia in funzione.', TRUE, '2026-09-16T12:06:47.641971', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(505, 100, '00:42:30', 'Errori di scena / Posizione', 'Nelle scene in cui Ellen attende Hutter sulle dune di sabbia, si nota una forte incongruenza nella direzione del vento. Tra un''inquadratura e l''altra, i capelli di Ellen e il suo scialle ondeggiano in direzioni opposte, rivelando che le riprese sono state effettuate in giorni diversi o con ventilatori di scena posizionati diversamente.', TRUE, '2026-09-16T12:06:47.641971', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(506, 100, '00:45:12', 'Anacronismi', 'Il microscopio utilizzato dal Professor Sievers durante le sue lezioni per analizzare i polipi e le piante carnivore è un modello con fusto in ottone e regolazione micrometrica tipico della fine del XIX secolo (circa 1880-1890). Poiché il film è ambientato nel 1838, l''uso di questo specifico strumento scientifico rappresenta un anacronismo di circa cinquant''anni.', TRUE, '2026-09-16T12:06:47.641971', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(507, 100, '01:02:05', 'Errori storici o fattuali', 'Quando le bare del Conte Orlok vengono aperte e ne fuoriescono i topi che diffonderanno la peste, si può chiaramente notare che gli animali utilizzati per la scena non sono ratti delle chiaviche (Rattus norvegicus), bensì porcellini d''India (cavie domestiche) a cui sono state applicate finte code, o ratti domestici addomesticati che si muovono in modo estremamente docile e innaturale per dei vettori selvatici di epidemie.', TRUE, '2026-09-16T12:06:47.641971', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(508, 100, '01:12:40', 'Errori di scena / Posizione', 'Nella celebre sequenza in cui il Conte Orlok trasporta la propria bara attraverso le strade di Wisborg, la scena dovrebbe svolgersi nel cuore della notte o alle primissime luci dell''alba. Tuttavia, a causa delle riprese effettuate in pieno giorno (day-for-night), si proiettano sui muri degli edifici ombre cortissime, nette e intensamente definite, tipiche del sole di mezzogiorno.', TRUE, '2026-09-16T12:06:47.641971', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(512, 103, '01:12:15', 'Troupe o microfoni visibili', 'Durante la caotica scena dell''imboscata urogna ai soldati britannici che lasciano il forte, nell''angolo superiore sinistro dell''inquadratura, per una frazione di secondo, è possibile scorgere un membro della troupe cinematografica che indossa una maglietta blu e un cappellino da baseball moderno, decisamente fuori contesto.', TRUE, '2026-09-16T13:02:08.462231', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(513, 103, '01:22:40', 'Errori di scena / Posizione', 'Nella scena all''interno della grotta dietro la cascata, i capelli di Cora Munro cambiano continuamente stato: sono completamente bagnati e appiccicati al viso in un''inquadratura, per poi apparire quasi asciutti, vaporosi e perfettamente acconciati nel controcampo successivo, per poi tornare bagnati subito dopo.', TRUE, '2026-09-16T13:02:08.462231', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(514, 103, '01:31:10', 'Anacronismi', 'Durante l''inseguimento e la battaglia finale sulle scogliere, uno dei guerrieri uroni che corre sullo sfondo indossa chiaramente delle scarpe da ginnastica moderne di colore scuro con suola chiara in gomma, invece dei tradizionali mocassini di pelle dell''epoca.', TRUE, '2026-09-16T13:02:08.462231', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(515, 103, '01:42:15', 'Errori di scena / Posizione', 'Nello scontro finale tra Chingachgook e Magua, Chingachgook colpisce Magua con la sua mazza da guerra sul lato sinistro del corpo. Tuttavia, nell''inquadratura successiva che mostra l''impatto e la reazione al dolore, Magua si tiene il fianco destro, e le ferite da taglio visibili sul suo corpo cambiano posizione tra i tagli di montaggio.', TRUE, '2026-09-16T13:02:08.462231', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(516, 95, '00:14:32', 'Errori di scena / Posizione', 'Durante la scena in cui il personaggio di Cooper Koch affronta Charithra Chandran nella cucina, la tazza di caffè sul bancone cambia posizione tra i tagli di inquadratura: prima è vicina al bordo sinistro con il manico rivolto a destra, poi appare improvvisamente al centro del tavolo con il manico girato dall''altra parte.', TRUE, '2026-09-16T16:09:24.728092', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(517, 95, '00:32:15', 'Troupe o microfoni visibili', 'Nella sequenza in cui la protagonista cammina frettolosamente lungo il corridoio del suo appartamento, si può chiaramente notare l''ombra del microfono a giraffa (boom mic) proiettata sulla parete bianca in alto a destra per circa tre secondi, mentre la telecamera indietreggia.', TRUE, '2026-09-16T16:09:24.728092', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(518, 95, '00:48:50', 'Errori di scena / Posizione', 'Durante la drammatica telefonata sotto la pioggia, i capelli di Charithra Chandran appaiono completamente bagnati e incollati al viso nelle inquadrature ravvicinate, ma risultano quasi asciutti e in piega nei campi medi successivi, rivelando una mancata continuità tra i diversi ciak.', TRUE, '2026-09-16T16:09:24.728092', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(519, 95, '01:05:12', 'Errori storici o fattuali', 'Quando Cooper Koch sblocca il suo smartphone per mostrare i messaggi, l''interfaccia del sistema operativo mostra l''orario ''14:30'', ma nella scena immediatamente precedente e in quella successiva gli orologi da parete nella stanza e la luce solare esterna indicano chiaramente che si tratta di notte fonda.', TRUE, '2026-09-16T16:09:24.728092', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(520, 95, '01:18:45', 'Troupe o microfoni visibili', 'Nella scena del confronto nel soggiorno, quando la telecamera compie un movimento circolare attorno ai due attori, sul vetro della finestra sullo sfondo si riflette nitidamente la sagoma di un operatore di ripresa che indossa una maglietta scura.', TRUE, '2026-09-16T16:09:24.728092', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(521, 95, '01:29:05', 'Errori di scena / Posizione', 'Durante la colluttazione fisica sul pavimento, la ferita da taglio sulla guancia sinistra del personaggio di Cooper Koch sanguina vistosamente. Tuttavia, nell''inquadratura successiva da dietro la sua spalla, la guancia appare pulita e priva di sangue, per poi tornare a sanguinare nel primo piano finale.', TRUE, '2026-09-16T16:09:24.728092', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(522, 95, '01:35:22', 'Anacronismi', 'Nonostante il film sia ambientato nel 2026, in una scena di flashback che la didascalia dichiara essere ambientata ''dieci anni prima'' (quindi nel 2016), si vede chiaramente sullo sfondo un cartellone pubblicitario di un modello di auto elettrica commercializzato solo a partire dal 2023.', TRUE, '2026-09-16T16:09:24.728092', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(523, 104, '00:14:22', 'Errori di scena / Posizione', 'Durante il primo incontro nell''ufficio di Kevin (Will Forte) con Wile E. Coyote, la pila di cataloghi della Acme Corporation sulla scrivania cambia disposizione tra le inquadrature. Nel piano medio il catalogo del 1996 è in cima, ma nel primo piano successivo si vede chiaramente l''edizione del 2004, per poi ritornare a quella del 1996 nell''inquadratura larga.', TRUE, '2026-09-16T16:28:52.963282', NULL, 0, 0, 'IA (Sistema)', 'ia')
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza") VALUES
(524, 104, '00:32:45', 'Troupe o microfoni visibili', 'Durante l''arringa iniziale dell''avvocato della Acme (interpretato da John Cena), mentre la telecamera effettua una panoramica verso sinistra, sul pannello di legno lucido alle spalle del giudice si riflette chiaramente per pochi secondi la sagoma di un microfono a giraffa (boom mic) e la testa dell''operatore.', TRUE, '2026-09-16T16:28:52.963282', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1023, 231, '00:58:15', 'Errori di scena / Posizione', 'Durante la sequenza delle trappole nello scantinato, la posizione e l''altezza del barattolo sospeso cambiano visibilmente tra il totale dell''ambiente e il primo piano del ladro che cerca di schivarlo.', TRUE, '2026-10-24T15:36:29.469711', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(525, 104, '00:48:10', 'Errori storici o fattuali', 'Nella sequenza di flashback che illustra l''incidente dei pattini a razzo Acme, datata esplicitamente ''Ottobre 1982'', sulla scatola del prodotto è stampato un codice a barre QR e l''indirizzo web ''www.acme-corp.com/warning''. Nel 1982 né i codici QR né il World Wide Web erano ancora stati inventati o commercializzati.', TRUE, '2026-09-16T16:28:52.963282', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(526, 104, '00:55:12', 'Troupe o microfoni visibili', 'Nella scena all''aperto nel deserto in cui Kevin parla con Wile E. Coyote vicino a un cartellone pubblicitario, l''ombra di una gru cinematografica con relativa telecamera è chiaramente visibile sulla sabbia nell''angolo inferiore destro dello schermo durante un movimento di camera a scendere.', TRUE, '2026-09-16T16:28:52.963282', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(527, 104, '01:02:15', 'Errori di scena / Posizione', 'Mentre il personaggio di Lana Condor esamina i progetti del magnete gigante Acme, tiene una penna rossa nella mano destra. Nell''inquadratura ravvicinata sul progetto, la mano stringe improvvisamente un evidenziatore blu, per poi tornare a mostrare la penna rossa nel controcampo successivo.', TRUE, '2026-09-16T16:28:52.963282', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(528, 104, '01:18:30', 'Errori storici o fattuali', 'Durante la testimonianza dell''esperto sulla pistola disintegratrice Acme, la formula chimica scritta sulla lavagna dell''aula di tribunale per spiegare la reazione della polvere disintegrante presenta un errore grossolano: la formula dell''acqua viene scritta come ''HO2'' invece di ''H2O'', nonostante lo scienziato la definisca correttamente a voce ''monossido di diidrogeno''.', TRUE, '2026-09-16T16:28:52.963282', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(529, 104, '01:29:05', 'Errori di scena / Posizione', 'Durante la dimostrazione finale in aula con la fionda gigante Acme, la fasciatura sull''orecchio di Wile E. Coyote cambia lato. Nelle inquadrature frontali la benda è posizionata sull''orecchio sinistro, mentre nei raccordi da dietro (alle spalle della giuria) la fasciatura appare sull''orecchio destro.', TRUE, '2026-09-16T16:28:52.963282', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(530, 104, '00:14:22', 'Errori di scena / Posizione', 'Durante la scena nell''ufficio dell''avvocato Kevin Clay, quando Wile E. Coyote mostra i faldoni dei brevetti difettosi ACME, la pila di documenti sul tavolo cambia altezza e disposizione tra i cambi di inquadratura. Inizialmente ci sono tre raccoglitori blu in cima, che diventano due rossi nel primo piano successivo.', TRUE, '2026-09-16T16:46:40.944956', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(550, 109, '01:19:40', 'Errori di scena / Posizione', 'Durante la folle corsa a bordo del fuoristrada Land Rover attraverso la vegetazione, il veicolo subisce gravi danni al parabrezza e alla carrozzeria laterale dopo un ribaltamento. Nell''inquadratura immediatamente successiva, il parabrezza torna ad essere intatto e privo di crepe.', TRUE, '2026-09-17T12:48:04.037056', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(531, 104, '00:22:10', 'Anacronismi', 'Sullo sfondo dell''ufficio postale da cui Wile E. Coyote ritira i pacchi ACME, è visibile un poster promozionale del servizio postale statunitense (USPS) che mostra il logo moderno introdotto solo nel 1993, nonostante la scena cerchi di ricreare un''atmosfera vintage da ufficio postale rurale degli anni ''70/''80 con vecchi schedari e arredi d''epoca.', TRUE, '2026-09-16T16:46:40.944956', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(532, 104, '00:32:15', 'Errori storici o fattuali', 'Nella scena del tribunale, viene citato il ''Federal Tort Claims Act'' come base legale per la giurisdizione contro una multinazionale privata come la ACME Corporation. Tuttavia, tale legge si applica esclusivamente alle richieste di risarcimento danni contro il governo federale degli Stati Uniti, non contro entità commerciali private.', TRUE, '2026-09-16T16:46:40.944956', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(533, 104, '00:45:10', 'Troupe o microfoni visibili', 'Durante l''inseguimento nel deserto del New Mexico, quando la telecamera esegue una panoramica rapida dal basso verso l''alto per seguire il volo di un razzo ACME difettoso, nell''angolo inferiore destro dello schermo è visibile per pochi fotogrammi l''ombra del braccio meccanico della telecamera (technocrane) riflessa sulla superficie lucida di una roccia.', TRUE, '2026-09-16T16:46:40.944956', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(534, 104, '00:58:35', 'Anacronismi', 'Nella sequenza flashback ambientata negli anni ''60 che mostra la fondazione di una delle sussidiarie della ACME, si vede un personaggio utilizzare una calcolatrice scientifica tascabile a cristalli liquidi (LCD). Le calcolatrici LCD commerciali non sono apparse sul mercato prima della metà degli anni ''70.', TRUE, '2026-09-16T16:46:40.944956', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(535, 104, '01:03:18', 'Troupe o microfoni visibili', 'Nella scena in cui l''avvocato difensore della ACME cammina lungo il corridoio del tribunale parlando ai giornalisti, si può notare nella riflessione delle porte a vetri sullo sfondo la sagoma di un fonico di linea che regge un microfono a giraffa (boom mic), parzialmente coperto da un pannello riflettente.', TRUE, '2026-09-16T16:46:40.944956', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(536, 104, '01:12:05', 'Errori di scena / Posizione', 'Durante la testimonianza di Road Runner (Beep Beep), il bicchiere d''acqua posto sul banco dei testimoni è inizialmente pieno a metà. Quando l''inquadratura si sposta su Wile E. Coyote e poi torna su Road Runner, il bicchiere è completamente vuoto, per poi tornare parzialmente pieno nell''inquadratura finale della scena, senza che nessuno lo abbia toccato.', TRUE, '2026-09-16T16:46:40.944956', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(537, 104, '01:21:40', 'Errori storici o fattuali', 'Nel cartello stradale visibile sullo sfondo durante la scena del viaggio verso il quartier generale della ACME, viene indicata la distanza per Albuquerque in ''chilometri'' anziché in ''miglia''. Trattandosi di una strada statale del New Mexico (USA), la segnaletica ufficiale utilizza esclusivamente il sistema imperiale.', TRUE, '2026-09-16T16:46:40.944956', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(538, 108, '00:14:32', 'Errori di scena / Posizione', 'Durante la discussione in cucina tra il personaggio interpretato da Anne Hathaway e quello di Ewan McGregor, il bicchiere d''acqua sul tavolo passa dall''essere quasi vuoto nel campo largo a essere completamente pieno nel controcampo, senza che nessuno si sia avvicinato alla caraffa.', TRUE, '2026-09-17T11:16:35.811481', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(539, 108, '00:32:15', 'Troupe o microfoni visibili', 'Nella scena notturna in cui la macchina da presa compie una rapida panoramica lungo il porticato della casa su Oak Street, sul vetro laterale del SUV scuro parcheggiato nel vialetto si nota chiaramente il riflesso del fonico con il microfono panoramico (boom).', TRUE, '2026-09-17T11:16:35.811481', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(540, 108, '00:54:10', 'Errori storici o fattuali', 'Quando il personaggio di Ewan McGregor analizza il tracciato delle frequenze al computer, l''interfaccia mostra un sistema di coordinate geografiche con valori di latitudine superiori a 90 gradi (94° 12'' N), un errore concettuale impossibile per qualsiasi sistema di navigazione reale.', TRUE, '2026-09-17T11:16:35.811481', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(704, 63, '00:35:10', 'Anacronismi', 'Nella sala del banchetto del castello, la struttura degli archi gotici e i dettagli delle vetrate mostrano elementi stilistici tipici del XIV secolo, anacronistici per l''ambientazione storica della Terza Crociata (1190 circa).', TRUE, '2026-09-25T19:09:14.246576', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(49, 15, '00:28:45', 'Continuity', 'Quando Bianca e Bernie salgono sull''albatros Orville, le cinghie del bagaglio di Bernie cambiano colore da marrone a verde tra due inquadrature consecutive.', TRUE, '2026-09-13T14:58:31.724666', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(541, 108, '01:12:45', 'Errori di scena / Posizione', 'Mentre Anne Hathaway corre verso il garage per aprirne la basculante, la sua giacca di pelle è completamente chiusa fino al collo. Nell''inquadratura immediatamente successiva dall''interno del garage, la giacca è completamente sbottonata ed aperta.', TRUE, '2026-09-17T11:16:35.811481', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(543, 108, '01:51:22', 'Troupe o microfoni visibili', 'Durante il momento di massima tensione lungo il viale alberato, l''inquadratura dall''alto verso il basso rivela l''ombra proiettata sull''asfalto della camera rig con lo stabilizzatore e l''operatore che segue gli attori.', TRUE, '2026-09-17T11:16:35.811481', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(544, 108, '02:08:40', 'Errori di scena / Posizione', 'Dopo il ferimento nello scontro finale, il personaggio di Anne Hathaway presenta un evidente taglio insanguinato sulla guancia sinistra. Nella scena successiva all''interno dell''ambulanza, la medicazione e la ferita si trovano sulla guancia destra.', TRUE, '2026-09-17T11:16:35.811481', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(545, 109, '00:04:15', 'Errori di scena / Posizione', 'Nella sequenza d''apertura sulle montagne dell''Himalaya, quando Ace tenta disperatamente di salvare il procione sospeso nel vuoto, la quantità di neve fresca accumulata sulle sue spalle e sul collo del giubbotto varia costantemente ad ogni cambio di inquadratura tra i primi piani e i campi larghi.', TRUE, '2026-09-17T12:48:04.037056', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(546, 109, '00:22:10', 'Troupe o microfoni visibili', 'Durante il ricevimento formale alla residenza del console Vincent Cadby, mentre Ace si muove tra gli ospiti infastidendo l''uomo vestito da mascotte del Monopoly, nella parte superiore dell''inquadratura è visibile l''ombra del microfono a giraffa (boom mic) rifratta sulla parete dello sfondo.', TRUE, '2026-09-17T12:48:04.037056', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(547, 109, '00:38:45', 'Errori di scena / Posizione', 'Durante la prova di coraggio al villaggio Wachati, Ace viene colpito alle cosce da due freccette avvelenate sparate con una cerbottana. L''inclinazione e la distanza reciproca delle due freccette piantate sulle sue gambe cambiano nettamente quando la ripresa passa dal primo piano alla visuale frontale mentre prova a camminare.', TRUE, '2026-09-17T12:48:04.037056', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(548, 109, '00:52:30', 'Errori di scena / Posizione', 'Nella celebre scena in cui Ace rimane bloccato all''interno del rinoceronte meccanico ed è costretto a uscire dal posteriore dell''animale, la quantità di sostanza vischiosa e sudore artificiale sul suo viso e sul corpo varia visibilmente tra il momento del contorcimento interno e l''uscita completa sul terreno.', TRUE, '2026-09-17T12:48:04.037056', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(549, 109, '01:08:15', 'Errori storici o fattuali', 'Nel santuario degli animali e nelle aree circostanti della giungla africana compaiono diverse specie animali completamente estranee alla fauna del continente africano, tra cui capibara e ara macao, tipici invece dell''America meridionale.', TRUE, '2026-09-17T12:48:04.037056', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(551, 109, '01:25:50', 'Anacronismi', 'Durante lo scontro finale tra le tribù Wachati e Wachootoo, viene impiegato un dispositivo di proiezione di diapositive perfettamente funzionante e ad alta luminosità nel mezzo della giungla incontaminata, in assenza totale di qualsiasi generatore o fonte di alimentazione elettrica visibile.', TRUE, '2026-09-17T12:48:04.037056', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(552, 110, '00:15:30', 'Anacronismi', 'L''uso del kilt (philibeg o belted plaid) da parte di William Wallace e dei clan scozzesi è un evidente anacronismo. Questo tipo di abbigliamento fu introdotto in Scozia solo a partire dal XVI-XVII secolo, mentre le vicende del film si svolgono alla fine del XIII secolo (circa 1297). All''epoca i guerrieri scozzesi indossavano tuniche gialle zafferano (leine) o semplici camicie di lana e armature di cuoio.', TRUE, '2026-09-17T13:04:39.959953', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(553, 110, '01:08:15', 'Errori storici o fattuali', 'La celebre ''Battaglia di Stirling Bridge'' viene combattuta nel film su una vasta pianura erbosa senza che si veda alcuna traccia del ponte (''bridge'') che dà il nome allo scontro. Storicamente, il ponte di legno fu l''elemento tattico cruciale che permise agli scozzesi di intrappolare e sconfiggere l''esercito inglese che lo stava attraversando. Il regista Mel Gibson decise di escluderlo per facilitare le riprese delle cariche di cavalleria.', TRUE, '2026-09-17T13:04:39.959953', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(554, 110, '01:11:50', 'Errori di scena / Posizione', 'Durante lo scontro ravvicinato a Stirling, quando un soldato scozzese colpisce un cavaliere inglese con un''ascia da battaglia, l''arma si piega visibilmente in modo innaturale come se fosse di gomma flessibile, rivelando la natura di ''prop'' di sicurezza utilizzato dagli stuntman per evitare infortuni sul set.', TRUE, '2026-09-17T13:04:39.959953', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(555, 110, '01:14:05', 'Errori di scena / Posizione', 'Durante i vari tagli di inquadratura della battaglia di Stirling, la pittura facciale blu (woad) sul volto di William Wallace cambia continuamente forma, densità e livello di sbavatura. In alcune inquadrature ravvicinate copre perfettamente metà del viso, mentre in quelle immediatamente successive appare sbiadita o con pattern leggermente diversi, rivelando molteplici sessioni di trucco tra i ciak.', TRUE, '2026-09-17T13:04:39.959953', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(556, 110, '01:22:10', 'Errori storici o fattuali', 'La principessa Isabella di Francia, interpretata da Sophie Marceau, viene mostrata come una donna adulta che ha una relazione romantica con William Wallace. Nella realtà storica, all''epoca della battaglia di Falkirk (1298), Isabella aveva circa tre anni e viveva in Francia. Sposò Edoardo II solo nel 1308, tre anni dopo la morte di Wallace, rendendo la loro storia d''amore e la gravidanza di lei storicamente impossibili.', TRUE, '2026-09-17T13:04:39.959953', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(557, 110, '01:28:45', 'Troupe o microfoni visibili', 'Durante la concitata sequenza della battaglia di Stirling, sullo sfondo dietro i cavalieri inglesi in carica, è possibile scorgere per una frazione di secondo un veicolo moderno di colore bianco (un furgone o un''automobile della troupe) parcheggiato tra gli alberi.', TRUE, '2026-09-17T13:04:39.959953', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(558, 110, '01:42:30', 'Troupe o microfoni visibili', 'In una scena di scontro ravvicinato tra scozzesi e inglesi, nell''angolo sinistro dell''inquadratura si può notare brevemente un membro della troupe cinematografica che indossa un cappellino da baseball moderno e una giacca blu, chiaramente fuori contesto rispetto ai costumi medievali dei figuranti.', TRUE, '2026-09-17T13:04:39.959953', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(559, 112, '00:04:15', 'Errori di scena / Posizione', 'Durante la sequenza dell''incidente d''auto iniziale, il telefono cellulare di Michelle vola via dal cruscotto. Nei fotogrammi successivi, la posizione del telefono sul tappetino e lo stato dello schermo (che passa da crepato a completamente integro tra un''inquadratura e l''altra) mostrano una chiara discrepanza di montaggio.', TRUE, '2026-09-17T16:01:00.029488', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(66, 27, '00:58:20', 'Crew & Equipment', 'Sulle corazze metalliche e lucide dei soldati romani si rispecchiano le luci dei riflettori del set cinematografico.', TRUE, '2026-09-13T15:01:46.488694', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(560, 112, '00:09:30', 'Errori di scena / Posizione', 'Quando Michelle si sveglia per la prima volta incatenata al muro del bunker, la flebo inserita nel suo braccio cambia posizione. Nelle inquadrature ravvicinate l''ago è fissato con un cerotto bianco inclinato, mentre nei campi medi il cerotto è dritto e posizionato più in alto sul braccio.', TRUE, '2026-09-17T16:01:00.029488', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(561, 112, '00:15:45', 'Errori storici o fattuali', 'Howard mostra a Michelle che non c''è segnale cellulare nel bunker sotterraneo a causa della profondità e della schermatura in cemento armato. Tuttavia, poco dopo, quando Michelle tenta di usare il telefono vicino alla botola, riceve brevemente una notifica di rete. Fisicamente, una schermatura del genere bloccherebbe completamente qualsiasi ponte radio senza ripetitori interni, rendendo impossibile anche una ricezione intermittente a quella profondità.', TRUE, '2026-09-17T16:01:00.029488', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(562, 112, '00:28:40', 'Errori di scena / Posizione', 'La ferita sul lato sinistro della fronte di Michelle, causata dall''incidente stradale, cambia costantemente aspetto. In alcune scene all''interno del bunker appare come un taglio profondo e sanguinante, mentre in altre sequenze ambientate nello stesso giorno appare già quasi completamente cicatrizzata e di dimensioni ridotte, per poi tornare vistosa successivamente.', TRUE, '2026-09-17T16:01:00.029488', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(616, 117, '01:42:30', 'Errori di scena / Posizione', 'Durante la recita teatrale di Neil Perry nel ruolo di Puck, la corona di rami e foglie che porta sul capo cambia inclinazione e altezza sulla fronte tra i primi piani stretti e le inquadrature più larghe sul palco.', TRUE, '2026-09-18T06:40:36.627653', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(563, 112, '00:42:10', 'Errori di scena / Posizione', 'Durante la scena in cui Michelle, Howard ed Emmett giocano a un gioco da tavolo e completano un puzzle, la disposizione dei pezzi sul tavolo cambia drasticamente tra i cambi di inquadratura. In un fotogramma il puzzle è quasi completato sul lato sinistro, mentre nell''inquadratura successiva i pezzi sono sparsi in modo diverso.', TRUE, '2026-09-17T16:01:00.029488', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(564, 112, '00:55:18', 'Troupe o microfoni visibili', 'Nella scena in cui Michelle sale sulla sedia per raggiungere il condotto dell''aria, sul riflesso della superficie metallica lucida del pannello di ventilazione adiacente è possibile scorgere per un breve istante la sagoma di un operatore della troupe con una telecamera e parte del pannello riflettente utilizzato per l''illuminazione.', TRUE, '2026-09-17T16:01:00.029488', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(565, 112, '01:18:30', 'Errori storici o fattuali', 'La tuta protettiva improvvisata che Michelle costruisce usando una tenda da doccia, nastro adesivo e una bottiglia di plastica non potrebbe mai garantire una tenuta stagna contro gas tossici o agenti biologici. Inoltre, il filtro creato con la bottiglia non presenta alcuna valvola di espirazione o materiale filtrante attivo (come il carbone attivo), rendendo la respirazione impossibile o del tutto inefficace contro l''atmosfera contaminata descritta.', TRUE, '2026-09-17T16:01:00.029488', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(566, 112, '01:32:15', 'Errori di scena / Posizione', 'Durante lo scontro finale con la nave aliena, Michelle lancia una bottiglia incendiaria improvvisata nella bocca della creatura/astronave. Tra l''inquadratura del lancio e quella dell''esplosione, la distanza tra Michelle e il veicolo alieno raddoppia inspiegabilmente, e la posizione del camion dietro cui si nasconde cambia orientamento rispetto alla traiettoria d''attacco dell''alieno.', TRUE, '2026-09-17T16:01:00.029488', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(567, 114, '00:02:15', 'Errori storici o fattuali', 'All''inizio del film, Drugo (The Dude) compila un assegno da 69 centesimi datato 11 settembre 1991. Sullo sfondo, la televisione trasmette il celebre discorso di George H.W. Bush ''This will not stand'' riguardo all''invasione del Kuwait. Tuttavia, quel discorso televisivo è stato pronunciato storicamente il 5 agosto 1990, creando un''incongruenza temporale di oltre un anno rispetto alla data dell''assegno.', TRUE, '2026-09-17T16:07:04.999935', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(568, 114, '00:11:15', 'Errori di scena / Posizione', 'Nella scena in cui Bunny Lebowski mostra i suoi piedi con lo smalto verde a Drugo vicino alla piscina, la posizione delle sue gambe e l''asciugamano su cui è sdraiata cambiano visibilmente tra le inquadrature strette e quelle larghe, rivelando una discontinuità nella postura dell''attrice Tara Reid durante le diverse riprese.', TRUE, '2026-09-17T16:07:04.999935', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(569, 114, '00:15:40', 'Anacronismi', 'Sebbene il film sia ambientato esplicitamente nel 1991, all''interno della sala da bowling si possono notare in diverse scene dei monitor per il punteggio automatico e dei loghi commerciali della Brunswick che sono stati introdotti sul mercato solo a metà degli anni ''90, diversi anni dopo il periodo in cui si svolge la narrazione.', TRUE, '2026-09-17T16:07:04.999935', NULL, 0, 0, 'IA (Sistema)', 'ia')
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza") VALUES
(570, 114, '00:42:10', 'Errori di scena / Posizione', 'Durante la fallimentare consegna del riscatto, Walter lancia la borsa civetta fuori dal finestrino della Ford Torino di Drugo. Nelle inquadrature dall''interno dell''auto il finestrino del passeggero è chiaramente spalancato per permettere il lancio, ma nell''inquadratura esterna immediatamente successiva, un attimo prima del lancio, il vetro appare completamente sollevato.', TRUE, '2026-09-17T16:07:04.999935', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(571, 114, '00:51:30', 'Troupe o microfoni visibili', 'Nella celebre sequenza in cui Drugo cerca di spegnere lo spinello che gli è caduto sul cavallo dei pantaloni e finisce per schiantarsi contro un cassonetto, per una frazione di secondo sul riflesso del finestrino laterale sinistro della Ford Torino è possibile scorgere la sagoma della telecamera montata sul braccio mobile (camera rig) e di un operatore della troupe posizionato a bordo strada.', TRUE, '2026-09-17T16:07:04.999935', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(572, 114, '00:56:45', 'Errori di scena / Posizione', 'Durante il primo incontro ravvicinato tra Drugo e Maude Lebowski nel suo studio d''arte, il livello del White Russian nel bicchiere di Drugo oscilla vistosamente. Il bicchiere passa dall''essere quasi vuoto a essere nuovamente pieno a metà tra un controcampo e l''altro, senza che Drugo abbia avuto il tempo materiale di versare altro latte o liquore.', TRUE, '2026-09-17T16:07:04.999935', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(573, 114, '01:18:25', 'Errori di scena / Posizione', 'Quando Walter distrugge a colpi di mazzetta la Corvette rossa credendo appartenga al giovane Larry Sellers, i danni sul parabrezza e sulla carrozzeria cambiano configurazione tra i primi piani e i campi medi. Inoltre, il sistema di allarme dell''auto inizia a suonare una frazione di secondo prima che la mazzetta di Walter colpisca effettivamente il cofano per la prima volta.', TRUE, '2026-09-17T16:07:04.999935', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(705, 63, '00:52:15', 'Troupe o microfoni visibili', 'Nella sequenza dell''agguato nella foresta di Sherwood, mentre Douglas Fairbanks esegue un''acrobazia arrampicandosi rapidamente su un grande albero, è chiaramente visibile il cavo di sicurezza in metallo teso sopra di lui.', TRUE, '2026-09-25T19:09:14.246576', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(574, 111, '00:22:30', 'Errori di scena / Posizione', 'All''inizio del film, quando Rose osserva il Titanic dal molo prima di imbarcarsi, il neo sulla sua guancia è chiaramente visibile sul lato sinistro del viso. Tuttavia, in diverse inquadrature successive all''interno della nave, il neo appare sul lato destro. Questo è dovuto al fatto che alcune inquadrature sono state specchiate in post-produzione per esigenze di montaggio e composizione visiva.', TRUE, '2026-09-17T16:13:06.376545', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(575, 111, '00:48:15', 'Anacronismi', 'Jack racconta a Rose di essere andato a pescare con suo padre sul lago Wissota, nel Wisconsin. Tuttavia, il lago Wissota è un bacino artificiale creato dalla costruzione di una diga, i cui lavori sono iniziati nel 1915 e completati nel 1917, ovvero diversi anni dopo il naufragio del Titanic avvenuto nell''aprile del 1912.', TRUE, '2026-09-17T16:13:06.376545', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(576, 111, '00:55:10', 'Troupe o microfoni visibili', 'Quando Jack, indossando l''abito da sera elegante, fa il suo ingresso nel salone di prima classe per partecipare alla cena formale, il riflesso di una telecamera di ripresa e di un membro della troupe è chiaramente visibile sulla superficie di vetro scuro e lucido di una delle porte che vengono aperte per accoglierlo.', TRUE, '2026-09-17T16:13:06.376545', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(577, 111, '01:15:35', 'Errori di scena / Posizione', 'Durante la celebre scena del ritratto in cui Rose posa per Jack, la punta della matita a carboncino di Jack si spezza visibilmente con un rumore netto mentre traccia una linea d''ombra. Nell''inquadratura immediatamente successiva, senza che il ragazzo abbia il tempo di temperarla o sostituirla, la punta della matita torna a essere perfettamente integra e affilata.', TRUE, '2026-09-17T16:13:06.376545', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(578, 111, '01:21:40', 'Anacronismi', 'Jack promette a Rose che la porterà sulle montagne russe del molo di Santa Monica, dove saliranno fino a farsi venire la nausea. Tuttavia, il parco divertimenti sul molo di Santa Monica e le sue famose montagne russe non furono costruiti e aperti al pubblico prima del 1916, rendendo questo dialogo storicamente incoerente con l''anno 1912.', TRUE, '2026-09-17T16:13:06.376545', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(579, 111, '02:12:05', 'Errori di scena / Posizione', 'Nella scena in cui Rose cerca di liberare Jack dalle manette nei corridoi allagati, decide di usare una scure d''emergenza. Quando colpisce il vetro della bacheca protettiva, lo manda completamente in frantumi liberando la cornice. Nell''inquadratura successiva, mentre infila la mano per afferrare la scure, gran parte dei frammenti di vetro è riapparsa miracolosamente incastrata nei bordi della bacheca.', TRUE, '2026-09-17T16:13:06.376545', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(580, 111, '02:46:30', 'Errori storici o fattuali', 'Mentre Rose fluttua sulla porta di legno nell''oceano gelido e guarda verso l''alto in attesa dei soccorsi, la volta celeste mostra una disposizione delle stelle del tutto casuale e simmetrica. Come evidenziato dall''astrofisico Neil deGrasse Tyson, la mappa stellare mostrata è scientificamente errata e non corrisponde al vero cielo notturno visibile nel Nord Atlantico il 15 aprile 1912 alle ore 04:20.', TRUE, '2026-09-17T16:13:06.376545', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(683, 111, '00:58:20', 'Troupe o microfoni visibili', 'Mentre Jack e Rose fuggono ridendo lungo i corridoi della prima classe per scappare dal maggiordomo Lovejoy, l''ombra della telecamera e dell''operatore che si muove su un carrello è chiaramente visibile per una frazione di secondo sulle superfici di legno lucido delle porte e sui pannelli dorati della parete di destra.', TRUE, '2026-09-21T20:46:10.325971', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(684, 111, '01:02:15', 'Errori di scena / Posizione', 'Durante la scena sul ponte di comando in cui al Capitano Smith viene servita una tazza di tè, lo si vede chiaramente girare lo zucchero con un cucchiaino. Nell''inquadratura immediatamente successiva, il cucchiaino scompare del tutto sia dalla tazza che dal piattino, e le mani del capitano si trovano in una posizione completamente diversa senza che ci sia stato il tempo fisico per posarlo.', TRUE, '2026-09-21T20:46:10.325971', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(680, 136, '02:14:40', 'Errori di scena / Posizione', 'Negli ultimi convulsi momenti della battaglia del Little Bighorn, il cappello a tesa larga di Custer cade a terra tra la polvere, ma nel controcampo successivo torna ad essere indossato in testa dal protagonista.', TRUE, '2026-09-21T20:36:15.565218', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(686, 111, '01:40:40', 'Errori storici o fattuali', 'Al momento della collisione con l''iceberg, si vedono grandi blocchi di ghiaccio compatti e geometrici cadere sul ponte di passeggiata della nave. Secondo le testimonianze storiche dei passeggeri superstiti che si trovavano sul ponte in quel momento, il ghiaccio caduto non era affatto composto da massi solidi, bensì da una miriade di piccoli frammenti e ghiaccio tritato finissimo, simile a neve pressata.', TRUE, '2026-09-21T20:46:10.325971', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(687, 111, '02:40:15', 'Errori di scena / Posizione', 'Quando la poppa del Titanic si solleva quasi verticalmente prima del collasso finale, Jack e Rose si aggrappano alla ringhiera di sicurezza. La distanza tra i montanti metallici della ringhiera varia vistosamente: nelle inquadrature ravvicinate i montanti sono molto distanziati per permettere agli attori di posizionarsi, mentre nei campi lunghi digitali la ringhiera appare molto più fitta e con dettagli geometrici differenti.', TRUE, '2026-09-21T20:46:10.325971', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(688, 111, '02:51:10', 'Anacronismi', 'Durante le drammatiche ricerche dei superstiti nell''acqua gelida, l''ufficiale Harold Lowe e i marinai utilizzano delle torce elettriche portatili che emettono un fascio di luce bianca estremamente potente, nitido e focalizzato, tipico delle moderne lampadine alogene o a LED. Nel 1912, le torce elettriche erano dispositivi rudimentali che emettevano una luce giallastra, fioca e diffusa, e le cui batterie al carbonio-zinco si esaurivano nel giro di pochissimi minuti.', TRUE, '2026-09-21T20:46:10.325971', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(581, 115, '00:21:15', 'Errori di scena / Posizione', 'Nella scena dell''appartamento di Brett, quando il quarto uomo esce improvvisamente dal bagno sparando all''impazzata contro Jules e Vincent, i fori dei proiettili sulla parete alle spalle dei due protagonisti sono chiaramente visibili ancor prima che l''uomo inizi a sparare.', TRUE, '2026-09-17T17:53:41.748245', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(582, 115, '00:36:45', 'Errori di scena / Posizione', 'Durante la cena al Jack Rabbit Slim''s, la sigaretta di Mia Wallace (Uma Thurman) cambia continuamente mano e lunghezza tra un''inquadratura e l''altra. In alcuni stacchi ravvicinati è quasi consumata, mentre nel totale successivo appare molto più lunga.', TRUE, '2026-09-17T17:53:41.748245', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(583, 115, '00:47:30', 'Errori di scena / Posizione', 'Nella drammatica scena dell''overdose, Vincent traccia un punto rosso con un pennarello sul petto di Mia per mirare con la siringa di adrenalina. Nell''inquadratura immediatamente successiva, ravvicinata sul petto prima dell''iniezione, il segno rosso scompare completamente, per poi riapparire diverso subito dopo.', TRUE, '2026-09-17T17:53:41.748245', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(584, 115, '01:11:40', 'Anacronismi', 'Durante la fuga di Butch in taxi dopo l''incontro di boxe, lo sfondo visibile oltre i finestrini della vettura guidata da Esmeralda Villalobos è una proiezione in bianco e nero che mostra automobili e strade degli anni ''40 e ''50, creando un evidente anacronismo con l''ambientazione anni ''90 del film.', TRUE, '2026-09-17T17:53:41.748245', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(585, 115, '01:24:30', 'Troupe o microfoni visibili', 'Quando Butch è fermo al semaforo a bordo della Honda Civic bianca e nota Marsellus Wallace attraversare la strada con i cartoni della colazione, nel riflesso del finestrino laterale dell''auto è chiaramente visibile la sagoma della cinepresa e di un operatore della troupe.', TRUE, '2026-09-17T17:53:41.748245', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(586, 115, '01:41:50', 'Errori di scena / Posizione', 'Dopo che Vincent spara accidentalmente in testa a Marvin all''interno della Chevy Nova, lo stato del finestrino posteriore destro cambia continuamente: in alcune inquadrature è completamente frantumato e mancante, mentre in altre si vedono ancora grossi frammenti di vetro sporchi di sangue attaccati alla guarnizione.', TRUE, '2026-09-17T17:53:41.748245', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(587, 115, '01:46:20', 'Errori di scena / Posizione', 'Durante la gestione dell''emergenza a casa di Jimmie, l''orologio da cucina mostra un''incongruenza temporale. Mentre Winston Wolf dichiara che mancano pochissimi minuti all''arrivo di Bonnie (previsto per le 09:30) e la tensione sale, l''orologio da parete sullo sfondo mostra le 08:15 in un''inquadratura e le 07:40 in quella successiva.', TRUE, '2026-09-17T17:53:41.748245', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(588, 115, '00:41:15', 'Errori di scena / Posizione', 'Nella celebre scena dell''appartamento di Brett, prima ancora che il quarto uomo esca dal bagno sparando all''impazzata contro Jules e Vincent, i fori dei proiettili sono già chiaramente visibili sulla parete alle spalle dei due protagonisti.', TRUE, '2026-09-17T18:00:05.719359', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(589, 115, '00:47:30', 'Errori di scena / Posizione', 'Prima di somministrare l''iniezione di adrenalina a Mia in overdose, Vincent traccia un cerchio rosso con un pennarello sul petto della donna per mirare al cuore. Subito dopo la miracolosa rianimazione, quando Mia si rialza ansimando, il segno rosso sul petto è completamente scomparso.', TRUE, '2026-09-17T18:00:05.719359', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(590, 115, '01:22:10', 'Troupe o microfoni visibili', 'Durante la drammatica scena nel seminterrato del banco dei pegni, quando Butch e Marsellus sono tenuti prigionieri, è possibile scorgere il riflesso di un operatore di ripresa con la telecamera sulla superficie lucida di una delle vetrinette sullo sfondo.', TRUE, '2026-09-17T18:00:05.719359', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(661, 129, '01:12:10', 'Errori di scena / Posizione', 'Nella scena in cui Noodles deposita la valigia con i soldi nella cassetta di sicurezza della stazione ferroviaria, la valigia viene inserita in un determinato senso. Nell''inquadratura successiva, quando la serratura viene chiusa, la valigia appare ruotata di 180 gradi, con la maniglia rivolta verso il lato opposto.', TRUE, '2026-09-19T19:44:18.773942', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(592, 115, '01:52:40', 'Errori storici o fattuali', 'Winston Wolfe dichiara che arriverà a casa di Jimmie in 9 minuti e 37 secondi, guidando la sua Acura NSX ad altissima velocità. Tuttavia, considerando la distanza geografica reale tra la sua posizione iniziale (un hotel a Los Angeles) e la fittizia casa di Jimmie a Toluca Lake, compiere quel tragitto in quel lasso di tempo di mattina presto sarebbe fisicamente impossibile a causa del traffico e dei limiti fisici del percorso stradale urbano.', TRUE, '2026-09-17T18:00:05.719359', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(593, 115, '00:37:15', 'Errori di scena / Posizione', 'Al locale Jack Rabbit Slim''s, quando Mia Wallace ordina il famoso frappè da 5 dollari (''Martin and Lewis''), il livello del liquido nel bicchiere sale e scende vistosamente tra un''inquadratura e l''altra, prima ancora che lei inizi a berlo con la cannuccia.', TRUE, '2026-09-17T18:00:05.719359', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(594, 115, '01:43:50', 'Errori di scena / Posizione', 'Dopo l''accidentale uccisione di Marvin all''interno dell''auto, Jules e Vincent si rifugiano da Jimmie per ripulirsi. Quando indossano i vestiti prestati da Jimmie (le magliette e i pantaloncini da surfisti), la disposizione e la dimensione delle macchie di sangue rimaste sul collo e sulle braccia di Jules cambiano drasticamente tra le inquadrature prima e dopo la doccia improvvisata.', TRUE, '2026-09-17T18:00:05.719359', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(595, 116, '00:12:15', 'Errori di scena / Posizione', 'Quando Theodore indossa per la prima volta l''auricolare per configurare il nuovo sistema operativo (Samantha), l''orientamento del piccolo dispositivo nel suo orecchio destro cambia visibilmente tra il primo piano e l''inquadratura successiva a mezzo busto, ruotando di circa 45 gradi.', TRUE, '2026-09-17T18:14:01.31731', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(596, 116, '00:22:45', 'Troupe o microfoni visibili', 'Durante una ripresa notturna nell''appartamento di Theodore, mentre la telecamera compie una lenta panoramica verso la vetrata che si affaccia sulla città illuminata, nel riflesso del vetro sul lato sinistro è possibile scorgere per pochi istanti la sagoma di un operatore della troupe e parte dell''attrezzatura di ripresa coperta da un panno scuro.', TRUE, '2026-09-17T18:14:01.31731', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(597, 116, '00:34:40', 'Errori di scena / Posizione', 'Nella scena in cui Theodore cammina sul molo e mostra il panorama a Samantha, la spilla da balia utilizzata per fissare il dispositivo mobile alla tasca della camicia (in modo che la telecamera sporga correttamente) cambia posizione. Nei primi piani è posizionata molto più in alto rispetto alle inquadrature larghe, dove il telefono appare visibilmente più affossato nella tasca.', TRUE, '2026-09-17T18:14:01.31731', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(598, 116, '00:52:10', 'Errori di scena / Posizione', 'Durante la cena per l''appuntamento al buio con il personaggio interpretato da Olivia Wilde, il livello del vino rosso nel bicchiere della donna fluttua in modo incoerente. Tra un montaggio serrato e l''altro, il bicchiere passa dall''essere quasi vuoto a riempirsi nuovamente a metà, senza che venga mostrato nessuno intento a versare altro vino.', TRUE, '2026-09-17T18:14:01.31731', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(599, 116, '01:12:05', 'Errori di scena / Posizione', 'Nella tesa scena del ristorante in cui Theodore incontra Catherine per firmare le carte del divorzio, la penna sul tavolo cambia continuamente posizione. Inizialmente è posizionata parallelamente al bordo del tavolo, ma nei controcampi successivi appare inclinata e poi nuovamente dritta, prima ancora che Catherine la prenda in mano per firmare.', TRUE, '2026-09-17T18:14:01.31731', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(600, 116, '01:35:15', 'Errori di scena / Posizione', 'Quando Theodore si siede disperato sui gradini della metropolitana dopo che Samantha è temporaneamente scomparsa, la tracolla della sua borsa di pelle cambia posizione tra le inquadrature. Nella ripresa dall''alto la tracolla è perfettamente tesa sulla spalla, mentre nel primo piano successivo è attorcigliata e posizionata più vicino al collo.', TRUE, '2026-09-17T18:14:01.31731', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(71, 30, '01:02:10', 'Anacronismo', 'Sullo sfondo di una sequenza ambientata nelle praterie selvagge si nota una recinzione con filo spinato industriale di manifattura moderna, incompatibile con l''epoca storica del racconto.', TRUE, '2026-09-13T15:08:13.543457', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(72, 31, '00:35:12', 'Crew & Equipment', 'Durante la rissa nel bar al Cairo, in sottofondo a sinistra si nota distintamente una comparsa che indossa una maglietta a maniche corte e jeans blu di taglio moderno.', TRUE, '2026-09-13T15:08:13.770472', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(73, 31, '01:14:05', 'Continuity', 'Nel celebre scontro attorno all''aereo ad elica, i tagli e le macchie di sangue sul viso di Indiana Jones cambiano forma, estensione e posizione tra una ripresa e l''altra.', TRUE, '2026-09-13T15:08:13.860739', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(74, 31, '01:28:40', 'Anacronismo', 'Nella sequenza animata con la mappa del volo di linea compare la dicitura ''Thailandia'', ma nel 1936 lo stato si chiamava ancora ufficialmente ''Siam''.', TRUE, '2026-09-13T15:08:13.954093', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(75, 32, '00:42:15', 'Anacronismo', 'Un nobile romano viene mostrato mentre legge un quotidiano stampato all''interno di un bar, sebbene la stampa a caratteri mobili e i giornali moderni siano stati inventati oltre un millennio dopo.', TRUE, '2026-09-13T15:10:37.439306', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(76, 32, '01:15:30', 'Fattuale / Storico', 'Durante una spettacolare battaglia nell''arena, un combattente sfreccia cavalcando un rinoceronte addestrato; non esistono fonti storiche o evidenze che attestino l''uso di rinoceronti come cavalcature da combattimento nel Colosseo.', TRUE, '2026-09-13T15:10:37.548762', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(77, 32, '01:38:05', 'Fattuale / Storico', 'La ricostruzione della naumachia mostra il Colosseo allagato e infestato da squali aggressivi; per quanto le battaglie navali venissero riprodotte, l''introduzione di squali in acqua dolce/salmastra all''epoca è biologicamente e storicamente inverosimile.', TRUE, '2026-09-13T15:10:37.628196', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(78, 32, '00:18:40', 'Continuity', 'Durante l''assedio iniziale a Numidia, i tagli e le macchie di sangue sul volto di Lucio cambiano forma, densità e posizione tra le inquadrature ravvicinate e i campi lunghi.', TRUE, '2026-09-13T15:10:37.723547', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(79, 33, '00:43:15', 'Anacronismo', 'Quando Frodo e Sam camminano tra i campi della Contea, sullo sfondo in alto a destra si nota chiaramente una vettura bianca in movimento lungo una strada di campagna.', TRUE, '2026-09-13T15:13:21.675286', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(80, 33, '01:25:10', 'Continuity', 'Durante la scena del Consiglio di Elrond a Gran Burrone, la posizione e l''ampiezza delle ferite sul viso di Frodo cambiano visibilmente tra una ripresa e l''altra.', TRUE, '2026-09-13T15:13:21.770342', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(81, 33, '02:15:40', 'Crew & Equipment', 'Nella battaglia finale ad Amon Hen, è visibile l''ombra di un cameraman con la propria attrezzatura proiettata su una roccia alle spalle di Aragorn.', TRUE, '2026-09-13T15:13:21.815251', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(82, 34, '00:38:22', 'Continuity', 'Quando Merry e Pipino giacciono prigionieri degli Uruk-hai, i polsi di Pipino appaiono legati; nell''inquadratura successiva la corda scompare del tutto per poi ricomparire quando taglia i legami.', TRUE, '2026-09-13T15:13:22.008909', NULL, 0, 0, 'IA (Sistema)', 'ia')
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza") VALUES
(710, 137, '00:24:15', 'Errori di scena / Posizione', 'Durante la scena del briefing nel magazzino, Spence (Sean Bean) illustra il piano d''imboscata disegnandolo con un pennarello su una lavagna bianca. Nel passaggio tra i campi e controcampi con Sam (Robert De Niro), le frecce, le annotazioni e i tratti del diagramma cambiano spessore, posizione e dettagli prima ancora che vengano cancellati.', TRUE, '2026-09-25T20:39:52.091491', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(711, 137, '00:33:40', 'Errori di scena / Posizione', 'Nello scontro a fuoco sotto il ponte durante l''acquisto delle armi, il parabrezza del furgone dei trafficanti viene ripetutamente crivellato di colpi d''arma da fuoco. Nel cambio di inquadratura in cui il veicolo fa retromarcia per scappare, la ragnatela di fori di proiettile è quasi del tutto assente e il vetro appare notevolmente più integro.', TRUE, '2026-09-25T20:39:52.091491', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(712, 137, '00:56:45', 'Errori di scena / Posizione', 'Durante l''inseguimento a Nizza, l''Audi S8 sperona la Mercedes 450 SEL riportando la frantumazione del faro anteriore sinistro e un evidente ripiegamento del cofano. In diverse inquadrature successive lungo la strada costiera, il faro dell''Audi riappare miracolosamente intatto e il cofano allineato, per poi tornare accartocciato nel montaggio seguente.', TRUE, '2026-09-25T20:39:52.091491', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(713, 137, '01:15:30', 'Errori di scena / Posizione', 'Nel rifugio di Jean-Pierre ad Arles, mentre Sam guida Vincent nell''estrazione chirurgica del proiettile con l''aiuto di uno specchio, la quantità e la distribuzione del sangue sul torace di De Niro variano bruscamente: il tampone e la garza risultano saturi di sangue, ma nell''inquadratura immediatamente successiva sono quasi immacolati.', TRUE, '2026-09-25T20:39:52.091491', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(714, 137, '01:31:10', 'Troupe o microfoni visibili', 'Nel corso del celebre inseguimento a Parigi tra la Peugeot 406 e la BMW Serie 5, durante una rapida virata lungo una curva stretta, sulla carrozzeria metallizzata della BMW si scorge chiaramente il riflesso della camera car e della struttura di supporto del braccio cinematografico montato a fianco della vettura.', TRUE, '2026-09-25T20:39:52.091491', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(715, 137, '01:33:25', 'Errori di scena / Posizione', 'Durante la guida contromano nel tunnel di Parigi, il parabrezza della Peugeot 406 guidata da Sam si incrina vistosamente per l''impatto con detriti e colpi d''arma da fuoco. Nei primi piani ripresi dall''interno dell''abitacolo verso De Niro e Reno, il parabrezza torna ad essere perfettamente trasparente e privo di crepe per permettere la visibilità dei volti degli attori.', TRUE, '2026-09-25T20:39:52.091491', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(716, 137, '01:47:10', 'Errori storici o fattuali', 'All''interno del palazzetto Le Zénith, il fucile di precisione impiegato per colpire la pattinatrice russa mostra un collimatore con un evidente fascio laser rosso visibile che viaggia dritto fino al bersaglio. Nei protocolli operativi dei tiratori scelti professionisti non si usano puntatori laser a fascio continuo a lungo raggio in ambienti illuminati, poiché disperdono la mira e rivelano all''istante l''esatta posizione del cecchino.', TRUE, '2026-09-25T20:39:52.091491', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1024, 231, '01:08:40', 'Troupe o microfoni visibili', 'Nella parte superiore dello schermo, durante la scena concitata nel corridoio della casa, si nota per qualche istante l''estremità del microfono a calza (boom mic) che entra dall''alto nell''inquadratura.', TRUE, '2026-10-24T15:36:29.469711', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(601, 116, '01:58:30', 'Errori di scena / Posizione', 'Sulla scena finale del tetto con Amy, la disposizione dei capelli di Theodore e i fiocchi di neve/fuliggine depositati sulla sua giacca cambiano tra i tagli di montaggio. In particolare, una vistosa macchia chiara sulla spalla sinistra scompare completamente nel cambio di inquadratura per poi riapparire subito dopo.', TRUE, '2026-09-17T18:14:01.31731', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(734, 140, '00:12:45', 'Anacronismo / Scenografia', 'Durante la sequenza dell''arrivo degli immigrati a Ellis Island, sullo sfondo di una parete dell''edificio principale è visibile per pochi secondi una placca elettrica per interruttori di concezione moderna, non compatibile con il 1921.', TRUE, '2026-09-27T17:50:13.295344', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(735, 140, '00:28:10', 'Errore di continuità', 'Quando Bruno (Joaquin Phoenix) parla con Ewa (Marion Cotillard) all''interno del teatro, la posizione dello scialle della donna cambia tra il campo e il controcampo: prima è avvolto saldamente intorno alle spalle, poi scivola lungo le braccia nel taglio successivo.', TRUE, '2026-09-27T17:50:13.295344', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(736, 140, '00:45:15', 'Attrezzatura visibile', 'Nella parte superiore dell''inquadratura, durante l''accesa discussione tra Bruno e i suoi collaboratori nel retrobottega, è possibile notare la parte inferiore del microfono a giraffa (boom mic) che entra brevemente nel campo.', TRUE, '2026-09-27T17:50:13.295344', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(737, 140, '01:02:30', 'Oggetti di scena / Continuità', 'Durante l''esibizione di magia di Orlando (Jeremy Renner), la posizione del mazzo di carte sul tavolo cambia vistosamente tra due inquadrature ravvicinate: prima si trova alla destra del calice d''acqua, poi alla sua sinistra senza che l''illusionista lo abbia spostato.', TRUE, '2026-09-27T17:50:13.295344', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(738, 140, '01:18:05', 'Anacronismo', 'Nella ripresa esterna a livello stradale di una via di Manhattan, si scorge nell''angolo inferiore sinistro un tombino in ghisa recante una sigla di codifica industriale adottata dalla città di New York solo a partire dagli anni ''50.', TRUE, '2026-09-27T17:50:13.295344', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(602, 83, '00:17:45', 'Errori di scena / Posizione', 'Durante il viaggio in pick-up verso le coordinate segrete della NASA, il pattern e lo spessore della polvere accumulata sul parabrezza e sul cofano del veicolo cambiano notevolmente tra l''inquadratura esterna e le riprese dall''interno dell''abitacolo.', TRUE, '2026-09-17T20:55:55.596861', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(603, 83, '00:48:15', 'Troupe o microfoni visibili', 'Nella sequenza in cui l''equipaggio si muove in assenza di gravità all''interno della nave Endurance, nel riflesso del vetro del portello e sulla visiera della tuta di Doyle è brevemente visibile la sagoma di un pannello luce della troupe e un cavo di sospensione.', TRUE, '2026-09-17T20:55:55.596861', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(604, 83, '00:58:20', 'Errori di scena / Posizione', 'Durante la conversazione tra l''equipaggio prima di scendere sul pianeta di Miller, la cinghia dell''imbracatura sulla spalla sinistra di Amelia Brand cambia posizione più volte, passando da perfettamente stesa a ritorta tra un controcampo e l''altro.', TRUE, '2026-09-17T20:55:55.596861', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(605, 83, '01:12:10', 'Errori storici o fattuali', 'Sul pianeta di Miller, la dilatazione temporale estrema (1 ora pari a 7 anni terrestri) richiederebbe una vicinanza al buco nero Gargantua tale che le imponenti forze di marea ne disintegrerebbero la struttura rocciosa, superando di gran lunga il limite di Roche.', TRUE, '2026-09-17T20:55:55.596861', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(606, 83, '01:42:35', 'Errori storici o fattuali', 'Durante l''esplorazione del pianeta del Dr. Mann, l''equipaggio cammina sotto ''nuvole di ghiaccio'' solide sospese nell''aria. Fisicamente, il ghiaccio d''acqua o di anidride carbonica non può formare strutture rigide galleggianti in atmosfera senza precipitare al suolo a causa della gravità.', TRUE, '2026-09-17T20:55:55.596861', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(607, 83, '02:09:15', 'Errori di scena / Posizione', 'Nella celebre scena dell''aggancio alla stazione Endurance in rotazione incontrollata, la velocità angolare di rotazione del mozzo centrale e l''inclinazione visiva del Ranger variano in modo incoerente tra le inquadrature soggettive del quadro comandi e le ampie riprese esterne.', TRUE, '2026-09-17T20:55:55.596861', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(608, 83, '02:28:40', 'Errori di scena / Posizione', 'All''interno della struttura del Tesseract, quando Cooper spinge i libri dalla libreria della cameretta di Murph, l''ordine dei volumi rimasti sugli scaffali e la posizione esatta di quelli caduti a terra cambiano nettamente tra i primi piani delle mani e i campi lunghi della stanza.', TRUE, '2026-09-17T20:55:55.596861', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(609, 117, '00:03:15', 'Errori di scena / Posizione', 'Durante la cerimonia d''apertura della Welton Academy, la candela che simboleggia la ''luce della conoscenza'' passata tra gli studenti cambia vistosamente altezza e intensità della fiamma tra un''inquadratura e l''altra, rivelando l''uso di candele diverse durante i vari ciak.', TRUE, '2026-09-18T06:40:36.627653', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(610, 117, '00:12:40', 'Errori di scena / Posizione', 'Nella celebre scena del corridoio in cui il professor Keating raduna gli studenti davanti alle foto d''epoca (''Carpe Diem''), i capelli di Robin Williams cambiano continuamente posizionamento: in alcune inquadrature ravvicinate sono spettinati sulla fronte, mentre nei campi medi sono perfettamente pettinati all''indietro.', TRUE, '2026-09-18T06:40:36.627653', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(611, 117, '00:18:50', 'Anacronismi', 'L''antologia di poesia utilizzata dagli studenti, ''Understanding Poetry'' di Brooks e Warren, mostra una veste grafica e una copertina rigida che corrispondono a un''edizione scolastica pubblicata solo a partire dalla metà degli anni ''70, mentre il film è rigorosamente ambientato nel 1959.', TRUE, '2026-09-18T06:40:36.627653', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(612, 117, '00:22:15', 'Troupe o microfoni visibili', 'Durante una delle prime lezioni di Keating in aula, mentre si muove tra i banchi spiegando la poesia, sul vetro dell''armadietto dei libri posizionato sul fondo della stanza si può notare per un breve istante il riflesso di un pannello riflettente della troupe e la sagoma di un operatore.', TRUE, '2026-09-18T06:40:36.627653', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(741, 141, '00:04:10', 'Continuità', 'Durante la scena dell''attacco notturno iniziale a Chrissie, la posizione dei suoi vestiti lasciati sulla spiaggia e lo stato dei suoi capelli (da completamente bagnati a parzialmente asciutti) cambiano in modo incoerente tra un''inquadratura e l''altra.', TRUE, '2026-09-27T20:43:10.736812', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(739, 140, '01:34:40', 'Continuità / Trucco', 'Dopo il confronto fisico tra Bruno e Orlando, la ferita da taglio sul labbro di quest''ultimo cambia forma ed estensione: nella prima inquadratura è un piccolo taglio con poco sangue, mentre nell''inquadratura successiva il sangue copre gran parte del mento.', TRUE, '2026-09-27T17:50:13.295344', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(740, 140, '01:48:20', 'Riflesso / Attrezzatura', 'Nel riflesso del lucido finestrino dell''automobile d''epoca che si allontana lungo la strada, si distinguono chiaramente i pannelli riflettenti bianchi usati dalla troupe per illuminare il volto degli attori.', TRUE, '2026-09-27T17:50:13.295344', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(591, 115, '01:12:05', 'Troupe o microfoni visibili', 'Durante la fuga in taxi di Butch con la guidatrice Esmeralda, i finestrini del veicolo mostrano chiaramente che lo sfondo è una proiezione posteriore (back-projection). In un paio di inquadrature ravvicinate, si nota il riflesso delle luci del set cinematografico e delle attrezzature della troupe sul parabrezza e sul finestrino laterale.', TRUE, '2026-09-17T18:00:05.719359', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(613, 117, '00:48:10', 'Errori di scena / Posizione', 'Nella scena in cui Knox Overstreet scende in bicicletta lungo la collina erbosa spaventando uno stormo di oche, sul prato sono chiaramente visibili i solchi lasciati dalle ruote della bicicletta nei passaggi e nei ciak precedenti, indicando che la scena è stata ripetuta più volte.', TRUE, '2026-09-18T06:40:36.627653', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(614, 117, '01:15:05', 'Errori di scena / Posizione', 'Quando Todd riceve il set da scrivania per il compleanno e decide di lanciarlo giù dal ponte insieme a Neil, l''oggetto si rompe a mezz''aria in un determinato modo. Tuttavia, nell''inquadratura successiva che mostra i pezzi al suolo, la disposizione e lo stato dei componenti distrutti non corrispondono alla dinamica di caduta appena mostrata.', TRUE, '2026-09-18T06:40:36.627653', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(615, 117, '01:35:10', 'Errori storici o fattuali', 'Nel programma di sala distribuito per la recita teatrale di ''Sogno di una notte di mezza estate'' a cui assistono i protagonisti, sono stati utilizzati caratteri tipografici digitali moderni (tra cui varianti di Helvetica e font simili) che non erano ancora stati progettati o commercializzati nel 1959.', TRUE, '2026-09-18T06:40:36.627653', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(617, 118, '00:22:15', 'Errori di scena / Posizione', 'Quando John Ruth e Daisy entrano nell''emporio di Minnie per sfuggire alla tormenta, i loro abiti e cappelli sono completamente ricoperti di neve fresca. Al cambio di inquadratura, un secondo dopo all''interno del locale, la quantità di neve sui vestiti di Kurt Russell è drasticamente diminuita e disposta in modo diverso, prima ancora che possa essersi sciolta o che lui possa averla scrollata via.', TRUE, '2026-09-18T10:36:10.375501', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1025, 231, '01:15:05', 'Errori storici o fattuali', 'Quando viene inquadrato lo schermo del videogioco online giocato da Finn, l''interfaccia di rete e la simulazione della chat multiplayer mostrano dinamiche e schermate prive di senso tecnico rispetto alle reali funzionalità delle console disponibili nel 2012.', TRUE, '2026-10-24T15:36:29.469711', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(618, 118, '00:25:40', 'Errori di scena / Posizione', 'La porta dell''emporio è rotta e deve essere inchiodata ogni volta che qualcuno entra o esce. Quando O.B. inchioda le assi di legno per sigillare la porta dopo l''ingresso di Warren e Ruth, la disposizione delle assi e la posizione dei chiodi cambiano visibilmente nelle inquadrature successive, mostrando una chiara discrepanza di montaggio tra i vari ciak.', TRUE, '2026-09-18T10:36:10.375501', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(619, 118, '01:02:45', 'Errori di scena / Posizione', 'Durante la scena in cui i personaggi mangiano lo stufato preparato da Minnie, il livello del cibo all''interno della ciotola di Major Warren sale e scende in modo incoerente. In un''inquadratura la ciotola è quasi vuota, mentre nel taglio successivo è nuovamente piena a metà, senza che il personaggio si sia servito nuovamente dal calderone.', TRUE, '2026-09-18T10:36:10.375501', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(620, 118, '01:15:15', 'Anacronismi', 'Il film è ambientato circa sei-otto anni dopo la fine della Guerra Civile Americana (quindi intorno al 1871-1873). Tuttavia, in diverse scene si vede chiaramente l''utilizzo di un revolver Remington Modello 1890. Questa pistola non era ancora stata progettata né prodotta all''epoca in cui si svolgono gli eventi del film, rappresentando un evidente anacronismo tecnologico.', TRUE, '2026-09-18T10:36:10.375501', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(621, 118, '01:32:20', 'Errori di scena / Posizione', 'Nella celebre scena in cui Daisy suona la chitarra e John Ruth gliela strappa di mano per distruggerla (dove venne accidentalmente distrutto un pezzo autentico da museo del 1870 anziché la copia di scena), si nota un salto di montaggio. La transizione tra l''inquadratura in cui Jennifer Jason Leigh suona lo strumento reale e quella in cui Kurt Russell lo distrugge mostra un repentino cambio di postura dell''attrice e una sfasatura nella reazione di shock reale di quest''ultima.', TRUE, '2026-09-18T10:36:10.375501', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(622, 118, '01:48:30', 'Errori di scena / Posizione', 'Durante la spiegazione di Major Warren riguardo alla sparatoria avvenuta nell''emporio, sul pavimento ci sono delle caramelle gommose (jellybeans) sparse vicino al bancone. Il numero di caramelle e la loro esatta disposizione sul pavimento di legno cambiano sensibilmente tra un''inquadratura e l''altra, rivelando che la scena è stata girata in più riprese senza riposizionare accuratamente gli elementi di scena.', TRUE, '2026-09-18T10:36:10.375501', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(623, 118, '02:12:10', 'Errori di scena / Posizione', 'Dopo che John Ruth viene avvelenato e vomita sangue addosso a Daisy Domergue, il volto di Jennifer Jason Leigh appare coperto di sangue. Nelle scene successive, mentre è incatenata al cadavere di Ruth, la disposizione, la densità e le macchie di sangue sul suo viso cambiano continuamente forma, consistenza e posizione tra i primi piani e i campi medi.', TRUE, '2026-09-18T10:36:10.375501', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(693, 65, '01:12:05', 'Anacronismi', 'Le armature e gli elmi indossati da Sir Ranulf e da alcuni soldati dello Sceriffo presentano dettagli metallici e finiture tipiche del XIV e XV secolo, decisamente troppo avanzati per il periodo storico del regno di Re Giovanni (inizio XIII secolo).', TRUE, '2026-09-22T20:36:28.422194', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia'),
(695, 65, '01:41:50', 'Errori storici o fattuali', 'Il veleno somministrato da Marian a se stessa e a Robin agisce in modo quasi istantaneo e indolore, permettendo loro un ultimo dialogo sereno. Dal punto di vista medico e storico, i veleni accessibili all''epoca (come derivati della belladonna o cicuta) avrebbero provocato spasmi violenti, vomito e agonia, incompatibili con la fine romantica mostrata.', TRUE, '2026-09-22T20:36:28.422194', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia'),
(689, 65, '00:04:30', 'Errori di scena / Posizione', 'Durante l''assedio iniziale del castello di Châlus, la disposizione delle pietre e delle macerie ai piedi delle mura cambia visibilmente tra l''inquadratura in cui il vecchio difensore lancia i sassi e quella successiva in cui i soldati di Re Riccardo si avvicinano.', TRUE, '2026-09-22T20:36:28.422194', NULL, 1, 0, 'mrtlsn07@gmail.com', 'ia'),
(624, 125, '00:15:45', 'Errori di scena / Posizione', 'Nel bar ''Simulatte'', durante la prima conversazione tra Thomas Anderson e Tiffany, la posizione degli oggetti sul tavolino cambia continuamente: la tazza da caffè di Tiffany e il tovagliolo con i dolci si spostano e ruotano visibilmente nei raccordi tra i controcampi senza che nessuno dei personaggi li abbia toccati.', TRUE, '2026-09-18T18:43:22.751693', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(625, 125, '00:28:12', 'Errori di scena / Posizione', 'Nella sequenza del bagno dell''ufficio in cui il nuovo Morpheus offre la pillola rossa a Neo, l''orientamento della capsula e l''apertura delle dita della mano di Morpheus cambiano tra l''inquadratura ravvicinata del palmo e il piano medio successivo.', TRUE, '2026-09-18T18:43:22.751693', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(626, 125, '00:54:30', 'Errori di scena / Posizione', 'Durante lo scontro a bordo del treno proiettile giapponese, i graffi e la scia di sangue sulla tempia destra di Neo cambiano forma ed estensione tra le inquadrature ravvicinate e quelle a figura intera, risultando prima più marcati e poi quasi asciutti o ridotti.', TRUE, '2026-09-18T18:43:22.751693', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(627, 125, '01:15:20', 'Errori di scena / Posizione', 'Nello scontro all''interno del magazzino tra Neo e Smith, quando Smith scaglia Neo contro una struttura in ceramica spaccandola, la disposizione dei frammenti a terra e l''entità della rottura della parete variano visibilmente tra il momento dell''impatto e il controcampo seguente.', TRUE, '2026-09-18T18:43:22.751693', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(628, 125, '01:35:10', 'Errori di scena / Posizione', 'Nel confronto al Simulatte in cui l''Analista attiva il Bullet Time, il proiettile sospeso a mezz''aria e la traiettoria rispetto al volto di Trinity e alla mano dell''Analista cambiano leggermente angolazione e distanza relativa tra i cambi di prospettiva della macchina da presa.', TRUE, '2026-09-18T18:43:22.751693', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(629, 125, '02:05:40', 'Troupe o microfoni visibili', 'Durante l''inseguimento notturno in motocicletta per le strade di San Francisco, nel riflesso lucido del serbatoio della moto e negli specchietti retrovisori cromati è possibile scorgere in alcuni fotogrammi l''intelaiatura del carrello di ripresa montato sul veicolo d''inseguimento della troupe.', TRUE, '2026-09-18T18:43:22.751693', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(630, 125, '02:12:15', 'Errori di scena / Posizione', 'Sulla cima del grattacielo prima del salto, l''illuminazione dell''alba e la direzione delle ombre sui volti di Neo e Trinity mostrano una forte incongruenza di continuità: nelle inquadrature strette la luce del sole è radente e calda sul lato sinistro, mentre nei piani larghi la luce è diffusa e il cielo appare con un livello di chiarore differente.', TRUE, '2026-09-18T18:43:22.751693', NULL, 0, 0, 'IA (Sistema)', 'ia')
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza") VALUES
(668, 133, '00:55:10', 'Errori di scena / Posizione', 'Mentre Cliff prepara la cena per il suo cane Brandy nella roulotte, apre una lattina di cibo ''Wolf''s Tooth''. La quantità di cibo che fuoriesce dalla lattina e la posizione del coperchio metallico tagliato cambiano vistosamente tra i primi piani e i campi medi.', TRUE, '2026-09-19T19:47:51.941973', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(631, 122, '00:27:15', 'Troupe o microfoni visibili', 'Nella celebre scena in cui Morpheus offre a Neo la scelta tra la pillola rossa e la pillola blu, nel pomello dorato della porta è nettamente visibile il riflesso della telecamera da presa, che è stata parzialmente nascosta con un pezzo di stoffa per farla coincidere con la giacca di Morpheus.', TRUE, '2026-09-18T18:45:37.070374', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(632, 122, '00:17:40', 'Errori di scena / Posizione', 'Durante l''interrogatorio condotto dall''Agente Smith, quando la bocca di Neo si fonde e si sigilla, Neo cade all''indietro contro la sedia. La posizione delle sue mani e le pieghe del colletto della camicia cambiano vistosamente tra il primo piano strettissimo e il campo medio subito successivo.', TRUE, '2026-09-18T18:45:37.070374', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(633, 122, '01:14:10', 'Errori di scena / Posizione', 'Nella scena del déjà vu con il gatto nero, il felino cammina lungo la porta e si scuote. Nel momento in cui la scena si ripete immediatamente dopo, la posizione delle ombre sulla parete di mattoni e la postura di Trinity sullo sfondo non coincidono con la prima inquadratura.', TRUE, '2026-09-18T18:45:37.070374', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(634, 122, '01:41:35', 'Errori di scena / Posizione', 'Durante la sequenza dello scontro a fuoco nell''atrio del palazzo, molte colonne di marmo vengono quasi totalmente distrutte dai proiettili. Tuttavia, in diversi controcampi successivi durante la medesima sparatoria, alcune colonne sullo sfondo appaiono di nuovo integre o con danni visibilmente differenti.', TRUE, '2026-09-18T18:45:37.070374', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(47, 14, '00:34:12', 'Continuity', 'Nella famosa scena in cui Michele mangia il gigantesco barattolo di Nutella, il livello della crema all''interno del vaso varia vistosamente da un''inquadratura all''altra.', TRUE, '2026-09-13T14:58:31.314737', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(635, 122, '01:45:50', 'Errori di scena / Posizione', 'Quando Neo spara con il cannone minigun dall''elicottero per coprire la fuga di Morpheus, una pioggia incessante di bossoli cade sul pavimento dell''ufficio. Nell''inquadratura dall''alto subito successiva, la quantità di bossoli a terra attorno agli Agenti è nettamente inferiore a quella mostrata durante la raffica.', TRUE, '2026-09-18T18:45:37.070374', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(636, 122, '01:48:20', 'Troupe o microfoni visibili', 'Nella scena in cui l''elicottero perde quota e si schianta contro il grattacielo di vetro, quando Neo sbalza fuori tenendo la corda per afferrare Trinity, sono chiaramente visibili i cavi di sicurezza del cordame di supporto collegati all''imbracatura dello stuntman.', TRUE, '2026-09-18T18:45:37.070374', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(637, 122, '01:52:45', 'Errori di scena / Posizione', 'Durante il combattimento nella metropolitana tra Neo e l''Agente Smith, Smith scaraventa Neo contro una colonna di cemento. Nei fotogrammi immediatamente precedenti all''impatto di Neo, si nota chiaramente la linea di giunzione pre-tagliata sul pannello della colonna, predisposta per cedere al momento del contatto.', TRUE, '2026-09-18T18:45:37.070374', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(638, 126, '00:18:45', 'Anacronismi', 'In diverse scene della pellicola viene fatto largo uso di candelotti di dinamite. Tuttavia, la dinamite fu brevettata da Alfred Nobel solo nel 1867, mentre gli eventi del film si svolgono con precisione nel 1862, durante la Campagna del Nuovo Messico della Guerra di Secessione Americana.', TRUE, '2026-09-18T18:52:12.025785', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(639, 126, '00:48:10', 'Errori di scena / Posizione', 'Durante la sequenza nel deserto in cui Tuco costringe il Biondo a camminare sotto il sole battente, le macchie di sudore sul poncho del Biondo e la quantità di polvere sul suo volto variano bruscamente da un''inquadratura all''altra, alternandosi tra primi piani e campi lunghi.', TRUE, '2026-09-18T18:52:12.025785', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(640, 126, '01:24:15', 'Errori storici o fattuali', 'Lungo la linea ferroviaria su cui viaggia il treno dei prigionieri guidato dai nordisti, i binari sono posati su traverse moderne in calcestruzzo ed evidenziano piastre d''acciaio con bulloneria standard moderna, del tutto inesistenti nell''infrastruttura ferroviaria statunitense del 1862.', TRUE, '2026-09-18T18:52:12.025785', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(641, 126, '01:52:30', 'Troupe o microfoni visibili', 'Durante la sequenza in cui la colonna militare muove vicino alle rovine del campo, nell''angolo superiore sinistro dell''inquadratura panoramica si intravede brevemente l''ombra del braccio del microfono (boom operator) proiettata sul bordo del ponte in legno.', TRUE, '2026-09-18T18:52:12.025785', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(642, 126, '02:18:05', 'Errori di scena / Posizione', 'Durante la scena del posizionamento dell''esplosivo al ponte di Langstone, il Biondo e Tuco collegano una miccia che, nel campo largo iniziale, appare tesa e lunga diversi metri, ma nel primissimo piano successivo di accensione risulta quasi consumata e collocata a ridosso delle cariche.', TRUE, '2026-09-18T18:52:12.025785', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(643, 126, '02:35:40', 'Anacronismi', 'Nella famosa scena del negozio d''armi, Tuco assembla un revolver personalizzato combinando pezzi di varie armi e inserisce cartucce metalliche per retrocarica. Nel 1862 la maggior parte delle armi corte dell''esercito usava ancora la carica ad avancarica con polvere e capsula a percussione; le conversioni a cartuccia metallica diventarono comuni solo a guerra finita.', TRUE, '2026-09-18T18:52:12.025785', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(644, 126, '02:48:50', 'Errori di scena / Posizione', 'Nel celebre triello finale all''interno del cimitero di Sad Hill, la posizione delle ombre proiettate dalle pietre tombali e dai tre protagonisti cambia drasticamente tra i primi piani sui volti e le inquadrature a figura intera, rivelando che la sequenza è stata girata in momenti diversi della giornata con il sole a diverse altezze.', TRUE, '2026-09-18T18:52:12.025785', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(645, 132, '00:14:32', 'Errori di scena / Posizione', 'Durante la scena del primo scontro sul ponte di Brooklyn, quando Spider-Man si rialza da terra dopo aver schivato un attacco, la lacerazione sul costume cambia lato: nell''inquadratura frontale lo strappo è ben visibile sulla guancia destra della maschera, mentre nel controcampo immediato si sposta sulla guancia sinistra.', TRUE, '2026-09-19T18:06:28.766949', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(646, 132, '00:38:15', 'Troupe o microfoni visibili', 'Mentre Peter Parker ed MJ parlano all''esterno del bar a Manhattan, nell''angolo superiore destro dello schermo si nota chiaramente la punta del microfono a giraffa (boom mic) con il peluche antivento nero che si abbassa per circa tre secondi all''interno del riquadro.', TRUE, '2026-09-19T18:06:28.766949', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(647, 132, '00:52:40', 'Anacronismi', 'In una sequenza di flashback ambientata visibilmente durante il primo anno di liceo dei protagonisti (circostanziata intorno al 2017), un passante sullo sfondo della strada sta chiaramente utilizzando un modello di iPhone 15 Pro, uscito sul mercato solo diversi anni dopo.', TRUE, '2026-09-19T18:06:28.766949', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(677, 136, '01:18:20', 'Troupe o microfoni visibili', 'Durante una carica di cavalleria ad ampie riprese nelle praterie, sul terreno brullo davanti ai cavalli sono distintamente visibili i solchi e le tracce degli pneumatici lasciati dalla vettura della macchina da presa (camera car).', TRUE, '2026-09-21T20:36:15.565218', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(678, 136, '01:35:05', 'Errori storici o fattuali', 'Viene mostrato un incontro formale e un negoziato privato faccia a faccia tra Custer e il capo nativo Cavallo Pazzo (Anthony Quinn). Storicamente, Cavallo Pazzo e Custer non si incontrarono né trattarono mai di persona.', TRUE, '2026-09-21T20:36:15.565218', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(679, 136, '02:10:15', 'Anacronismi', 'Durante l''epica carica finale al Little Bighorn, i cavalleggeri del 7° Cavalleria sguainano e usano le sciabole d''ordinanza. Nella realtà, le sciabole furono lasciate nei depositi del forte prima dell''inizio della campagna per alleggerire l''equipaggiamento.', TRUE, '2026-09-21T20:36:15.565218', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1026, 225, '02:01:25', 'Errori di scena / Posizione', 'Mentre Nathan Algren (Tom Cruise) smonta da cavallo arrivando al villaggio prima della battaglia, lo stallone sferra un involontario calcio all''inguine di una comparsa vestita da samurai sullo sfondo a destra, la quale si piega in due dal dolore tentando di rimanere in parte nell''inquadratura.', TRUE, '2026-10-24T15:38:16.555456', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(663, 129, '02:22:15', 'Errori di scena / Posizione', 'Durante la lussuosa cena romantica tra Noodles e Deborah nel ristorante sul mare, il livello dello champagne nei calici dei due personaggi sale e scende in modo del tutto incoerente tra i vari controcampi, senza che nessuno dei due abbia effettivamente bevuto o che il cameriere abbia versato nuovamente la bevanda.', TRUE, '2026-09-19T19:44:18.773942', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(665, 129, '03:15:40', 'Errori storici o fattuali', 'Nella sezione del film ambientata nel 1968, quando Noodles visita il sontuoso mausoleo, viene mostrata una targa commemorativa. Le date di nascita e morte riportate per alcuni personaggi non coincidono temporalmente con la cronologia degli eventi narrati nella prima parte del film, creando una discrepanza storica interna alla narrazione di Leone.', TRUE, '2026-09-19T19:44:18.773942', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(666, 133, '02:12:15', 'Anacronismi', 'Durante il volo di ritorno di Rick e Cliff dall''Italia su un aereo della Pan Am, viene mostrato un Boeing 747. Tuttavia, la tratta si svolge nell''agosto del 1969, mentre il Boeing 747 è entrato in servizio commerciale per la Pan Am solo nel gennaio del 1970.', TRUE, '2026-09-19T19:47:51.941973', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(667, 133, '00:28:40', 'Errori di scena / Posizione', 'Nella scena in cui Cliff Booth guida la Cadillac di Rick Dalton di giorno, i suoi occhiali da sole a goccia cambiano posizione tra le inquadrature: in un frame sono calzati sul viso, mentre nel taglio successivo si trovano appesi al colletto della camicia, per poi tornare sul viso senza che lui compia il movimento di indossarli.', TRUE, '2026-09-19T19:47:51.941973', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(342, 59, '02:41:05', 'Errori di scena / Posizione', 'Nella scena post-credits ambientata 10 anni dopo, Elizabeth e suo figlio sono sulla scogliera ad attendere il ritorno di Will. L''ombra proiettata dai due personaggi sul terreno cambia angolazione di oltre 45 gradi tra il primo piano e la panoramica finale verso il tramonto, rivelando che le riprese sono state effettuate in momenti della giornata molto differenti.', TRUE, '2026-09-14T14:15:12.32037', 'Pirati dei Caraibi - Ai confini del mondo Nella scena postcredits ambientata 10 anni dopo Elizabeth mistake error', 0, 0, 'IA (Sistema)', 'ia'),
(674, 136, '00:12:30', 'Errori storici o fattuali', 'La pellicola mostra George Armstrong Custer che arriva all''Accademia Militare di West Point nel 1861, in concomitanza con lo scoppio della Guerra di Secessione. Nella realtà storica, Custer entrò a West Point nel 1857 e si diplomò nel giugno del 1861.', TRUE, '2026-09-21T20:36:15.565218', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(675, 136, '00:28:45', 'Anacronismi', 'Durante le sequenze di battaglia ambientate nella Guerra Civile (1861-1865), molti soldati dell''Unione impugnano revolver Colt Single Action Army ''Peacemaker'' e fucili Springfield Trapdoor, armi introdotte solo nel 1873.', TRUE, '2026-09-21T20:36:15.565218', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(676, 136, '00:45:10', 'Errori di scena / Posizione', 'Nella scena del dialogo romantico tra Custer e Libbie nel salotto, la sciarpa di Libbie cambia posizione tra le inquadrature: prima si trova sulla spalla destra, poi nei primi piani appare posizionata centralmente sul petto, per poi tornare indietro.', TRUE, '2026-09-21T20:36:15.565218', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(14, 2, '02:27:00', 'Fattuale / Storico', 'Commodo muore nel Colosseo ucciso da Massimo. Storicamente, Commodo governò per 12 anni e morì nel 192 d.C. strangolato nel suo bagno dal lottatore Narciso a seguito di una congiura di palazzo.', TRUE, '2026-09-13T14:42:52.709705', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(51, 16, '00:18:22', 'Fattuale / Storico', 'L''aquila gigante Marahute presenta caratteristiche anatomiche ed etologiche tipiche delle aquile calve americane, del tutto assenti nella fauna selvatica australiana.', TRUE, '2026-09-13T14:58:32.129787', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(83, 34, '02:05:12', 'Continuity', 'Durante la carica al Fosso di Helm, la spada nella faretra di Aragorn scompare momentaneamente durante la corsa lungo la rampa per poi riapparire nella ripresa seguente.', TRUE, '2026-09-13T15:13:22.085534', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(20, 3, '01:14:05', 'Continuity', 'Quando l''elicottero precipita a Central Park, le pale del rotore principale appaiono completamente spezzate nell''inquadratura dall''interno, ma ritornano parzialmente integre e piegate nell''inquadratura successiva esterna.', TRUE, '2026-09-13T14:43:24.75352', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(660, 129, '00:38:40', 'Anacronismi', 'Nelle scene ambientate nel 1918 nel Lower East Side di New York, sui tetti di alcuni edifici sullo sfondo sono chiaramente visibili diverse antenne televisive e cavi telefonici moderni, elementi del tutto inesistenti all''epoca in cui è ambientata l''infanzia dei protagonisti.', TRUE, '2026-09-19T19:44:18.773942', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(761, 143, '01:31:10', 'Attrezzatura visibile', 'Durante la sequenza di panico nei tunnel subacquei, in un''inquadratura grandangolare si possono notare i riflessi delle luci di produzione e di parte della troupe cinematografica sulle pareti curve in plexiglass che simulano il tunnel sommerso.', TRUE, '2026-09-28T06:24:16.525723', NULL, 0, 0, 'lrscrm73@gmail.com', 'utente'),
(718, 118, '12', 'Errori di scena / Posizione', 'boooh', TRUE, '2026-09-26T09:29:00.982833', NULL, 0, 0, 'mrtrrt67@gmail.com', 'utente'),
(510, 103, '00:38:20', 'Errori storici o fattuali', 'La bandiera britannica (Union Jack) che sventola su Forte William Henry include la croce rossa diagonale di San Patrizio. Questo disegno della bandiera è stato adottato solo nel 1801 con l''Atto di Unione, mentre le vicende del film si svolgono nel 1757 durante la guerra franco-indiana.', TRUE, '2026-09-16T13:02:08.462231', NULL, 0, 0, 'IA (Sistema)', 'utente'),
(509, 103, '00:14:35', 'Errori di scena / Posizione', 'Durante la cena a casa di Jack Winthrop, la posizione delle candele sul tavolo e il livello della loro cera cambiano vistosamente tra i primi piani e i campi medi, tornando ad essere più lunghe in alcune inquadrature successive.', TRUE, '2026-09-16T13:02:08.462231', NULL, 0, 0, 'IA (Sistema)', 'utente'),
(719, 6, '2', 'Errori di scena / Posizione', 'asdsasddsadasasd', TRUE, '2026-09-26T12:20:09.059413', NULL, 0, 0, 'mrtrrt67@gmail.com', 'utente'),
(1027, 225, '00:06:15', 'Anacronismi', 'All''inizio del film, durante l''esibizione dei fucili negli Stati Uniti ambientata nel 1876, viene mostrata una bandiera americana con 43 stelle. Nel 1876 gli Stati Uniti avevano 38 stati (la bandiera a 43 stelle fu adottata solo nel 1890).', TRUE, '2026-10-24T15:38:16.555456', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1028, 225, '01:08:40', 'Errori di scena / Posizione', 'Durante il duro allenamento con le spade di legno sotto la pioggia battente tra Algren e Ujiio, la quantità e la disposizione del fango sul viso e sulla tunica di Tom Cruise cambiano visibilmente ad ogni stacco di montaggio tra i primi piani e i campi medi.', TRUE, '2026-10-24T15:38:16.555456', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1029, 225, '02:14:10', 'Errori storici o fattuali', 'Nella scontro finale ambientato durante la ribellione di Satsuma (1877), l''esercito imperiale impiega mitragliatrici Gatling Modello 1883 con caricatore circolare superiore, armi che non esistevano ancora all''epoca degli avvenimenti.', TRUE, '2026-10-24T15:38:16.555456', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1030, 225, '00:46:20', 'Troupe o microfoni visibili', 'Durante la prima battaglia nella foresta avvolta dalla nebbia, nei dettagli lucidi dell''armatura di un samurai in prima fila è chiaramente visibile il riflesso di uno schermo riflettente bianco della troupe utilizzato per illuminare gli attori.', TRUE, '2026-10-24T15:38:16.555456', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1031, 225, '02:19:50', 'Errori di scena / Posizione', 'Nel momento in cui Katsumoto compie il rituale del seppuku assistito da Algren, la posizione della lama del tantō e l''estensione delle macchie di sangue sul petto del samurai variano visibilmente nel passaggio dalle inquadrature ampie al primo piano.', TRUE, '2026-10-24T15:38:16.555456', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(672, 133, '02:18:45', 'Errori storici o fattuali', 'La notte del 9 agosto 1969 (la notte degli omicidi Manson nella realtà), il cielo nel film mostra una luna quasi piena e molto luminosa. Storicamente, quella notte la luna era in fase di calante avanzata (circa il 18% di visibilità), rendendo la notte estremamente buia.', TRUE, '2026-09-19T19:47:51.941973', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(673, 133, '00:32:15', 'Troupe o microfoni visibili', 'Durante la scena in cui Cliff Booth guida la Cadillac di Rick Dalton di sera e passa davanti ai cinema al neon, sul parabrezza lucido e sulla carrozzeria della vettura si riflette chiaramente la sagoma della telecamera montata sul veicolo di ripresa (camera car) che precede l''auto.', TRUE, '2026-09-19T19:47:51.941973', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1038, 236, '00:24:15', 'Troupe o microfoni visibili', 'Nella scena dell''ospedale psichiatrico, mentre la telecamera ruota attorno a Jeffrey Goines (Brad Pitt) che parla freneticamente, sul vetro divisorio sbarrato è possibile scorgere per un istante il riflesso dell''operatore della mdp e dell''attrezzatura d''illuminazione della troupe.', TRUE, '2026-10-24T15:59:46.407659', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1039, 236, '00:48:30', 'Errori di scena / Posizione', 'Quando Cole viene catapultato erroneamente nella trincea della Prima Guerra Mondiale nel 1917 e viene ferito, la chiazza di sangue sui suoi pantaloni cambia estensione e posizione esatta tra il momento del fendente e la ripresa successiva in cui viene trascinato.', TRUE, '2026-10-24T15:59:46.407659', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia')
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza") VALUES
(1040, 236, '01:12:40', 'Errori di scena / Posizione', 'Nella drammatica scena della stanza d''albergo dove Cole si strappa da solo un dente con le pinze, le sbavature di sangue sul mento e sulle mani cambiano completamente disposizione tra il primo piano e il controcampo.', TRUE, '2026-10-24T15:59:46.407659', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1041, 236, '01:34:10', 'Anacronismi', 'Durante le riprese esterne ambientate nel 1990, in sottofondo nel traffico urbano è visibile un modello di automobile (un restyling della Ford Taurus) commercializzato solo a partire dalla fine del 1991.', TRUE, '2026-10-24T15:59:46.407659', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1042, 236, '01:45:15', 'Errori storici o fattuali', 'Quando la dottoressa Kathryn Railly estrae la pallottola dalla gamba di Cole, afferma che si tratta di un proiettile risalente alla Prima Guerra Mondiale (1917). Tuttavia, la forma della ogiva mostrata in primo piano è quella di un proiettile camiciato di concezione moderna, incompatibile con la munizione d''epoca citata.', TRUE, '2026-10-24T15:59:46.407659', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1043, 236, '02:02:50', 'Errori di scena / Posizione', 'Nella sequenza finale all''aeroporto, quando Cole indossa la parrucca e i baffi finti per integrarsi tra i passeggeri, l''inclinazione e la simmetria dei baffi finti cambiano visibilmente tra un''inquadratura e l''altra mentre corre.', TRUE, '2026-10-24T15:59:46.407659', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(742, 141, '00:14:25', 'Errori nei testi', 'Quando il capo Brody sta battendo a macchina il rapporto sulla morte della prima vittima, digita erroneamente ''CORNER''S OFFICE'' anziché ''CORONER''S OFFICE''.', TRUE, '2026-09-27T20:43:10.736812', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(706, 63, '01:14:30', 'Errori di scena / Posizione', 'Durante la scena sentimentale al balcone con Lady Marian, il velo del suo elaborato copricapo cade lungo la spalla sinistra nel campo medio, ma nel controcampo ravvicinato si trova completamente spostato dietro la schiena.', TRUE, '2026-09-25T19:09:14.246576', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(707, 63, '01:32:05', 'Anacronismi', 'Durante la zuffa tra le guardie e i fuorilegge, uno degli stuntman che cade all''indietro mostra distintamente la suola di gomma stampata con scanalature moderne sotto gli stivali di pelle.', TRUE, '2026-09-25T19:09:14.246576', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(708, 63, '01:48:50', 'Troupe o microfoni visibili', 'Nella celebre scena in cui Robin Hood scivola lungo la gigantesca tenda della sala del trono, per diversi fotogrammi è visibile la carrucola di supporto e il cavo di guida nascosto nella piega superiore del tessuto.', TRUE, '2026-09-25T19:09:14.246576', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(709, 63, '02:03:15', 'Errori storici o fattuali', 'Sugli stendardi del Principe Giovanni e sulle tuniche dei soldati compare lo stemma reale con i tre leoni passanti, simboleggiamento che venne introdotto ufficialmente da Riccardo Cuor di Leone solo nel 1198, cioè anni dopo gli eventi narrati nel film.', TRUE, '2026-09-25T19:09:14.246576', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(19, 3, '01:05:12', 'Crew & Equipment', 'Nella sequenza d''azione all''interno del tunnel della metropolitana, in un fotogramma illuminato dal visore notturno è visibile sulla parete sinistra l''ombra dell''operatore di ripresa con il supporto per la telecamera.', TRUE, '2026-09-13T14:43:24.654587', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1044, 235, '00:12:35', 'Errori di scena / Posizione', 'Durante la scena del licenziamento di Noah in ufficio, la cravatta del protagonista cambia posizione tra un''inquadratura e l''altra: prima è leggermente allentata e storta, poi nei controcampi appare perfettamente dritta e allacciata fino al colletto.', TRUE, '2026-10-24T16:37:16.320661', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1045, 235, '00:28:40', 'Troupe o microfoni visibili', 'Mentre Marilyn (Diane Keaton) scarica le valigie dall''auto per trasferirsi a casa del figlio, nell''angolo superiore sinistro dello schermo è chiaramente visibile la punta del microfono a boom che scende nel campo visivo per un paio di secondi.', TRUE, '2026-10-24T16:37:16.320661', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1046, 235, '00:41:15', 'Errori di scena / Posizione', 'Nella cucina della casa, durante la discussione a colazione, il livello del succo d''arancia nel bicchiere di Clare (Liv Tyler) varia continuamente: è quasi vuoto quando parla Noah, ma torna pieno nella ripresa successiva a piano medio.', TRUE, '2026-10-24T16:37:16.320661', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1047, 235, '00:55:02', 'Errori di scena / Posizione', 'Durante la scena in cui i cani di Marilyn corrono nel soggiorno, un cuscino decorativo rosso sul divano scompare e riappare improvvisamente nei vari stacchi di montaggio.', TRUE, '2026-10-24T16:37:16.320661', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1048, 235, '01:08:20', 'Troupe o microfoni visibili', 'Quando Noah sale in macchina per andare a un colloquio di lavoro, nel riflesso del finestrino laterale del guidatore si distingue nettamente la sagoma di un operatore della troupe con un pannello riflettente.', TRUE, '2026-10-24T16:37:16.320661', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1049, 235, '01:19:45', 'Errori storici o fattuali', 'Sulla domanda di assunzione che Noah sta compilando a penna, la data visibile nel modulo indica il mese di marzo, ma nell''inquadratura subito successiva sul calendario appeso al muro della stanza viene mostrato chiaramente il mese di novembre.', TRUE, '2026-10-24T16:37:16.320661', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(648, 132, '01:12:05', 'Errori storici o fattuali', 'Durante la lezione universitaria a cui assiste Peter, il professore proietta una diapositiva indicando che la Costituzione della Repubblica Italiana è entrata in vigore nel 1946 anziché il 1° gennaio 1948, commettendo un errore concettuale non corretto dal dialogo.', TRUE, '2026-09-19T18:06:28.766949', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(649, 132, '01:35:50', 'Errori di scena / Posizione', 'Nel corso di un concitato inseguimento tra i tetti della città, l''orologio da polso di Peter Parker segna le 14:15. Nell''inquadratura immediatamente successiva, mentre l''eroe scaglia una ragnatela in primo piano, il quadrante segna improvvisamente le 16:40, nonostante la scena si svolga in tempo reale.', TRUE, '2026-09-19T18:06:28.766949', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(650, 132, '01:51:18', 'Troupe o microfoni visibili', 'Durante il combattimento decisivo all''interno del capannone industriale, nel riflesso dell''ampia vetrata posta dietro il villain si distingue nettamente la sagoma di un operatore della troupe con maglietta chiara che manovra una telecamera su stabilizzatore Gimbal.', TRUE, '2026-09-19T18:06:28.766949', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(651, 132, '02:08:45', 'Errori di scena / Posizione', 'Nella scena di chiusura al parco, la tazza di caffè d''asporto presa da MJ cambia aspetto tra i tagli di montaggio: inizialmente presenta un coperchio di plastica bianca con la linguetta aperta, ma nell''inquadratura seguente il coperchio diventa di colore marrone scuro e completamente sigillato.', TRUE, '2026-09-19T18:06:28.766949', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(652, 127, '00:08:24', 'Errori di scena / Posizione', 'Durante la celebre sequenza iniziale alla stazione di Cattle Corner, Stony (Woody Strode) raccoglie le gocce d''acqua che cadono dal serbatoio sulla tesa del cappello. Tra le inquadrature ravvicinate e i campi medi, la quantità d''acqua accumulata e la macchia d''umidità sul feltro cambiano visibilmente di forma e consistenza senza logica temporale.', TRUE, '2026-09-19T18:08:29.015384', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(653, 127, '00:22:40', 'Anacronismi', 'Durante il massacro della famiglia McBain a Sweetwater, gli scagnozzi guidati da Frank impugnano fucili a ripetizione Winchester modello 1892 con leva a passante largo, modificati per sembrare modelli precedenti. L''ambientazione storica della ferrovia transcontinentale colloca tuttavia la vicenda attorno al 1868-1869, rendendo l''uso di tali armi anacronistico di oltre vent''anni.', TRUE, '2026-09-19T18:08:29.015384', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(654, 127, '00:32:10', 'Errori di scena / Posizione', 'All''arrivo di Jill McBain (Claudia Cardinale) alla stazione di Flagstone, la posizione della veletta nera e delle ciocche di capelli che le scendono sulla spalla sinistra varia continuamente a ogni stacco di montaggio tra il primo piano e la figura intera, passando da ordinata a parzialmente sciolta.', TRUE, '2026-09-19T18:08:29.015384', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(655, 127, '01:14:45', 'Troupe o microfoni visibili', 'All''interno della lussuosa carrozza ferroviaria privata del magnate Morton, durante il dialogo ravvicinato tra quest''ultimo e Frank, sulle superfici laccate in mogano lucido e sui vetri delle vetrinette si distinguono chiaramente i riflessi dei pannelli riflettenti bianchi e di una lampada dell''impianto di illuminazione di scena.', TRUE, '2026-09-19T18:08:29.015384', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1051, 186, '00:14:20', 'Errori di scena / Posizione', 'Durante la sequenza iniziale dell''incendio boschivo, Pete effettua una picchiata per scaricare il ritardante chimico rosso sul motore in fiamme dell''aereo di Al. Nella ripresa esterna il liquido colpisce in pieno la cabina di pilotaggio oscurando quasi totalmente il parabrezza, ma nello stacco successivo dall''interno dell''abitacolo i finestrini risultano incredibilmente puliti, consentendo ad Al una visibilità quasi perfetta.', TRUE, '2026-10-24T17:15:05.956821', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1052, 186, '00:24:10', 'Errori di scena / Posizione', 'Nella celebre scena in cui Pete e Dorinda ballano nel capannone al suono di ''Smoke Gets in Your Eyes'', l''acconciatura di Holly Hunter cambia continuamente: nei campi lunghi i suoi capelli sono sciolti e ordinati dietro le spalle, mentre nei primi piani diverse ciocche le ricadono disordinate sul viso e sulla clavicola a seconda dell''inquadratura.', TRUE, '2026-10-24T17:15:05.956821', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1053, 186, '00:32:05', 'Errori di scena / Posizione', 'Nel momento culminante in cui l''aereo A-26 Invader di Pete prende fuoco e vira verso l''alto prima di esplodere, è chiaramente visibile all''interno dell''abitacolo un manichino rigido e inanimato al posto di Richard Dreyfuss, posizionato con le braccia fisse sulla cloche senza alcun movimento naturale.', TRUE, '2026-10-24T17:15:05.956821', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1054, 186, '00:38:40', 'Errori di scena / Posizione', 'Nell''incontro ultraterreno tra Pete e l''angelo Hap (Audrey Hepburn) nella radura, Hap usa le forbici per tagliare i capelli a Pete. La quantità di ciocche di capelli visibili sul colletto e sulle spalle della camicia di Pete varia ripetutamente da un''inquadratura all''altra: in alcuni controcampi il tessuto è cosparso di capelli tagliati, mentre nei piani stretti successivi è perfettamente pulito.', TRUE, '2026-10-24T17:15:05.956821', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1055, 186, '01:13:25', 'Troupe o microfoni visibili', 'Durante le sequenze di addestramento aereo di Ted Baker guidato dallo spirito di Pete, in un''inquadratura laterale che riprende il cockpit dall''esterno si nota, sul plexiglas della cappottina e sul bordo metallico della fusoliera, il riflesso netto del supporto della macchina da presa cinematografica e di un pannello riflettente montato sulla struttura di ripresa.', TRUE, '2026-10-24T17:15:05.956821', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1056, 186, '01:47:30', 'Errori storici o fattuali', 'Nella sequenza finale in cui Dorinda decolla per salvare la squadra di vigili del fuoco intrappolata, il lancio del ritardante chimico rosso estingue all''istante l''intero fronte di fiamma alta come alberi. Nella realtà operativa degli incendi boschivi, i ritardanti a base di fosfato d''ammonio non soffocano istantaneamente incendi di quelle proporzioni, ma servono a impregnare la vegetazione non ancora bruciata per rallentare l''avanzata delle fiamme.', TRUE, '2026-10-24T17:15:05.956821', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1057, 217, '00:18:45', 'Errori di scena / Posizione', 'Nel primo episodio, durante la prigionia di Boba Fett presso il campo dei Sabbipodi, le catene che legano i suoi polsi al palo cambiano disposizione: nel campo largo sono incrociate l''una sull''altra, mentre nel primo piano successivo risultano posizionate in parallelo senza che il personaggio si sia mosso.', TRUE, '2026-10-24T18:58:42.581832', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1058, 217, '00:24:12', 'Troupe o microfoni visibili', 'Nel terzo episodio, durante la sequenza dell''inseguimento sugli speeder bike colorati della banda di ragazzi mod per le vie di Mos Espa, sulle superfici cromate e negli specchietti di uno dei veicoli si intravede chiaramente il riflesso del rig della telecamera e dell''operatore di ripresa.', TRUE, '2026-10-24T18:58:42.581832', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1059, 217, '00:32:05', 'Errori di scena / Posizione', 'Nel terzo episodio, durante l''imboscata notturna di Black Krrsantan nella stanza della vasca di bacta, le ferite e le macchie di sporco sul petto e sul volto di Boba Fett variano vistosamente di intensità e posizione da un''inquadratura all''altra mentre viene trascinato sul pavimento.', TRUE, '2026-10-24T18:58:42.581832', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1060, 217, '00:41:10', 'Errori di scena / Posizione', 'Nel secondo episodio, durante l''assalto al treno dei Pyke nel deserto di Tatooine, la posizione delle ombre proiettate dai veicoli sulla sabbia cambia istantaneamente da sinistra a destra tra due stacchi di montaggio consecutivi, rivelando che la scena è stata girata in momenti della giornata completamente differenti.', TRUE, '2026-10-24T18:58:42.581832', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1061, 217, '00:15:30', 'Errori di scena / Posizione', 'Nel quinto episodio, quando il Mandaloriano impugna la Darksaber all''interno della macelleria della stazione spaziale, la posizione della lama rispetto alla sua elsa e l''orientamento dell''impugnatura cambiano angolazione tra il piano d''ascolto frontale e il controcampo da dietro le spalle.', TRUE, '2026-10-24T18:58:42.581832', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1062, 217, '00:48:15', 'Errori di scena / Posizione', 'Nel finale di stagione (Capitolo 7), mentre Boba Fett cavalca il Rancor lungo le rovine della città, il bastone Gaffi agganciato sulla sua schiena cambia orientamento: la punta ricurva è rivolta verso destra nelle riprese da lontano, ma appare orientata a sinistra nei primi piani a mezzobusto.', TRUE, '2026-10-24T18:58:42.581832', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1065, 161, '00:29:50', 'Errori storici o fattuali', 'Quando il medico spiega a Lucy la natura della sostanza CPH4, la descrive come un prodotto sintetico basato su una molecola naturale prodotta dalle donne alla sesta settimana di gravidanza. In realtà, la CPH4 (6-carbossitetraidropterina) è un metabolita intermedio reale ma non ha alcuna delle proprietà chimiche o biologiche descritte nel film.', TRUE, '2026-10-24T19:39:37.558157', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1066, 161, '00:32:40', 'Errori di scena / Posizione', 'Nella scena dell''ospedale in cui Lucy si fa operare all''addome per rimuovere il pacchetto di droga, la quantità e l''estensione delle macchie di sangue sulla sua maglietta bianca variano vistosamente da un''inquadratura all''altra.', TRUE, '2026-10-24T19:39:37.558157', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1067, 161, '00:43:50', 'Troupe o microfoni visibili', 'All''interno del bagno dell''aereo, quando Lucy inizia a perdere la forma fisica e a disintegrarsi, sulle superfici metalliche e lucide del lavello si nota chiaramente il riflesso dell''attrezzatura di illuminazione del set e la sagoma dell''operatore di ripresa.', TRUE, '2026-10-24T19:39:37.558157', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1068, 161, '00:54:15', 'Errori di scena / Posizione', 'Durante il rocambolesco inseguimento in auto a Parigi a bordo della Peugeot 308 blu, lo specchietto retrovisore sinistro della vettura si spezza dopo un impatto, ma nelle inquadrature successive torna a essere perfettamente integro e montato sulla carrozzeria.', TRUE, '2026-10-24T19:39:37.558157', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1063, 161, '00:22:40', 'Errori storici o fattuali', 'L''intera premessa del film e la lezione tenuta dal Professor Norman (Morgan Freeman) si basano sul celebre mito secondo cui gli esseri umani utilizzerebbero solo il 10% del proprio cervello. In ambito neuroscientifico si tratta di un falso fattuale ampiamente smentito, poiché le tecniche di neuroimaging mostrano che l''uomo utilizza praticamente tutte le parti del cervello.', TRUE, '2026-10-24T19:39:37.558157', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1064, 161, '00:17:15', 'Errori di scena / Posizione', 'Nella stanza in cui Lucy viene tenuta prigioniera prima del pestaggio, la posizione delle sue mani ammanettate e le ciocche di capelli che le ricadono sul viso cambiano radicalmente posizione ad ogni stacco di montaggio tra il primo piano e la figura intera.', TRUE, '2026-10-24T19:39:37.558157', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(480, 96, '00:09:15', 'Errori di scena / Posizione', 'Quando il protagonista cade attraverso il pavimento ed entra per la prima volta nel Livello 0, la macchia di umidità sulla carta da parati gialla dietro di lui cambia forma e dimensione tra l''inquadratura panoramica e il primo piano successivo.', TRUE, '2026-09-16T11:56:08.67314', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1069, 151, '00:24:15', 'Errori di scena / Posizione', 'Durante la camminata tra le dune, la posizione del cappuccio e del tubo del sistema filtrante della tuta distillante sul collo di Chani cambia sistemazione tra il campo largo e il primo piano successivo, spostandosi da sopra a sotto la spagna destra.', TRUE, '2026-10-24T21:20:30.061684', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1070, 151, '00:48:30', 'Errori di scena / Posizione', 'Quando Paul cavalca il Verme delle Sabbie per la prima volta, la sabbia accumulata sulla parte anteriore del suo mantello compare e scompare improvvisamente nelle inquadrature ravvicinate rispetto ai campi lunghi da lontano.', TRUE, '2026-10-24T21:20:30.061684', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1071, 151, '01:12:10', 'Errori di scena / Posizione', 'Durante l''attacco al mietitore di spezia Harkonnen, la macchia di fuliggine e polvere sulla guancia sinistra di Gurney Halleck varia visibilmente per forma e densità nel passaggio da un piano medio a un primo piano.', TRUE, '2026-10-24T21:20:30.061684', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1072, 151, '01:35:45', 'Errori di scena / Posizione', 'Nella sequenza dell''arena monocromatica su Giedi Prime, la posizione del sangue sul pugnale di Feyd-Rautha cambia visibilmente direzione e quantità tra due stacchi di montaggio consecutivi.', TRUE, '2026-10-24T21:20:30.061684', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1073, 151, '02:05:15', 'Errori di scena / Posizione', 'Nel confronto finale nella sala del trono, le mani dell''Imperatore Shaddam IV cambiano posizione sul bastone: nell''inquadratura frontale la mano destra copre la sinistra, mentre nel controcampo la sinistra è posizionata sopra la destra.', TRUE, '2026-10-24T21:20:30.061684', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1074, 151, '02:22:10', 'Errori di scena / Posizione', 'Nel duello all''ultimo sangue tra Paul e Feyd-Rautha, la ferita da taglio sul fianco di Paul appare visibilmente insanguinata nei primi piani, ma torna ad essere del tutto pulita nelle inquadrature a figura intera.', TRUE, '2026-10-24T21:20:30.061684', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(193, 46, '01:22:40', 'Errori di scena / Posizione', 'Durante la discussione accesa nell''hotel, la sigaretta accesa tenuta da Ginger passa istantaneamente dalla mano destra alla mano sinistra tra due stacchi di montaggio consecutivi.', TRUE, '2026-09-14T13:49:14.103711', NULL, 0, 0, 'IA (Sistema)', 'ia')
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza") VALUES
(1075, 170, '00:45:10', 'Errori di scena / Posizione', 'Durante l''esplosione del tunnel di New York, Jasmine si rifugia in una nicchia di servizio insieme al figlio e al cane Boomer. Sebbene le fiamme avvolgano completamente l''esterno e la porta dell''intercapedine, nella scena immediatamente successiva la porta di legno e i personaggi risultano totalmente privi di bruciature o segni di fuliggine.', TRUE, '2026-10-24T21:24:19.042577', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1076, 170, '00:48:30', 'Errori storici o fattuali', 'Nella celebre sequenza della distruzione dell''Empire State Building, l''edificio viene mostrato posizionato direttamente al centro del viale prospettico. Nella realtà geografica di New York, l''Empire State Building sorge all''angolo tra la 34ª strada e la Fifth Avenue e non al termine di una strada rettilinea.', TRUE, '2026-10-24T21:24:19.042577', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1077, 170, '01:02:15', 'Errori di scena / Posizione', 'Mentre Steven Hiller (Will Smith) trascina il corpo dell''alieno avvolto nel paracadute attraverso il deserto, la fune di traino cambia visibilmente posizione e tensione tra i primi piani e i campi lunghi, risultando prima tesa sulle spalle e subito dopo allentata a terra.', TRUE, '2026-10-24T21:24:19.042577', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1078, 170, '01:04:05', 'Errori di scena / Posizione', 'Dopo aver colpito l''alieno con un pugno dicendo la celebre battuta ''Benvenuto sulla Terra!'', Steven Hiller ha un sigaro tra i denti. Al cambio di inquadratura, il sigaro scompare dalla sua bocca per riapparire istantaneamente nella sua mano destra.', TRUE, '2026-10-24T21:24:19.042577', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1079, 170, '01:24:40', 'Troupe o microfoni visibili', 'All''interno del laboratorio dell''Area 51, durante la scena in cui David Levinson (Jeff Goldblum) si sfoga frustrato facendo cadere i cestini della spazzatura, nel riflesso del pannello di vetro sulla destra della stanza si nota chiaramente l''ombra di un cameraman della troupe in movimento.', TRUE, '2026-10-24T21:24:19.042577', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1080, 170, '02:08:15', 'Anacronismi', 'Durante il caricamento del virus informatico sulla nave madre aliena, il laptop Apple PowerBook 5300 di David mostra un''interfaccia grafica avanzata con conteggio alla rovescia personalizzato. Per la tecnologia del 1996, era del tutto anacronistico e impossibile compilare un software dotato di GUI complessa e interamente compatibile con un''architettura aliena sconosciuta in poche ore.', TRUE, '2026-10-24T21:24:19.042577', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1081, 170, '00:18:40', 'Errori storici o fattuali', 'Quando le navi aliene entrano simultaneamente nell''atmosfera posizionandosi sopra le principali metropoli del pianeta (tra cui Washington, New York, Los Angeles, Mosca e il Golfo Persico), la piena luce del giorno splende indistintamente su tutte le località, ignorando del tutto i fusi orari e l''alternanza giorno-notte del pianeta Terra.', TRUE, '2026-10-24T21:24:37.773434', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1082, 170, '00:46:15', 'Errori di scena / Posizione', 'Nella sequenza del tunnel di Los Angeles in cui Jasmine cerca salvezza prima dell''esplosione, la porta del locale tecnico di sicurezza cambia stato: nell''inquadratura ravvicinata la donna la spalanca a fatica e vi trascina dentro il cane Boomer lasciando lo spiraglio aperto, ma nello stacco successivo grandangolare, un istante prima dell''impatto del muro di fuoco, la porta risulta completamente chiusa e serrata.', TRUE, '2026-10-24T21:24:37.773434', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1083, 170, '00:48:30', 'Errori storici o fattuali', 'Nel momento in cui il raggio distruttore colpisce l''Empire State Building, l''edificio è inquadrato al centro esatto di una lunghissima prospettiva stradale frontale. Nella reale griglia urbanistica di Manhattan, l''Empire State Building si trova all''incrocio tra la Fifth Avenue e la 34ª Strada Ovest e non sbarra il termine visivo di alcun viale in quella maniera scenografica.', TRUE, '2026-10-24T21:24:37.773434', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1084, 170, '01:03:15', 'Errori di scena / Posizione', 'Mentre il capitano Steven Hiller attraversa a piedi il deserto salato trascinando il corpo dell''alieno avvolto nel paracadute, la posizione della creatura muta tra i cambi di campo: nei primi piani la testa dell''alieno è rivolta verso l''alto con il volto visibile, mentre nelle inquadrature a figura intera da lontano il corpo è girato a pancia in giù.', TRUE, '2026-10-24T21:24:37.773434', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1085, 170, '01:22:10', 'Errori di scena / Posizione', 'Nella base segreta di Area 51, David Levinson si ubriaca e scaraventa a terra con rabbia alcuni cestini e bottiglie di plastica. Nel dialogo immediatamente successivo con suo padre Julius, il disordine sul pavimento cambia radicalmente posizione tra i controcampi e diversi flaconi precedentemente rovesciati ricompaiono allineati sul tavolo da lavoro.', TRUE, '2026-10-24T21:24:37.773434', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1086, 170, '01:47:50', 'Troupe o microfoni visibili', 'Durante il celebre discorso motivazionale del Presidente Whitmore prima del contrattacco aereo, sul lato sinistro inferiore dell''inquadratura panoramica che mostra i piloti radunati sotto il caccia, si nota nettamente l''ombra allungata della camera da presa montata su dolly e l''estremità di un''asta microfonica fuori campo.', TRUE, '2026-10-24T21:24:37.773434', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1087, 238, '00:24:10', 'Troupe o microfoni visibili', 'Quando Chris esplora la soffitta buia utilizzando una candela per indagare sui misteriosi rumori nel soffitto, l''ombra del microfono a giraffa e dell''operatore si proietta chiaramente sulla parete di legno a sinistra.', TRUE, '2026-10-25T08:35:00.516491', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1088, 238, '00:48:15', 'Errori di scena / Posizione', 'Durante la sequenza dell''arteriografia cerebrale in ospedale, la posizione dei teli chirurgici, delle mani del medico e del catetere inserito nel collo di Regan cambia palesemente tra il primo piano e il campo medio subito prima dello schizzo di sangue.', TRUE, '2026-10-25T08:35:00.516491', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1089, 238, '01:18:30', 'Troupe o microfoni visibili', 'Nella celebre scena in cui Regan vomita la sostanza verde contro Padre Karras, è visibile lungo il lato destro della guancia della ragazzina (o del manichino) il tubicino trasparente di plastica utilizzato dalla troupe per spruzzare la zuppa a pressione.', TRUE, '2026-10-25T08:35:00.516491', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1090, 238, '01:28:45', 'Troupe o microfoni visibili', 'Nel momento in cui Chris viene colpita e violentemente scagliata indietro sul pavimento dalla figlia posseduta, nell''angolo inferiore dell''inquadratura è visibile il cavo di sicurezza imbracato attorno all''attrice Ellen Burstyn per tirarla di colpo.', TRUE, '2026-10-25T08:35:00.516491', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1091, 238, '01:42:10', 'Errori di scena / Posizione', 'Nella camera da letto congelata, la presenza del fiato condensato dei sacerdoti è del tutto incostante: mentre Padre Merrin pronuncia le formule rituali il vapore dalla bocca è denso e visibile, ma al cambio d''inquadratura immediato su Padre Karras la condensa scompare del tutto per poi riapparire nella ripresa successiva.', TRUE, '2026-10-25T08:35:00.516491', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1092, 238, '01:56:20', 'Errori di scena / Posizione', 'Durante la fatale caduta di Padre Karras lungo la ripidissima scalinata esterna di Georgetown, nelle inquadrature frontali si nota chiaramente il volto della controfigura (lo stuntman Chuck Waters) al posto dell''attore Jason Miller.', TRUE, '2026-10-25T08:35:00.516491', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1093, 13, '00:18:45', 'Anacronismi', 'Nella sequenza ambientata a New York durante la parata del 1969 per gli astronauti dell''Apollo 11, sullo sfondo di una via commerciale si nota una cabina telefonica recante il restyling del logo AT&T ''Bell System'' entrato in uso solo tra la fine del 1969 e il 1970, oltre a un idrante con conformazione moderna non presente all''epoca.', TRUE, '2026-10-25T08:58:52.392568', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1094, 13, '00:32:15', 'Troupe o microfoni visibili', 'Durante l''inseguimento a cavallo all''interno delle gallerie della metropolitana di New York, sul fianco metallico lucido del vagone del treno che sfreccia accanto a Indy si intravede per un istante il riflesso del braccio meccanico della camera di ripresa e del pannello LED di illuminazione.', TRUE, '2026-10-25T08:58:52.392568', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1095, 13, '00:48:10', 'Errori di scena / Posizione', 'Nella scena dell''asta clandestina nell''hotel di Tangeri, la posizione dei frammenti del Quadrante sul tavolo da gioco cambia notevolmente tra il campo largo e il primo piano: prima i pezzi sono disposti quasi a contatto, poi risultano ruotati e distanziati di diversi centimetri senza che nessuno li abbia toccati.', TRUE, '2026-10-25T08:58:52.392568', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1096, 13, '01:12:35', 'Errori di scena / Posizione', 'Durante la sequenza d''immersione al largo della Grecia per esplorare il relitto, il cinturino della maschera subacquea di Indiana Jones si trova chiaramente posizionato sopra le orecchie nei campi lunghi, mentre nei primi piani ravvicinati scivola improvvisamente al di sotto del lobo.', TRUE, '2026-10-25T08:58:52.392568', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1097, 13, '01:38:50', 'Errori storici o fattuali', 'Durante la battaglia dell''assedio di Siracusa (212 a.C.), le navi romane mostrate nell''inquadratura aerea presentano un sartiame e una disposizione delle vele quadrate con manovre tipiche dei galeoni del XVII secolo, storicamente inesistenti nell''architettura navale dell''antica Roma.', TRUE, '2026-10-25T08:58:52.392568', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1098, 13, '01:54:20', 'Errori storici o fattuali', 'All''interno del laboratorio di Archimede a Siracusa, sugli scrigni e sui manufatti dell''inventore sono visibili dettagli di ingranaggi in bronzo con filettature e passi di vite realizzati con una precisione da lavorazione meccanica industriale, del tutto incompatibili con le tecniche metallurgiche del III secolo a.C.', TRUE, '2026-10-25T08:58:52.392568', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(1099, 239, '00:04:10', 'Troupe o microfoni visibili', 'Durante il famoso piano sequenza iniziale girato in soggettiva, quando il piccolo Michael gira attorno alla casa per entrare dalla porta sul retro, si può notare l''ombra della cinepresa e dell''operatore proiettata sulla parete esterna dell''abitazione.', TRUE, '2026-10-25T12:32:22.589571', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1100, 239, '00:09:15', 'Errori di scena / Posizione', 'Durante la sequenza dell''evasione dal manicomio di Smith''s Grove, Michael Myers assale l''auto della dottoressa Marion Chambers. In un''inquadratura il finestrino del lato passeggero è chiaramente del tutto abbassato, ma nel stacco successivo Michael lo frantuma con una mano come se fosse completamente alzato.', TRUE, '2026-10-25T12:32:22.589571', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1101, 239, '00:16:30', 'Anacronismi', 'Il film è ambientato nella fittizia cittadina di Haddonfield, nell''Illinois, ma è stato interamente girato in California. In diverse scene in cui Laurie cammina per le strade della città si possono notare chiaramente sullo sfondo diverse palme, alberi del tutto assenti nel clima medioevale dell''Illinois.', TRUE, '2026-10-25T12:32:22.589571', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1102, 239, '00:24:10', 'Troupe o microfoni visibili', 'Quando Laurie cammina verso casa e vede la figura di Michael Myers nascosta dietro la siepe del giardino, sul lato sinistro dello schermo entra una vistosa nuvola di fumo di sigaretta. Si trattava del fumo del regista John Carpenter, che stava fumando proprio accanto alla macchina da presa.', TRUE, '2026-10-25T12:32:22.589571', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1103, 239, '00:32:45', 'Errori storici o fattuali', 'Nelle scene ambientate lungo le strade di Haddonfield (Illinois), le automobili parcheggiate a bordo strada mostrano le targhe dello stato della California (all''epoca nere con lettere gialle e con il bollino di registrazione visibile) invece delle targhe dell''Illinois.', TRUE, '2026-10-25T12:32:22.589571', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1104, 239, '01:12:10', 'Errori di scena / Posizione', 'Nella scena in cui Laurie trova il cadavere di Annie adagiato sul letto sotto la lapide trafugata di Judith Myers, l''angolazione e l''orientamento della lapide cambiano visibilmente passando dal campo lungo al primo piano.', TRUE, '2026-10-25T12:32:22.589571', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1105, 239, '01:21:40', 'Errori di scena / Posizione', 'Dopo che Laurie pugnala Michael al collo con un ferro da maglia, la posizione del foro sulla tuta da lavoro e la quantità di sangue finto presente sul collo del killer variano in modo incoerente nelle inquadrature successive dello scontro.', TRUE, '2026-10-25T12:32:22.589571', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia'),
(1106, 240, '00:04:15', 'Errori di scena / Posizione', 'Nella scena iniziale in cui Georgie rincorre la barchetta sotto la pioggia battere, il livello d''inzuppamento dell''impermeabile giallo del bambino e la traiettoria della barchetta cambiano visibilmente tra il campo largo e i primi piani.', TRUE, '2026-10-25T12:35:48.868669', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(1107, 240, '00:32:40', 'Anacronismi', 'All''interno della farmacia di Derry, sugli scaffali sullo sfondo sono visibili confezioni di prodotti e medicinali con loghi aziendali moderni e codici a barre con formati introdotti solo dopo il 1989.', TRUE, '2026-10-25T12:35:48.868669', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(1108, 240, '00:48:10', 'Errori di scena / Posizione', 'Durante la sequenza in cui Beverly e i ragazzi puliscono il bagno imbrattato di sangue, la disposizione e la quantità di macchie ematiche sul viso e sulla maglietta di Beverly cambiano incoerentemente da un''inquadratura all''altra.', TRUE, '2026-10-25T12:35:48.868669', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(1109, 240, '01:02:15', 'Troupe o microfoni visibili', 'Nella scena del garage, quando il proiettore di diapositive inizia a funzionare da solo, sulla superficie metallica e cromata del manubrio della bicicletta si nota il riflesso della sagoma di un operatore di ripresa e di un faretto di illuminazione.', TRUE, '2026-10-25T12:35:48.868669', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(1110, 240, '01:18:05', 'Errori di scena / Posizione', 'Durante la ''guerra delle pietre'' (Rock War) lungo il torrente, la posizione degli occhiali di Richie e l''orientamento del suo corpo a terra cambiano improvvisamente tra il controcampo e il piano sequenza successivo.', TRUE, '2026-10-25T12:35:48.868669', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(1111, 240, '01:35:50', 'Anacronismi', 'Nella sala giochi/arcade frequentata dai ragazzi si scorgono cabinati con grafiche e titoli di videogiochi usciti nei primi anni ''90, mentre la vicenda è rigorosamente ambientata nell''estate del 1989.', TRUE, '2026-10-25T12:35:48.868669', NULL, 0, 0, 'mrtrrt@libero.it', 'ia'),
(542, 108, '01:38:05', 'Anacronismi', 'Nella sequenza flashback ambientata nei primi anni ''90, sullo sfondo dell''incrocio stradale si scorge chiaramente una colonnina di ricarica per veicoli elettrici di ultima generazione montata sul marciapiede.', TRUE, '2026-09-17T11:16:35.811481', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(685, 111, '01:12:10', 'Errori di scena / Posizione', 'Durante la celebre scena romantica sulla prua in cui Rose dice ''Sto volando'', in alcune inquadrature ravvicinate di profilo si può notare che la linea dell''orizzonte marino alle spalle dei protagonisti presenta una leggera curvatura innaturale verso l''alto. Questo svela la presenza del bordo della gigantesca vasca d''acqua esterna utilizzata per le riprese nei Baja Studios a Rosarito.', TRUE, '2026-09-21T20:46:10.325971', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(681, 111, '00:25:40', 'Anacronismi', 'Mentre Rose sistema i suoi dipinti nella cabina di prima classe, mostra a Cal un''opera di Claude Monet raffigurante delle ninfee. Tuttavia, la specifica tela mostrata nel film fa parte di una serie che Monet dipinse tra il 1915 e il 1926, diversi anni dopo il naufragio del Titanic avvenuto nel 1912. Inoltre, quel dipinto reale è conservato al Musée de l''Orangerie a Parigi, il che significa che non è mai affondato con la nave.', TRUE, '2026-09-21T20:46:10.325971', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(682, 111, '00:38:50', 'Errori di scena / Posizione', 'Subito dopo aver salvato Rose che rischiava di cadere dalla poppa della nave, Jack viene trattenuto dagli ufficiali. In questa sequenza, i capelli di Jack cambiano ripetutamente aspetto tra un''inquadratura e l''altra: prima appaiono bagnati, spettinati e madidi di sudore, poi improvvisamente asciutti e perfettamente in ordine, per poi tornare disordinati nel cambio di telecamera successivo.', TRUE, '2026-09-21T20:46:10.325971', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(754, 142, '01:42:15', 'Discontinuità visiva / Modello meccanico', 'Nel climax finale, le bruciature e le cicatrici sul lato destro del muso dello squalo (causate dall''esplosione della barca a motore) cambiano forma, profondità e colore rispetto alle scene precedenti, rivelando l''uso di pupazzi meccanici differenti non perfettamente identici.', TRUE, '2026-09-28T06:16:30.26034', NULL, 0, 0, 'lrscrm73@gmail.com', 'ia'),
(656, 127, '01:29:15', 'Errori di scena / Posizione', 'Nella cucina della fattoria McBain, durante la conversazione tra Jill e Cheyenne, quest''ultimo beve da una tazza di metallo e tiene in mano un pezzo di pane. Nei controcampi la mano con cui regge la tazza si alterna improvvisamente tra la destra e la sinistra, e il livello del caffè all''interno passa dall''essere quasi vuoto a nuovamente pieno.', TRUE, '2026-09-19T18:08:29.015384', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(753, 142, '01:34:50', 'Errore di scena / Posizione', 'Sull''isolotto della centrale elettrica (Cable Junction), il livello della marea attorno alle rocce dove si rifugiano i ragazzi sale e scende in modo del tutto arbitrario tra un montaggio e l''altro, passando dal livello della caviglia alla vita senza soluzione di continuità.', TRUE, '2026-09-28T06:16:30.26034', NULL, 0, 0, 'lrscrm73@gmail.com', 'ia'),
(662, 129, '02:05:30', 'Troupe o microfoni visibili', 'Durante la sequenza in cui la banda di gangster si sposta a bordo delle grandi berline nere degli anni ''30, sulla fiancata lucida dell''auto di Max è possibile scorgere nitidamente per alcuni secondi il riflesso di un pannello riflettente bianco e di un operatore della troupe cinematografica con la macchina da presa.', TRUE, '2026-09-19T19:44:18.773942', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(664, 129, '02:48:50', 'Anacronismi', 'Quando Noodles si reca alla stazione ferroviaria per fuggire da New York nel 1933, sullo sfondo si nota un treno passeggeri con carrozze metalliche i cui dettagli di design e i loghi della compagnia ferroviaria appartengono a modelli introdotti solo alla fine degli anni ''40 o nei primi anni ''50.', TRUE, '2026-09-19T19:44:18.773942', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(670, 133, '00:48:20', 'Errori di scena / Posizione', 'Durante la conversazione sul set di ''Lancer'' tra Rick Dalton e la giovane attrice Trudi Fraser, il libro che Rick tiene in mano (''The Bronze Killer'') cambia orientamento. In alcune inquadrature ravvicinate la copertina è rivolta verso l''alto, mentre nei controcampi è capovolta, nonostante Rick non lo muova.', TRUE, '2026-09-19T19:47:51.941973', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(671, 133, '02:22:10', 'Errori di scena / Posizione', 'Durante lo scontro finale nella villa di Rick Dalton, quando il cane Brandy morde Tex Watson alla coscia, la ferita da morso e lo strappo sui pantaloni appaiono e scompaiono tra i diversi tagli di montaggio, mostrando i pantaloni di Tex alternativamente lacerati e poi quasi intatti.', TRUE, '2026-09-19T19:47:51.941973', NULL, 0, 0, 'IA (Sistema)', 'ia'),
(317, 61, '00:32:10', 'Anacronismi', 'Durante la scena del tentativo di esecuzione di Jack Sparrow e Carina Smyth, viene utilizzata una ghigliottina. La ghigliottina moderna con lama obliqua è stata introdotta in Francia solo nel 1792 durante la Rivoluzione Francese, mentre gli eventi del film si svolgono diversi decenni prima, intorno al 1740-1750.', TRUE, '2026-09-14T14:11:22.346951', '{
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza") VALUES
(334, 59, '00:11:35', 'Errori storici o fattuali', 'Nelle scene ambientate a Singapore intorno al 1730, la città viene rappresentata come un imponente porto mercantile con complesse infrastrutture in stile cinese e bagni pubblici sotterranei. Storicamente, all''epoca Singapore era solo un piccolo villaggio di pescatori quasi disabitato e ricoperto dalla giungla; lo sviluppo urbano e portuale mostrato nel film avvenne solo dopo la fondazione britannica nel 1819.', TRUE, '2026-09-14T14:15:11.483002', 'Pirati dei Caraibi - Ai confini del mondo Nelle scene ambientate a Singapore intorno al 1730 mistake error', 0, 0, 'IA (Sistema)', 'ia'),
(337, 59, '01:14:50', 'Anacronismi', 'Durante il Consiglio dei Fratelli nella Baia dei Relitti, Capitano Teague (interpretato da Keith Richards) suona una chitarra acustica. Un''attenta visione della pala dello strumento rivela meccaniche di intonazione in metallo sigillate con ingranaggi a vite senza fine, una tecnologia per chitarra inventata e brevettata solo nel XIX secolo.', TRUE, '2026-09-14T14:15:11.826697', 'Pirati dei Caraibi - Ai confini del mondo Durante il Consiglio dei Fratelli nella Baia dei mistake error', 0, 0, 'IA (Sistema)', 'ia')
