INSERT INTO public.configurazioni ("chiave", "valore", "visibile") VALUES
('home_promo_int_titolo', 'Promo Startup attiva: registrati gratis a vita!', TRUE),
('home_promo_interna', 'Approfitta della promozione di lancio: registrati ora per ottenere l''accesso Premium Lifetime gratuito. I pagamenti e gli abbonamenti a pagamenti partiranno solo al termine dell''offerta promozionale!!', TRUE),
('promo_button_text', '💎 Listino Piani post-lancio', TRUE),
('promo_card_text', 'Approfitta della promozione di lancio: registrati ora per ottenere l''accesso <b>Premium Lifetime gratuito</b>. I pagamenti e gli abbonamenti a pagamento partiranno solo al termine dell''offerta promozionale!!', TRUE),
('promo_card_title', 'Promo Startup attiva: Registrati gratis a vita!', TRUE),
('soglia_punti_lifetime', '1000', TRUE),
('soglia_punti_mensile', '100', TRUE),
('promo_lifetime_deadline', '2027-01-01', TRUE),
('classifica_banner_titolo', 'Come funziona il sistema di punti e premi?', TRUE),
('classifica_testo_1', 'contribuisci segnalando nuovi errori o facendo validare le tue segnalazioni dall''amministratore.', TRUE),
('classifica_testo_2', '⭐ Premio Mensile (Ogni {soglia_mensile} punti): Ogni volta che accumuli {soglia_mensile} punti, sblocchi automaticamente 1 mese di abbonamento Premium gratuito.', TRUE),
('classifica_testo_3', '👑 Premio Lifetime ({soglia_lifetime} punti): Raggiungi la vetta della community arrivando a {soglia_lifetime} punti per sbloccare l''accesso Lifetime gratuito a vita!', TRUE),
('classifica_titolo', 'Classifica Cacciatori di Bloopers', TRUE),
('footer_testo_amazon', 'In qualità di Affiliato Amazon, riceviamo un guadagno dagli acquisti idonei.', TRUE),
('footer_testo_principale', 'FilmBloopers Hub — Il database intelligente degli errori cinematografici | P.IVA: 12345678901 | Sede Legale: Via Roma 1, Torino | Contatti: supporto@filmbloopers.it', TRUE),
('home_archivio', 'Inizia la scoperta: vai su Esplora e Cerca nel menu a sinistra, inserisci un titolo o una saga e premi Invio per esplorare o generare nuovi contenuti.', TRUE),
('home_banner_top_badge', 'Offerta a Tempo Limitato', TRUE),
('home_banner_top_testo', 'Registrati o scala la classifica entro il 2026-12-31 per sbloccare subito l''accesso <b>Premium Lifetime gratuito</b> a vita!', TRUE),
('home_banner_top_titolo', 'PROMO SPECIALE DI LANCIO STARTUP', TRUE),
('home_header_sottotitolo', 'Esplora, scopri e cataloga in tempo reale i bloopers, le sviste e i dettagli nascosti della storia del cinema.', TRUE),
('home_header_titolo', 'Archivio Errori e Incongruenze Cinematografiche', TRUE),
('home_inizia_subito', 'usa il menu a sinistra per andare su Esplora e Cerca. Se il film non è ancora catalogato, la nostra intelligenza artificiale lo analizzerà in tempo reale per te!', TRUE),
('home_main_p1', 'Quante volte, guardando un film, ti sei detto: "Questo errore lo sapevo già!" oppure "Possibile che non ci avessi mai fatto caso prima?". Questo progetto nasce dalla passione per il cinema vissuto fotogramma per fotogramma, raccogliendo i piccoli e grandi scivoloni, i bloopers e le incongruenze che popolano la storia della settima arte.', TRUE),
('home_main_p2', 'Dalle sviste storiche più clamorose agli errori di raccordo che fanno sorridere, ogni scheda è un viaggio dentro il set per riscoprire i tuoi film preferiti con occhi nuovi, unendo i titoli cult che tutti ricordiamo a scoperte del tutto inedite.', TRUE),
('home_main_titolo', 'Errori, sviste e ciak falsi nella storia del cinema: dai classici che tutti conosciamo alle sorprese più inaspettate', TRUE)
